  admin shopping_admins @relation("shopping_admin_action_logs_of_admin_id", fields: [admin_id], references: [id], onDelete: Cascade)
  affectedAdmin shopping_admins? @relation("shopping_admin_action_logs_of_affected_admin_id", fields: [affected_admin_id], references: [id], onDelete: Cascade)
  affectedSeller shopping_sellers? @relation(fields: [affected_seller_id], references: [id], onDelete: Cascade)
