  suspendedSeller shopping_sellers? @relation(fields: [suspended_seller_id], references: [id], onDelete: Cascade)
  suspendedCustomer shopping_customers? @relation(fields: [suspended_customer_id], references: [id], onDelete: Cascade)

  shopping_appeals shopping_appeals[]

  @@index([suspended_admin_id])
  @@index([suspended_seller_id])
  @@index([suspended_customer_id])
  @@index([admin_id, created_at])
  @@index([reason(ops: raw("gin_trgm_ops"))], type: Gin)
}

/// Stores all platform-wide announcements initiated by admins. Each record
/// captures title, content, target audience, visibility windows, publication
/// status, and author (admin reference). Used to push maintenance, update,
/// and official notices to all or filtered user segments. Status and
/// schedule fields control announcement display periods.
///
/// @namespace AdminOps
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model shopping_platform_announcements {
  //----
  // COLUMNS
  //----
  /// Primary Key.
