  @@index([admin_id, created_at])
  @@index([title(ops: raw("gin_trgm_ops"))], type: Gin)
  @@index([body(ops: raw("gin_trgm_ops"))], type: Gin)
}

/// Tracks all detected or reported business policy violations involving any
/// actor or entity (customer/seller/admin/product/order/etc). Each record
/// references the violated policy, the reporting actor, affected entity,
/// violation type/code, description, status, dates, and decision history.
/// Used for compliance, after-action reviews, automation triggers, and
/// escalation to appeals. Supports complex violation lifecycle.
///
/// @namespace AdminOps
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model shopping_policy_violations {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// Reference to violated business policy configuration. {@link
  /// shopping_business_policies.id}.
  policy_id String @db.Uuid

  /// Admin who filed the violation report, if applicable. {@link
  /// shopping_admins.id}.
  reported_by_admin_id String? @db.Uuid

  /// Seller who reported the violation, if any. {@link shopping_sellers.id}.
  reported_by_seller_id String? @db.Uuid

  /// Customer who reported the violation, if any. {@link
  /// shopping_customers.id}.
  reported_by_customer_id String? @db.Uuid

  /// Admin account affected by the violation (e.g., internal compliance
  /// cases). {@link shopping_admins.id}.
  affected_admin_id String? @db.Uuid

  /// Seller account affected by violation. {@link shopping_sellers.id}.
  affected_seller_id String? @db.Uuid

  /// Customer account affected by violation. {@link shopping_customers.id}.
  affected_customer_id String? @db.Uuid

  /// Product affected by violation. {@link shopping_products.id}.
  affected_product_id String? @db.Uuid

  /// Order affected by violation. {@link shopping_orders.id}.
  affected_order_id String? @db.Uuid

  /// Constant for violation class (e.g., 'abuse', 'fraud',
  /// 'duplicate_account', 'policy_breach').
  violation_type String

  /// Machine-readable code for violation (from business policy reference).
  violation_code String

  /// Human-readable violation summary for admins/reviewers.
  description String?

  /// Current lifecycle status (e.g., 'open', 'under_review', 'resolved',
  /// 'escalated', 'invalid', 'canceled').
  status String

  /// Resolution or adjudication result; null if not yet decided.
  decision String?

  /// Timestamp of the resolution decision.
  decision_at DateTime? @db.Timestamptz

  /// Time when violation record was created.
  created_at DateTime @db.Timestamptz

  /// Last update timestamp (typically investigation note/decision).
  updated_at DateTime @db.Timestamptz

  /// Soft delete for audit/cleanup, not for physical erasure.
  deleted_at DateTime? @db.Timestamptz

  //----
  // RELATIONS
  //----
  policy shopping_business_policies @relation(fields: [policy_id], references: [id], onDelete: Cascade)
  reportedByAdmin shopping_admins? @relation("shopping_policy_violations_of_reported_by_admin_id", fields: [reported_by_admin_id], references: [id], onDelete: Cascade)
  reportedBySeller shopping_sellers? @relation("shopping_policy_violations_of_reported_by_seller_id", fields: [reported_by_seller_id], references: [id], onDelete: Cascade)
  reportedByCustomer shopping_customers? @relation("shopping_policy_violations_of_reported_by_customer_id", fields: [reported_by_customer_id], references: [id], onDelete: Cascade)
  affectedAdmin shopping_admins? @relation("shopping_policy_violations_of_affected_admin_id", fields: [affected_admin_id], references: [id], onDelete: Cascade)
  affectedSeller shopping_sellers? @relation("shopping_policy_violations_of_affected_seller_id", fields: [affected_seller_id], references: [id], onDelete: Cascade)
  affectedCustomer shopping_customers? @relation("shopping_policy_violations_of_affected_customer_id", fields: [affected_customer_id], references: [id], onDelete: Cascade)
  affectedProduct shopping_products? @relation(fields: [affected_product_id], references: [id], onDelete: Cascade)
  affectedOrder shopping_orders? @relation(fields: [affected_order_id], references: [id], onDelete: Cascade)

  shopping_appeals shopping_appeals[]

  @@index([reported_by_admin_id])
  @@index([reported_by_seller_id])
  @@index([reported_by_customer_id])
  @@index([affected_admin_id])
  @@index([affected_seller_id])
  @@index([affected_customer_id])
  @@index([affected_product_id])
  @@index([affected_order_id])

  @@index([policy_id, created_at])
  @@index([status, created_at])
  @@index([description(ops: raw("gin_trgm_ops"))], type: Gin)
}

/// Tracks formal appeals filed against suspensions, account actions,
/// business policy violations, or other adverse admin/adminops actions.
/// Records the target entity, appeal reason, status, decision, and reviewer
/// admin. Supports audit trail, multi-stage decision, and escalations.
/// Crucial for regulatory, compliance, and dispute-handling processes.
///
/// @namespace AdminOps
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model shopping_appeals {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// References the base suspension being appealed, if applicable. {@link
  /// shopping_admin_suspensions.id}.
  appeal_of_suspension_id String? @db.Uuid

  /// References corresponding policy violation, if applicable. {@link
  /// shopping_policy_violations.id}.
  appeal_of_policy_violation_id String? @db.Uuid

  /// Admin who filed the appeal, if initiated internally. {@link
  /// shopping_admins.id}.
  filed_by_admin_id String? @db.Uuid

  /// Seller who filed the appeal, if externally. {@link shopping_sellers.id}.
  filed_by_seller_id String? @db.Uuid

  /// Customer who filed the appeal. {@link shopping_customers.id}.
  filed_by_customer_id String? @db.Uuid

  /// Admin who reviewed or decided the appeal. {@link shopping_admins.id}.
  reviewed_by_admin_id String? @db.Uuid

  /// Detailed business reason and supporting context for the appeal.
  reason String

  /// Current appeal lifecycle status (e.g., 'filed', 'under_review',
  /// 'approved', 'rejected', 'closed', 'escalated').
  status String

  /// Decision/result of the appeal process if known (e.g., 'upheld',
  /// 'overturned').
  decision String?

  /// Datetime of appeal decision.
  decision_at DateTime? @db.Timestamptz

  /// Appeal filing timestamp.
  created_at DateTime @db.Timestamptz

  /// Last updated timestamp (investigation, notes, status changes).
  updated_at DateTime @db.Timestamptz

  /// Soft delete timestamp for audit/cleanup.
  deleted_at DateTime? @db.Timestamptz

  //----
  // RELATIONS
  //----
  appealOfSuspension shopping_admin_suspensions? @relation(fields: [appeal_of_suspension_id], references: [id], onDelete: Cascade)
  appealOfPolicyViolation shopping_policy_violations? @relation(fields: [appeal_of_policy_violation_id], references: [id], onDelete: Cascade)
  filedByAdmin shopping_admins? @relation("shopping_appeals_of_filed_by_admin_id", fields: [filed_by_admin_id], references: [id], onDelete: Cascade)
  filedBySeller shopping_sellers? @relation(fields: [filed_by_seller_id], references: [id], onDelete: Cascade)
  filedByCustomer shopping_customers? @relation(fields: [filed_by_customer_id], references: [id], onDelete: Cascade)
  reviewedByAdmin shopping_admins? @relation("shopping_appeals_of_reviewed_by_admin_id", fields: [reviewed_by_admin_id], references: [id], onDelete: Cascade)

  @@index([reviewed_by_admin_id])

  @@index([status, created_at])
  @@index([filed_by_admin_id, created_at])
  @@index([filed_by_seller_id, created_at])
  @@index([filed_by_customer_id, created_at])
  @@index([appeal_of_suspension_id])
  @@index([appeal_of_policy_violation_id])
  @@index([reason(ops: raw("gin_trgm_ops"))], type: Gin)
}

schemas.schema-11-policy.prisma:
/// Defines named business policies for platform-wide application or specific
/// domains. Used to codify and audit enforceable business rules such as
/// return windows, commission rates, and user eligibility thresholds.
/// Referenced by other domains for outward enforcement; never contains
/// operational data itself.
///
/// @namespace Policy
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model shopping_business_policies {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// Unique name for the business policy (e.g., 'order_return_window',
  /// 'seller_onboarding_requirement'). Used for outward reference and
  /// enforcement in other domains.
  policy_name String

  /// Scope or domain where this policy applies (e.g., 'global', 'orders',
  /// 'sellers').
  scope String

  /// Value or threshold for the policy (e.g., '30', 'approved'). Can be
  /// interpreted as string, integer, or enum as required by consuming domain.
  value String

  /// Detailed description of the business purpose and operational impact of
  /// this policy.
  description String

  /// Whether this policy is currently active and enforced platform-wide.
  active Boolean

  /// Policy creation timestamp.
  created_at DateTime @db.Timestamptz

  /// Policy update timestamp.
  updated_at DateTime @db.Timestamptz

  /// Soft delete timestamp, if the policy is archived or replaced. Null if
  /// active.
  deleted_at DateTime? @db.Timestamptz

  //----
  // RELATIONS
  //----
  shopping_policy_violations shopping_policy_violations[]

  @@unique([policy_name, scope])
  @@index([active])
  @@index([description(ops: raw("gin_trgm_ops"))], type: Gin)
}

/// Defines system-wide or domain-specific constraints (e.g., rate limits,
/// maximum SKU count, min/max purchase values). Used for enforcing
/// quantitative limits or operational boundaries across the platform.
/// Referenced by other domains by outward FK, never inward.
///
/// @namespace Policy
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model shopping_business_constraints {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// Unique name of the constraint (e.g., 'max_orders_per_user_day',
  /// 'sku_max_per_product'). Used for lookups and enforcement.
  constraint_name String

  /// Scope or domain for the constraint (e.g., 'global', 'carts', 'checkout',
  /// 'products').
  scope String

  /// Constraint value, typically an integer or decimal encoded as string
  /// (actual enforcement handled in consuming domain).
  limit_value String

  /// Unit for the constraint's value (e.g., 'count', 'seconds', 'amount').
  unit String

  /// Full business explanation of what limit this constraint applies and its
  /// operational significance.
  description String

  /// Whether the constraint is currently in force.
  active Boolean

  /// Constraint creation timestamp.
  created_at DateTime @db.Timestamptz

  /// Constraint last update timestamp.
  updated_at DateTime @db.Timestamptz

  /// Soft delete timestamp; null if constraint is active.
  deleted_at DateTime? @db.Timestamptz

  //----
  // RELATIONS
  //----
  @@unique([constraint_name, scope])
  @@index([active])
  @@index([description(ops: raw("gin_trgm_ops"))], type: Gin)
}

/// Manages feature toggles and rollout switches for platform capabilities
/// (e.g., beta features, A/B experiments, domain-scoped rollouts). Admins
/// can independently enable/disable features or set percentage rollout.
/// Outward referenced for controlled enablement, not bound to specific
/// session or user here.
///
/// @namespace Policy
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model shopping_feature_flags {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// Unique name of the feature flag (e.g., 'new_checkout_flow',
  /// 'wishlist_enabled'). Used for outward reference and API enablement.
  flag_name String

  /// Domain or context where this feature applies (e.g., 'global', 'orders',
  /// 'checkout', 'frontend').
  scope String

  /// Indicates whether the feature is enabled system-wide for the associated
  /// scope.
  enabled Boolean

  /// (Optional) Percentage 0-100 for gradual rollout/experimentation. 100 =
  /// fully enabled, 0 = off (used for A/B testing).
  rollout Float? @db.DoublePrecision

  /// Explanation of feature flag purpose and behavior under enabled/disabled
  /// conditions.
  description String

  /// Feature flag creation timestamp.
  created_at DateTime @db.Timestamptz

  /// Update timestamp for the feature flag.
  updated_at DateTime @db.Timestamptz

  /// Soft delete timestamp; null if flag is active.
  deleted_at DateTime? @db.Timestamptz

  //----
  // RELATIONS
  //----
  @@unique([flag_name, scope])
  @@index([enabled])
  @@index([description(ops: raw("gin_trgm_ops"))], type: Gin)
}

