schemas.schema-01-systematic.prisma:
/// Platform-wide key/value configuration entries for system-level settings
/// (URL, SMTP, feature flags, etc). These are needed for initialization,
/// seeding, and global runtime parameterization. Each config is uniquely
/// keyed and soft deletable for historical reference.
///
/// @namespace Systematic
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model shopping_system_configurations {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// Unique system configuration key (case-insensitive, e.g.
  /// 'core.smtp_server').
  config_key String

  /// Configuration value, serialized as text (JSON or plain values).
  config_value String

  /// Documentation of what this config controls.
  description String?

  /// Configuration creation timestamp.
  created_at DateTime @db.Timestamptz

  /// Configuration last modification timestamp.
  updated_at DateTime @db.Timestamptz

  /// Configuration deletion timestamp (soft delete).
  deleted_at DateTime? @db.Timestamptz

  //----
  // RELATIONS
  //----
  @@unique([config_key])
  @@index([created_at])
  @@index([config_value(ops: raw("gin_trgm_ops"))], type: Gin)
}

/// Global business policy and operational settings for the shopping
/// platform: currency, supported regions, tax policy, regulatory flags, etc.
/// Used for deployment-wide logic, onboarding, and migration. Only one row
/// per setting type/key is permitted. No coupling to business actors.
///
/// @namespace Systematic
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model shopping_business_settings {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// Business setting key (e.g., 'currency', 'country', 'tax_region').
  setting_key String

  /// Arbitrary string data for the setting value (could serialize as JSON for
  /// compound).
  setting_value String

  /// Description of this setting.
  description String?

  /// Row creation timestamp.
  created_at DateTime @db.Timestamptz

  /// Row last update timestamp.
  updated_at DateTime @db.Timestamptz

  /// Row deletion time (soft delete).
  deleted_at DateTime? @db.Timestamptz

  //----
  // RELATIONS
  //----
  @@unique([setting_key])
  @@index([created_at])
}

/// Centralized status code/enum definitions for use across the platform
/// (orders, reviews, payments, etc). Enables reference-integrity, decouples
/// code from hardcoded enums, and allows runtime editing of business states.
/// Soft deletable for historical tracking.
///
/// @namespace Systematic
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model shopping_status_enums {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// Domain/entity scope for this status enum (such as 'order', 'review',
  /// 'payment').
  enum_domain String

  /// Exact status code (e.g., 'pending', 'paid', 'failed', case-insensitive).
  status_code String

  /// Human-readable label to display for this status in UIs.
  display_label String

  /// Ordering value for deterministic sequence in dropdowns or reports.
  sort_order Int @db.Integer

  /// Whether this status code is currently in active use (business logic
  /// toggle).
  is_active Boolean

  /// Comment or description for this enum value.
  description String?

  /// Time when the enum was created.
  created_at DateTime @db.Timestamptz

  /// When this row was last updated.
  updated_at DateTime @db.Timestamptz

  /// Soft delete timestamp for enum deprecation.
  deleted_at DateTime? @db.Timestamptz

  //----
  // RELATIONS
  //----
  @@unique([enum_domain, status_code])
  @@index([enum_domain])
  @@index([is_active])
  @@index([display_label(ops: raw("gin_trgm_ops"))], type: Gin)
}

/// Root node definition for each independent category tree or taxonomy used
/// by the platform (e.g., shop main categories, secondary/auxiliary trees
/// for brands, etc). Not tied to actors or transactions. Implements unique
/// category tree code per taxonomy.
///
/// @namespace Systematic
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model shopping_category_trees {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// Unique category tree code for this taxonomy (case-insensitive, e.g.,
  /// 'main', 'brand')
  tree_code String

  /// English/official display name for this category tree.
  tree_name String

  /// Business context for the category tree usage/role.
  description String?

  /// Tree creation timestamp.
  created_at DateTime @db.Timestamptz

  /// Tree update timestamp.
  updated_at DateTime @db.Timestamptz

  /// Soft delete timestamp.
  deleted_at DateTime? @db.Timestamptz

  //----
  // RELATIONS
  //----
  shopping_categories shopping_categories[]

  @@unique([tree_code])
  @@index([created_at])
  @@index([tree_name(ops: raw("gin_trgm_ops"))], type: Gin)
}

/// One row per category node in any registered category tree. Supports
/// multi-level hierarchical structure via optional parent relationship. Used
/// only for classification and system-level grouping – never directly
/// coupled to transactions or business actors. Category code and tree ID
/// must be unique per tree.
///
/// @namespace Systematic
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model shopping_categories {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// Belonged category tree's {@link shopping_category_trees.id} (required).
  category_tree_id String @db.Uuid

  /// Parent category's {@link shopping_categories.id} (nullable for root).
  parent_id String? @db.Uuid

  /// Unique code for this category node, lowercase, unique per tree (e.g.
  /// 'womens_dresses').
  category_code String

  /// Display name for this category node.
  category_name String

  /// Order among siblings for deterministic tree display.
  sort_order Int @db.Integer

  /// Optional category notes or usage documentation.
  description String?

  /// Category creation time.
  created_at DateTime @db.Timestamptz

  /// Category update time.
  updated_at DateTime @db.Timestamptz

  /// Category deletion (soft delete).
  deleted_at DateTime? @db.Timestamptz

  //----
  // RELATIONS
  //----
  categoryTree shopping_category_trees @relation(fields: [category_tree_id], references: [id], onDelete: Cascade)
  parent       shopping_categories?    @relation("recursive", fields: [parent_id], references: [id], onDelete: Cascade)

  recursive                             shopping_categories[]                   @relation("recursive")
  shopping_category_product_assignments shopping_category_product_assignments[]

  @@unique([category_tree_id, category_code])
  @@index([category_tree_id])
  @@index([parent_id])
  @@index([category_name(ops: raw("gin_trgm_ops"))], type: Gin)
}

/// System-wide append-only audit or operational logs. Used for tracking
/// system events, errors, administrative actions, migrations, or audit
/// trails. Not tied to user/business actor context. Full-text search enabled
/// for efficient diagnostics.
///
/// @namespace Systematic
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model shopping_system_logs {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// Timestamp for when the log event was generated.
  event_time DateTime @db.Timestamptz

  /// Severity or log level (e.g., 'info', 'warn', 'error', 'fatal').
  log_level String

  /// Type/category of log event (e.g., 'system_init', 'migration',
  /// 'admin_action').
  event_type String

  /// Origin/source of the event (module, subsystem, service name).
  event_source String

  /// Summary log message.
  message String

  /// Optional event details, stack trace, or contextual metadata (potentially
  /// JSON-encoded).
  details String?

  /// Log row creation time (for durability trace).
  created_at DateTime @db.Timestamptz

  //----
  // RELATIONS
  //----
  @@index([event_time])
  @@index([log_level])
  @@index([event_type])
  @@index([message(ops: raw("gin_trgm_ops"))], type: Gin)
}

schemas.schema-02-actors.prisma:
/// Registered customer accounts. Each customer has unique authentication
/// credentials, personal contact details, address book (via
/// shopping_customer_addresses), and is the principal actor for placing
/// consumer orders, writing reviews, and managing shopping carts. Sessions
/// are managed by shopping_customer_sessions.
///
/// @namespace Actors
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model shopping_customers {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// Customer email for login, uniquely identifies the account. Used for
  /// authentication and transactional notification.
  email String

  /// Password hash (never plain). Used for secure login verification per
  /// industry standards.
  password_hash String

  /// Full display name of the customer for delivery and personalization.
  name String

  /// Primary contact phone for verification and delivery notifications.
  phone String

  /// Indicates if the customer account is active and allowed to log in.
  is_active Boolean

  /// Timestamp for soft-deletion of the account. Used for GDPR/business
  /// retention.
  deleted_at DateTime? @db.Timestamptz

  /// Timestamp at which the customer account was created.
  created_at DateTime @db.Timestamptz

  /// Timestamp for last account data update.
  updated_at DateTime @db.Timestamptz

  //----
  // RELATIONS
  //----
  shopping_customer_sessions                            shopping_customer_sessions[]
  shopping_customer_addresses                           shopping_customer_addresses[]
  shopping_user_emails                                  shopping_user_emails[]
  shopping_password_resets                              shopping_password_resets[]
  shopping_carts                                        shopping_carts?
  shopping_wishlists                                    shopping_wishlists?
  shopping_orders                                       shopping_orders[]
  shopping_refund_requests                              shopping_refund_requests[]
  shopping_refund_status_histories                      shopping_refund_status_histories[]
  shopping_reviews                                      shopping_reviews[]
  shopping_review_abuse_reports                         shopping_review_abuse_reports[]
  shopping_audit_logs                                   shopping_audit_logs[]
  shopping_admin_action_logs                            shopping_admin_action_logs[]
  shopping_admin_suspensions                            shopping_admin_suspensions[]
  shopping_policy_violations_of_reported_by_customer_id shopping_policy_violations[]       @relation("shopping_policy_violations_of_reported_by_customer_id")
  shopping_policy_violations_of_affected_customer_id    shopping_policy_violations[]       @relation("shopping_policy_violations_of_affected_customer_id")
  shopping_appeals                                      shopping_appeals[]

  @@unique([email])
  @@index([phone])
  @@index([name(ops: raw("gin_trgm_ops"))], type: Gin)
}

/// Sessions for logged in customers. Each session records authentication,
/// connection metadata, audit, and supports multiple concurrent logins per
/// customer. Linked to customer via shopping_customers.id.
///
/// @namespace Actors
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model shopping_customer_sessions {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// Belonged customer's {@link shopping_customers.id}.
  shopping_customer_id String @db.Uuid

  /// Client IP address where the session originated.
  ip String

  /// URL on which login or session was established.
  href String

  /// Referring page or context for session creation.
  referrer String

  /// Timestamp for session creation/login event.
  created_at DateTime @db.Timestamptz

  /// Timestamp when the session ended or was revoked (nullable for open
  /// sessions).
  expired_at DateTime? @db.Timestamptz

  //----
  // RELATIONS
  //----
  customer shopping_customers @relation(fields: [shopping_customer_id], references: [id], onDelete: Cascade)

  @@index([shopping_customer_id, created_at])
}

/// Address book for customers. Contains shipping and billing addresses per
/// customer. Each address explicitly belongs to one customer only.
///
/// @namespace Actors
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model shopping_customer_addresses {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// Owning customer's {@link shopping_customers.id}.
  shopping_customer_id String @db.Uuid

  /// First address line (street, apartment no, etc.)
  address_line1 String

  /// Second address line (optional details such as suite, etc).
  address_line2 String?

  /// City or locality for address.
  city String

  /// State, province or administrative district.
  state String

  /// Postal or ZIP code for the address.
  postal_code String

  /// Country name (e.g. South Korea, United States, etc.)
  country String

  /// Marks if this is the primary/default address for customer.
  is_primary Boolean

  /// Contact phone number for recipient at this address.
  phone String

  /// Recipient's display name for delivery purposes.
  recipient_name String

  /// Address record creation timestamp.
  created_at DateTime @db.Timestamptz

  /// Last update timestamp for the address entry.
  updated_at DateTime @db.Timestamptz

  /// Soft deletion timestamp for address records, for compliance/audit.
  deleted_at DateTime? @db.Timestamptz

  //----
  // RELATIONS
  //----
  customer shopping_customers @relation(fields: [shopping_customer_id], references: [id], onDelete: Cascade)

  @@index([shopping_customer_id, is_primary])
  @@index([address_line1(ops: raw("gin_trgm_ops"))], type: Gin)
  @@index([city(ops: raw("gin_trgm_ops"))], type: Gin)
}

/// Registered merchant accounts. Each seller has unique business
/// credentials, authentication, profile, and is the principal actor managing
/// products, fulfillment, and inventory. Sessions are managed via
/// shopping_seller_sessions. Business data is stored in
/// shopping_seller_business_infos. Seller addresses managed via
/// shopping_seller_addresses.
///
/// @namespace Actors
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model shopping_sellers {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// Seller email for login, notifications, and business verification.
  /// Uniquely identifies seller in authentication flows.
  email String

  /// Password hash for seller account authentication.
  password_hash String

  /// Public-facing business/shop name of the seller.
  display_name String

  /// Primary business contact phone for seller.
  contact_phone String

  /// Seller account status (pending, active, suspended, rejected). Used for
  /// onboarding/compliance.
  status String

  /// Timestamp for account soft-deletion (retain for legal and audit).
  deleted_at DateTime? @db.Timestamptz

  /// Stamp for seller account creation and onboarding.
  created_at DateTime @db.Timestamptz

  /// Last update timestamp for seller profile.
  updated_at DateTime @db.Timestamptz

  //----
  // RELATIONS
  //----
  shopping_seller_sessions                            shopping_seller_sessions[]
  shopping_seller_business_infos                      shopping_seller_business_infos?
  shopping_seller_addresses                           shopping_seller_addresses[]
  shopping_user_emails                                shopping_user_emails[]
  shopping_password_resets                            shopping_password_resets[]
  shopping_products                                   shopping_products[]
  shopping_order_lines                                shopping_order_lines[]
  shopping_order_splits                               shopping_order_splits[]
  shopping_order_fulfillments                         shopping_order_fulfillments[]
  shopping_shipments                                  shopping_shipments[]
  shopping_audit_logs                                 shopping_audit_logs[]
  shopping_admin_action_logs                          shopping_admin_action_logs[]
  shopping_admin_suspensions                          shopping_admin_suspensions[]
  shopping_policy_violations_of_reported_by_seller_id shopping_policy_violations[]    @relation("shopping_policy_violations_of_reported_by_seller_id")
  shopping_policy_violations_of_affected_seller_id    shopping_policy_violations[]    @relation("shopping_policy_violations_of_affected_seller_id")
  shopping_appeals                                    shopping_appeals[]

  @@unique([email])
  @@index([display_name(ops: raw("gin_trgm_ops"))], type: Gin)
}

/// Authentication/audit sessions for sellers. Tracks session-specific
/// context for business/operational security, and supports concurrent device
/// logins. Each session belongs to one seller only.
///
/// @namespace Actors
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model shopping_seller_sessions {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// The associated seller's {@link shopping_sellers.id}.
  shopping_seller_id String @db.Uuid

  /// Originating IP address of the logged-in session.
  ip String

  /// Connection URL or endpoint at session start.
  href String

  /// HTTP referrer at login/session init.
  referrer String

  /// Session instantiation timestamp.
  created_at DateTime @db.Timestamptz

  /// When session ended/revoked. Nullable for currently open sessions.
  expired_at DateTime? @db.Timestamptz

  //----
  // RELATIONS
  //----
  seller shopping_sellers @relation(fields: [shopping_seller_id], references: [id], onDelete: Cascade)

  @@index([shopping_seller_id, created_at])
}

/// Legal and business registration/compliance details for sellers. Stores
/// documentation, registration numbers, tax info, and all admin proof-of-KYC
/// for compliance. Strictly 1:1 per seller.
///
/// @namespace Actors
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model shopping_seller_business_infos {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// One-to-one relation: the associated seller's {@link shopping_sellers.id}.
  shopping_seller_id String @db.Uuid

  /// Registered legal entity/business name for tax, KYC, and compliance.
  legal_entity_name String

  /// Business registration/tax number required for platform compliance.
  registration_number String

  /// Official representative's name for legal contacts.
  representative_name String

  /// Customer support phone/email for merchant business.
  support_contact String

  /// Primary bank account for settlement/payment payouts to seller business.
  bank_account_number String

  /// Timestamp for legal/business info submission or most recent update.
  created_at DateTime @db.Timestamptz

  /// Timestamp for last update of business information.
  updated_at DateTime @db.Timestamptz

  //----
  // RELATIONS
  //----
  seller shopping_sellers @relation(fields: [shopping_seller_id], references: [id], onDelete: Cascade)

  @@unique([shopping_seller_id])
}

/// Address book for sellers. Stores origin, business, and return addresses,
/// delivery endpoints and branch pickup points. Each address attached to
/// exactly one seller.
///
/// @namespace Actors
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model shopping_seller_addresses {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// Owning seller's {@link shopping_sellers.id}.
  shopping_seller_id String @db.Uuid

  /// Primary address string (building/street).
  address_line1 String

  /// Detail address (suite/floor, etc).
  address_line2 String?

  /// City/locality.
  city String

  /// Administrative region/province/state.
  state String

  /// ZIP/postal code for this address.
  postal_code String

  /// Country name field.
  country String

  /// True if this entry is for goods returns/refunds (not a shipping origin).
  is_return_address Boolean

  /// Indicates if this is the primary/main address for the shop.
  is_primary Boolean

  /// Local business/contact phone for branch/pickup site.
  phone String

  /// Address entry creation timestamp.
  created_at DateTime @db.Timestamptz

  /// Last update timestamp of address detail.
  updated_at DateTime @db.Timestamptz

  /// Soft-deletion timestamp for address entry, audit/compliance.
  deleted_at DateTime? @db.Timestamptz

  //----
  // RELATIONS
  //----
  seller shopping_sellers @relation(fields: [shopping_seller_id], references: [id], onDelete: Cascade)

  shopping_order_fulfillments shopping_order_fulfillments[]

  @@index([shopping_seller_id, is_primary])
  @@index([address_line1(ops: raw("gin_trgm_ops"))], type: Gin)
  @@index([city(ops: raw("gin_trgm_ops"))], type: Gin)
}

/// Platform administrator accounts. Have system-level permissions to manage
/// users, sellers, escalations and platform settings. MFA and immutable
/// audit logging apply. Not authorized for purchasing/selling.
///
/// @namespace Actors
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model shopping_admins {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// Unique admin email for login and notifications.
  email String

  /// Password hash for authentication.
  password_hash String

  /// Admin real name, used for audit and communications.
  name String

  /// Admin privilege level (super, support, etc). Used for RBAC policy
  /// enforcement.
  role String

  /// Admin account business status (active, suspended, pending, etc).
  status String

  /// Soft deletion timestamp, for audit/compliance. Cannot be physically
  /// deleted while system active.
  deleted_at DateTime? @db.Timestamptz

  /// Account creation timestamp.
  created_at DateTime @db.Timestamptz

  /// Last update timestamp for admin record.
  updated_at DateTime @db.Timestamptz

  //----
  // RELATIONS
  //----
  shopping_admin_sessions                            shopping_admin_sessions[]
  shopping_password_resets                           shopping_password_resets[]
  shopping_refund_approvals                          shopping_refund_approvals[]
  shopping_refund_admin_overrides                    shopping_refund_admin_overrides[]
  shopping_review_moderations                        shopping_review_moderations[]
  shopping_audit_logs                                shopping_audit_logs[]
  shopping_admin_action_logs_of_admin_id             shopping_admin_action_logs[]      @relation("shopping_admin_action_logs_of_admin_id")
  shopping_admin_action_logs_of_affected_admin_id    shopping_admin_action_logs[]      @relation("shopping_admin_action_logs_of_affected_admin_id")
  shopping_admin_suspensions_of_admin_id             shopping_admin_suspensions[]      @relation("shopping_admin_suspensions_of_admin_id")
  shopping_admin_suspensions_of_suspended_admin_id   shopping_admin_suspensions[]      @relation("shopping_admin_suspensions_of_suspended_admin_id")
  shopping_platform_announcements                    shopping_platform_announcements[]
  shopping_policy_violations_of_reported_by_admin_id shopping_policy_violations[]      @relation("shopping_policy_violations_of_reported_by_admin_id")
  shopping_policy_violations_of_affected_admin_id    shopping_policy_violations[]      @relation("shopping_policy_violations_of_affected_admin_id")
  shopping_appeals_of_filed_by_admin_id              shopping_appeals[]                @relation("shopping_appeals_of_filed_by_admin_id")
  shopping_appeals_of_reviewed_by_admin_id           shopping_appeals[]                @relation("shopping_appeals_of_reviewed_by_admin_id")

  @@unique([email])
  @@index([name(ops: raw("gin_trgm_ops"))], type: Gin)
}

/// Record of authentication sessions for admin actors. Used for session
/// security, audit, and two-factor tracking. Each session belongs to one
/// admin.
///
/// @namespace Actors
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model shopping_admin_sessions {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// Associated admin user's {@link shopping_admins.id}.
  shopping_admin_id String @db.Uuid

  /// Login IP address for event.
  ip String

  /// URL on which admin authentication took place.
  href String

  /// Referring or source URL for session start.
  referrer String

  /// Login/session start timestamp.
  created_at DateTime @db.Timestamptz

  /// Timestamp for session end/logout. Nullable if open session.
  expired_at DateTime? @db.Timestamptz

  //----
  // RELATIONS
  //----
  admin shopping_admins @relation(fields: [shopping_admin_id], references: [id], onDelete: Cascade)

  @@index([shopping_admin_id, created_at])
}

/// Stores secondary, unverified, or historical emails for users (both
/// customers and sellers), supporting contact updates, verification flows,
/// and audit/history. A user can have multiple entries but only one primary
/// login email (stored on customers/sellers table).
///
/// @namespace Actors
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model shopping_user_emails {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// Linked customer's {@link shopping_customers.id} if customer email.
  shopping_customer_id String? @db.Uuid

  /// Linked seller's {@link shopping_sellers.id} if seller email.
  shopping_seller_id String? @db.Uuid

  /// Secondary, pending, or historical email address.
  email String

  /// Indicates if this email address has been verified by user action.
  is_verified Boolean

  /// Indicates if this is current primary email for user (must sync to
  /// associated customer/seller table).
  is_primary Boolean

  /// Timestamp when this email entry was created/added.
  created_at DateTime @db.Timestamptz

  /// Most recent update to this email record.
  updated_at DateTime @db.Timestamptz

  /// Soft deletion timestamp (removed from account but retained for audit).
  deleted_at DateTime? @db.Timestamptz

  //----
  // RELATIONS
  //----
  customer shopping_customers? @relation(fields: [shopping_customer_id], references: [id], onDelete: Cascade)
  seller   shopping_sellers?   @relation(fields: [shopping_seller_id], references: [id], onDelete: Cascade)

  @@unique([email])
  @@index([shopping_customer_id])
  @@index([shopping_seller_id])
}

/// Verification and tracking for password reset requests. Supports secure
/// reset links, session tokens, expiration, and audit traceability for
/// customers, sellers, and admins. Associated via at least one FK to actor
/// table. Reset tokens and security details handled at the application
/// service level, not stored here.
///
/// @namespace Actors
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model shopping_password_resets {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// Password reset request linked to customer (nullable for seller/admin
  /// usage).
  shopping_customer_id String? @db.Uuid

  /// Password reset request linked to seller (nullable for customer/admin
  /// usage).
  shopping_seller_id String? @db.Uuid

  /// Password reset request linked to admin (nullable for customer/seller
  /// usage).
  shopping_admin_id String? @db.Uuid

  /// Email used to request password reset, used for lookup and audit.
  request_email String

  /// One-time reset code/token (never plaintext in schema—used for service
  /// token lookup/audit/expiration only).
  reset_code String

  /// Expiration timestamp for the reset code (typically 1 hour).
  expires_at DateTime @db.Timestamptz

  /// If reset code has been used/invalidated, timestamp of consumption event.
  consumed_at DateTime? @db.Timestamptz

  /// Request creation timestamp for trace and audit.
  created_at DateTime @db.Timestamptz

  /// Most recent update to reset request record (for auditing changes, e.g.,
  /// cancelation).
  updated_at DateTime @db.Timestamptz

  //----
  // RELATIONS
  //----
  customer shopping_customers? @relation(fields: [shopping_customer_id], references: [id], onDelete: Cascade)
  seller   shopping_sellers?   @relation(fields: [shopping_seller_id], references: [id], onDelete: Cascade)
  admin    shopping_admins?    @relation(fields: [shopping_admin_id], references: [id], onDelete: Cascade)

  @@unique([reset_code])
  @@index([shopping_customer_id])
  @@index([shopping_seller_id])
  @@index([shopping_admin_id])
  @@index([request_email])
}

schemas.schema-03-catalog.prisma:
/// Core catalog products available in the shopping mall platform. Each
/// product contains general product information (name, description, price,
/// main image, etc.) and is associated with a seller (FK to
/// shopping_sellers), categories, tags, and SKUs. Supports both published
/// (active) and draft/archived status, provides audit and soft delete
/// fields. Subject to category and tag assignments via subsidiary tables.
///
/// @namespace Catalog
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model shopping_products {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// Belonged seller's {@link shopping_sellers.id}.
  shopping_seller_id String @db.Uuid

  /// Unique business code for the product, used for lookup or external
  /// referencing.
  code String

  /// Product display name shown to shoppers. Used for search and catalog
  /// display.
  name String

  /// Long description of the product for customer information and search
  /// indexing.
  description String

  /// URI to the primary display image associated with this product.
  main_image_uri String? @db.VarChar(80000)

  /// Product status (e.g., draft, active, archived, under_review). Used in
  /// workflow.
  status String

  /// Business workflow status (e.g., in_review, approved, rejected).
  business_status String

  /// Creation timestamp for auditing.
  created_at DateTime @db.Timestamptz

  /// Last updated timestamp for auditing.
  updated_at DateTime @db.Timestamptz

  /// Soft-deleted timestamp. If not null, product is archived/not shown to
  /// shoppers.
  deleted_at DateTime? @db.Timestamptz

  //----
  // RELATIONS
  //----
  seller shopping_sellers @relation(fields: [shopping_seller_id], references: [id], onDelete: Cascade)

  shopping_product_snapshots            shopping_product_snapshots[]
  shopping_product_images               shopping_product_images[]
  shopping_skus                         shopping_skus[]
  shopping_product_attributes           shopping_product_attributes[]
  shopping_category_product_assignments shopping_category_product_assignments[]
  shopping_product_tag_assignments      shopping_product_tag_assignments[]
  shopping_review_rating_aggregates     shopping_review_rating_aggregates[]
  shopping_policy_violations            shopping_policy_violations[]

  @@unique([code])
  @@index([shopping_seller_id])
  @@index([status])
  @@index([created_at])
  @@index([name(ops: raw("gin_trgm_ops"))], type: Gin)
  @@index([description(ops: raw("gin_trgm_ops"))], type: Gin)
}

/// Historical snapshots of full product state for audit trail and change
/// history. Captures all product fields and foreign key references as they
/// were at the time of the snapshot. Used to reconstruct prior states,
/// enable moderation, or restore historical product versions. All edits to
/// shopping_products generate a snapshot entry.
///
/// @namespace Catalog
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model shopping_product_snapshots {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// Parent product's {@link shopping_products.id}.
  shopping_product_id String @db.Uuid

  /// Business code at time of snapshot.
  code String

  /// Name at time of snapshot.
  name String

  /// Long description at time of snapshot.
  description String

  /// Primary image at time of snapshot.
  main_image_uri String? @db.VarChar(80000)

  /// Product status at time of snapshot.
  status String

  /// Business workflow status at time of snapshot.
  business_status String

  /// Snapshot creation timestamp.
  created_at DateTime @db.Timestamptz

  //----
  // RELATIONS
  //----
  product shopping_products @relation(fields: [shopping_product_id], references: [id], onDelete: Cascade)

  @@index([shopping_product_id])
  @@index([created_at])
  @@index([name(ops: raw("gin_trgm_ops"))], type: Gin)
  @@index([description(ops: raw("gin_trgm_ops"))], type: Gin)
}

/// Images associated with products for catalog display. Each image is linked
/// to a product and stores a URI reference. Allows multiple images per
/// product (up to 10 per business rules).
///
/// @namespace Catalog
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model shopping_product_images {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// Parent product's {@link shopping_products.id}.
  shopping_product_id String @db.Uuid

  /// URI pointing to an image file (JPEG/PNG, up to 5MB per upload).
  image_uri String @db.VarChar(80000)

  /// Zero-based display order for product images.
  order_index Int? @db.Integer

  /// Upload/creation timestamp.
  created_at DateTime @db.Timestamptz

  //----
  // RELATIONS
  //----
