  const uniqueSellerEmail = typia.random<string & tags.Format<"email">>();
  const sellerRegBody = {
    email: uniqueSellerEmail,
    password: RandomGenerator.alphaNumeric(12),
    display_name: RandomGenerator.name(2),
    contact_phone: RandomGenerator.mobile(),
