import api from "@ORGANIZATION/PROJECT-api";
import type { IShoppingAdmin } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingAdmin";
import type { IShoppingAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingAuthorizationToken";
import type { IShoppingCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingCategory";
import type { IShoppingCategoryTree } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingCategoryTree";

/**
 * Validate that an admin can create a new category in a category tree including
 * all fields and hierarchy rules.
 *
 * 1. Register a new admin (establish authentication)
 * 2. Create a category tree
 * 3. Add a root category (parent_id: null, all fields populated)
 * 4. Add a child category (parent_id set to root category id, all fields
 *    populated)
 * 5. Validate success, relationships, and field integrity
 */
export async function test_api_admin_create_category_in_tree_with_all_fields(
  connection: api.IConnection,
) {
  // Step 1: Register a new admin for authentication
  const adminEmail = `${RandomGenerator.alphaNumeric(8)}@company.com`;
  const adminJoinBody = {
    email: adminEmail,
    password: RandomGenerator.alphaNumeric(12),
    name: RandomGenerator.name(),
    role: RandomGenerator.pick(["super", "operator", "support"]) as string,
    status: "active",
  } satisfies IShoppingAdmin.IJoin;
  const admin: IShoppingAdmin.IAuthorized =
    await api.functional.auth.admin.join(connection, { body: adminJoinBody });
  typia.assert(admin);
  TestValidator.equals(
    "created admin email matches input",
    admin.email,
    adminEmail,
  );
  TestValidator.equals("admin is active", admin.status, "active");

  // Step 2: Create a new category tree
  const treeCode = RandomGenerator.alphaNumeric(10).toLowerCase();
  const treeName = RandomGenerator.paragraph({ sentences: 2 });
  const treeDescription = RandomGenerator.paragraph({ sentences: 4 });
  const treeCreateBody = {
    tree_code: treeCode,
    tree_name: treeName,
    description: treeDescription,
  } satisfies IShoppingCategoryTree.ICreate;
  const catTree: IShoppingCategoryTree =
    await api.functional.shopping.admin.categoryTrees.create(connection, {
      body: treeCreateBody,
    });
  typia.assert(catTree);
  TestValidator.equals(
    "created tree code matches input",
    catTree.tree_code,
    treeCode,
  );
  TestValidator.equals(
    "created tree name matches input",
    catTree.tree_name,
    treeName,
  );
  TestValidator.equals(
    "created tree description matches input",
    catTree.description,
    treeDescription,
  );

  // Step 3: Create a root category (no parent_id, all fields filled)
  const rootCode = RandomGenerator.alphaNumeric(10).toLowerCase();
  const rootName = RandomGenerator.paragraph({ sentences: 2 });
  const rootDescription = RandomGenerator.paragraph({ sentences: 3 });
  const rootSortOrder = typia.random<
    number & tags.Type<"int32"> & tags.Minimum<1> & tags.Maximum<50>
  >();
  const rootCreateBody = {
    category_tree_id: catTree.id,
    category_code: rootCode,
    category_name: rootName,
    parent_id: null,
    sort_order: rootSortOrder,
    description: rootDescription,
  } satisfies IShoppingCategory.ICreate;
  const rootCategory: IShoppingCategory =
    await api.functional.shopping.admin.categoryTrees.categories.create(
      connection,
      {
        treeCode,
        body: rootCreateBody,
      },
    );
  typia.assert(rootCategory);
  TestValidator.equals(
    "root category assigned to correct tree",
    rootCategory.category_tree_id,
    catTree.id,
  );
  TestValidator.equals(
    "root category has null parent_id",
    rootCategory.parent_id,
    null,
  );
  TestValidator.equals(
    "root category code matches input",
    rootCategory.category_code,
    rootCode,
  );
  TestValidator.equals(
    "root category name matches input",
    rootCategory.category_name,
    rootName,
  );
  TestValidator.equals(
    "root category description matches input",
    rootCategory.description,
    rootDescription,
  );
  TestValidator.equals(
    "root category sort_order matches input",
    rootCategory.sort_order,
    rootSortOrder,
  );

  // Step 4: Create child category (set parent_id, all fields)
  const childCode = RandomGenerator.alphaNumeric(10).toLowerCase();
  const childName = RandomGenerator.paragraph({ sentences: 2 });
  const childDescription = RandomGenerator.paragraph({ sentences: 3 });
  const childSortOrder = typia.random<
    number & tags.Type<"int32"> & tags.Minimum<1> & tags.Maximum<50>
  >();
  const childCreateBody = {
    category_tree_id: catTree.id,
    category_code: childCode,
    category_name: childName,
    parent_id: rootCategory.id,
    sort_order: childSortOrder,
    description: childDescription,
  } satisfies IShoppingCategory.ICreate;
  const childCategory: IShoppingCategory =
    await api.functional.shopping.admin.categoryTrees.categories.create(
      connection,
      {
        treeCode,
        body: childCreateBody,
      },
    );
  typia.assert(childCategory);
  TestValidator.equals(
    "child category is in same tree",
    childCategory.category_tree_id,
    catTree.id,
  );
  TestValidator.equals(
    "child category's parent_id matches root",
    childCategory.parent_id,
    rootCategory.id,
  );
  TestValidator.equals(
    "child category code",
    childCategory.category_code,
    childCode,
  );
  TestValidator.equals(
    "child category name",
    childCategory.category_name,
    childName,
  );
  TestValidator.equals(
    "child category description",
    childCategory.description,
    childDescription,
  );
  TestValidator.equals(
    "child category sort_order",
    childCategory.sort_order,
    childSortOrder,
  );

  // Step 5: Attempt to create category with duplicate code and validate error
  await TestValidator.error(
    "duplicate category_code in same tree should fail",
    async () => {
      await api.functional.shopping.admin.categoryTrees.categories.create(
        connection,
        {
          treeCode,
          body: {
            category_tree_id: catTree.id,
            category_code: rootCode, // duplicate code
            category_name: RandomGenerator.paragraph({ sentences: 2 }),
            parent_id: null,
            sort_order: typia.random<
              number & tags.Type<"int32"> & tags.Minimum<51> & tags.Maximum<100>
            >(),
            description: RandomGenerator.paragraph({ sentences: 3 }),
          } satisfies IShoppingCategory.ICreate,
        },
      );
    },
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IShoppingAdmin } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingAdmin";
import type { IShoppingAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingAuthorizationToken";
import type { IShoppingCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingCategory";
import type { IShoppingCategoryTree } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingCategoryTree";

/**
 * Validates admin capability to update a category's details and hierarchy
 * within a category tree.
 *
 * 1. Register a new admin for isolation and authentication
 * 2. Create a category tree
 * 3. Create two categories (catA: as initial root, catB: as another root)
 * 4. Update catB: change name, sort order, and assign catA as its parent
 * 5. Verify all updates reflected, including hierarchy
 * 6. Attempt to create a hierarchical cycle by updating catA's parent to catB and
 *    ensure it fails
 * 7. Attempt to update catB's name to duplicate a sibling's name and ensure it
 *    fails
 * 8. Ensure all successful updates are audit-trail consistent
 */
export async function test_api_admin_update_category_details_and_hierarchy(
  connection: api.IConnection,
) {
  // 1. Admin registration and authentication
  const adminEmail = RandomGenerator.name(1).toLowerCase() + "@shop-admin.com";
  const admin: IShoppingAdmin.IAuthorized =
    await api.functional.auth.admin.join(connection, {
      body: {
        email: adminEmail,
        password: RandomGenerator.alphaNumeric(12),
        name: RandomGenerator.name(),
        role: "superadmin",
        status: "active",
      } satisfies IShoppingAdmin.IJoin,
    });
  typia.assert(admin);
  // admin.token is automatically used by the SDK

  // 2. Create one category tree
  const catTreeCode = RandomGenerator.alphaNumeric(10).toLowerCase();
  const catTree: IShoppingCategoryTree =
    await api.functional.shopping.admin.categoryTrees.create(connection, {
      body: {
        tree_code: catTreeCode,
        tree_name: RandomGenerator.paragraph({ sentences: 2 }),
        description: RandomGenerator.paragraph({ sentences: 8 }),
      } satisfies IShoppingCategoryTree.ICreate,
    });
  typia.assert(catTree);
  TestValidator.equals("tree_code matches", catTree.tree_code, catTreeCode);

  // 3. Create 2 root categories
  const catA_code = RandomGenerator.alphaNumeric(8).toLowerCase();
  const catB_code = RandomGenerator.alphaNumeric(8).toLowerCase();
  const catA: IShoppingCategory =
    await api.functional.shopping.admin.categoryTrees.categories.create(
      connection,
      {
        treeCode: catTree.tree_code,
        body: {
          category_tree_id: catTree.id,
          category_code: catA_code,
          category_name: RandomGenerator.name(2),
          sort_order: 1,
          parent_id: null,
          description: RandomGenerator.paragraph({ sentences: 6 }),
        } satisfies IShoppingCategory.ICreate,
      },
    );
  typia.assert(catA);
  const catB: IShoppingCategory =
    await api.functional.shopping.admin.categoryTrees.categories.create(
      connection,
      {
        treeCode: catTree.tree_code,
        body: {
          category_tree_id: catTree.id,
          category_code: catB_code,
          category_name: RandomGenerator.name(2),
          sort_order: 2,
          parent_id: null,
          description: RandomGenerator.paragraph({ sentences: 5 }),
        } satisfies IShoppingCategory.ICreate,
      },
    );
  typia.assert(catB);

  // 4. Update catB: change name, sort_order, and assign catA as parent
  const newNameB = RandomGenerator.paragraph({ sentences: 2 });
  const newDescB = RandomGenerator.paragraph({ sentences: 4 });
  const newSortB = 10;
  const updatedCatB: IShoppingCategory =
    await api.functional.shopping.admin.categoryTrees.categories.update(
      connection,
      {
        treeCode: catTree.tree_code,
        categoryCode: catB.category_code,
        body: {
          category_name: newNameB,
          sort_order: newSortB,
          description: newDescB,
          parent_id: catA.id,
        } satisfies IShoppingCategory.IUpdate,
      },
    );
  typia.assert(updatedCatB);
  TestValidator.equals(
    "category_name updated",
    updatedCatB.category_name,
    newNameB,
  );
  TestValidator.equals("sort_order updated", updatedCatB.sort_order, newSortB);
  TestValidator.equals("parent_id updated", updatedCatB.parent_id, catA.id);
  TestValidator.equals(
    "description updated",
    updatedCatB.description,
    newDescB,
  );
  TestValidator.equals(
    "category_tree_id stays the same",
    updatedCatB.category_tree_id,
    catTree.id,
  );

  // 5. Ensure audit trail consistency (updated_at is greater than created_at)
  TestValidator.predicate(
    "updated_at is after created_at",
    new Date(updatedCatB.updated_at).getTime() >=
      new Date(updatedCatB.created_at).getTime(),
  );

  // 6. Attempt to create cycle: set catA's parent to catB (should fail)
  await TestValidator.error(
    "category hierarchy cycle is prevented",
    async () => {
      await api.functional.shopping.admin.categoryTrees.categories.update(
        connection,
        {
          treeCode: catTree.tree_code,
          categoryCode: catA.category_code,
          body: {
            category_name: catA.category_name,
            sort_order: catA.sort_order,
            parent_id: catB.id,
          } satisfies IShoppingCategory.IUpdate,
        },
      );
    },
  );

  // 7. Attempt to update catB's name to duplicate catA's name under same parent (should fail)
  await TestValidator.error(
    "category_name uniqueness among siblings is enforced",
    async () => {
      await api.functional.shopping.admin.categoryTrees.categories.update(
        connection,
        {
          treeCode: catTree.tree_code,
          categoryCode: catB.category_code,
          body: {
            category_name: catA.category_name,
            sort_order: catB.sort_order,
            parent_id: catA.id,
          } satisfies IShoppingCategory.IUpdate,
        },
      );
    },
  );
}

