import type { IShoppingRefundRequestItem } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingRefundRequestItem";
import type { IShoppingRefundStatusHistory } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingRefundStatusHistory";
import type { IShoppingSeller } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingSeller";
import type { IShoppingSku } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingSku";

/**
 * Test that a customer can successfully soft-delete their own refund, return,
 * or cancellation request, verifying that the deleted_at field is updated,
 * subsequent retrieval is blocked, and audit/deletion events are properly
 * logged. Confirm the refund request is not in a locked or reviewed status at
 * deletion time.
 *
 * 1. Register a new customer and authenticate.
 * 2. Place a new order as the customer.
 * 3. Submit a new refund request (type 'refund') for an order line from the just
 *    created order.
 * 4. Ensure the refund request status is deletable (e.g., 'pending').
 * 5. Perform the erase (soft-delete) operation.
 * 6. Confirm no errors occur; in a real system, you would check that deleted_at is
 *    updated and status_histories reflect the deletion. If no GET endpoint
 *    exists for the refund after deletion, this is not validated in code.
 */
export async function test_api_customer_refund_request_erase_success(
  connection: api.IConnection,
) {
  // 1. Register a new customer and authenticate
  const customerEmail = typia.random<string & tags.Format<"email">>();
  const customer = await api.functional.auth.customer.join(connection, {
    body: {
      email: customerEmail,
      password: RandomGenerator.alphaNumeric(12),
      name: RandomGenerator.name(),
      phone: RandomGenerator.mobile(),
      href: "https://www.autobe-test.com/join",
      referrer: "https://www.autobe-test.com/landing",
      ip: "127.0.0.1",
    } satisfies IShoppingCustomer.ICreate,
  });
  typia.assert(customer);

  // 2. Place a new shopping order
  const orderLineSkuId = typia.random<string & tags.Format<"uuid">>();
  const orderLineQuantity = 1;
  const unitPrice = 10000;
  const orderBody = {
    total_price: unitPrice * orderLineQuantity,
    order_lines: [
      {
        shopping_sku_id: orderLineSkuId,
        quantity: orderLineQuantity,
        unit_price: unitPrice,
      },
    ] satisfies IShoppingOrderLine.ICreate[],
    shipping_addresses: [
      {
        type: "shipping",
        recipient_name: customer.name,
        recipient_phone: customer.phone,
        zip_code: "04524",
        base_address: "1 Eulji-ro, Jung-gu",
        detail_address: "5th Floor, Test Plaza",
        city: "Seoul",
        state_province: "Seoul",
        country: "South Korea",
      },
    ] satisfies IShoppingOrderAddress.ICreate[],
    payment_method: "card",
  } satisfies IShoppingOrder.ICreate;
  const order = await api.functional.shopping.customer.orders.create(
    connection,
    {
      body: orderBody,
    },
  );
  typia.assert(order);
  TestValidator.predicate(
    "order created with single order line",
    order.order_lines.length === 1,
  );

  // 3. Create a refund request for the order and its order line
  const refundRequestType: "refund" | "return" | "cancellation" = "refund";
  const refundReason = RandomGenerator.paragraph({ sentences: 2 });
  const refundRequestItem = {
    shopping_order_id: order.id,
    shopping_order_line_id: order.order_lines[0].id,
    quantity: order.order_lines[0].quantity,
  } satisfies IShoppingRefundRequestItem.ICreate;
  const refundReqBody = {
    shopping_order_id: order.id,
    request_type: refundRequestType,
    business_reason: refundReason,
    items: [refundRequestItem],
  } satisfies IShoppingRefundRequest.ICreate;
  const refundRequest = await api.functional.shopping.customer.refunds.create(
    connection,
    { body: refundReqBody },
  );
  typia.assert(refundRequest);
  TestValidator.equals(
    "refund request status must be pending",
    refundRequest.status,
    "pending",
  ); // Assumption: new refund is in 'pending' status

  // 4. Erase (soft-delete) the refund request
  await api.functional.shopping.customer.refunds.erase(connection, {
    refundRequestId: refundRequest.id,
  });

  // 5. Since no GET endpoint for the deleted refund, we can't directly validate deleted_at or status_histories here
  // (If such endpoint existed: fetch refundRequest again and assert deleted_at is now non-null)
  // Success is determined by lack of error and successful flow up to this point
  TestValidator.predicate(
    "refund request erase (soft-delete) succeeded without error",
    true,
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IShoppingAttributeDimension } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingAttributeDimension";
import type { IShoppingAttributeValue } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingAttributeValue";
import type { IShoppingAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingAuthorizationToken";
import type { IShoppingCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingCategory";
import type { IShoppingProduct } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingProduct";
import type { IShoppingProductAttribute } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingProductAttribute";
import type { IShoppingProductImage } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingProductImage";
import type { IShoppingSeller } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingSeller";
import type { IShoppingSellerAddress } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingSellerAddress";
import type { IShoppingSku } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingSku";
import type { IShoppingSkuImage } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingSkuImage";
import type { IShoppingSkuVariant } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingSkuVariant";
import type { IShoppingTag } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingTag";

/**
 * Validates seller address soft delete functionality with full authorization
 * and business edge case coverage.
 *
 * This scenario covers:
 *
 * 1. SellerA successfully registering and creating an address
 * 2. SellerA soft-deleting (erase) their address, expecting deleted_at to be set
 * 3. Attempting to delete the address again should not physically remove it
 *    (should stay soft-deleted)
 * 4. SellerB failing to erase SellerA's address (should get authorization error)
 * 5. If seller’s only primary/return address, deletion should fail with a business
 *    error
 */
export async function test_api_seller_address_soft_delete_with_authorization(
  connection: api.IConnection,
) {
  // 1. Register SellerA and authenticate
  const emailA = typia.random<string & tags.Format<"email">>();
  const sellerA: IShoppingSeller.IAuthorized =
    await api.functional.auth.seller.join(connection, {
      body: {
        email: emailA,
        password: "passwordA123!",
        display_name: RandomGenerator.name(),
        contact_phone: RandomGenerator.mobile(),
        status: "pending",
      } satisfies IShoppingSeller.IJoin,
    });
  typia.assert(sellerA);

  // 2. SellerA creates address
  const addressInfoA = {
    address_line1: RandomGenerator.paragraph({ sentences: 1 }),
    address_line2: RandomGenerator.paragraph({ sentences: 1 }),
    city: RandomGenerator.name(1),
    state: RandomGenerator.name(1),
    postal_code: RandomGenerator.alphaNumeric(8),
    country: "South Korea",
    is_primary: true,
    is_return_address: true,
    phone: RandomGenerator.mobile(),
    recipient_name: RandomGenerator.name(1),
  } satisfies IShoppingSellerAddress.ICreate;
  const addressA: IShoppingSellerAddress =
    await api.functional.shopping.seller.sellers.addresses.create(connection, {
      sellerId: sellerA.id,
      body: addressInfoA,
    });
  typia.assert(addressA);
  TestValidator.equals(
    "created address - is not deleted",
    addressA.deleted_at,
    null,
  );

  // 3. SellerA soft deletes address
  const erased: IShoppingSellerAddress =
    await api.functional.shopping.seller.sellers.addresses.erase(connection, {
      sellerId: sellerA.id,
      addressId: addressA.id,
    });
  typia.assert(erased);
  TestValidator.predicate(
    "deleted_at is set after soft delete",
    erased.deleted_at !== null && erased.deleted_at !== undefined,
  );

  // 4. Attempt to soft delete again: should still be present (deleted_at remains set)
  const erasedAgain: IShoppingSellerAddress =
    await api.functional.shopping.seller.sellers.addresses.erase(connection, {
      sellerId: sellerA.id,
      addressId: addressA.id,
    });
  typia.assert(erasedAgain);
  TestValidator.equals(
    "repeated erase does not physically remove address",
    erasedAgain.deleted_at !== null && erasedAgain.deleted_at !== undefined,
    true,
  );

  // 5. Register SellerB
  const emailB = typia.random<string & tags.Format<"email">>();
  const sellerB: IShoppingSeller.IAuthorized =
    await api.functional.auth.seller.join(connection, {
      body: {
        email: emailB,
        password: "passwordB123!",
        display_name: RandomGenerator.name(),
        contact_phone: RandomGenerator.mobile(),
        status: "pending",
      } satisfies IShoppingSeller.IJoin,
    });
  typia.assert(sellerB);

  // 6. SellerB tries to erase SellerA's address (should be forbidden)
  await TestValidator.error(
    "authorization error for deleting another seller's address",
    async () => {
      await api.functional.shopping.seller.sellers.addresses.erase(connection, {
        sellerId: sellerB.id,
        addressId: addressA.id,
      });
    },
  );

  // 7. Attempt to delete only primary/return address for SellerB (should fail)
  const addressInfoB = {
    address_line1: RandomGenerator.paragraph({ sentences: 1 }),
    address_line2: RandomGenerator.paragraph({ sentences: 1 }),
    city: RandomGenerator.name(1),
    state: RandomGenerator.name(1),
    postal_code: RandomGenerator.alphaNumeric(8),
    country: "South Korea",
    is_primary: true,
    is_return_address: true,
    phone: RandomGenerator.mobile(),
    recipient_name: RandomGenerator.name(1),
  } satisfies IShoppingSellerAddress.ICreate;
  const addressB: IShoppingSellerAddress =
    await api.functional.shopping.seller.sellers.addresses.create(connection, {
      sellerId: sellerB.id,
      body: addressInfoB,
    });
  typia.assert(addressB);
  await TestValidator.error(
    "cannot delete only primary/return address (business rule)",
    async () => {
      await api.functional.shopping.seller.sellers.addresses.erase(connection, {
        sellerId: sellerB.id,
        addressId: addressB.id,
      });
    },
  );
}

