  // 4. Customer places order
  const address = {
    type: "shipping",
    recipient_name: RandomGenerator.name(),
    recipient_phone: RandomGenerator.mobile(),
    zip_code: "12345",
    base_address: RandomGenerator.paragraph({ sentences: 3 }),
    detail_address: null,
    city: "Metropolis",
    state_province: "Seoul",
    country: "South Korea",
