import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IShoppingAdmin } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingAdmin";
import type { IShoppingAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingAuthorizationToken";

/**
 * Validates successful registration of a new admin account for the shopping
 * mall backend.
 *
 * This test targets the /auth/admin/join endpoint, ensuring that a new admin
 * can join the platform with a unique business email, secure password, real
 * audit-compliant name, specifically assigned role, and default status
 * (typically 'active').
 *
 * Test Steps:
 *
 * 1. Generate unique random values for all required fields:
 *
 *    - Unique business email
 *    - Complex password (8-128 chars)
 *    - Real name (1-100 chars)
 *    - Role (2-32 chars, allowed values)
 *    - Status ('active', compliant)
 * 2. Register the new admin.
 * 3. Inspect the result:
 *
 *    - Verify that the response shape matches IShoppingAdmin.IAuthorized
 *    - Confirm tokens are present and of proper format
 *    - Inspect audit-related fields and role/status correctness
 * 4. Attempt to register again with the same email, expecting error due to
 *    uniqueness restriction.
 *
 * Returns nothing if all validations pass.
 */
export async function test_api_admin_registration_success(
  connection: api.IConnection,
) {
  // 1. Prepare unique, policy-compliant admin registration data
  const uniqueEmail = RandomGenerator.alphabets(8) + "@company-admin.com";
  const strongPassword = RandomGenerator.alphaNumeric(16) + "!Aa1"; // ensure complexity
  const adminName = RandomGenerator.name();
  const allowedRoles = ["super", "support", "compliance", "operator"] as const;
  const role = RandomGenerator.pick(allowedRoles);
  const allowedStatuses = ["active", "pending", "suspended", "locked"] as const;
  const status = "active"; // prefer default valid status

  const registrationBody = {
    email: uniqueEmail as string & tags.Format<"email">,
    password: strongPassword as string &
      tags.MinLength<8> &
      tags.MaxLength<128>,
    name: adminName as string & tags.MinLength<1> & tags.MaxLength<100>,
    role: role as string & tags.MinLength<2> & tags.MaxLength<32>,
    status: status as string & tags.MinLength<3> & tags.MaxLength<20>,
  } satisfies IShoppingAdmin.IJoin;

  // 2. Register new admin
  const output = await api.functional.auth.admin.join(connection, {
    body: registrationBody,
  });
  typia.assert<typeof output>(output);

  // 3. Validate output structure/content
  TestValidator.equals(
    "registered admin email matches",
    output.email,
    registrationBody.email,
  );
  TestValidator.equals(
    "registered admin name matches",
    output.name,
    registrationBody.name,
  );
  TestValidator.equals(
    "admin role matches",
    output.role,
    registrationBody.role,
  );
  TestValidator.equals("admin status is active", output.status, "active");

  // Validate audit fields presence and formats
  TestValidator.predicate("created_at is ISO", /T.*Z$/.test(output.created_at));
  TestValidator.predicate("updated_at is ISO", /T.*Z$/.test(output.updated_at));
  TestValidator.predicate("token exists", typeof output.token === "object");
  typia.assert<IShoppingAuthorizationToken>(output.token);

  // 4. Ensure duplicate registration with same email is rejected
  await TestValidator.error("duplicate email registration fails", async () => {
    await api.functional.auth.admin.join(connection, {
      body: registrationBody,
    });
  });
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IShoppingAdmin } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingAdmin";
import type { IShoppingAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingAuthorizationToken";

/**
 * Validate the login functionality for an existing admin account.
 *
 * This test verifies that after registering a new admin via /auth/admin/join, a
 * login attempt using the correct email and password yields a valid
 * IShoppingAdmin.IAuthorized response envelope (including JWT access/refresh
 * tokens), and that authentication fails for invalid credentials and when
 * status is not 'active'.
 *
 * Steps:
 *
 * 1. Register a random admin (with status = 'active')
 * 2. Login with correct email/password; validate tokens and session fields
 * 3. Login with wrong password; expect error
 * 4. Register suspended admin; login attempt fails
 */
export async function test_api_admin_login_existing(
  connection: api.IConnection,
) {
  // Step 1: Register a random admin (status active)
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const adminPassword = RandomGenerator.alphaNumeric(16);
  const adminData = {
    email: adminEmail,
    password: adminPassword satisfies string as string,
    name: RandomGenerator.name(),
    role: RandomGenerator.pick(["super", "support", "operator"] as const),
    status: "active",
  } satisfies IShoppingAdmin.IJoin;
  const admin: IShoppingAdmin.IAuthorized =
    await api.functional.auth.admin.join(connection, { body: adminData });
  typia.assert(admin);
  TestValidator.equals("admin email matches", admin.email, adminEmail);
  TestValidator.equals("admin status is active", admin.status, "active");
  TestValidator.equals("authorized structure has token", !!admin.token, true);
  typia.assert<IShoppingAuthorizationToken>(admin.token);

  // Step 2: Successful login with correct credentials
  const loginBody = {
    email: adminEmail,
    password: adminPassword,
    href: "https://admin.example.com/login",
    referrer: "https://admin.example.com/",
  } satisfies IShoppingAdmin.ILogin;
  const loginResult: IShoppingAdmin.IAuthorized =
    await api.functional.auth.admin.login(connection, { body: loginBody });
  typia.assert(loginResult);
  TestValidator.equals("login email matches", loginResult.email, adminEmail);
  typia.assert<IShoppingAuthorizationToken>(loginResult.token);
  TestValidator.notEquals(
    "new token after login",
    admin.token.access,
    loginResult.token.access,
  );

  // Step 3: Login with wrong password (should fail)
  await TestValidator.error("login fails with incorrect password", async () => {
    await api.functional.auth.admin.login(connection, {
      body: {
        ...loginBody,
        password: adminPassword + "X",
      } satisfies IShoppingAdmin.ILogin,
    });
  });

  // Step 4: Register new admin (non-active), then login fails
  const suspendedEmail = typia.random<string & tags.Format<"email">>();
  const suspendedPassword = RandomGenerator.alphaNumeric(14);
  const suspendedAdminData = {
    email: suspendedEmail,
    password: suspendedPassword satisfies string as string,
    name: RandomGenerator.name(),
    role: RandomGenerator.pick(["super", "operator", "support"] as const),
    status: "suspended",
  } satisfies IShoppingAdmin.IJoin;
  const suspendedAdmin: IShoppingAdmin.IAuthorized =
    await api.functional.auth.admin.join(connection, {
      body: suspendedAdminData,
    });
  typia.assert(suspendedAdmin);
  TestValidator.equals(
    "suspended admin email matches",
    suspendedAdmin.email,
    suspendedEmail,
  );
  TestValidator.equals(
    "suspended admin status",
    suspendedAdmin.status,
    "suspended",
  );
  await TestValidator.error("login fails for suspended admin", async () => {
    await api.functional.auth.admin.login(connection, {
      body: {
        email: suspendedEmail,
        password: suspendedPassword,
        href: "https://admin.example.com/login",
        referrer: "https://admin.example.com/",
      } satisfies IShoppingAdmin.ILogin,
    });
  });
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IShoppingAdmin } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingAdmin";
import type { IShoppingAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingAuthorizationToken";
import type { IShoppingCustomer } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingCustomer";

/**
 * Validate permanent deletion of a customer account by admin.
 *
 * This test covers the lifecycle: admin creation and authentication, customer
 * creation, admin-initiated deletion, and post-deletion checks.
 *
 * 1. Register a new admin account for authentication.
 * 2. Authenticate as the new admin (implicit in /auth/admin/join response).
 * 3. Create a new customer account with randomized credentials.
 * 4. As the admin, permanently delete the newly created customer by customerId.
 * 5. Attempt to delete again (should error: already deleted or non-existent).
 * 6. Attempt to authenticate as the deleted customer (should error:
 *    forbidden/login fails).
 * 7. (Conceptually) Confirm that all associated data for the deleted customer is
 *    handled as per compliance - considered passed if no errors and customer
 *    cannot be recovered.
 */
export async function test_api_customer_account_permanent_removal_by_admin(
  connection: api.IConnection,
) {
  // 1. Admin registration
  const adminEmail = RandomGenerator.name(1) + "@admin-autobe.com";
  const admin: IShoppingAdmin.IAuthorized =
    await api.functional.auth.admin.join(connection, {
      body: {
        email: adminEmail,
        password: RandomGenerator.alphaNumeric(16),
        name: RandomGenerator.name(2),
        role: "super",
        status: "active",
      } satisfies IShoppingAdmin.IJoin,
    });
  typia.assert(admin);
  TestValidator.predicate("admin is active", admin.status === "active");

  // 2. Customer registration
  const customerEmail = RandomGenerator.name(1) + "@customer-autobe.com";
  const customerPassword = RandomGenerator.alphaNumeric(16);
  const customer: IShoppingCustomer.IAuthorized =
    await api.functional.auth.customer.join(connection, {
      body: {
        email: customerEmail,
        password: customerPassword,
        name: RandomGenerator.name(2),
        phone: RandomGenerator.mobile(),
        href: "https://e2e.local/join/customer", // plausible href for session context
        referrer: "https://e2e.local/landing",
        ip: null,
      } satisfies IShoppingCustomer.ICreate,
    });
  typia.assert(customer);
  TestValidator.equals("customer role is correct", customer.role, "customer");

  // 3. Admin deletes the customer
  await api.functional.shopping.admin.customers.erase(connection, {
    customerId: customer.id,
  });

  // 4. Repeat: Attempt to delete again (should error, e.g. already deleted/nonexistent)
  await TestValidator.error(
    "deleting already deleted customer should error",
    async () => {
      await api.functional.shopping.admin.customers.erase(connection, {
        customerId: customer.id,
      });
    },
  );

  // 5. Attempt authentication as deleted customer (should fail)
  await TestValidator.error(
    "deleted customer cannot re-authenticate; login fails",
    async () => {
      // Join API is the only available auth path; so try join with same credentials (should reject duplicate email),
      // or, if login endpoint was available, would attempt login (which should also fail as user is deleted).
      await api.functional.auth.customer.join(connection, {
        body: {
          email: customerEmail,
          password: customerPassword,
          name: RandomGenerator.name(2),
          phone: RandomGenerator.mobile(),
          href: "https://e2e.local/join/customer", // plausible href for session context
          referrer: "https://e2e.local/landing",
          ip: null,
        } satisfies IShoppingCustomer.ICreate,
      });
    },
  );
}

