import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IShoppingAdmin } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingAdmin";
import type { IShoppingAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingAuthorizationToken";

/**
 * Permanently deletes a platform administrator account, enforcing all
 * compliance constraints.
 *
 * 1. Register a new admin via /auth/admin/join, using randomized but valid
 *    credentials
 * 2. Log in as the new admin using /auth/admin/login, verifying authentication
 * 3. As a different (super) admin, permanently delete the target admin via
 *    /shopping/admin/admins/:adminId
 * 4. Attempt to log in using the deleted admin credentials (should fail)
 * 5. Attempt self-deletion: After login, try deleting own account (should fail)
 * 6. Attempt to delete the last remaining admin (should fail)
 * 7. Verify deletion logic: ensure privileges are revoked, access is blocked, and
 *    no accidental soft deletion occurs
 */
export async function test_api_admin_permanent_removal_of_platform_admin_account(
  connection: api.IConnection,
) {
  // Step 1: Register a new admin account
  const testEmail = RandomGenerator.alphaNumeric(12) + "@testdomain.com";
  const testPassword = RandomGenerator.alphaNumeric(16) + "!Qq1";
  const testName = RandomGenerator.name(2);
  const testRole = "super";
  const testStatus = "active";
  const newAdmin: IShoppingAdmin.IAuthorized =
    await api.functional.auth.admin.join(connection, {
      body: {
        email: testEmail,
        password: testPassword satisfies string as string,
        name: testName,
        role: testRole,
        status: testStatus,
      } satisfies IShoppingAdmin.IJoin,
    });
  typia.assert(newAdmin);

  // Step 2: Log in as the newly registered admin
  const loginOutput: IShoppingAdmin.IAuthorized =
    await api.functional.auth.admin.login(connection, {
      body: {
        email: testEmail,
        password: testPassword,
        href: "https://admin-portal.test/login",
        referrer: "https://admin-portal.test/",
      } satisfies IShoppingAdmin.ILogin,
    });
  typia.assert(loginOutput);
  TestValidator.equals(
    "admin.id should match login output id",
    loginOutput.id,
    newAdmin.id,
  );

  // Step 3: Register a second admin (acts as super-admin to perform deletion)
  const superEmail = RandomGenerator.alphaNumeric(12) + "@admincore.io";
  const superPassword = RandomGenerator.alphaNumeric(16) + "!Zz2";
  const superAdmin: IShoppingAdmin.IAuthorized =
    await api.functional.auth.admin.join(connection, {
      body: {
        email: superEmail,
        password: superPassword satisfies string as string,
        name: RandomGenerator.name(2),
        role: "super",
        status: "active",
      } satisfies IShoppingAdmin.IJoin,
    });
  typia.assert(superAdmin);

  // Step 4: Super-admin logs in to perform deletion
  await api.functional.auth.admin.login(connection, {
    body: {
      email: superEmail,
      password: superPassword,
      href: "https://admin-portal.test/login",
      referrer: "https://admin-portal.test/",
    } satisfies IShoppingAdmin.ILogin,
  });

  // Step 5: Super-admin deletes the first admin
  await api.functional.shopping.admin.admins.erase(connection, {
    adminId: newAdmin.id,
  });

  // Step 6: Confirm deleted admin cannot log in
  await TestValidator.error("deleted admin login should fail", async () => {
    await api.functional.auth.admin.login(connection, {
      body: {
        email: testEmail,
        password: testPassword,
        href: "https://admin-portal.test/login",
        referrer: "https://admin-portal.test/",
      } satisfies IShoppingAdmin.ILogin,
    });
  });

  // Step 7: Attempt self-deletion (should fail)
  // Super-admin logs in again for fresh session
  await api.functional.auth.admin.login(connection, {
    body: {
      email: superEmail,
      password: superPassword,
      href: "https://admin-portal.test/login",
      referrer: "https://admin-portal.test/",
    } satisfies IShoppingAdmin.ILogin,
  });
  await TestValidator.error(
    "self-deletion of admin must be prohibited",
    async () => {
      await api.functional.shopping.admin.admins.erase(connection, {
        adminId: superAdmin.id,
      });
    },
  );

  // Step 8: Register a single (only) admin and attempt to delete (should fail)
  const loneEmail = RandomGenerator.alphaNumeric(10) + "@lonely.com";
  const lonePassword = RandomGenerator.alphaNumeric(16) + "!Xx3";
  const loneAdmin: IShoppingAdmin.IAuthorized =
    await api.functional.auth.admin.join(connection, {
      body: {
        email: loneEmail,
        password: lonePassword satisfies string as string,
        name: RandomGenerator.name(2),
        role: "super",
        status: "active",
      } satisfies IShoppingAdmin.IJoin,
    });
  typia.assert(loneAdmin);
  // log in as only admin
  await api.functional.auth.admin.login(connection, {
    body: {
      email: loneEmail,
      password: lonePassword,
      href: "https://onlyadmin.test/login",
      referrer: "https://onlyadmin.test/",
    } satisfies IShoppingAdmin.ILogin,
  });
  await TestValidator.error(
    "prohibit deletion of last/only admin account",
    async () => {
      await api.functional.shopping.admin.admins.erase(connection, {
        adminId: loneAdmin.id,
      });
    },
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IPageIShoppingAdminSession } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIShoppingAdminSession";
import type { IShoppingAdmin } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingAdmin";
import type { IShoppingAdminSession } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingAdminSession";
import type { IShoppingAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingAuthorizationToken";

/**
 * Test secure, audit-compliant admin session retrieval
 *
 * 1. Register an admin with a unique business email, secure password, RBAC role,
 *    and "active" status
 * 2. Login as the new admin to generate session record, save login context (href,
 *    referrer, IP)
 * 3. Fetch session histories using filtering (status, IP, dates), ordering,
 *    pagination; verify results/scoping
 * 4. Check unauthorized access is blocked
 */
export async function test_api_admin_fetch_admin_session_history_with_security_compliance(
  connection: api.IConnection,
) {
  // 1. Register a new admin
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const adminPassword = RandomGenerator.alphaNumeric(16) + "1!Aa";
  const adminName = RandomGenerator.name();
  const adminRole = "super"; // RBAC example
  const adminStatus = "active";
  const joinBody = {
    email: adminEmail,
    password: adminPassword,
    name: adminName,
    role: adminRole,
    status: adminStatus,
  } satisfies IShoppingAdmin.IJoin;
  const admin = await api.functional.auth.admin.join(connection, {
    body: joinBody,
  });
  typia.assert(admin);
  TestValidator.equals("admin email matches", admin.email, adminEmail);
  TestValidator.equals("admin role matches", admin.role, adminRole);
  TestValidator.equals("admin status matches", admin.status, adminStatus);

  // 2. Login as admin to establish session
  const adminHref = "https://admin.shoppingplatform.test/dashboard";
  const adminReferrer = "https://admin.shoppingplatform.test/login";
  // Deliberately supply a random IPv4 for traceability
  const adminIp = typia.random<string & tags.Format<"ipv4">>();
  const loginBody = {
    email: adminEmail,
    password: adminPassword,
    ip: adminIp,
    href: adminHref,
    referrer: adminReferrer,
  } satisfies IShoppingAdmin.ILogin;
  const authorized = await api.functional.auth.admin.login(connection, {
    body: loginBody,
  });
  typia.assert(authorized);
  TestValidator.equals(
    "authorized id matches joined id",
    authorized.id,
    admin.id,
  );

  // 3. Query session list (active) for this admin
  const nowIso = new Date().toISOString();
  const reqBody: IShoppingAdminSession.IRequest = {
    status: "active",
    ip: adminIp,
    login_time_from: authorized.created_at, // after creation
    login_time_to: nowIso,
    order_by: "created_at",
    order_direction: "desc",
    page: 1 as number & tags.Type<"int32"> & tags.Default<1> & tags.Minimum<1>,
    limit: 10 as number &
      tags.Type<"int32"> &
      tags.Default<20> &
      tags.Minimum<1> &
      tags.Maximum<100>,
  };
  const sessionsPage =
    await api.functional.shopping.admin.admins.sessions.index(connection, {
      adminId: admin.id,
      body: reqBody,
    });
  typia.assert(sessionsPage);
  // Pagination sanity
  TestValidator.equals(
    "pagination current page",
    sessionsPage.pagination.current,
    reqBody.page,
  );
  TestValidator.equals(
    "pagination limit",
    sessionsPage.pagination.limit,
    reqBody.limit,
  );
  // Check each session's metadata
  for (const session of sessionsPage.data) {
    typia.assert(session);
    TestValidator.equals(
      "session links correct admin",
      session.shopping_admin_id,
      admin.id,
    );
    TestValidator.equals("session origin IP", session.ip, adminIp);
    TestValidator.predicate(
      "session login after creation_from",
      new Date(session.created_at) >= new Date(authorized.created_at),
    );
    if (session.expired_at !== null && session.expired_at !== undefined) {
      TestValidator.predicate(
        "expired session expired_at after created_at",
        new Date(session.expired_at) >= new Date(session.created_at),
      );
    }
    // No sensitive auth fields exposed
    TestValidator.predicate(
      "no tokens in session summary",
      !("token" in session),
    );
  }

  // 4. Assert session endpoint is protected: try with unauthenticated connection (should fail)
  const unauthConn: api.IConnection = { ...connection, headers: {} };
  await TestValidator.error(
    "session endpoint blocks unauthenticated access",
    async () => {
      await api.functional.shopping.admin.admins.sessions.index(unauthConn, {
        adminId: admin.id,
        body: reqBody,
      });
    },
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IShoppingAdmin } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingAdmin";
import type { IShoppingAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingAuthorizationToken";

/**
 * Test refreshing JWT tokens for an admin with an active session.
 *
 * 1. Register a new admin via the join endpoint and receive the initial access &
 *    refresh tokens.
 * 2. Use the valid refresh token from the join response to call the refresh API.
 * 3. Validate that new access/refresh tokens are issued and are correctly formed.
 * 4. Confirm session rotation: the new refresh token is different from the
 *    previous one.
 * 5. Confirm the admin account remains active and has not been deleted.
 * 6. Assert that all critical fields in the admin and token DTOs are present and
 *    valid.
 */
export async function test_api_admin_refresh_token_with_valid_session(
  connection: api.IConnection,
) {
  // 1. Register a new admin (to get valid tokens)
  const adminEmail: string = typia.random<string & tags.Format<"email">>();
  const password: string = RandomGenerator.alphaNumeric(12);
  const requestBody = {
    email: adminEmail,
    password: password satisfies string &
      tags.MinLength<8> &
      tags.MaxLength<128>,
    name: RandomGenerator.name(),
    role: RandomGenerator.pick([
      "super",
      "support",
      "compliance",
      "operator",
    ] as const),
    status: "active",
  } satisfies IShoppingAdmin.IJoin;

  const joinResult: IShoppingAdmin.IAuthorized =
    await api.functional.auth.admin.join(connection, { body: requestBody });
  typia.assert(joinResult);
  TestValidator.equals(
    "returned email matches input",
    joinResult.email,
    adminEmail,
  );
  TestValidator.equals(
    "returned role matches input",
    joinResult.role,
    requestBody.role,
  );
  TestValidator.equals(
    "admin account should be active",
    joinResult.status,
    "active",
  );
  TestValidator.equals(
    "admin account not deleted",
    joinResult.deleted_at,
    null,
  );
  TestValidator.predicate(
    "newly created admin id is a uuid",
    typeof joinResult.id === "string" &&
      /^[0-9a-fA-F-]{36}$/.test(joinResult.id),
  );

  // 2. Refresh tokens with the valid refresh token
  const refreshBody = {
    refresh_token: joinResult.token.refresh,
  } satisfies IShoppingAdmin.IRefresh;
  const refreshed: IShoppingAdmin.IAuthorized =
    await api.functional.auth.admin.refresh(connection, { body: refreshBody });
  typia.assert(refreshed);
  TestValidator.equals(
    "refreshed email matches original",
    refreshed.email,
    adminEmail,
  );
  TestValidator.equals(
    "refreshed admin id matches original",
    refreshed.id,
    joinResult.id,
  );
  TestValidator.notEquals(
    "refresh token has been rotated",
    refreshed.token.refresh,
    joinResult.token.refresh,
  );
  TestValidator.notEquals(
    "access token has been rotated",
    refreshed.token.access,
    joinResult.token.access,
  );
  TestValidator.equals(
    "account status remains active",
    refreshed.status,
    "active",
  );
  TestValidator.equals(
    "admin still not deleted after refresh",
    refreshed.deleted_at,
    null,
  );
  TestValidator.predicate(
    "refreshed admin id is a uuid",
    typeof refreshed.id === "string" && /^[0-9a-fA-F-]{36}$/.test(refreshed.id),
  );
  TestValidator.equals(
    "issued email still matches",
    refreshed.email,
    adminEmail,
  );
  TestValidator.predicate(
    "refresh token is a non-empty string",
    typeof refreshed.token.refresh === "string" &&
      refreshed.token.refresh.length > 0,
  );
  TestValidator.predicate(
    "access token is a non-empty string",
    typeof refreshed.token.access === "string" &&
      refreshed.token.access.length > 0,
  );
  // Check the expired_at and refreshable_until are ISO date-time strings
  TestValidator.predicate(
    "expired_at on access token is ISO string",
    typeof refreshed.token.expired_at === "string" &&
      /^[0-9]{4}-[0-9]{2}-[0-9]{2}T[0-9]{2}:[0-9]{2}:[0-9]{2}\.\d{3}Z$/.test(
        refreshed.token.expired_at,
      ),
  );
  TestValidator.predicate(
    "refreshable_until on token is ISO string",
    typeof refreshed.token.refreshable_until === "string" &&
      /^[0-9]{4}-[0-9]{2}-[0-9]{2}T[0-9]{2}:[0-9]{2}:[0-9]{2}\.\d{3}Z$/.test(
        refreshed.token.refreshable_until,
      ),
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IPageIShoppingSystemConfiguration } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIShoppingSystemConfiguration";
import type { IShoppingAdmin } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingAdmin";
import type { IShoppingAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingAuthorizationToken";
import type { IShoppingSystemConfiguration } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingSystemConfiguration";

/**
 * E2E test for admin system configuration search API.
 *
 * 1. Register a new admin
 * 2. As admin, search configurations with different filters (partial config_key,
 *    creation date range, description keyword)
 * 3. Assert that only active (non-soft-deleted) configurations are returned
 * 4. Check that pagination metadata is correct
 * 5. Attempt access as unauthenticated/non-admin and assert access is denied
 */
export async function test_api_admin_system_configurations_search_by_admin(
  connection: api.IConnection,
) {
  // 1. Register admin
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const adminPassword = RandomGenerator.alphaNumeric(12);
  const admin: IShoppingAdmin.IAuthorized =
    await api.functional.auth.admin.join(connection, {
      body: {
        email: adminEmail,
        password: adminPassword,
        name: RandomGenerator.name(),
        role: "super", // Assume "super" is a valid admin role. Adjust if not.
        status: "active",
      } satisfies IShoppingAdmin.IJoin,
    });
  typia.assert(admin);

  // 2. Prepare reference configuration data by searching without filter (get real configs from the API, for comparison)
  const pageSize = 5;
  const initialPage = 1;
  const fullDataPage: IPageIShoppingSystemConfiguration.ISummary =
    await api.functional.shopping.admin.systemConfigurations.index(connection, {
      body: {
        page: initialPage as number & tags.Type<"int32"> & tags.Minimum<1>,
        limit: pageSize as number &
          tags.Type<"int32"> &
          tags.Minimum<1> &
          tags.Maximum<100>,
      } satisfies IShoppingSystemConfiguration.IRequest,
    });
  typia.assert(fullDataPage);
  TestValidator.predicate(
    "returned data array exists",
    Array.isArray(fullDataPage.data),
  );
  TestValidator.equals(
    "limit matches",
    fullDataPage.pagination.limit,
    pageSize,
  );

  // Find a reference config to use for filter scenario
  const refConfig = fullDataPage.data.find(
    (cfg) => !cfg.deleted_at && !!cfg.config_key && !!cfg.description,
  );
  const hasValidConfig = refConfig !== undefined;
  TestValidator.predicate(
    "at least one non-deleted config with key+description found",
    hasValidConfig,
  );
  if (!hasValidConfig) return;
  typia.assert(refConfig!);

  // 3a. Search by partial config_key (substring)
  const partialKey = refConfig!.config_key.substring(
    0,
    Math.max(1, Math.floor(refConfig!.config_key.length / 2)),
  );
  const partialKeyPage =
    await api.functional.shopping.admin.systemConfigurations.index(connection, {
      body: {
        page: 1 as number & tags.Type<"int32"> & tags.Minimum<1>,
        limit: pageSize as number &
          tags.Type<"int32"> &
          tags.Minimum<1> &
          tags.Maximum<100>,
        search: partialKey,
      } satisfies IShoppingSystemConfiguration.IRequest,
    });
  typia.assert(partialKeyPage);
  TestValidator.predicate(
    "all returned config_keys contain partialKey",
    partialKeyPage.data.every((cfg) => cfg.config_key.includes(partialKey)),
  );

  // 3b. Search by exact config_key
  const exactKeyPage =
    await api.functional.shopping.admin.systemConfigurations.index(connection, {
      body: {
        page: 1 as number & tags.Type<"int32"> & tags.Minimum<1>,
        limit: pageSize as number &
          tags.Type<"int32"> &
          tags.Minimum<1> &
          tags.Maximum<100>,
        configKey: refConfig!.config_key,
      } satisfies IShoppingSystemConfiguration.IRequest,
    });
  typia.assert(exactKeyPage);
  TestValidator.equals(
    "only configs with that key included",
    exactKeyPage.data[0]?.config_key,
    refConfig!.config_key,
  );

  // 3c. Search by created_at date range
  const createdFrom = refConfig!.created_at;
  const createdTo = refConfig!.created_at;
  const dateRangePage =
    await api.functional.shopping.admin.systemConfigurations.index(connection, {
      body: {
        page: 1 as number & tags.Type<"int32"> & tags.Minimum<1>,
        limit: pageSize as number &
          tags.Type<"int32"> &
          tags.Minimum<1> &
          tags.Maximum<100>,
        createdFrom,
        createdTo,
      } satisfies IShoppingSystemConfiguration.IRequest,
    });
  typia.assert(dateRangePage);
  TestValidator.predicate(
    "all configs in date range",
    dateRangePage.data.every(
      (cfg) => cfg.created_at >= createdFrom && cfg.created_at <= createdTo,
    ),
  );

  // 3d. Search by description keyword (choose word from reference config)
  const [firstWord = refConfig!.description!] =
    refConfig!.description!.split(" ");
  const descPage =
    await api.functional.shopping.admin.systemConfigurations.index(connection, {
      body: {
        page: 1 as number & tags.Type<"int32"> & tags.Minimum<1>,
        limit: pageSize as number &
          tags.Type<"int32"> &
          tags.Minimum<1> &
          tags.Maximum<100>,
        description: firstWord,
      } satisfies IShoppingSystemConfiguration.IRequest,
    });
  typia.assert(descPage);
  TestValidator.predicate(
    "all configs in description search have first word in description",
    descPage.data.every((cfg) => (cfg.description ?? "").includes(firstWord)),
  );

  // 4. Ensure all returned configs are not soft-deleted
  for (const cfg of [
    ...partialKeyPage.data,
    ...exactKeyPage.data,
    ...dateRangePage.data,
    ...descPage.data,
  ]) {
    TestValidator.equals(
      "all returned configs are not soft-deleted",
      cfg.deleted_at,
      null,
    );
  }

  // 5. Pagination metadata
  TestValidator.predicate(
    "pagination object present",
    typeof partialKeyPage.pagination === "object" &&
      partialKeyPage.pagination !== null,
  );
  TestValidator.predicate(
    "pagination limit positive",
    partialKeyPage.pagination.limit > 0,
  );
  TestValidator.predicate(
    "pagination current page positive",
    partialKeyPage.pagination.current > 0,
  );

  // 6. Access denied when not authenticated as admin
  const unauthConn: api.IConnection = { ...connection, headers: {} };
  await TestValidator.error(
    "non-admin cannot access configurations API",
    async () => {
      await api.functional.shopping.admin.systemConfigurations.index(
        unauthConn,
        {
          body: {
            page: 1 as number & tags.Type<"int32"> & tags.Minimum<1>,
            limit: 1 as number &
              tags.Type<"int32"> &
              tags.Minimum<1> &
              tags.Maximum<100>,
          } satisfies IShoppingSystemConfiguration.IRequest,
        },
      );
    },
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IShoppingAdmin } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingAdmin";
import type { IShoppingAdminSuspension } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingAdminSuspension";
import type { IShoppingAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingAuthorizationToken";

/**
 * Test that a platform administrator can successfully create a new admin
 * suspension record for another admin actor. The scenario includes the full
 * administrative workflow: authenticating as an admin, submitting the
 * suspension creation request with all required context (target actor, type,
 * reason, duration), and verifying that a new suspension entry is created and
 * returned in the response. The test must validate business rules such as not
 * suspending oneself and preventing duplicate or invalid suspensions. The
 * expected outcome is a suspension entry reflecting all provided context and
 * audit traceability.
 */
export async function test_api_admin_admin_suspension_creation_by_admin(
  connection: api.IConnection,
) {
  // 1. Register two admin accounts (issuer and target)
  const issuerEmail = `${RandomGenerator.alphabets(8)}@company.com`;
  const targetEmail = `${RandomGenerator.alphabets(8)}@company.com`;
  const password = RandomGenerator.alphaNumeric(12);
  const name1 = RandomGenerator.name();
  const name2 = RandomGenerator.name();

  const issuerAdmin = await api.functional.auth.admin.join(connection, {
    body: {
      email: issuerEmail,
      password: password,
      name: name1,
      role: "super", // assuming 'super' is a valid role for suspension authority
      status: "active",
    } satisfies IShoppingAdmin.IJoin,
  });
  typia.assert(issuerAdmin);
  const targetAdmin = await api.functional.auth.admin.join(connection, {
    body: {
      email: targetEmail,
      password: password,
      name: name2,
      role: "support", // target gets a different role
      status: "active",
    } satisfies IShoppingAdmin.IJoin,
  });
  typia.assert(targetAdmin);

  // 2. Authenticate as issuer admin (token managed automatically)

  // 3. Construct valid suspension creation body
  const now = new Date();
  const startAt = now.toISOString();
  const endAt = new Date(now.getTime() + 7 * 24 * 60 * 60 * 1000).toISOString(); // 7 days later
  const body = {
    admin_id: issuerAdmin.id,
    suspended_admin_id: targetAdmin.id,
    suspended_seller_id: null,
    suspended_customer_id: null,
    suspension_type: RandomGenerator.pick([
      "temporary",
      "permanent",
      "pending_appeal",
    ] as const),
    reason: RandomGenerator.paragraph({ sentences: 6 }),
    start_at: startAt,
    end_at: endAt,
    status: "active",
  } satisfies IShoppingAdminSuspension.ICreate;

  // 4. Create the suspension
  const suspension =
    await api.functional.shopping.admin.adminSuspensions.create(connection, {
      body,
    });
  typia.assert(suspension);
  TestValidator.equals(
    "suspension admin id",
    suspension.admin_id,
    issuerAdmin.id,
  );
  TestValidator.equals(
    "suspended_admin_id",
    suspension.suspended_admin_id,
    targetAdmin.id,
  );
  TestValidator.equals(
    "suspension type",
    suspension.suspension_type,
    body.suspension_type,
  );
  TestValidator.equals("reason matches", suspension.reason, body.reason);
  TestValidator.equals("status is active", suspension.status, "active");
  TestValidator.predicate(
    "created timestamps present",
    Boolean(suspension.created_at) && Boolean(suspension.updated_at),
  );

  // 5. Error: Cannot suspend self
  await TestValidator.error("admin cannot suspend themselves", async () => {
    await api.functional.shopping.admin.adminSuspensions.create(connection, {
      body: {
        ...body,
        suspended_admin_id: issuerAdmin.id,
      },
    });
  });

  // 6. Error: Duplicate suspension (should fail for already-suspended target admin)
  await TestValidator.error(
    "cannot create duplicate admin suspension",
    async () => {
      await api.functional.shopping.admin.adminSuspensions.create(connection, {
        body,
      });
    },
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IShoppingAdmin } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingAdmin";
import type { IShoppingAdminSuspension } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingAdminSuspension";
import type { IShoppingAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingAuthorizationToken";

/**
 * Validate updating admin suspension records by a privileged admin.
 *
 * Scenario:
 *
 * 1. Register a new admin and authenticate.
 * 2. Create an initial admin suspension for an admin actor.
 * 3. Update the suspension: change status (e.g., from active to revoked), update
 *    reason, and modify the end date in the case of a temporary suspension.
 * 4. Confirm response reflects the requested update and business rules are
 *    respected.
 * 5. Negative test: attempt an illegal update (e.g., unlock a permanent suspension
 *    without justification) and confirm that the system rejects the operation.
 *
 * Implementation Details:
 *
 * - Randomize admin identity and target to ensure test isolation.
 * - For required IDs, use values from admin creation.
 * - For updates, use IShoppingAdminSuspension.IUpdate (partial update possible).
 * - Confirm that updated fields take effect; assert with TestValidator and
 *   typia.assert.
 * - Assert that the audit trail (created_at/updated_at) is logically consistent.
 * - Attempt business-rule-violating update (e.g., changing permanent ban to
 *   active with no end_at), expect rejection via TestValidator.error.
 */
export async function test_api_admin_admin_suspension_update_by_admin(
  connection: api.IConnection,
) {
  // 1. Register a new admin and authenticate.
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const adminJoinBody = {
    email: adminEmail,
    password: RandomGenerator.alphaNumeric(12),
    name: RandomGenerator.name(),
    role: "super",
    status: "active",
  } satisfies IShoppingAdmin.IJoin;
  const adminAuth = await api.functional.auth.admin.join(connection, {
    body: adminJoinBody,
  });
  typia.assert(adminAuth);

  // 2. Create a new suspension on the registering admin as target (self-suspension allowed for test)
  const suspensionCreateBody = {
    admin_id: adminAuth.id,
    suspended_admin_id: adminAuth.id,
    suspended_seller_id: null,
    suspended_customer_id: null,
    suspension_type: "temporary",
    reason: RandomGenerator.paragraph({ sentences: 2 }),
    start_at: new Date().toISOString(),
    end_at: new Date(Date.now() + 7 * 24 * 60 * 60 * 1000).toISOString(), // 7 days from now
    status: "active",
  } satisfies IShoppingAdminSuspension.ICreate;
  const suspension =
    await api.functional.shopping.admin.adminSuspensions.create(connection, {
      body: suspensionCreateBody,
    });
  typia.assert(suspension);
  TestValidator.equals(
    "admin is actor of suspension",
    suspension.admin_id,
    adminAuth.id,
  );
  TestValidator.equals(
    "suspended admin",
    suspension.suspended_admin_id,
    adminAuth.id,
  );
  TestValidator.equals("status is active", suspension.status, "active");
  TestValidator.equals(
    "suspension_type is temporary",
    suspension.suspension_type,
    "temporary",
  );

  // 3. Update the suspension: status to revoked, new end_at, updated reason
  const updateBody = {
    status: "revoked",
    end_at: new Date(Date.now() + 14 * 24 * 60 * 60 * 1000).toISOString(), // Extend ban by another week
    reason: RandomGenerator.paragraph({ sentences: 3 }),
  } satisfies IShoppingAdminSuspension.IUpdate;
  const updated = await api.functional.shopping.admin.adminSuspensions.update(
    connection,
    {
      adminSuspensionId: suspension.id,
      body: updateBody,
    },
  );
  typia.assert(updated);
  TestValidator.equals("suspension id should match", updated.id, suspension.id);
  TestValidator.equals("status updated to revoked", updated.status, "revoked");
  TestValidator.equals("end_at changed", updated.end_at, updateBody.end_at);
  TestValidator.equals("reason updated", updated.reason, updateBody.reason);
  TestValidator.predicate(
    "updated_at is newer or equal to created_at",
    new Date(updated.updated_at).getTime() >=
      new Date(updated.created_at).getTime(),
  );

  // 4. Attempt to unlock a permanent suspension without justification (should fail)
  // First, set to permanent
  const setPermanent = {
    suspension_type: "permanent",
    status: "active",
    end_at: null,
    reason: "Serious policy violation",
  } satisfies IShoppingAdminSuspension.IUpdate;
  const permanent = await api.functional.shopping.admin.adminSuspensions.update(
    connection,
    {
      adminSuspensionId: suspension.id,
      body: setPermanent,
    },
  );
  typia.assert(permanent);
  TestValidator.equals("now permanent", permanent.suspension_type, "permanent");
  TestValidator.equals("end_at is null for permanent", permanent.end_at, null);

  // Try to set status to active (improper unlock attempt)
  await TestValidator.error(
    "cannot unlock permanent suspension without justification",
    async () => {
      await api.functional.shopping.admin.adminSuspensions.update(connection, {
        adminSuspensionId: suspension.id,
        body: {
          status: "active", // try to reactivate
          end_at: new Date(Date.now() + 24 * 60 * 60 * 1000).toISOString(), // A day later
        } satisfies IShoppingAdminSuspension.IUpdate,
      });
    },
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IShoppingAdmin } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingAdmin";
import type { IShoppingAdminSuspension } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingAdminSuspension";
import type { IShoppingAppeal } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingAppeal";
import type { IShoppingAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingAuthorizationToken";
import type { IShoppingBusinessPolicy } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingBusinessPolicy";
import type { IShoppingPolicyViolation } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingPolicyViolation";

/**
 * Validate the entire admin lifecycle of appeal status update, including field
 * transitions, audit compliance, and security.
 *
 * 1. Register admin with valid credentials and allowed RBAC/roles, authenticated
 *    via join
 * 2. Create a random appeal entity via API (simulate pre-existing record)
 * 3. Transition status from 'under_review' to 'approved'
 * 4. Update decision rationale and verify audit trail
 * 5. Transition status from 'approved' to 'rejected' with new rationale
 * 6. Confirm business field rules and enumeration constraints
 * 7. Attempt forbidden field update as another (unauthenticated) admin and expect
 *    error
 * 8. Attempt update as unauthenticated context and expect error
 */
export async function test_api_admin_appeal_status_update_lifecycle_transition(
  connection: api.IConnection,
) {
  // 1. Register admin
  const adminJoinBody = {
    email: typia.random<string & tags.Format<"email">>(),
    password: RandomGenerator.alphaNumeric(12),
    name: RandomGenerator.name(),
    role: "super", // assume 'super' is a valid RBAC role
    status: "active",
  } satisfies IShoppingAdmin.IJoin;
  const adminAuth: IShoppingAdmin.IAuthorized =
    await api.functional.auth.admin.join(connection, { body: adminJoinBody });
  typia.assert(adminAuth);

  // 2. Simulate existing appeal record: create using typia.random (would normally be created by another flow, e.g., from a seller/customer side)
  const originalAppeal: IShoppingAppeal = typia.random<IShoppingAppeal>();
  typia.assert(originalAppeal);

  // 3. Update status under admin to 'under_review'
  const underReviewBody = {
    status: "under_review",
    reason: RandomGenerator.paragraph(),
  } satisfies IShoppingAppeal.IUpdate;
  const underReview: IShoppingAppeal =
    await api.functional.shopping.admin.appeals.update(connection, {
      appealId: originalAppeal.id,
      body: underReviewBody,
    });
  typia.assert(underReview);
  TestValidator.equals(
    "appeal moved to under_review",
    underReview.status,
    "under_review",
  );
  TestValidator.equals(
    "rationale/remarks stored",
    underReview.reason,
    underReviewBody.reason,
  );

  // 4. Approve the appeal with a detailed decision and rationale
  const approvedBody = {
    status: "approved",
    decision: "upheld",
    decision_at: new Date().toISOString(),
    reason: RandomGenerator.paragraph(),
  } satisfies IShoppingAppeal.IUpdate;
  const approved: IShoppingAppeal =
    await api.functional.shopping.admin.appeals.update(connection, {
      appealId: originalAppeal.id,
      body: approvedBody,
    });
  typia.assert(approved);
  TestValidator.equals("appeal approved", approved.status, "approved");
  TestValidator.equals("decision present", approved.decision, "upheld");
  TestValidator.equals(
    "rationale included",
    approved.reason,
    approvedBody.reason,
  );

  // 5. Now try transition to rejected with new rationale
  const rejectedBody = {
    status: "rejected",
    decision: "overturned",
    decision_at: new Date().toISOString(),
    reason: RandomGenerator.paragraph(),
  } satisfies IShoppingAppeal.IUpdate;
  const rejected: IShoppingAppeal =
    await api.functional.shopping.admin.appeals.update(connection, {
      appealId: originalAppeal.id,
      body: rejectedBody,
    });
  typia.assert(rejected);
  TestValidator.equals("appeal rejected", rejected.status, "rejected");
  TestValidator.equals(
    "decision is overturned",
    rejected.decision,
    "overturned",
  );

  // 6. Confirm audit trail exists and field transitions are logged in audit_history
  TestValidator.predicate(
    "audit_history includes both approved and rejected states",
    Array.isArray(rejected.audit_history) &&
      rejected.audit_history.some((h) => h.status_to === "approved") &&
      rejected.audit_history.some((h) => h.status_to === "rejected"),
  );

  // 7. Register and switch to a second admin, then attempt forbidden update (should fail)
  const otherAdminBody = {
    email: typia.random<string & tags.Format<"email">>(),
    password: RandomGenerator.alphaNumeric(12),
    name: RandomGenerator.name(),
    role: "support",
    status: "active",
  } satisfies IShoppingAdmin.IJoin;
  const otherAdminAuth: IShoppingAdmin.IAuthorized =
    await api.functional.auth.admin.join(connection, { body: otherAdminBody });
  typia.assert(otherAdminAuth);

  // Simulate logout (unauthenticated context)
  const unauthConn: api.IConnection = { ...connection, headers: {} };

  // Attempt forbidden update with unauthenticated context
  await TestValidator.error(
    "unauthenticated admin cannot change appeal status",
    async () => {
      await api.functional.shopping.admin.appeals.update(unauthConn, {
        appealId: originalAppeal.id,
        body: {
          status: "closed",
          reason: RandomGenerator.paragraph(),
        } satisfies IShoppingAppeal.IUpdate,
      });
    },
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IPageIShoppingBusinessPolicy } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIShoppingBusinessPolicy";
import type { IShoppingAdmin } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingAdmin";
import type { IShoppingAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingAuthorizationToken";
import type { IShoppingBusinessPolicy } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingBusinessPolicy";

/**
 * This test validates that an authenticated admin can perform advanced search,
 * filtering, and pagination over business policy configuration records
 * (BusinessPolicy table) via the admin businessPolicies search API.
 *
 * Steps:
 *
 * 1. Register a new admin via the join endpoint.
 * 2. As the authenticated admin, execute the PATCH
 *    /shopping/admin/businessPolicies endpoint with advanced query options:
 *
 *    - Filters: policy_name, scope, status, q (text search)
 *    - Pagination: page, limit
 *    - Sorting: order_by, order_direction
 * 3. Validate the paginated summary DTO is returned with all results matching
 *    query constraints, no sensitive fields are exposed.
 * 4. Confirm correct pagination output fields (current, limit, records, pages),
 *    all field types, and that no extraneous fields are present.
 * 5. Confirm advanced search, filtering, and sorting behave as expected. Malformed
 *    or unauthorized requests should be rejected.
 */
export async function test_api_admin_business_policy_search_query_pagination(
  connection: api.IConnection,
) {
  // 1. Register a new admin (join)
  const adminJoin = {
    email: typia.random<string & tags.Format<"email">>(),
    password: RandomGenerator.alphaNumeric(12),
    name: RandomGenerator.name(),
    role: RandomGenerator.pick([
      "super",
      "support",
      "compliance",
      "operator",
    ] as const),
    status: RandomGenerator.pick([
      "active",
      "pending",
      "suspended",
      "locked",
    ] as const),
  } satisfies IShoppingAdmin.IJoin;
  const authorized: IShoppingAdmin.IAuthorized =
    await api.functional.auth.admin.join(connection, { body: adminJoin });
  typia.assert(authorized);

  // 2. As authenticated admin, search with advanced query + pagination
  const searchRequestAdvanced = {
    policy_name: undefined,
    scope: undefined,
    status: undefined,
    q: undefined, // Full-text
    page: 1 as number & tags.Type<"int32">,
    limit: 5 as number & tags.Type<"int32">,
    order_by: RandomGenerator.pick(["policy_name", "created_at"] as const),
    order_direction: RandomGenerator.pick(["asc", "desc"] as const),
  } satisfies IShoppingBusinessPolicy.IRequest;
  const result: IPageIShoppingBusinessPolicy.ISummary =
    await api.functional.shopping.admin.businessPolicies.index(connection, {
      body: searchRequestAdvanced,
    });
  typia.assert(result);
  // Validate page object
  TestValidator.predicate(
    "pagination current page is 1",
    result.pagination.current === 1,
  );
  TestValidator.predicate(
    "pagination limit is 5",
    result.pagination.limit === 5,
  );
  TestValidator.predicate(
    "pagination total pages >= 1",
    result.pagination.pages >= 1,
  );
  TestValidator.predicate(
    "pagination total records >= 0",
    result.pagination.records >= 0,
  );
  // Validate records: no sensitive fields, all required fields present
  for (const summary of result.data) {
    typia.assert(summary);
    TestValidator.predicate(
      "summary does not contain sensitive/internal note",
      typeof (summary as any).internal_notes === "undefined",
    );
  }

  // 3. Search with filters: status, scope, fuzzy q
  const searchRequestFilter = {
    status: RandomGenerator.pick(["active", "inactive"] as const),
    scope: RandomGenerator.paragraph({ sentences: 1 }),
    q: RandomGenerator.paragraph({ sentences: 2 }),
    page: 1 as number & tags.Type<"int32">,
    limit: 2 as number & tags.Type<"int32">,
    order_by: "created_at",
    order_direction: "desc",
  } satisfies IShoppingBusinessPolicy.IRequest;
  const filteredResult: IPageIShoppingBusinessPolicy.ISummary =
    await api.functional.shopping.admin.businessPolicies.index(connection, {
      body: searchRequestFilter,
    });
  typia.assert(filteredResult);
  TestValidator.predicate(
    "filtered - correct limit",
    filteredResult.pagination.limit === 2,
  );
  // 4. Unauthorized: use unauthenticated connection
  const unauthConn: api.IConnection = { ...connection, headers: {} };
  await TestValidator.error(
    "unauthenticated user cannot query admin business policies",
    async () => {
      await api.functional.shopping.admin.businessPolicies.index(unauthConn, {
        body: searchRequestAdvanced,
      });
    },
  );
  // 5. Malformed query: wrong order_direction (should fail)
  await TestValidator.error(
    "malformed order_direction should fail",
    async () => {
      await api.functional.shopping.admin.businessPolicies.index(connection, {
        body: { ...searchRequestAdvanced, order_direction: "ascending" as any },
      });
    },
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IShoppingAttributeDimension } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingAttributeDimension";
import type { IShoppingAttributeValue } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingAttributeValue";
import type { IShoppingAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingAuthorizationToken";
import type { IShoppingCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingCategory";
import type { IShoppingCustomer } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingCustomer";
import type { IShoppingOrder } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingOrder";
import type { IShoppingOrderAddress } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingOrderAddress";
import type { IShoppingOrderLine } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingOrderLine";
import type { IShoppingOrderLineFulfillment } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingOrderLineFulfillment";
import type { IShoppingOrderPaymentAttempt } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingOrderPaymentAttempt";
import type { IShoppingOrderShipment } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingOrderShipment";
import type { IShoppingOrderSplit } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingOrderSplit";
import type { IShoppingOrderStatusHistory } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingOrderStatusHistory";
import type { IShoppingProduct } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingProduct";
import type { IShoppingProductAttribute } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingProductAttribute";
import type { IShoppingProductImage } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingProductImage";
import type { IShoppingSeller } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingSeller";
import type { IShoppingSku } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingSku";
import type { IShoppingSkuImage } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingSkuImage";
import type { IShoppingSkuVariant } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingSkuVariant";
import type { IShoppingTag } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingTag";

/**
 * Validates that an authenticated seller can successfully retrieve full details
 * for an order containing their product(s).
 *
 * 1. Registers a seller and authenticates the seller session.
 * 2. Seller creates a product with explicit code.
 * 3. Seller creates a SKU under their newly created product with a unique sku_code
 *    and required attributes.
 * 4. Registers a customer and authenticates the customer session.
 * 5. Customer creates an order, purchasing quantity 1 of the seller's SKU (with
 *    valid price), with full shipping address and a designated payment method.
 * 6. Switches authentication context back to the seller session.
 * 7. Seller retrieves the full order details by order_code using the seller GET
 *    order endpoint.
 * 8. Asserts presence of all required order sub-entities such as order_lines,
 *    splits, payment_attempts, shipments, addresses, and all audit/status
 *    fields in the detailed view.
 * 9. Asserts that the order data references the correct seller, product, and
 *    relationships appropriately for a cross-actor traceable order.
 * 10. Validates that all security and business linkage rules for seller-accessed
 *     order detail are enforced including order structure integrity.
 */
export async function test_api_seller_order_detail_retrieval_authorized(
  connection: api.IConnection,
) {
  // 1. Seller registration and authentication
  const sellerEmail = typia.random<string & tags.Format<"email">>();
  const seller: IShoppingSeller.IAuthorized =
    await api.functional.auth.seller.join(connection, {
      body: {
        email: sellerEmail,
        password: "TestPassword!123",
        display_name: RandomGenerator.name(),
        contact_phone: RandomGenerator.mobile(),
        status: "pending",
      } satisfies IShoppingSeller.IJoin,
    });
  typia.assert(seller);

  // 2. Seller creates product
  // Use random product code for uniqueness
  const productCode = RandomGenerator.alphaNumeric(10);
  const product: IShoppingProduct =
    await api.functional.shopping.seller.products.create(connection, {
      body: {
        code: productCode,
        name: RandomGenerator.name(2),
        description: RandomGenerator.content({
          paragraphs: 2,
          sentenceMin: 4,
          sentenceMax: 7,
        }),
        main_image_uri: "https://dummyimage.com/600x400/000/fff",
        status: "active",
        business_status: "in_review",
      } satisfies IShoppingProduct.ICreate,
    });
  typia.assert(product);

  // 3. Seller creates SKU under product
  const skuCode = RandomGenerator.alphaNumeric(8);
  const variantValues: string[] = [];
  const sku: IShoppingSku =
    await api.functional.shopping.seller.products.skus.create(connection, {
      productCode: product.code,
      body: {
        sku_code: skuCode,
        price: 10000,
        is_active: true,
        barcode: null,
        status: "in_stock",
        variant_attribute_value_ids: [], // no attributes enabled for minimal viable SKU
      } satisfies IShoppingSku.ICreate,
    });
  typia.assert(sku);

  // 4. Customer registration and authentication
  const customerEmail = typia.random<string & tags.Format<"email">>();
  const customer: IShoppingCustomer.IAuthorized =
    await api.functional.auth.customer.join(connection, {
      body: {
        email: customerEmail,
        password: "TestPassword!123",
        name: RandomGenerator.name(),
        phone: RandomGenerator.mobile(),
        href: "https://test.customer-landing-page.com/",
        referrer: "https://test.referrer-origin.com/",
        ip: undefined,
      } satisfies IShoppingCustomer.ICreate,
    });
  typia.assert(customer);

  // 5. Customer creates order (order contains the seller's SKU)
  // Uses shipping address with all required fields
  const orderBody = {
    total_price: sku.price,
    order_lines: [
      {
        shopping_sku_id: sku.id,
        quantity: 1,
        unit_price: sku.price,
      } satisfies IShoppingOrderLine.ICreate,
    ],
    shipping_addresses: [
      {
        type: "shipping",
        recipient_name: customer.name,
        recipient_phone: customer.phone,
        zip_code: "12345",
        base_address: "123 Test Ave",
        detail_address: "Apt 1",
        city: "Seoul",
        state_province: "Seoul",
        country: "South Korea",
      } satisfies IShoppingOrderAddress.ICreate,
    ],
    payment_method: "credit_card",
  } satisfies IShoppingOrder.ICreate;

  const order: IShoppingOrder =
    await api.functional.shopping.customer.orders.create(connection, {
      body: orderBody,
    });
  typia.assert(order);

  // 6. Switch session back to seller (seller is already authenticated)
  // No-op as session is already set due to the join operation earlier

  // 7. Seller retrieves order details by order code
  const orderDetails: IShoppingOrder =
    await api.functional.shopping.seller.orders.at(connection, {
      orderCode: order.order_code,
    });
  typia.assert(orderDetails);

  // 8. Validate that all expected fields and sub-entity arrays exist and are populated
  TestValidator.equals(
    "order_code matches",
    orderDetails.order_code,
    order.order_code,
  );
  TestValidator.predicate(
    "order_lines should be present",
    Array.isArray(orderDetails.order_lines) &&
      orderDetails.order_lines.length > 0,
  );
  TestValidator.predicate(
    "order_splits should exist",
    Array.isArray(orderDetails.order_splits),
  );
  TestValidator.predicate(
    "addresses should exist",
    Array.isArray(orderDetails.addresses),
  );
  TestValidator.predicate(
    "status_history should exist",
    Array.isArray(orderDetails.status_history),
  );
  TestValidator.predicate(
    "payment_attempts should exist",
    Array.isArray(orderDetails.payment_attempts),
  );
  TestValidator.predicate(
    "shipments should exist",
    Array.isArray(orderDetails.shipments),
  );
  // 9. Relationship checks
  const foundLine = orderDetails.order_lines.find((l) => l.sku.id === sku.id);
  TestValidator.predicate("order contains the original SKU", !!foundLine);
  TestValidator.equals(
    "order_line seller matches",
    foundLine?.seller.id,
    seller.id,
  );
  // 10. Audit fields and business rules
  TestValidator.predicate(
    "order detail created_at/updated_at populated",
    typeof orderDetails.created_at === "string" &&
      typeof orderDetails.updated_at === "string",
  );
  TestValidator.predicate(
    "order total_price matches",
    orderDetails.total_price === orderBody.total_price,
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IShoppingAdmin } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingAdmin";
import type { IShoppingAttributeDimension } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingAttributeDimension";
import type { IShoppingAttributeValue } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingAttributeValue";
import type { IShoppingAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingAuthorizationToken";
import type { IShoppingCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingCategory";
import type { IShoppingCustomer } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingCustomer";
import type { IShoppingOrder } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingOrder";
import type { IShoppingOrderAddress } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingOrderAddress";
import type { IShoppingOrderLine } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingOrderLine";
import type { IShoppingOrderLineFulfillment } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingOrderLineFulfillment";
import type { IShoppingOrderPaymentAttempt } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingOrderPaymentAttempt";
import type { IShoppingOrderShipment } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingOrderShipment";
import type { IShoppingOrderSplit } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingOrderSplit";
import type { IShoppingOrderStatusHistory } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingOrderStatusHistory";
import type { IShoppingProduct } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingProduct";
import type { IShoppingProductAttribute } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingProductAttribute";
import type { IShoppingProductImage } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingProductImage";
import type { IShoppingSeller } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingSeller";
import type { IShoppingSku } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingSku";
import type { IShoppingSkuImage } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingSkuImage";
import type { IShoppingSkuVariant } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingSkuVariant";
import type { IShoppingTag } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingTag";

/**
 * This test verifies that an admin can retrieve the full details of any order
 * in the system, regardless of order ownership or status. The scenario ensures
 * that admin permissions provide comprehensive visibility into all aspects of
 * an order—including order lines, splits, payment attempts, shipments,
 * addresses, and audit history—thus supporting compliance requirements and
 * troubleshooting workflows.
 *
 * Test Workflow:
 *
 * 1. Authenticate as an admin to obtain admin privileges.
 * 2. Register a seller account and create a product.
 * 3. Under the seller, create a valid SKU for the product.
 * 4. Register a customer account.
 * 5. Place a customer order with the seller's SKU and valid order data, ensuring
 *    the order is created in the system.
 * 6. Use admin privileges to retrieve the order using its order_code.
 * 7. Validate that the retrieved order includes all required sections (lines,
 *    splits, payment attempts, shipments, addresses, audit history), and that
 *    order_code matches.
 *
 * This test covers both business logic and permission aspects: order must be
 * visible to admin actors regardless of its creator or status, and all
 * relational data must be accessible for audit and support purposes.
 */
export async function test_api_admin_order_detail_retrieval_any_order(
  connection: api.IConnection,
) {
  // 1. Register/admin join
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const adminPassword = RandomGenerator.alphaNumeric(16);
  const admin: IShoppingAdmin.IAuthorized =
    await api.functional.auth.admin.join(connection, {
      body: {
        email: adminEmail,
        password: adminPassword,
        name: RandomGenerator.name(),
        role: "super",
        status: "active",
      },
    });
  typia.assert(admin);

  // 2. Register a seller
  const sellerEmail = typia.random<string & tags.Format<"email">>();
  const sellerPassword = RandomGenerator.alphaNumeric(14);
  const seller: IShoppingSeller.IAuthorized =
    await api.functional.auth.seller.join(connection, {
      body: {
        email: sellerEmail,
        password: sellerPassword,
        display_name: RandomGenerator.name(),
        contact_phone: RandomGenerator.mobile(),
        status: "pending",
      },
    });
  typia.assert(seller);

  // 3. Seller creates a product
  const productCode = RandomGenerator.alphaNumeric(12);
  const product: IShoppingProduct =
    await api.functional.shopping.seller.products.create(connection, {
      body: {
        code: productCode,
        name: RandomGenerator.paragraph({ sentences: 2 }),
        description: RandomGenerator.content({
          paragraphs: 1,
          sentenceMin: 8,
          sentenceMax: 15,
        }),
        main_image_uri: "https://picsum.photos/200",
        status: "draft",
        business_status: "in_review",
      },
    });
  typia.assert(product);

  // 4. Seller creates a SKU for the product (minItems<1> variant_attribute_value_ids)
  const dummyVariantId = typia.random<string & tags.Format<"uuid">>();
  const skuCode = RandomGenerator.alphaNumeric(10);
  const sku: IShoppingSku =
    await api.functional.shopping.seller.products.skus.create(connection, {
      productCode,
      body: {
        sku_code: skuCode,
        price: 5000,
        is_active: true,
        barcode: RandomGenerator.alphaNumeric(8),
        status: "in_stock",
        variant_attribute_value_ids: [dummyVariantId],
      },
    });
  typia.assert(sku);

  // 5. Register a customer
  const customerEmail = typia.random<string & tags.Format<"email">>();
  const customerPassword = RandomGenerator.alphaNumeric(12);
  const customer: IShoppingCustomer.IAuthorized =
    await api.functional.auth.customer.join(connection, {
      body: {
        email: customerEmail,
        password: customerPassword,
        name: RandomGenerator.name(),
        phone: RandomGenerator.mobile(),
        href: "https://example.com/registration",
        referrer: "https://google.com/",
        ip: null,
      },
    });
  typia.assert(customer);

  // 6. Customer places an order with valid addresses
  const shipping: IShoppingOrderAddress.ICreate = {
    type: "shipping",
    recipient_name: RandomGenerator.name(),
    recipient_phone: RandomGenerator.mobile(),
    zip_code: RandomGenerator.alphaNumeric(5),
    base_address: RandomGenerator.paragraph({ sentences: 2 }),
    detail_address: null,
    city: RandomGenerator.name(1),
    state_province: RandomGenerator.paragraph({ sentences: 1 }),
    country: "Republic of Test",
  };
  const orderBody: IShoppingOrder.ICreate = {
    total_price: 5000,
    order_lines: [
      {
        shopping_sku_id: sku.id,
        quantity: 1,
        unit_price: 5000,
      },
    ],
    shipping_addresses: [shipping],
    payment_method: "test_card",
    coupon_code: null,
  };
  const order: IShoppingOrder =
    await api.functional.shopping.customer.orders.create(connection, {
      body: orderBody,
    });
  typia.assert(order);

  // 7. As admin, retrieve order by order_code
  const adminOrder: IShoppingOrder =
    await api.functional.shopping.admin.orders.at(connection, {
      orderCode: order.order_code,
    });
  typia.assert(adminOrder);

  // 8. Validate the order is the one just created and includes full detail
  TestValidator.equals(
    "order_code matches",
    adminOrder.order_code,
    order.order_code,
  );
  TestValidator.predicate(
    "admin can view all required top-level order properties",
    typeof adminOrder.total_price === "number" &&
      adminOrder.status !== undefined &&
      Array.isArray(adminOrder.order_lines) &&
      Array.isArray(adminOrder.order_splits) &&
      Array.isArray(adminOrder.addresses) &&
      Array.isArray(adminOrder.status_history) &&
      Array.isArray(adminOrder.payment_attempts) &&
      Array.isArray(adminOrder.shipments),
  );

  TestValidator.predicate(
    "order_lines contains the SKU ordered",
    adminOrder.order_lines.some((line) => line.sku.sku_code === skuCode),
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IShoppingAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingAuthorizationToken";
import type { IShoppingPasswordReset } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingPasswordReset";
import type { IShoppingSeller } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingSeller";

/**
 * End-to-end verification of the seller password reset request update flow.
 *
 * This test performs the following sequence:
 *
 * 1. Register a new seller account
 * 2. Initiate a seller password reset request (request-reset)
 * 3. (Pretend to retrieve the resulting reset record as admin -- this simulates
 *    the database lookup step that would occur in actual implementation, since
 *    the password reset id is not returned to the user for security)
 * 4. Update the password reset request as the authenticated seller (extend
 *    expires_at)
 * 5. Mark the password reset request as consumed (set consumed_at)
 * 6. Attempt to update the reset request again after consumption (expect error)
 * 7. Attempt to update the reset request as unauthenticated actor (expect error)
 */
export async function test_api_seller_password_reset_update_by_seller(
  connection: api.IConnection,
) {
  // 1. Register seller
  const sellerBody = {
    email: typia.random<string & tags.Format<"email">>(),
    password: RandomGenerator.alphaNumeric(12),
    display_name: RandomGenerator.name(),
    contact_phone: RandomGenerator.mobile(),
    status: "pending",
  } satisfies IShoppingSeller.IJoin;
  const seller: IShoppingSeller.IAuthorized =
    await api.functional.auth.seller.join(connection, { body: sellerBody });
  typia.assert(seller);

  // 2. Initiate password reset request for seller (as if forgot password)
  const resetReq = {
    email: seller.email,
  } satisfies IShoppingSeller.IResetPasswordRequest;
  await api.functional.auth.seller.password.request_reset.requestPasswordReset(
    connection,
    { body: resetReq },
  );
  // --- Assume admin can see the latest reset entry for the seller ---
  // (In E2E test, simulate fetch by generating expected matching data)
  // Since we can't query the reset list, assume ID = typia.random<string & tags.Format<"uuid">>() for demonstration
  // In a real test, this would come from a secure system-controlled channel
  const passwordResetId = typia.random<string & tags.Format<"uuid">>();

  // 3. Update reset: extend expiry as seller
  const newExpiresAt = new Date(Date.now() + 60 * 60 * 1000).toISOString();
  const updateBody = {
    expires_at: newExpiresAt,
  } satisfies IShoppingPasswordReset.IUpdate;
  const updated = await api.functional.shopping.seller.passwordResets.update(
    connection,
    {
      passwordResetId,
      body: updateBody,
    },
  );
  typia.assert(updated);
  TestValidator.predicate(
    "updated expires_at should be >= now",
    new Date(updated.expires_at) >= new Date(),
  );
  TestValidator.equals("not consumed", updated.consumed_at, null);

  // 4. Mark reset as consumed as seller
  const consumedAt = new Date().toISOString();
  const consumeBody = {
    expires_at: updated.expires_at,
    consumed_at: consumedAt,
  } satisfies IShoppingPasswordReset.IUpdate;
  const consumed = await api.functional.shopping.seller.passwordResets.update(
    connection,
    {
      passwordResetId,
      body: consumeBody,
    },
  );
  typia.assert(consumed);
  TestValidator.equals(
    "consumed_at recorded",
    consumed.consumed_at,
    consumedAt,
  );

  // 5. Update after consumption: should fail
  await TestValidator.error(
    "cannot update password reset after consumption",
    async () => {
      await api.functional.shopping.seller.passwordResets.update(connection, {
        passwordResetId,
        body: {
          expires_at: new Date(Date.now() + 2 * 60 * 60 * 1000).toISOString(),
        } satisfies IShoppingPasswordReset.IUpdate,
      });
    },
  );

  // 6. Attempt update as unauthenticated (simulate new connection)
  const unauthConn: api.IConnection = { ...connection, headers: {} };
  await TestValidator.error(
    "unauthenticated user cannot update password reset",
    async () => {
      await api.functional.shopping.seller.passwordResets.update(unauthConn, {
        passwordResetId,
        body: {
          expires_at: new Date(Date.now() + 3 * 60 * 60 * 1000).toISOString(),
        } satisfies IShoppingPasswordReset.IUpdate,
      });
    },
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IShoppingAdmin } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingAdmin";
import type { IShoppingAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingAuthorizationToken";
import type { IShoppingCustomer } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingCustomer";

/**
 * E2E test for admin erasing password reset entries (success, not found,
 * unauthorized).
 *
 * 1. Register a new admin account and authenticate as admin.
 * 2. Simulate a customer password reset request (creates a reset entry).
 * 3. As admin, attempt to erase (DELETE) the reset request by its ID (success
 *    path).
 * 4. Attempt to erase the same password reset again (should return an error).
 * 5. Attempt to erase a random/nonexistent password reset ID (should return an
 *    error).
 * 6. Attempt unauthorized deletion (no admin login) and ensure forbidden.
 */
export async function test_api_admin_password_reset_erase_by_admin(
  connection: api.IConnection,
) {
  // 1. Register and authenticate as a new admin
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const admin: IShoppingAdmin.IAuthorized =
    await api.functional.auth.admin.join(connection, {
      body: {
        email: adminEmail,
        password: RandomGenerator.alphaNumeric(12) + "!A1",
        name: RandomGenerator.name(),
        role: "super",
        status: "active",
      } satisfies IShoppingAdmin.IJoin,
    });
  typia.assert(admin);

  // 2. Simulate a customer initiating password reset (creates a reset entity).
  const customerEmail = typia.random<string & tags.Format<"email">>();
  const resetResp =
    await api.functional.auth.customer.password.reset_request.requestPasswordReset(
      connection,
      {
        body: {
          request_email: customerEmail,
        } satisfies IShoppingCustomer.IRequestPasswordReset,
      },
    );
  typia.assert(resetResp);

  // [SKIP: No API to directly fetch reset entry. Assume test knows the reset request ID. Use randomized UUID.]
  const passwordResetId: string & tags.Format<"uuid"> = typia.random<
    string & tags.Format<"uuid">
  >();

  // 3. As admin, attempt to erase a password reset by ID (simulate success)
  await api.functional.shopping.admin.passwordResets.erase(connection, {
    passwordResetId: passwordResetId,
  });

  // 4. Attempt to delete the same reset ID again (should error)
  await TestValidator.error(
    "deleting already-deleted password reset returns error",
    async () => {
      await api.functional.shopping.admin.passwordResets.erase(connection, {
        passwordResetId: passwordResetId,
      });
    },
  );

  // 5. Attempt to delete a completely random UUID (not found error)
  await TestValidator.error(
    "deleting nonexistent reset returns error",
    async () => {
      await api.functional.shopping.admin.passwordResets.erase(connection, {
        passwordResetId: typia.random<string & tags.Format<"uuid">>(),
      });
    },
  );

  // 6. Attempt unauthorized deletion: reset connection to unauthenticated and DELETE
  const unauthConn: api.IConnection = { ...connection, headers: {} };
  await TestValidator.error("unauthorized deletion forbidden", async () => {
    await api.functional.shopping.admin.passwordResets.erase(unauthConn, {
      passwordResetId: typia.random<string & tags.Format<"uuid">>(),
    });
  });
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IPageIShoppingCustomer } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIShoppingCustomer";
import type { IShoppingAdmin } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingAdmin";
import type { IShoppingAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingAuthorizationToken";
import type { IShoppingCustomer } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingCustomer";

/**
 * Validates that an authenticated admin can search and retrieve paginated,
 * filtered lists of customers with core search/filter/sort features, only
 * receiving summary data, and with pagination info correct.
 *
 * Steps:
 *
 * 1. Register & login as admin (with random but valid credentials for all required
 *    fields).
 * 2. Perform search for customers via /shopping/admin/customers (PATCH), using
 *    various filter, sort, and page settings.
 * 3. Verify all returned data matches search criteria and only summary fields are
 *    present for each customer.
 * 4. Validate pagination structure in the response.
 * 5. Validate business logic: cannot call without admin auth; only summary-level,
 *    compliant output; can filter by name/email/status/date, sort results,
 *    paginate over pages, and receive correct result sets.
 */
export async function test_api_admin_customer_list_basic_search(
  connection: api.IConnection,
) {
  // Step 1: Admin registration and authentication
  const email = typia.random<string & tags.Format<"email">>();
  const admin: IShoppingAdmin.IAuthorized =
    await api.functional.auth.admin.join(connection, {
      body: {
        email,
        password: RandomGenerator.alphaNumeric(12),
        name: RandomGenerator.name(2),
        role: RandomGenerator.pick([
          "super",
          "support",
          "operator",
          "compliance",
        ] as const),
        status: RandomGenerator.pick([
          "active",
          "pending",
          "suspended",
          "locked",
        ] as const),
      } satisfies IShoppingAdmin.IJoin,
    });
  typia.assert(admin); // Validate admin output

  // Step 2: Quick base customer search - no filters, first page
  const baseSearchReq = {
    page: 1 as number & tags.Type<"int32"> & tags.Minimum<1>,
    limit: 5 as number &
      tags.Type<"int32"> &
      tags.Minimum<1> &
      tags.Maximum<100>,
  } satisfies IShoppingCustomer.IRequest;
  const baseList = await api.functional.shopping.admin.customers.index(
    connection,
    {
      body: baseSearchReq,
    },
  );
  typia.assert(baseList);
  TestValidator.equals(
    "pagination page matches",
    baseList.pagination.current,
    1,
  );
  TestValidator.predicate(
    "all data are summary",
    baseList.data.every(
      (v) =>
        typeof v.id === "string" &&
        typeof v.email === "string" &&
        typeof v.name === "string" &&
        typeof v.is_active === "boolean" &&
        typeof v.created_at === "string" &&
        (typeof v.deleted_at === "string" || v.deleted_at === null),
    ),
  );

  // Step 3: Search by name (using value from list if list has customers)
  if (baseList.data.length > 0) {
    const sample = baseList.data[0];
    const nameSearchReq = {
      ...baseSearchReq,
      search: sample.name.slice(
        0,
        Math.max(3, Math.floor(sample.name.length / 2)),
      ),
    } satisfies IShoppingCustomer.IRequest;
    const nameList = await api.functional.shopping.admin.customers.index(
      connection,
      { body: nameSearchReq },
    );
    typia.assert(nameList);
    TestValidator.predicate(
      "all name search result matches filter",
      nameList.data.every((c) => c.name.includes(nameSearchReq.search!)),
    );
  }

  // Step 4: Search by email (using value from list if list has customers)
  if (baseList.data.length > 0) {
    const sample = baseList.data[0];
    const emailSearchReq = {
      ...baseSearchReq,
      search: sample.email.slice(
        0,
        Math.max(3, Math.floor(sample.email.length / 2)),
      ),
    } satisfies IShoppingCustomer.IRequest;
    const emailList = await api.functional.shopping.admin.customers.index(
      connection,
      { body: emailSearchReq },
    );
    typia.assert(emailList);
    TestValidator.predicate(
      "all email search result matches filter",
      emailList.data.every((c) => c.email.includes(emailSearchReq.search!)),
    );
  }

  // Step 5: Search by is_active status (sample both true and false in API)
  for (const is_active of [true, false]) {
    const statusList = await api.functional.shopping.admin.customers.index(
      connection,
      {
        body: {
          ...baseSearchReq,
          is_active,
        } satisfies IShoppingCustomer.IRequest,
      },
    );
    typia.assert(statusList);
    TestValidator.predicate(
      `all customers have is_active = ${is_active}`,
      statusList.data.every((c) => c.is_active === is_active),
    );
  }

  // Step 6: Search with registration date range (if available)
  if (baseList.data.length > 0) {
    const sample = baseList.data[0];
    // try filtering by created_at (cut beginning/end)
    const createdAt = sample.created_at;
    const dateRangeReq = {
      ...baseSearchReq,
      created_at_from: createdAt,
      created_at_to: createdAt,
    } satisfies IShoppingCustomer.IRequest;
    const dateList = await api.functional.shopping.admin.customers.index(
      connection,
      { body: dateRangeReq },
    );
    typia.assert(dateList);
    TestValidator.predicate(
      "all results in date range",
      dateList.data.every((c) => c.created_at === createdAt),
    );
  }

  // Step 7: Pagination (if more than one page)
  if (baseList.pagination.pages > 1) {
    const secondPageReq = {
      ...baseSearchReq,
      page: 2 as number & tags.Type<"int32"> & tags.Minimum<1>,
    } satisfies IShoppingCustomer.IRequest;
    const secondPage = await api.functional.shopping.admin.customers.index(
      connection,
      {
        body: secondPageReq,
      },
    );
    typia.assert(secondPage);
    TestValidator.equals(
      "pagination page matches (2)",
      secondPage.pagination.current,
      2,
    );
  }

  // Step 8: Sorting (by name asc, by created_at desc)
  for (const [field, order] of [
    ["name", "asc"],
    ["created_at", "desc"],
    ["email", "asc"],
    ["is_active", "desc"],
  ] as const) {
    const sortReq = {
      ...baseSearchReq,
      sort_by: field,
      sort_order: order,
    } satisfies IShoppingCustomer.IRequest;
    const sorted = await api.functional.shopping.admin.customers.index(
      connection,
      { body: sortReq },
    );
    typia.assert(sorted);
    TestValidator.equals("sort field matches", sorted.pagination.current, 1);
    // We cannot guarantee actual sort order in test if single page/low data, so only basic assertion here
    TestValidator.predicate(
      "all customers have required summary fields",
      sorted.data.every(
        (c) =>
          typeof c.id === "string" &&
          typeof c.name === "string" &&
          typeof c.email === "string" &&
          typeof c.is_active === "boolean" &&
          typeof c.created_at === "string",
      ),
    );
  }
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IShoppingAdmin } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingAdmin";
import type { IShoppingAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingAuthorizationToken";
import type { IShoppingCustomer } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingCustomer";

/**
 * Validate that admin can view customer details, including profile information,
 * status, and audit fields.
 *
 * Business context:
 *
 * - Only admin or the customer (owner) can view full detail.
 * - Nonexistent or forbidden access must be rejected properly.
 *
 * Test steps:
 *
 * 1. Register an admin using the admin join endpoint.
 * 2. Create a customer using password reset request (for indirect account creation
 *    with email).
 * 3. Query customer details by UUID as the admin and validate all
 *    profile/status/audit fields.
 * 4. Attempt to view a non-existent customerId and verify error is returned.
 * 5. Remove admin credentials and verify forbidden on customer detail access.
 */
export async function test_api_admin_customer_detail_view(
  connection: api.IConnection,
) {
  // 1. Register an admin
  const adminJoin = {
    email: typia.random<string & tags.Format<"email">>(),
    password: RandomGenerator.alphaNumeric(12) + "_Aa1!",
    name: RandomGenerator.name(),
    role: "super", // assume "super" is a valid role
    status: "active", // valid status
  } satisfies IShoppingAdmin.IJoin;
  const admin: IShoppingAdmin.IAuthorized =
    await api.functional.auth.admin.join(connection, { body: adminJoin });
  typia.assert(admin);

  // 2. Create a customer (indirect creation to guarantee real customerId)
  const customerEmail = typia.random<string & tags.Format<"email">>();
  const resetResult =
    await api.functional.auth.customer.password.reset_request.requestPasswordReset(
      connection,
      {
        body: { request_email: customerEmail },
      },
    );
  typia.assert(resetResult);

  // 3. Query all existing customers to find the just-created customer (simulate lookup; in real flow, presume availability via DB or fixture)
  // For test purposes, attempt to fetch by trial with random UUID until found. But here, demonstrate proper pattern:
  const customersToTry = [customerEmail];
  let foundCustomer: IShoppingCustomer | undefined = undefined;
  for (const email of customersToTry) {
    // Attempt up to 5 times with random delay to simulate DB propagation delay (if needed)
    for (let tryNum = 0; tryNum < 5; ++tryNum) {
      try {
        // Suppose you can directly fetch by the email using admin power (simulate: get customer UUID after creation)
        // For this framework, just simulate getting random but valid customerId
        const testCustomerId = typia.random<string & tags.Format<"uuid">>();
        const customer = await api.functional.shopping.admin.customers.at(
          connection,
          { customerId: testCustomerId },
        );
        typia.assert(customer);
        if (customer.email === customerEmail) {
          foundCustomer = customer;
          break;
        }
      } catch (exp) {
        // skip errors (customer not found), try again unless found
      }
    }
    if (foundCustomer) break;
  }

  TestValidator.predicate(
    "admin can retrieve customer by UUID",
    !!foundCustomer && foundCustomer.email === customerEmail,
  );
  if (!!foundCustomer) {
    TestValidator.predicate(
      "customer is active or soft-deleted",
      foundCustomer.is_active === true ||
        (foundCustomer.deleted_at !== null &&
          foundCustomer.deleted_at !== undefined),
    );
    TestValidator.predicate(
      "customer profile fields present",
      typeof foundCustomer.name === "string" &&
        typeof foundCustomer.phone === "string",
    );
    TestValidator.predicate(
      "audit fields present",
      typeof foundCustomer.created_at === "string" &&
        typeof foundCustomer.updated_at === "string",
    );
  }

  // 4. Try non-existent customerId
  const nonExistentId = typia.random<string & tags.Format<"uuid">>();
  await TestValidator.error(
    "admin cannot fetch non-existent customerId",
    async () => {
      await api.functional.shopping.admin.customers.at(connection, {
        customerId: nonExistentId,
      });
    },
  );

  // 5. Remove admin token (simulate unauthenticated scenario)
  const unauthConn: api.IConnection = { ...connection, headers: {} };
  await TestValidator.error(
    "forbidden for unauthenticated access",
    async () => {
      await api.functional.shopping.admin.customers.at(unauthConn, {
        customerId:
          foundCustomer?.id ?? typia.random<string & tags.Format<"uuid">>(),
      });
    },
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
