/**
 * Test that a logged-in customer can successfully soft-delete their own
 * wishlist.
 *
 * 1. Register a new customer using valid credentials.
 * 2. Simulate wishlist creation for that customer (direct instantiation).
 * 3. Attempt to delete the wishlist as its owner and validate deletion result.
 * 4. Attempt to delete the wishlist as a different user and expect an error.
 */
export async function test_api_customer_wishlist_deletion_by_owner(
  connection: api.IConnection,
) {
  // 1. Register as customer A
  const emailA = typia.random<string & tags.Format<"email">>();
  const customerA = await api.functional.auth.customer.join(connection, {
    body: {
      email: emailA,
      password: RandomGenerator.alphabets(12),
      name: RandomGenerator.name(),
      phone: RandomGenerator.mobile(),
      href: "https://test.example.com/signup",
      referrer: "https://test.example.com/landing",
      ip: undefined,
    },
  });
  typia.assert(customerA);
  const customerIdA = customerA.id;

  // 2. Simulate wishlist creation for customer A
  // (since wishlist creation API is not present, mock it)
  const wishlist: IShoppingWishlist = {
    id: typia.random<string & tags.Format<"uuid">>(),
    shopping_customer_id: customerIdA,
    created_at: new Date().toISOString(),
    updated_at: new Date().toISOString(),
    items: [],
  };
  typia.assert(wishlist);

  // 3. Delete wishlist using correct user (owner)
  const erased = await api.functional.shopping.customer.wishlists.erase(
    connection,
    {
      wishlistId: wishlist.id,
    },
  );
  typia.assert(erased);
  TestValidator.equals(
    "soft-deleted wishlist has expected id",
    erased.id,
    wishlist.id,
  );
  // No further property can be checked due to lack of deleted_at in IShoppingWishlist; soft-delete mechanism may be handled in backend only.

  // 4. Register as customer B (non-owner)
  const emailB = typia.random<string & tags.Format<"email">>();
  const customerB = await api.functional.auth.customer.join(connection, {
    body: {
      email: emailB,
      password: RandomGenerator.alphabets(12),
      name: RandomGenerator.name(),
      phone: RandomGenerator.mobile(),
      href: "https://test.example.com/signup",
      referrer: "https://test.example.com/landing",
      ip: undefined,
    },
  });
  typia.assert(customerB);

  // Switch connection context to customer B (automatic via SDK after join)
  // Attempt to delete wishlist belonging to customer A -- should error.
  await TestValidator.error(
    "deletion attempt by non-owner must be blocked",
    async () => {
      await api.functional.shopping.customer.wishlists.erase(connection, {
        wishlistId: wishlist.id,
      });
    },
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IPageIShoppingWishlistItem } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIShoppingWishlistItem";
import type { IShoppingAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingAuthorizationToken";
import type { IShoppingCustomer } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingCustomer";
import type { IShoppingSku } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingSku";
import type { IShoppingWishlistItem } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingWishlistItem";

/**
 * Validate customer wishlist item pagination and filtering.
 *
 * 1. Register a customer
 * 2. Create a wishlist for the customer (by attempting to add first item)
 * 3. Add multiple SKUs/items to the wishlist with different sku_codes and product
 *    names
 * 4. Retrieve all wishlist items paginated (test page/limit logic is correct)
 * 5. Filter the wishlist by a particular product name or SKU code using search,
 *    verify results
 * 6. Attempt to retrieve a wishlist as a different (unauthorized) customer,
 *    expecting authorization failure (error)
 */
export async function test_api_customer_wishlist_items_pagination_and_filtering(
  connection: api.IConnection,
) {
  // 1. Register primary customer
  const customerData = {
    email: `${RandomGenerator.alphaNumeric(8)}@example.com`,
    password: RandomGenerator.alphaNumeric(12),
    name: RandomGenerator.name(),
    phone: RandomGenerator.mobile(),
    href: "https://example.com/signup",
    referrer: "https://example.com",
  } satisfies IShoppingCustomer.ICreate;
  const customer: IShoppingCustomer.IAuthorized =
    await api.functional.auth.customer.join(connection, { body: customerData });
  typia.assert(customer);

  // 2. Create wishlist by adding the first SKU (simulate multiple unique skus for test)
  const skuCodes = ArrayUtil.repeat(
    8,
    (i) => `SKU-AUTO-${RandomGenerator.alphaNumeric(5)}-${i}`,
  );
  const createdItems: IShoppingWishlistItem[] = [];
  for (const sku_code of skuCodes) {
    const item = await api.functional.shopping.customer.wishlists.items.create(
      connection,
      {
        wishlistId: customer.id as string & tags.Format<"uuid">,
        body: { sku_code } satisfies IShoppingWishlistItem.ICreate,
      },
    );
    typia.assert(item);
    createdItems.push(item);
  }

  // 3. Paginate: Retrieve items, page 1/limit 3
  let pageResult = await api.functional.shopping.customer.wishlists.items.index(
    connection,
    {
      wishlistId: customer.id as string & tags.Format<"uuid">,
      body: {
        page: 1 as number & tags.Type<"int32"> & tags.Minimum<1>,
        limit: 3 as number &
          tags.Type<"int32"> &
          tags.Minimum<1> &
          tags.Maximum<100>,
      },
    },
  );
  typia.assert(pageResult);
  TestValidator.equals(
    "pagination count matches limit or dataset size",
    pageResult.data.length,
