          tags.Minimum<1> &
          tags.Maximum<100>,
      },
    },
  );
  typia.assert(pageResult);
  TestValidator.equals("current page is 2", pageResult.pagination.current, 2);

  // 5. Filtering: Search by SKU code substring
  const searchSku = skuCodes[0].substring(0, 8);
