  const filters = {
    tracking_source: "courier_api",
    status: "in_transit",
    event_start_at: new Date(
      Date.now() - 7 * 24 * 60 * 60 * 1000,
    ).toISOString(),
    event_end_at: new Date().toISOString(),
    sort_by: "last_update_at",
    sort_order: "desc",
    page: 1,
    limit: 20,
  } satisfies IShoppingShipmentTracking.IRequest;
