/**
 * Verify that an admin can retrieve the details of a specific approval action
 * associated with a refund request, including all required business fields for
 * audit and compliance.
 *
 * Steps:
 *
 * 1. Register an admin (with privilege and status).
 * 2. Register a seller (with product and SKU setup).
 * 3. Register a customer.
 * 4. Customer places an order for the SKU.
 * 5. Customer requests a refund for the order.
 * 6. (Simulated) Approval by admin (since no approval POST API is available, we
 *    reuse refund request with auto-generated approval for test).
 * 7. Admin retrieves approval detail with GET
 *    /shopping/admin/refunds/{refundRequestId}/approvals/{approvalId}.
 * 8. Validate all critical approval fields: actor, action type/status, rationale,
 *    audit timestamps.
 * 9. Assert approval returned matches approval on parent refund request and is
 *    complete for audit.
 */
export async function test_api_admin_refund_approval_retrieval_correct_chain(
  connection: api.IConnection,
) {
  // 1. Register admin
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const adminPassword = RandomGenerator.alphaNumeric(12);
  const admin: IShoppingAdmin.IAuthorized =
    await api.functional.auth.admin.join(connection, {
      body: {
        email: adminEmail,
        password: adminPassword,
        name: RandomGenerator.name(),
        role: "support",
        status: "active",
      },
    });
  typia.assert(admin);

  // 2. Register seller
  const sellerEmail = typia.random<string & tags.Format<"email">>();
  const sellerPassword = RandomGenerator.alphaNumeric(10);
  const seller: IShoppingSeller.IAuthorized =
    await api.functional.auth.seller.join(connection, {
      body: {
        email: sellerEmail,
        password: sellerPassword,
        display_name: RandomGenerator.name(2),
        contact_phone: RandomGenerator.mobile(),
        status: "active",
      },
    });
  typia.assert(seller);

  // 3. Register customer
  const customerEmail = typia.random<string & tags.Format<"email">>();
  const customerPassword = RandomGenerator.alphaNumeric(10);
  const customer: IShoppingCustomer.IAuthorized =
    await api.functional.auth.customer.join(connection, {
      body: {
        email: customerEmail,
        password: customerPassword,
        name: RandomGenerator.name(),
        phone: RandomGenerator.mobile(),
        href: "https://test.customer.local/registration",
        referrer: "https://test.customer.local/welcome",
      },
    });
  typia.assert(customer);

  // 4. Seller creates a product
  const productCode = RandomGenerator.alphaNumeric(8);
  const product: IShoppingProduct =
    await api.functional.shopping.seller.products.create(connection, {
      body: {
        code: productCode,
        name: RandomGenerator.paragraph({ sentences: 2 }),
        description: RandomGenerator.content({
          paragraphs: 1,
          sentenceMin: 8,
          sentenceMax: 12,
        }),
        main_image_uri:
          "https://cdn.test.mall/img/" +
          RandomGenerator.alphaNumeric(12) +
          ".jpg",
        status: "active",
        business_status: "in_review",
      },
    });
  typia.assert(product);

  // 5. Seller creates a SKU under the product
  const attributeValueId = typia.random<string & tags.Format<"uuid">>();
  const skuCode = RandomGenerator.alphaNumeric(8);
  const sku: IShoppingSku =
    await api.functional.shopping.seller.products.skus.create(connection, {
      productCode: product.code,
      body: {
        sku_code: skuCode,
        price: 19900,
        is_active: true,
        status: "in_stock",
        variant_attribute_value_ids: [attributeValueId],
      },
    });
  typia.assert(sku);

  // 6. Customer places an order for the SKU
  const order: IShoppingOrder =
    await api.functional.shopping.customer.orders.create(connection, {
      body: {
        total_price: sku.price,
        order_lines: [
          {
            shopping_sku_id: sku.id,
            quantity: 1 as number & tags.Type<"int32"> & tags.Minimum<1>,
            unit_price: sku.price,
          },
        ],
        shipping_addresses: [
          {
            type: "shipping",
            recipient_name: RandomGenerator.name(2),
            recipient_phone: RandomGenerator.mobile(),
            zip_code: RandomGenerator.alphaNumeric(5),
            base_address: RandomGenerator.paragraph({
              sentences: 2,
              wordMin: 2,
              wordMax: 5,
            }),
            city: "Seoul",
            state_province: "Seoul",
            country: "Korea",
          },
        ],
        payment_method: "virtual_account",
      },
    });
  typia.assert(order);

  // 7. Customer requests a refund for the order
  const refundRequest: IShoppingRefundRequest =
    await api.functional.shopping.customer.refunds.create(connection, {
      body: {
        shopping_order_id: order.id,
        request_type: "refund",
        business_reason: "Change of mind",
        items: [
          {
            shopping_order_id: order.id,
            shopping_order_line_id: order.order_lines[0].id,
            quantity: 1 as number & tags.Type<"int32">,
          },
        ],
      },
    });
  typia.assert(refundRequest);

  // 8. Find at least one approval generated on refundRequest for verification
  TestValidator.predicate(
    "refund request has at least one approval",
    refundRequest.approvals.length > 0,
  );
  const approval = refundRequest.approvals[0];
  typia.assert(approval);

  // 9. Admin retrieves approval details by GET endpoint
  const approvalDetail: IShoppingRefundApproval =
    await api.functional.shopping.admin.refunds.approvals.at(connection, {
      refundRequestId: refundRequest.id,
      approvalId: approval.id,
    });
  typia.assert(approvalDetail);

  // 10. Validate critical approval fields
  TestValidator.equals("approval id matches", approvalDetail.id, approval.id);
  TestValidator.equals(
    "approval action matches",
    approvalDetail.action,
    approval.action,
  );
  TestValidator.equals(
    "approval actor matches",
    approvalDetail.actor_id,
    approval.actor_id,
  );
  TestValidator.equals(
    "approval note matches",
    approvalDetail.note,
    approval.note,
  );
  TestValidator.equals(
    "approval created_at matches",
    approvalDetail.created_at,
    approval.created_at,
  );

  // 11. Validation: approval must link to the correct refundRequestId
  TestValidator.equals(
    "approval requestId matches",
    approvalDetail.shopping_refund_request_id,
    refundRequest.id,
  );

  // 12. Validate action value is one of the allowed business values
  TestValidator.predicate(
    "approval action is one of 'approved' or 'rejected'",
    approvalDetail.action === "approved" ||
      approvalDetail.action === "rejected",
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IShoppingAdmin } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingAdmin";
import type { IShoppingAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingAuthorizationToken";
import type { IShoppingFeatureFlag } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingFeatureFlag";

/**
 * Validates retrieval of a feature flag's details by an authenticated admin.
 *
 * - Registers a new admin with random business email, secure password, name,
 *   role, and status.
 * - Authenticates as this admin; session will be used for all API calls.
 * - Creates a new unique feature flag (random flag_name) with required fields and
 *   random rollout (present or omitted).
 * - Retrieves the feature flag by its flag_name using the admin GET endpoint.
 * - Asserts all flag fields: id, flag_name, scope, enabled, rollout, description,
 *   timestamps, and deleted_at.
 * - Ensures only non-soft-deleted flags are returned.
 * - Guarantees type safety and business compliance throughout.
 */
export async function test_api_admin_feature_flag_retrieval_by_admin(
  connection: api.IConnection,
) {
  // Step 1: Register admin
  const adminEmail = `${RandomGenerator.alphaNumeric(8)}@company.com`;
  const adminPassword = RandomGenerator.alphaNumeric(16);
  const adminJoinBody = {
    email: adminEmail,
    password: adminPassword,
    name: RandomGenerator.name(),
    role: RandomGenerator.pick([
      "super",
      "support",
      "operator",
      "compliance",
    ] as const),
    status: RandomGenerator.pick([
      "active",
      "suspended",
      "pending",
      "locked",
    ] as const),
  } satisfies IShoppingAdmin.IJoin;
  const adminAuthorized: IShoppingAdmin.IAuthorized =
    await api.functional.auth.admin.join(connection, { body: adminJoinBody });
  typia.assert(adminAuthorized);

  // Step 2: Create feature flag as admin
  const flagName = `flag_${RandomGenerator.alphaNumeric(8)}`;
  const flagCreateBody = {
    flag_name: flagName,
    scope: RandomGenerator.pick([
      "global",
      "orders",
      "checkout",
      "frontend",
    ] as const),
    enabled: RandomGenerator.pick([true, false] as const),
    rollout:
      RandomGenerator.pick([
        null,
        undefined,
        Math.floor(Math.random() * 101),
      ]) ?? undefined,
    description: RandomGenerator.paragraph({ sentences: 4 }),
  } satisfies IShoppingFeatureFlag.ICreate;
  const createdFlag: IShoppingFeatureFlag =
    await api.functional.shopping.admin.featureFlags.create(connection, {
      body: flagCreateBody,
    });
  typia.assert(createdFlag);

  // Step 3: Retrieve feature flag by flagName
  const retrievedFlag: IShoppingFeatureFlag =
    await api.functional.shopping.admin.featureFlags.at(connection, {
      flagName,
    });
  typia.assert(retrievedFlag);

  // Step 4: Assert flag fields are correct and not soft-deleted
  TestValidator.equals(
    "retrieved id matches created",
    retrievedFlag.id,
    createdFlag.id,
  );
  TestValidator.equals(
    "retrieved flag_name matches",
    retrievedFlag.flag_name,
    flagName,
  );
  TestValidator.equals(
    "retrieved scope matches",
    retrievedFlag.scope,
    flagCreateBody.scope,
  );
  TestValidator.equals(
    "retrieved enabled matches",
    retrievedFlag.enabled,
    flagCreateBody.enabled,
  );
  TestValidator.equals(
    "retrieved rollout matches",
    retrievedFlag.rollout,
    flagCreateBody.rollout ?? null,
  );
  TestValidator.equals(
    "retrieved description matches",
    retrievedFlag.description,
    flagCreateBody.description,
  );
  TestValidator.equals(
    "retrieved not soft-deleted",
    retrievedFlag.deleted_at,
    null,
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IShoppingAdmin } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingAdmin";
import type { IShoppingAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingAuthorizationToken";
import type { IShoppingFeatureFlag } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingFeatureFlag";

/**
 * Confirm that a newly joined admin can create a feature flag with required
 * parameters: flag_name (unique code), scope, enabled, rollout percent, and
 * description. Test checks admin authentication, global uniqueness of
 * flag_name, and full field population on creation. Also asserts
 * unauthenticated creation is denied, and duplicate flag_name prevents
 * creation.
 *
 * 1. Register a new admin
 * 2. With admin session, create a feature flag with random valid input
 * 3. Check response matches input and all required fields are present
 * 4. Attempt to create duplicate flag_name (expect error)
 * 5. Try unauthenticated creation (expect error)
 */
export async function test_api_admin_feature_flag_creation(
  connection: api.IConnection,
) {
  // 1. Register a new admin
  const adminEmail: string = typia.random<string & tags.Format<"email">>();
  const admin: IShoppingAdmin.IAuthorized =
    await api.functional.auth.admin.join(connection, {
      body: {
        email: adminEmail,
        password: RandomGenerator.alphaNumeric(12),
        name: RandomGenerator.name(),
        role: RandomGenerator.pick([
          "super",
          "compliance",
          "support",
          "operator",
        ] as const),
        status: "active",
      } satisfies IShoppingAdmin.IJoin,
    });
  typia.assert(admin);

  // 2. Create a feature flag as the admin
  const flagInput = {
    flag_name: `fflag_${RandomGenerator.alphaNumeric(8)}`,
    scope: RandomGenerator.pick([
      "global",
      "orders",
      "checkout",
      "frontend",
    ] as const),
    enabled: true,
    rollout: 50,
    description: RandomGenerator.paragraph({ sentences: 6 }),
  } satisfies IShoppingFeatureFlag.ICreate;
  const flag: IShoppingFeatureFlag =
    await api.functional.shopping.admin.featureFlags.create(connection, {
      body: flagInput,
    });
  typia.assert(flag);
  TestValidator.equals(
    "returned flag_name matches input",
    flag.flag_name,
    flagInput.flag_name,
  );
  TestValidator.equals("scope matches", flag.scope, flagInput.scope);
  TestValidator.equals("enabled matches", flag.enabled, flagInput.enabled);
  TestValidator.equals("rollout matches", flag.rollout, flagInput.rollout);
  TestValidator.equals(
    "description matches",
    flag.description,
    flagInput.description,
  );

  TestValidator.predicate(
    "id is uuid",
    typeof flag.id === "string" && flag.id.length > 0,
  );
  TestValidator.predicate(
    "created_at present",
    typeof flag.created_at === "string" && flag.created_at.length > 0,
  );
  TestValidator.predicate(
    "updated_at present",
    typeof flag.updated_at === "string" && flag.updated_at.length > 0,
  );

  // 4. Attempt to create flag with duplicate flag_name
  await TestValidator.error("duplicate flag_name is rejected", async () => {
    await api.functional.shopping.admin.featureFlags.create(connection, {
      body: { ...flagInput },
    });
  });

  // 5. Attempt feature flag creation as unauthenticated (simulate by blank headers)
  const unauthConn: api.IConnection = { ...connection, headers: {} };
  await TestValidator.error(
    "unauthenticated flag creation is denied",
    async () => {
      await api.functional.shopping.admin.featureFlags.create(unauthConn, {
        body: {
          flag_name: `fflag_${RandomGenerator.alphaNumeric(8)}`,
          scope: RandomGenerator.pick([
            "global",
            "orders",
            "checkout",
            "frontend",
          ] as const),
          enabled: true,
          rollout: 80,
          description: RandomGenerator.paragraph({ sentences: 4 }),
        } satisfies IShoppingFeatureFlag.ICreate,
      });
    },
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IPageIShoppingInventory } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIShoppingInventory";
import type { IShoppingAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingAuthorizationToken";
import type { IShoppingInventory } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingInventory";
import type { IShoppingSeller } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingSeller";

/**
 * Verifies the seller inventory listing API with authentication and filtering.
 *
 * 1. Register a new seller to obtain authentication (token automatically issued).
 * 2. Fetch inventory with valid token (general case, no filters).
 * 3. Apply SKU code filter with a random value (should return zero results).
 * 4. Apply quantity range filter (min/max).
 * 5. Test pagination by using limit = 1 and page = 2 (if possible).
 * 6. Attempt to access the endpoint without authentication (should fail).
 * 7. Attempt to access with an invalid token (should fail).
 * 8. For each search/filter, check that only the test seller's inventory is
 *    returned.
 * 9. Assert that pagination fields are consistent and correct.
 * 10. Assert business logic holds for all filters and result sets.
 */
export async function test_api_seller_inventory_index_with_authentication_and_sku_filtering(
  connection: api.IConnection,
) {
  // 1. Register a new seller
  const sellerBody = {
    email: typia.random<string & tags.Format<"email">>(),
    password: RandomGenerator.alphaNumeric(12),
    display_name: RandomGenerator.name(),
    contact_phone: RandomGenerator.mobile(),
    status: "pending",
  } satisfies IShoppingSeller.IJoin;
  const seller = await api.functional.auth.seller.join(connection, {
    body: sellerBody,
  });
  typia.assert(seller);
  const sellerId = seller.id;

  // 2. Fetch inventory (no filters)
  const invReqBase = {
    page: 1 as number & tags.Type<"int32"> & tags.Minimum<1>,
    limit: 5 as number &
      tags.Type<"int32"> &
      tags.Default<20> &
      tags.Minimum<1> &
      tags.Maximum<100>,
  } satisfies IShoppingInventory.IRequest;
  const page1 = await api.functional.shopping.seller.inventory.index(
    connection,
    { body: invReqBase },
  );
  typia.assert(page1);

  // 3. Assert all returned inventory belongs to this seller
  for (const entry of page1.data) {
    TestValidator.equals(
      "seller receives only own inventory",
      sellerId,
      sellerId,
    );
  }
  TestValidator.predicate(
    "pagination current page is as requested",
    page1.pagination.current === 1,
  );
  TestValidator.equals(
    "pagination limit matches request",
    page1.pagination.limit,
    invReqBase.limit,
  );

  // 4. Apply SKU code filter (random SKU: should return none)
  const randomSkuCode = RandomGenerator.alphaNumeric(15);
  const invReqSku = {
    ...invReqBase,
    sku_code: randomSkuCode,
  } satisfies IShoppingInventory.IRequest;
  const skuFiltered = await api.functional.shopping.seller.inventory.index(
    connection,
    { body: invReqSku },
  );
  typia.assert(skuFiltered);
  TestValidator.equals(
    "sku_code filter returns 0 results",
    skuFiltered.data.length,
    0,
  );

  // 5. Apply quantity min/max (edge case, unlikely to match anything; just check API works)
  const invReqQuantity = {
    ...invReqBase,
    min_quantity: 10000 as number & tags.Type<"int32">, // excessively high
    max_quantity: 20000 as number & tags.Type<"int32">, // higher
  } satisfies IShoppingInventory.IRequest;
  const qtyFiltered = await api.functional.shopping.seller.inventory.index(
    connection,
    { body: invReqQuantity },
  );
  typia.assert(qtyFiltered);
  TestValidator.predicate(
    "quantity filter works (result set valid)",
    Array.isArray(qtyFiltered.data),
  );

  // 6. Pagination: limit 1, page 2
  const invReqPage2 = {
    ...invReqBase,
    page: 2,
    limit: 1,
  } satisfies IShoppingInventory.IRequest;
  const paged2 = await api.functional.shopping.seller.inventory.index(
    connection,
    { body: invReqPage2 },
  );
  typia.assert(paged2);
  TestValidator.equals("pagination page is 2", paged2.pagination.current, 2);
  TestValidator.equals("pagination limit is 1", paged2.pagination.limit, 1);

  // 7. Access without token (should fail)
  const unauthConn: api.IConnection = { ...connection, headers: {} };
  await TestValidator.error("denies unauthenticated access", async () => {
    await api.functional.shopping.seller.inventory.index(unauthConn, {
      body: invReqBase,
    });
  });

  // 8. Access with invalid token (should fail)
  const invalidTokenConn: api.IConnection = {
    ...connection,
    headers: { Authorization: "Bearer invalid-token" },
  };
  await TestValidator.error("denies invalid token", async () => {
    await api.functional.shopping.seller.inventory.index(invalidTokenConn, {
      body: invReqBase,
    });
  });
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IShoppingAdmin } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingAdmin";
import type { IShoppingAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingAuthorizationToken";
import type { IShoppingInventory } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingInventory";
import type { IShoppingProduct } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingProduct";
import type { IShoppingSku } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingSku";

/**
 * Test that only an authenticated admin can retrieve inventory details for a
 * SKU by its code and that error and RBAC handling is robust.
 */
export async function test_api_admin_inventory_detail_by_sku_with_auth(
  connection: api.IConnection,
) {
  // 1. Register a new admin (for authentication)
  const adminJoinInput = {
    email: typia.random<string & tags.Format<"email">>(),
    password: RandomGenerator.alphaNumeric(16),
    name: RandomGenerator.name(),
    role: RandomGenerator.pick([
      "super",
      "operator",
      "compliance",
      "support",
    ] as const),
    status: "active",
  } satisfies IShoppingAdmin.IJoin;
  const admin = await api.functional.auth.admin.join(connection, {
    body: adminJoinInput,
  });
  typia.assert(admin);
  TestValidator.predicate(
    "admin join returns valid token",
    typeof admin.token.access === "string" && admin.token.access.length > 0,
  );

  // 2. Attempt to retrieve inventory for a random SKU code (success or not-found)
  const validSkuCode = typia.random<string>();
  let inventory: IShoppingInventory | undefined = undefined;
  try {
    inventory = await api.functional.shopping.admin.inventory.at(connection, {
      skuCode: validSkuCode,
    });
    typia.assert(inventory);
    TestValidator.equals(
      "inventory.sku_code matches input",
      inventory.sku.sku_code,
      validSkuCode,
    );
    TestValidator.predicate(
      "inventory quantity is non-negative",
      inventory.quantity >= 0,
    );
  } catch (_exp) {
    // If SKU does not exist, treat as correct error scenario
    inventory = undefined;
  }

  // 3. Test error for non-existent SKU code
  const notFoundSku = validSkuCode + "-notfound";
  await TestValidator.error("returns error for absent SKU", async () => {
    await api.functional.shopping.admin.inventory.at(connection, {
      skuCode: notFoundSku,
    });
  });

  // 4. Try as unauthenticated (no admin login)
  const unauthConn: api.IConnection = { ...connection, headers: {} };
  await TestValidator.error("unauthenticated access is denied", async () => {
    await api.functional.shopping.admin.inventory.at(unauthConn, {
      skuCode: validSkuCode,
    });
  });
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IShoppingAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingAuthorizationToken";
import type { IShoppingCustomer } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingCustomer";
import type { IShoppingCustomerAddress } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingCustomerAddress";

/**
 * Validate soft-deletion of a customer's saved address by self-removal.
 *
 * 1. Register a customer and retrieve authorization context.
 * 2. Register a new address for this customer.
 * 3. Remove the address using the soft-delete (erase) endpoint.
 * 4. Verify the address deleted_at field is populated in the response.
 * 5. Attempt to remove another customer's address and ensure forbidden.
 */
export async function test_api_customer_address_soft_delete(
  connection: api.IConnection,
) {
  // 1. Register first customer
  const customerEmail = typia.random<string & tags.Format<"email">>();
  const customerRegister = {
    email: customerEmail,
    password: RandomGenerator.alphaNumeric(12),
    name: RandomGenerator.name(),
    phone: RandomGenerator.mobile(),
    href: "https://www.customer-registration.com/",
    referrer: "https://www.landing.com/signup",
  } satisfies IShoppingCustomer.ICreate;
  const customer: IShoppingCustomer.IAuthorized =
    await api.functional.auth.customer.join(connection, {
      body: customerRegister,
    });
  typia.assert(customer);

  // 2. Register address for this customer
  const addressBody = {
    address_line1: RandomGenerator.paragraph({ sentences: 2 }),
    city: RandomGenerator.paragraph({ sentences: 1 }),
    state: RandomGenerator.paragraph({ sentences: 1 }),
    postal_code: RandomGenerator.alphaNumeric(6),
    country: "South Korea",
    is_primary: true,
    phone: RandomGenerator.mobile(),
    recipient_name: RandomGenerator.name(),
  } satisfies IShoppingCustomerAddress.ICreate;
  const address =
    await api.functional.shopping.customer.customers.addresses.create(
      connection,
      {
        customerId: customer.id,
        body: addressBody,
      },
    );
  typia.assert(address);
  TestValidator.equals(
    "address assigned to correct customer after create",
    address.shopping_customer_id,
    customer.id,
  );
  TestValidator.equals(
    "address not soft-deleted upon creation",
    address.deleted_at,
    null,
  );

  // 3. Remove the address (soft-delete)
  const erased =
    await api.functional.shopping.customer.customers.addresses.erase(
      connection,
      {
        customerId: customer.id,
        addressId: address.id,
      },
    );
  typia.assert(erased);
  TestValidator.equals(
    "deleted_at must be populated on erase",
    typeof erased.deleted_at,
    "string",
  );
  TestValidator.notEquals(
    "address info still retrievable by id after soft deletion",
    erased.deleted_at,
    null,
  );
  TestValidator.equals(
    "customer id remains as original",
    erased.shopping_customer_id,
    customer.id,
  );

  // 4. Register a second customer (for prohibited removal test)
  const otherCustomerEmail = typia.random<string & tags.Format<"email">>();
  const otherCustomerRegister = {
    email: otherCustomerEmail,
    password: RandomGenerator.alphaNumeric(12),
    name: RandomGenerator.name(),
    phone: RandomGenerator.mobile(),
    href: "https://www.customer-registration.com/",
    referrer: "https://www.landing.com/signup",
  } satisfies IShoppingCustomer.ICreate;
  const otherCustomer: IShoppingCustomer.IAuthorized =
    await api.functional.auth.customer.join(connection, {
      body: otherCustomerRegister,
    });
  typia.assert(otherCustomer);

  // 5. Register address for the second customer
  const otherAddressBody = {
    address_line1: RandomGenerator.paragraph({ sentences: 2 }),
    city: RandomGenerator.paragraph({ sentences: 1 }),
    state: RandomGenerator.paragraph({ sentences: 1 }),
    postal_code: RandomGenerator.alphaNumeric(6),
    country: "South Korea",
    is_primary: false,
    phone: RandomGenerator.mobile(),
    recipient_name: RandomGenerator.name(),
  } satisfies IShoppingCustomerAddress.ICreate;
  const otherAddress =
    await api.functional.shopping.customer.customers.addresses.create(
      connection,
      {
        customerId: otherCustomer.id,
        body: otherAddressBody,
      },
    );
  typia.assert(otherAddress);
  TestValidator.equals(
    "address assigned to correct customer after create",
    otherAddress.shopping_customer_id,
    otherCustomer.id,
  );

  // 6. Attempt to erase other's address using first customer's context
  await TestValidator.error(
    "forbidden: cannot erase another customer's address",
    async () => {
      await api.functional.shopping.customer.customers.addresses.erase(
        connection,
        {
          customerId: customer.id,
          addressId: otherAddress.id,
        },
      );
    },
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IPageIShoppingCustomerSession } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIShoppingCustomerSession";
import type { IShoppingAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingAuthorizationToken";
import type { IShoppingCustomer } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingCustomer";
import type { IShoppingCustomerSession } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingCustomerSession";

/**
 * Validates that a customer can retrieve their full session history and manage
 * multiple device logins.
 *
 * This test covers full multi-device authentication lifecycle for a customer:
 *
 * 1. Register a new unique customer.
 * 2. Perform multiple (3) logins from distinct device contexts (varying
 *    href/referrer, etc).
 * 3. Retrieve session list via PATCH
 *    /shopping/customer/customers/{customerId}/sessions using correct customer
 *    ID.
 * 4. Confirm all created sessions for this customer are listed, with proper IP,
 *    href, referrer, and created_at metadata.
 * 5. Ensure the pagination works, and filtering by status ('active', 'expired')
 *    returns correct subsets.
 * 6. Security: Attempt to retrieve sessions for another customer; validate access
 *    is denied.
 * 7. Confirm other users' sessions are never present in this customer's session
 *    history.
 */
export async function test_api_customer_sessions_retrieve_by_owner(
  connection: api.IConnection,
) {
  // 1. Register Customer A
  const registerA = {
    email: typia.random<string & tags.Format<"email">>(),
    password: RandomGenerator.alphabets(12),
    name: RandomGenerator.name(),
    phone: RandomGenerator.mobile(),
    href: "https://device-a.example.com", // Simulate device
    referrer: "https://ref.device-a.example.com",
    ip: "192.168.0.10",
  } satisfies IShoppingCustomer.ICreate;
  const customerA = await api.functional.auth.customer.join(connection, {
    body: registerA,
  });
  typia.assert(customerA);

  // 2. Perform two more logins from new devices for customerA (storing all unique session contexts)
  const loginContexts = [
    {
      href: "https://device-b.example.com",
      referrer: "https://ref.device-b.example.com",
      ip: "192.168.0.11",
    },
    {
      href: "https://device-c.example.com",
      referrer: "https://ref.device-c.example.com",
      ip: "192.168.0.12",
    },
  ];
  await ArrayUtil.asyncForEach(loginContexts, async (ctx) => {
    const loginBody = {
      email: registerA.email,
      password: registerA.password,
      href: ctx.href,
      referrer: ctx.referrer,
      ip: ctx.ip,
    } satisfies IShoppingCustomer.ILogin;
    const loginRes = await api.functional.auth.customer.login(connection, {
      body: loginBody,
    });
    typia.assert(loginRes);
  });

  // 3. Fetch session list for Customer A
  const sessionsPage =
    await api.functional.shopping.customer.customers.sessions.index(
      connection,
      {
        customerId: customerA.id,
        body: {},
      },
    );
  typia.assert(sessionsPage);
  TestValidator.predicate(
    "returns at least one session for customer",
    sessionsPage.data.length >= 1,
  );
  sessionsPage.data.forEach((session) => {
    TestValidator.equals(
      "session belongs to correct customer",
      session.shopping_customer_id,
      customerA.id,
    );
    TestValidator.predicate(
      "session has created_at timestamp",
      typeof session.created_at === "string" && session.created_at.length > 0,
    );
    TestValidator.predicate(
      "session has device href",
      typeof session.href === "string" &&
        session.href.startsWith("https://device-"),
    );
    TestValidator.predicate(
      "session IP looks like IPv4",
      typeof session.ip === "string" && session.ip.split(".").length === 4,
    );
  });
  // 4. Validate pagination (limit = 2)
  const paged = await api.functional.shopping.customer.customers.sessions.index(
    connection,
    {
      customerId: customerA.id,
      body: { limit: 2 },
    },
  );
  typia.assert(paged);
  TestValidator.predicate(
    "pagination returns <= 2 records",
    paged.data.length <= 2,
  );
  // 5. Test status filtering
  const activeList =
    await api.functional.shopping.customer.customers.sessions.index(
      connection,
      {
        customerId: customerA.id,
        body: { status: "active" },
      },
    );
  typia.assert(activeList);
  activeList.data.forEach((s) => {
    TestValidator.equals("active session is not expired", s.expired_at, null);
  });
  // 6. Register Customer B
  const registerB = {
    email: typia.random<string & tags.Format<"email">>(),
    password: RandomGenerator.alphabets(12),
    name: RandomGenerator.name(),
    phone: RandomGenerator.mobile(),
    href: "https://device-x.example.com",
    referrer: "https://ref.device-x.example.com",
    ip: "10.0.0.1",
  } satisfies IShoppingCustomer.ICreate;
  const customerB = await api.functional.auth.customer.join(connection, {
    body: registerB,
  });
  typia.assert(customerB);
  // Attempt: Fetch Customer A's sessions while logged in as Customer B (should fail)
  await api.functional.auth.customer.login(connection, {
    body: {
      email: registerB.email,
      password: registerB.password,
      href: registerB.href,
      referrer: registerB.referrer,
      ip: registerB.ip,
    },
  });
  await TestValidator.error(
    "Customer B cannot fetch A's sessions",
    async () => {
      await api.functional.shopping.customer.customers.sessions.index(
        connection,
        {
          customerId: customerA.id,
          body: {},
        },
      );
    },
  );
  // 7. Confirm Customer B only sees their own sessions
  const bSessions =
    await api.functional.shopping.customer.customers.sessions.index(
      connection,
      {
        customerId: customerB.id,
        body: {},
      },
    );
  typia.assert(bSessions);
  bSessions.data.forEach((s) => {
    TestValidator.equals(
      "session belongs to customer B",
      s.shopping_customer_id,
      customerB.id,
    );
  });
}

