  );

  // Ensure no sensitive fields like password_hash are present
  TestValidator.predicate(
    "seller object contains only allowed fields",
    Object.keys(seller).every((k) =>
      [
        "id",
        "email",
        "display_name",
        "contact_phone",
        "status",
        "created_at",
        "updated_at",
