import api from "@ORGANIZATION/PROJECT-api";
import type { IShoppingAdmin } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingAdmin";
import type { IShoppingAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingAuthorizationToken";

/**
 * Validates soft-deletion of split portions of orders by an admin.
 *
 * 1. Authenticate as a new admin account.
 * 2. Attempt to soft-delete (archive) an order split with random orderCode and
 *    splitCode (simulate eligible case).
 * 3. Attempt to soft-delete the same split again (should be denied—already
 *    deleted).
 * 4. Attempt to delete a totally non-existent split (should fail as non-existent).
 * 5. Attempt deletion as a non-admin (simulate by resetting connection headers)
 *    and verify access is denied.
 *
 * Business rules, composite uniqueness, and audit trace are considered by
 * checking error behaviors and only using allowed API.
 */
export async function test_api_order_split_remove_by_admin(
  connection: api.IConnection,
) {
  // 1. Admin registration and authentication
  const joinBody = {
    email: typia.random<string & tags.Format<"email">>(),
    password: RandomGenerator.alphaNumeric(12),
    name: RandomGenerator.name(),
    role: RandomGenerator.pick(["super", "support", "operator"] as const),
    status: "active",
  } satisfies IShoppingAdmin.IJoin;
  const admin: IShoppingAdmin.IAuthorized =
    await api.functional.auth.admin.join(connection, { body: joinBody });
  typia.assert(admin);

  // 2. Attempt soft-delete (archive) on simulated order split by admin (random codes, eligibility cannot be truly verified without create API)
  const orderCode = RandomGenerator.alphaNumeric(10);
  const splitCode = RandomGenerator.alphaNumeric(8);
  await api.functional.shopping.admin.orders.splits.erase(connection, {
    orderCode,
    splitCode,
  });

  // 3. Attempt to delete the same split again (simulate already deleted logic; should throw)
  await TestValidator.error(
    "deleting already deleted order split should fail",
    async () => {
      await api.functional.shopping.admin.orders.splits.erase(connection, {
        orderCode,
        splitCode,
      });
    },
  );

  // 4. Attempt to delete a totally non-existent split (random unused codes)
  const nonExistentOrderCode = RandomGenerator.alphaNumeric(10);
  const nonExistentSplitCode = RandomGenerator.alphaNumeric(8);
  await TestValidator.error(
    "deleting non-existent order split should fail",
    async () => {
      await api.functional.shopping.admin.orders.splits.erase(connection, {
        orderCode: nonExistentOrderCode,
        splitCode: nonExistentSplitCode,
      });
    },
  );

  // 5. Attempt deletion as non-admin (simulate unauth with fresh connection headers: forbidden)
  const unauthConn: api.IConnection = { ...connection, headers: {} };
  await TestValidator.error(
    "non-admin actor should be denied split deletion",
    async () => {
      await api.functional.shopping.admin.orders.splits.erase(unauthConn, {
        orderCode,
        splitCode,
      });
    },
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IPageIShoppingOrderStatusHistory } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIShoppingOrderStatusHistory";
import type { IShoppingAdmin } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingAdmin";
import type { IShoppingAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingAuthorizationToken";
import type { IShoppingOrderStatusHistory } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingOrderStatusHistory";

/**
 * Validates that an admin can access the paginated, filterable status history
 * of an order, filtering by status, actor, and date.
 *
 * Flow:
 *
 * 1. Register and authenticate an admin
 * 2. Use a (random) order code to query the endpoint for paginated status history
 * 3. Validate that standard paged results work
 * 4. Query with filter options (by from_status, to_status, actor, start_date,
 *    end_date)
 * 5. Validate empty result for orders with no transitions
 * 6. Validate error for non-existent orderCode
 */
export async function test_api_order_status_history_paginated_search_by_admin(
  connection: api.IConnection,
) {
  // 1. Register and authenticate an admin
  const adminJoinBody = {
    email: typia.random<string & tags.Format<"email">>(),
    password: RandomGenerator.alphaNumeric(12),
    name: RandomGenerator.name(),
    role: RandomGenerator.pick([
      "super",
      "support",
      "compliance",
      "operator",
    ] as const),
    status: RandomGenerator.pick(["active", "pending", "suspended"] as const),
  } satisfies IShoppingAdmin.IJoin;
  const admin = await api.functional.auth.admin.join(connection, {
    body: adminJoinBody,
  });
  typia.assert(admin);

  // 2. Create a hypothetical (random) order code for positive test
  const orderCode: string = RandomGenerator.alphaNumeric(14);

  // 3. Search with no filters (all history, default)
  const allHistory =
    await api.functional.shopping.admin.orders.status_history.index(
      connection,
      {
        orderCode,
        body: {
          page: 1 as number & tags.Type<"int32">,
          limit: 10 as number & tags.Type<"int32">,
        },
      },
    );
  typia.assert(allHistory);
  TestValidator.equals(
    "paginated data returned",
    Array.isArray(allHistory.data),
    true,
  );
  TestValidator.equals(
    "pagination structure valid",
    typeof allHistory.pagination === "object",
    true,
  );

  // 4. Try filtered search by from_status
  const filterStatus = "pending";
  const statusFiltered =
    await api.functional.shopping.admin.orders.status_history.index(
      connection,
      {
        orderCode,
        body: {
          page: 1 as number & tags.Type<"int32">,
          limit: 5 as number & tags.Type<"int32">,
          from_status: filterStatus,
        },
      },
    );
  typia.assert(statusFiltered);
  if (statusFiltered.data.length > 0) {
    for (const hist of statusFiltered.data) {
      TestValidator.equals(
        "status filtered correctly",
        hist.from_status,
        filterStatus,
      );
    }
  }

  // 5. Try filtered by actor and date range
  const filterActor = "admin";
  const nowISO = new Date().toISOString();
  const actorDateFiltered =
    await api.functional.shopping.admin.orders.status_history.index(
      connection,
      {
        orderCode,
        body: {
          page: 1 as number & tags.Type<"int32">,
          limit: 2 as number & tags.Type<"int32">,
          actor: filterActor,
          start_date: nowISO,
          end_date: nowISO,
        },
      },
    );
  typia.assert(actorDateFiltered);
  if (actorDateFiltered.data.length > 0) {
    for (const item of actorDateFiltered.data) {
      TestValidator.equals("filtered by actor", item.triggered_by, filterActor);
      TestValidator.predicate(
        "date filter applies",
        item.occurred_at >= nowISO && item.occurred_at <= nowISO,
      );
    }
  }

  // 6. Query for an orderCode that has no transitions
  const emptyOrderCode = RandomGenerator.alphaNumeric(16);
  const emptyHistory =
    await api.functional.shopping.admin.orders.status_history.index(
      connection,
      {
        orderCode: emptyOrderCode,
        body: {
          page: 1 as number & tags.Type<"int32">,
          limit: 3 as number & tags.Type<"int32">,
        },
      },
    );
  typia.assert(emptyHistory);
  TestValidator.equals(
    "no transitions yields empty array",
    emptyHistory.data.length,
    0,
  );

  // 7. Error case: non-existent orderCode
  await TestValidator.error("non-existent orderCode should error", async () => {
    await api.functional.shopping.admin.orders.status_history.index(
      connection,
      {
        orderCode: "__NO_SUCH_ORDER_CODE__",
        body: {
          page: 1 as number & tags.Type<"int32">,
          limit: 1 as number & tags.Type<"int32">,
        },
      },
    );
  });
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IPageIShoppingShipment } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIShoppingShipment";
import type { IShoppingAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingAuthorizationToken";
import type { IShoppingSeller } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingSeller";
import type { IShoppingShipment } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingShipment";

/**
 * Validate advanced shipment search for an authenticated seller.
 *
 * This test covers the workflow for a seller to register, authenticate, and
 * then perform a search for their shipments using advanced filters and
 * pagination. The steps include:
 *
 * 1. Register a new seller (join as a seller)
 * 2. Perform shipment search with basic pagination as the authenticated seller
 * 3. Search with various filters including carrier company, status, and scheduled
 *    dispatch date range
 * 4. Validate that only shipments belonging to the authenticated seller are
 *    returned in the results
 * 5. Ensure that pagination and sort ordering work as expected (via multi-page
 *    requests)
 * 6. Attempt searching for unowned shipments and validate that such shipments are
 *    not returned
 */
export async function test_api_seller_shipment_search_with_authentication(
  connection: api.IConnection,
) {
  // 1. Register a new seller for authentication
  const sellerEmail = typia.random<string & tags.Format<"email">>();
  const sellerPassword = RandomGenerator.alphaNumeric(12);
  const sellerDisplayName = RandomGenerator.name();
  const sellerContactPhone = RandomGenerator.mobile();
  const seller: IShoppingSeller.IAuthorized =
    await api.functional.auth.seller.join(connection, {
      body: {
        email: sellerEmail,
        password: sellerPassword,
        display_name: sellerDisplayName,
        contact_phone: sellerContactPhone,
        status: "pending",
      } satisfies IShoppingSeller.IJoin,
    });
  typia.assert(seller);

  // 2. Search for shipments as the authenticated seller - basic default search
  const requestBase = {
    page: 1 as number & tags.Type<"int32"> & tags.Minimum<1>,
  } satisfies IShoppingShipment.IRequest;
  const baseResult = await api.functional.shopping.seller.shipments.index(
    connection,
    {
      body: requestBase,
    },
  );
  typia.assert(baseResult);
  TestValidator.equals(
    "pagination information exists",
    typeof baseResult.pagination,
    "object",
  );
  TestValidator.equals("data is array", Array.isArray(baseResult.data), true);

  // 3. Search shipments with specific status filter (even if possibly empty)
  const requestStatus = {
    page: 1 as number & tags.Type<"int32"> & tags.Minimum<1>,
    status: "pending",
  } satisfies IShoppingShipment.IRequest;
  const statusResult = await api.functional.shopping.seller.shipments.index(
    connection,
    {
      body: requestStatus,
    },
  );
  typia.assert(statusResult);
  if (statusResult.data.length > 0)
    for (const shipment of statusResult.data) {
      TestValidator.equals(
        "shipment belongs to authenticated seller",
        shipment.shopping_seller_id,
        seller.id,
      );
      TestValidator.equals("status is as filtered", shipment.status, "pending");
    }

  // 4. Search by carrier company (random string value)
  const carrierCompany = RandomGenerator.paragraph({
    sentences: 1,
    wordMin: 4,
    wordMax: 8,
  });
  const requestCarrier = {
    page: 1 as number & tags.Type<"int32"> & tags.Minimum<1>,
    carrier_company: carrierCompany,
  } satisfies IShoppingShipment.IRequest;
  const carrierResult = await api.functional.shopping.seller.shipments.index(
    connection,
    {
      body: requestCarrier,
    },
  );
  typia.assert(carrierResult);
  for (const shipment of carrierResult.data) {
    TestValidator.equals(
      "shipment belongs to authenticated seller",
      shipment.shopping_seller_id,
      seller.id,
    );
    TestValidator.equals(
      "carrier company matches filter",
      shipment.carrier_company,
      carrierCompany,
    );
  }

  // 5. Search by scheduled dispatch date range (next week)
  const now = new Date();
  const from = new Date(now.getTime() + 1000 * 60 * 60 * 24 * 1).toISOString(); // 1 day from now
  const to = new Date(now.getTime() + 1000 * 60 * 60 * 24 * 7).toISOString(); // 7 days from now
  const requestDateRange = {
    page: 1 as number & tags.Type<"int32"> & tags.Minimum<1>,
    scheduled_dispatch_at_from: from,
    scheduled_dispatch_at_to: to,
  } satisfies IShoppingShipment.IRequest;
  const dateRangeResult = await api.functional.shopping.seller.shipments.index(
    connection,
    {
      body: requestDateRange,
    },
  );
  typia.assert(dateRangeResult);
  for (const shipment of dateRangeResult.data) {
    TestValidator.equals(
      "shipment belongs to authenticated seller (date range)",
      shipment.shopping_seller_id,
      seller.id,
    );
    if (
      shipment.scheduled_dispatch_at !== null &&
      shipment.scheduled_dispatch_at !== undefined
    ) {
      TestValidator.predicate(
        "scheduled_dispatch_at in [from, to]",
        shipment.scheduled_dispatch_at >= from &&
          shipment.scheduled_dispatch_at <= to,
      );
    }
  }

  // 6. Pagination and sort order test: fetch two pages (if available)
  const limitForPagination = 2 as number &
    tags.Type<"int32"> &
    tags.Minimum<1> &
    tags.Maximum<100>;
  const pagedResult1 = await api.functional.shopping.seller.shipments.index(
    connection,
    {
      body: {
        page: 1,
        limit: limitForPagination,
        sort_field: "created_at",
        sort_order: "asc",
      } satisfies IShoppingShipment.IRequest,
    },
  );
  typia.assert(pagedResult1);
  const pagedResult2 = await api.functional.shopping.seller.shipments.index(
    connection,
    {
      body: {
        page: 2,
        limit: limitForPagination,
        sort_field: "created_at",
        sort_order: "asc",
      } satisfies IShoppingShipment.IRequest,
    },
  );
  typia.assert(pagedResult2);
  if (pagedResult1.data.length > 0 && pagedResult2.data.length > 0) {
    TestValidator.notEquals(
      "pagination separation",
      pagedResult1.data[0],
      pagedResult2.data[0],
    );
  }
  for (const shipment of pagedResult1.data.concat(pagedResult2.data)) {
    TestValidator.equals(
      "shipment belongs to authenticated seller (pagination)",
      shipment.shopping_seller_id,
      seller.id,
    );
  }
  // 7. Verify that shipments for other sellers are not returned (use random seller_id filter)
  const fakeSellerId = typia.random<string & tags.Format<"uuid">>();
  const otherSellerRequest = {
    page: 1 as number & tags.Type<"int32"> & tags.Minimum<1>,
    seller_id: fakeSellerId,
  } satisfies IShoppingShipment.IRequest;
  const otherSellerResult =
    await api.functional.shopping.seller.shipments.index(connection, {
      body: otherSellerRequest,
    });
  typia.assert(otherSellerResult);
  for (const shipment of otherSellerResult.data) {
    TestValidator.equals(
      "filtering by unowned seller returns none or only other seller's shipment",
      shipment.shopping_seller_id,
      fakeSellerId,
    );
  }
}

