  const pkg: IShoppingShipmentPackage =
    typia.random<IShoppingShipmentPackage>();
  typia.assert(pkg);

  // 3. Use correct code and packageLabel to fetch
  const result = await api.functional.shopping.seller.shipments.packages.at(
    connection,
