/**
 * Customer retrieves all refund approval/rejection audit log entries for their
 * own refund request.
 *
 * This test covers: customer registration, seller registration & product/SKU
 * creation, order placing, refund initiation, and then customer fetches all
 * approval log entries for that refund via PATCH
 * /shopping/customer/refunds/{refundRequestId}/approvals. It validates (a)
 * successful response structure and typing, (b) correct access control
 * visibility, and (c) that all entries represent only admin/seller approval
 * actions (not system/customer actions).
 */
export async function test_api_refund_approvals_retrieval_by_customer(
  connection: api.IConnection,
) {
  // 1. Register new customer
  const customerEmail = RandomGenerator.alphaNumeric(10) + "@testmail.com";
  const customer: IShoppingCustomer.IAuthorized =
    await api.functional.auth.customer.join(connection, {
      body: {
        email: customerEmail,
        password: RandomGenerator.alphaNumeric(12),
        name: RandomGenerator.name(),
        phone: RandomGenerator.mobile(),
        href: "https://testdomain.com/ref",
        referrer: "https://testdomain.com/register",
      },
    });
  typia.assert(customer);

  // 2. Register seller
  const sellerEmail = RandomGenerator.alphaNumeric(10) + "@testmail.com";
  const seller: IShoppingSeller.IAuthorized =
    await api.functional.auth.seller.join(connection, {
      body: {
        email: sellerEmail,
        password: "S3ll3rP@ssw0rd!",
        display_name: RandomGenerator.name(),
        contact_phone: RandomGenerator.mobile(),
        status: "pending",
      },
    });
  typia.assert(seller);

  // 3. Seller creates a product
  const productCode = RandomGenerator.alphaNumeric(8);
  const product: IShoppingProduct =
    await api.functional.shopping.seller.products.create(connection, {
      body: {
        code: productCode,
        name: RandomGenerator.paragraph({
          sentences: 3,
          wordMin: 4,
          wordMax: 9,
        }),
        description: RandomGenerator.content({ paragraphs: 2 }),
        main_image_uri:
          "https://cdn.example.com/prod/" +
          RandomGenerator.alphaNumeric(8) +
          ".jpg",
        status: "active",
        business_status: "in_review",
      },
    });
  typia.assert(product);

  // 4. Seller creates SKU for product - fix: variant_attribute_value_ids must have at least 1 id
  const skuCode = RandomGenerator.alphaNumeric(12);
  const variantAttributeId = typia.random<string & tags.Format<"uuid">>();
  const sku: IShoppingSku =
    await api.functional.shopping.seller.products.skus.create(connection, {
      productCode: product.code,
      body: {
        sku_code: skuCode,
        price: 9900,
        is_active: true,
        status: "in_stock",
        variant_attribute_value_ids: [variantAttributeId],
      },
    });
  typia.assert(sku);

  // 5. Customer places an order
  const shippingAddress = {
    type: "shipping" as const,
    recipient_name: RandomGenerator.name(),
    recipient_phone: RandomGenerator.mobile(),
    zip_code: RandomGenerator.alphaNumeric(5),
    base_address: RandomGenerator.paragraph({ sentences: 2 }),
    detail_address: RandomGenerator.paragraph({ sentences: 2 }),
    city: "Seoul",
    state_province: "Seoul",
    country: "South Korea",
  };
  const order: IShoppingOrder =
    await api.functional.shopping.customer.orders.create(connection, {
      body: {
        total_price: sku.price,
        order_lines: [
          {
            shopping_sku_id: sku.id,
            quantity: 1,
            unit_price: sku.price,
          },
        ],
        shipping_addresses: [shippingAddress],
        payment_method: "CARD",
      },
    });
  typia.assert(order);

  // 6. Customer submits a refund request
  const refund: IShoppingRefundRequest =
    await api.functional.shopping.customer.refunds.create(connection, {
      body: {
        shopping_order_id: order.id,
        request_type: "refund",
        business_reason: "Item not working",
        items: [
          {
            shopping_order_id: order.id,
            shopping_order_line_id: order.order_lines[0].id,
            quantity: 1,
          },
        ],
      },
    });
  typia.assert(refund);

  // 7. Customer fetches refund approval records (audit actions by admin/seller for this refund)
  const page: IPageIShoppingRefundApproval.ISummary =
    await api.functional.shopping.customer.refunds.approvals.index(connection, {
      refundRequestId: refund.id,
      body: {
        page: 1,
        pageSize: 20,
      },
    });
  typia.assert(page);

  // Basic validations
  TestValidator.equals(
    "refund approvals request returns correct refundRequestId for all entries",
    page.data.every((x) => x.shopping_refund_request_id === refund.id),
    true,
  );
  TestValidator.predicate(
    "refund approvals result type is array",
    Array.isArray(page.data),
  );
  // All actor_type must be either 'admin' or 'seller'
  TestValidator.equals(
    "all refund approval entries should have actor_type as admin or seller",
    page.data.every((x) => ["admin", "seller"].includes(x.actor_type)),
    true,
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IPageIShoppingAppeal } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIShoppingAppeal";
import type { IShoppingAdmin } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingAdmin";
import type { IShoppingAppeal } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingAppeal";
import type { IShoppingAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingAuthorizationToken";

/**
 * Test that an admin can search and retrieve paginated, filtered list of all
 * appeals.
 *
 * Validates:
 *
 * 1. Admin is registered and authenticated for privileged appeal search.
 * 2. Appeal list is returned successfully when filters for status/type/date are
 *    provided.
 * 3. Result adheres to administrator scope and correct pagination/sorting.
 * 4. API returns a response conforming to IPageIShoppingAppeal.ISummary DTO.
 *
 * Steps:
 *
 * 1. Register a new admin account (prerequisite for authentication).
 * 2. Test /shopping/admin/appeals with full/partial filters and valid input.
 * 3. Validate response structure, business logic and pagination.
 */
export async function test_api_admin_appeals_index_success(
  connection: api.IConnection,
) {
  // 1. Register admin for authentication
  const adminJoinBody = {
    email: typia.random<string & tags.Format<"email">>(),
    password: RandomGenerator.alphaNumeric(12),
    name: RandomGenerator.name(),
    role: RandomGenerator.pick([
      "super",
      "support",
      "compliance",
      "operator",
    ] as const),
    status: "active",
  } satisfies IShoppingAdmin.IJoin;
  const admin: IShoppingAdmin.IAuthorized =
    await api.functional.auth.admin.join(connection, { body: adminJoinBody });
  typia.assert(admin);

  // 2. Prepare advanced filters for appeal search
  // Generate random/status/type/filer_actor_type filters
  const filters: IShoppingAppeal.IRequest[] = [
    {
      status: RandomGenerator.pick([
        "filed",
        "under_review",
        "approved",
        "rejected",
        "closed",
        "escalated",
      ] as const),
      type: RandomGenerator.pick([
        "suspension",
        "policy_violation",
        "account_action",
      ] as const),
      filer_actor_type: RandomGenerator.pick([
        "customer",
        "seller",
        "admin",
      ] as const),
      page: 1,
      limit: 10,
      sort_by: RandomGenerator.pick([
        "created_at",
        "status",
        "decision_at",
      ] as const),
      sort_direction: RandomGenerator.pick(["asc", "desc"] as const),
    },
    {
      // Partial filter - date range only
      created_from: new Date(
        Date.now() - 1000 * 60 * 60 * 24 * 30,
      ).toISOString(), // 30 days ago
      created_to: new Date().toISOString(),
      page: 1,
      limit: 5,
    },
    {
      // Empty filter - all results scoped by admin
      page: 1,
      limit: 20,
    },
  ];

  // 3. Test each filter, validate paginated response
  for (const idx in filters) {
    const req = filters[idx as any];
    const res: IPageIShoppingAppeal.ISummary =
      await api.functional.shopping.admin.appeals.index(connection, {
        body: req,
      });
    typia.assert(res);
    // Check pagination info
    TestValidator.predicate(
      `pagination present on response #${idx}`,
      res.pagination !== undefined &&
        typeof res.pagination.current === "number" &&
        typeof res.pagination.limit === "number",
    );
    // Validate that data is an array
    TestValidator.predicate(
      `appeal data is array on response #${idx}`,
      Array.isArray(res.data),
    );
    // Validate each item matches ISummary
    for (const a of res.data) {
      typia.assert<IShoppingAppeal.ISummary>(a);
      TestValidator.predicate(
        `appeal summary must have id for response #${idx}`,
        typeof a.id === "string" && a.id.length > 0,
      );
      TestValidator.predicate(
        `appeal summary status valid for response #${idx}`,
        typeof a.status === "string" && a.status.length > 0,
      );
      TestValidator.predicate(
        `appeal summary type valid for response #${idx}`,
        typeof a.type === "string" && a.type.length > 0,
      );
    }
  }
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IPageIShoppingAppeal } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIShoppingAppeal";
import type { IShoppingAppeal } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingAppeal";
import type { IShoppingAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingAuthorizationToken";
import type { IShoppingSeller } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingSeller";

/**
 * Test that a seller can retrieve a paginated, filtered list of appeals that
 * they have initiated.
 *
 * This test registers a new seller, authenticates as that seller, and issues an
 * appeals index query with a variety of filter, search, and sort options. It
 * then validates that:
 *
 * 1. Only appeals where the filer_actor_id matches the authenticated seller's id
 *    are returned
 * 2. Pagination metadata is present and correct for the response
 * 3. All returned appeals match the requested filter/search criteria
 * 4. All results are within the requested page limit
 * 5. The list is sorted by the requested field and direction
 */
export async function test_api_seller_appeals_index_success(
  connection: api.IConnection,
) {
  // 1. Register a new seller and get their id
  const joinInput = {
    email: typia.random<string & tags.Format<"email">>(),
    password: RandomGenerator.alphaNumeric(12),
    display_name: RandomGenerator.name(2),
    contact_phone: RandomGenerator.mobile(),
    status: "pending",
  } satisfies IShoppingSeller.IJoin;
  const seller = await api.functional.auth.seller.join(connection, {
    body: joinInput,
  });
  typia.assert(seller);
  const sellerId = seller.id;

  // 2. Build a request body for appeals index using the seller's id as filer_actor_id
  const filterBody = {
    filer_actor_id: sellerId,
    filer_actor_type: "seller",
    page: 1 as number & tags.Type<"int32">,
    limit: 10 as number & tags.Type<"int32">,
    // Optional advanced filters:
    status: undefined,
    type: undefined,
    decision: undefined,
    affected_actor_type: undefined,
    affected_actor_id: undefined,
    appeal_of_policy_violation_id: undefined,
    appeal_of_suspension_id: undefined,
    created_from: undefined,
    created_to: undefined,
    decision_from: undefined,
    decision_to: undefined,
    search: undefined,
    sort_by: "created_at",
    sort_direction: "desc",
  } satisfies IShoppingAppeal.IRequest;

  // 3. Search (index) - call the seller appeals index API endpoint
  const result = await api.functional.shopping.seller.appeals.index(
    connection,
    { body: filterBody },
  );
  typia.assert(result);
  TestValidator.predicate(
    "all appeals must have filer_actor_id equal to the authenticated seller's id",
    result.data.every((appeal) => appeal.filer_actor_id === sellerId),
  );

  // 4. Validate pagination information
  const pagination = result.pagination;
  TestValidator.predicate("current page should be 1", pagination.current === 1);
  TestValidator.predicate("page limit should be 10", pagination.limit === 10);

  // 5. Validate that list size does not exceed limit
  TestValidator.predicate(
    "number of items never exceeds limit",
    result.data.length <= filterBody.limit,
  );

  // 6. Validate sorting (descending by created_at)
  const sorted = Array.from(result.data).sort((a, b) =>
    b.created_at.localeCompare(a.created_at),
  );
  TestValidator.equals(
    "results are sorted descending by created_at",
    result.data.map((a) => a.id),
    sorted.map((a) => a.id),
  );

  // 7. (Optional) Validate that all data (appeal summaries) conform to schema
  result.data.forEach((item) => typia.assert(item));
}

