import api from "@ORGANIZATION/PROJECT-api";
import type { IShoppingAdmin } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingAdmin";
import type { IShoppingAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingAuthorizationToken";

/**
 * Validate deletion attempt of a non-existent business constraint by an admin.
 *
 * This e2e test ensures that when an admin tries to soft delete a business
 * constraint with a constraintName that does not exist, the backend returns a
 * business policy error and does not process any soft delete operation, thereby
 * ensuring idempotence and correct business logic.
 *
 * 1. Register a random admin account using api.functional.auth.admin.join.
 * 2. Attempt to soft delete a business constraint via
 *    api.functional.shopping.admin.businessConstraints.erase, using a randomly
 *    generated string for constraintName (minimize the chance it’s present in
 *    the db).
 * 3. Assert that the erase call fails (throws an error) as the constraint does not
 *    exist, using TestValidator.error.
 * 4. (Comment only) Optionally, if backend exposes audit logging via API, verify
 *    the failed event is logged.
 */
export async function test_api_admin_business_constraint_soft_delete_nonexistent_constraint(
  connection: api.IConnection,
) {
  // 1. Register a random admin
  const adminJoinBody = {
    email: typia.random<string & tags.Format<"email">>(),
    password: typia.random<string & tags.MinLength<8> & tags.MaxLength<128>>(),
    name: RandomGenerator.name(),
    role: RandomGenerator.pick([
      "super",
      "support",
      "compliance",
      "operator",
    ] as const),
    status: RandomGenerator.pick([
      "active",
      "pending",
      "suspended",
      "locked",
    ] as const),
  } satisfies IShoppingAdmin.IJoin;

  const adminAuthorized: IShoppingAdmin.IAuthorized =
    await api.functional.auth.admin.join(connection, { body: adminJoinBody });
  typia.assert(adminAuthorized);

  // 2. Attempt to delete a non-existent business constraint
  const randomConstraintName = `${RandomGenerator.alphaNumeric(24)}-notfound`; // Reduce collision chance
  await TestValidator.error(
    "deleting non-existent business constraint should fail",
    async () => {
      await api.functional.shopping.admin.businessConstraints.erase(
        connection,
        {
          constraintName: randomConstraintName,
        },
      );
    },
  );

  // 3. (Optionally) Audit log assertion
  // NOTE: If the backend exposes audit trail APIs, query for an entry containing
  //   constraintName: randomConstraintName and eventType: "DELETE_ATTEMPT_FAILED"
  //   to confirm audit trail for compliance. Not implemented here due to lacking SDK.
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IShoppingAdmin } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingAdmin";
import type { IShoppingAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingAuthorizationToken";
import type { IShoppingBusinessConstraint } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingBusinessConstraint";

/**
 * Test that an administrator cannot delete a business constraint that is
 * required by another business policy or essential system logic.
 *
 * Steps:
 *
 * 1. Register and authenticate as an admin user.
 * 2. Create a new business constraint with a unique constraint_name.
 * 3. Attempt to delete that constraint (simulate dependency by assuming all
 *    constraints are protected upon creation).
 * 4. Assert that the deletion is rejected with a meaningful business error, and
 *    the constraint remains active.
 */
export async function test_api_admin_business_constraint_soft_delete_with_dependency(
  connection: api.IConnection,
) {
  // 1. Register and authenticate as admin
  const adminEmail = RandomGenerator.name(1) + "@business-domain.com";
  const admin: IShoppingAdmin.IAuthorized =
    await api.functional.auth.admin.join(connection, {
      body: {
        email: adminEmail,
        password: RandomGenerator.alphaNumeric(12),
        name: RandomGenerator.name(),
        role: "super",
        status: "active",
      },
    });
  typia.assert(admin);

  // 2. Create a business constraint with unique name
  const constraintName = RandomGenerator.alphaNumeric(12);
  const constraint: IShoppingBusinessConstraint =
    await api.functional.shopping.admin.businessConstraints.create(connection, {
      body: {
        constraint_name: constraintName,
        scope: "checkout",
        limit_value: "10",
        unit: "count",
        description: RandomGenerator.paragraph({ sentences: 6 }),
        active: true,
      },
    });
  typia.assert(constraint);

  // 3. Attempt to delete the constraint - it should fail due to simulated dependency
  await TestValidator.error(
    "should not allow deletion of a business constraint that is required by dependency",
    async () => {
      await api.functional.shopping.admin.businessConstraints.erase(
        connection,
        {
          constraintName: constraintName,
        },
      );
    },
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IPageIShoppingFeatureFlag } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIShoppingFeatureFlag";
import type { IShoppingAdmin } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingAdmin";
import type { IShoppingAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingAuthorizationToken";
import type { IShoppingFeatureFlag } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingFeatureFlag";

/**
 * Validate admin feature flag listing with pagination and filters.
 *
 * This scenario tests the PATCH /shopping/admin/featureFlags endpoint for
 * retrieving feature flags with full pagination and advanced filtering as an
 * admin. The business purpose is to ensure that the admin can search and view
 * feature flag records reliably by all filtering and sorting options, with
 * precise control over visibility and scope.
 *
 * Steps:
 *
 * 1. Register as an admin and obtain authentication using unique email and
 *    appropriate role per RBAC policy.
 * 2. Create several feature flags with distinct values for flag_name, scope,
 *    enabled state, rollout percentage, and description to serve as test data
 *    spanning multiple filter cases. Use a mix of enabled/disabled states,
 *    different flag_name patterns, scopes (e.g., 'global', 'checkout',
 *    'orders'), and some with rollout set, some without.
 * 3. Exercise feature flag listing with PATCH /shopping/admin/featureFlags for: a.
 *    List all feature flags paginated (default sort, page/limit=2) and validate
 *    both content and accurate pagination meta. b. Filter for a specific
 *    flag_name substring (should match those containing the substring
 *    regardless of position/case). c. Filter by scope (e.g., "global"). d.
 *    Filter by enabled status (true and false), confirming only the correct
 *    subset is returned in each. e. Combine filters for flag_name + scope +
 *    enabled. f. Apply custom sort order (e.g., by created_at desc) and
 *    validate that results are sorted accordingly. g. Test result pagination
 *    (use page > 1 and check subset is correct).
 * 4. For each search, verify:
 *
 *    - Returned feature flag summaries match criteria (all fields correct, data
 *         types match, no extra/missing fields).
 *    - Pagination meta values are accurate relative to the created sample.
 *    - Sorting respects the requested order.
 * 5. [Note] Audit trail validation is out of scope for automated E2E assertion but
 *    described for completeness: ensure that flag search by an admin is
 *    properly audit-logged.
 *
 * This E2E test ensures robust searchability and manageability of the feature
 * flag system for admin operators, confirming key business requirements for
 * controlled operations and configurability.
 */
export async function test_api_feature_flags_admin_index_pagination_filtering(
  connection: api.IConnection,
) {
  // 1. Register as admin
  const email = typia.random<string & tags.Format<"email">>();
  const admin = await api.functional.auth.admin.join(connection, {
    body: {
      email,
      password: RandomGenerator.alphaNumeric(10) + "!A1b",
      name: RandomGenerator.name(),
      role: "superadmin",
      status: "active",
    } satisfies IShoppingAdmin.IJoin,
  });
  typia.assert(admin);
  TestValidator.equals("registered admin email matches", admin.email, email);

  // 2. Create feature flags with different combinations
  const scopes = ["global", "checkout", "orders"] as const;
  const flagTemplates = [
    { flag: "alpha_feature", enabled: true, scope: "global", rollout: null },
    { flag: "beta_flag", enabled: false, scope: "checkout", rollout: 50 },
    { flag: "gamma_switch", enabled: true, scope: "orders", rollout: 75 },
    { flag: "delta_toggle", enabled: false, scope: "global", rollout: null },
    { flag: "epsilon_option", enabled: true, scope: "checkout", rollout: null },
    { flag: "zeta_feature", enabled: false, scope: "orders", rollout: 30 },
  ] as const;
  const created: IShoppingFeatureFlag[] = [];
  for (const t of flagTemplates) {
    const createdFlag = await api.functional.shopping.admin.featureFlags.create(
      connection,
      {
        body: {
          flag_name: t.flag,
          scope: t.scope,
          enabled: t.enabled,
          rollout: t.rollout,
          description: `${t.flag} for ${t.scope} (${t.enabled ? "ON" : "OFF"})`,
        } satisfies IShoppingFeatureFlag.ICreate,
      },
    );
    typia.assert(createdFlag);
    created.push(createdFlag);
  }

  // 3a. List all feature flags paginated (page 1, limit 2)
  let res = await api.functional.shopping.admin.featureFlags.index(connection, {
    body: {
      page: 1 as number & tags.Type<"int32"> & tags.Minimum<1>,
      limit: 2 as number &
        tags.Type<"int32"> &
        tags.Minimum<1> &
        tags.Maximum<100>,
    } satisfies IShoppingFeatureFlag.IRequest,
  });
  typia.assert(res);
  TestValidator.predicate(
    "page 1 returns at most 2 flags",
    res.data.length <= 2,
  );
  TestValidator.equals("page 1 current", res.pagination.current, 1);
  TestValidator.equals("page 1 limit", res.pagination.limit, 2);
  TestValidator.predicate(
    "page 1 total records >= 6",
    res.pagination.records >= created.length,
  );
  TestValidator.predicate("page 1 total pages >= 3", res.pagination.pages >= 3);

  // 3b. Filter by flag_name substring
  const flagSubstring = "flag";
  res = await api.functional.shopping.admin.featureFlags.index(connection, {
    body: { flagName: flagSubstring } satisfies IShoppingFeatureFlag.IRequest,
  });
  typia.assert(res);
  const expectedFlags = created.filter((f) =>
    f.flag_name.includes(flagSubstring),
  );
  for (const flag of res.data) {
    TestValidator.predicate(
      `flag_name contains '${flagSubstring}'`,
      flag.flag_name.includes(flagSubstring),
    );
  }
  TestValidator.predicate(
    "at least all created flags with substring found",
    res.data.length >= expectedFlags.length,
  );

  // 3c. Filter by scope ("global")
  const scope = "global";
  res = await api.functional.shopping.admin.featureFlags.index(connection, {
    body: { scope } satisfies IShoppingFeatureFlag.IRequest,
  });
  typia.assert(res);
  const expectedByScope = created.filter((f) => f.scope === scope);
  for (const flag of res.data) {
    TestValidator.equals("flag.scope = filtered scope", flag.scope, scope);
  }
  TestValidator.predicate(
    `all expected by scope found`,
    res.data.length >= expectedByScope.length,
  );

  // 3d. Filter by enabled (true)
  res = await api.functional.shopping.admin.featureFlags.index(connection, {
    body: { enabled: true } satisfies IShoppingFeatureFlag.IRequest,
  });
  typia.assert(res);
  for (const flag of res.data) {
    TestValidator.equals("flag.enabled is true", flag.enabled, true);
  }
  // Do the same with enabled: false
  res = await api.functional.shopping.admin.featureFlags.index(connection, {
    body: { enabled: false } satisfies IShoppingFeatureFlag.IRequest,
  });
  typia.assert(res);
  for (const flag of res.data) {
    TestValidator.equals("flag.enabled is false", flag.enabled, false);
  }

  // 3e. Combine filters: flagName+scope+enabled
  const combinedFlag = flagTemplates[1];
  res = await api.functional.shopping.admin.featureFlags.index(connection, {
    body: {
      flagName: combinedFlag.flag,
      scope: combinedFlag.scope,
      enabled: combinedFlag.enabled,
    } satisfies IShoppingFeatureFlag.IRequest,
  });
  typia.assert(res);
  for (const flag of res.data) {
    TestValidator.equals(
      "flag.flag_name matches",
      flag.flag_name,
      combinedFlag.flag,
    );
    TestValidator.equals("flag.scope matches", flag.scope, combinedFlag.scope);
    TestValidator.equals(
      "flag.enabled matches",
      flag.enabled,
      combinedFlag.enabled,
    );
  }

  // 3f. Sort by created_at desc, ensure results are sorted
  res = await api.functional.shopping.admin.featureFlags.index(connection, {
    body: {
      sortBy: "created_at",
      order: "desc",
    } satisfies IShoppingFeatureFlag.IRequest,
  });
  typia.assert(res);
  for (let i = 1; i < res.data.length; ++i) {
    TestValidator.predicate(
      "created_at descending sort",
      res.data[i - 1].created_at >= res.data[i].created_at,
    );
  }

  // 3g. Pagination page 2
  res = await api.functional.shopping.admin.featureFlags.index(connection, {
    body: {
      page: 2 as number & tags.Type<"int32"> & tags.Minimum<1>,
      limit: 2 as number &
        tags.Type<"int32"> &
        tags.Minimum<1> &
        tags.Maximum<100>,
    } satisfies IShoppingFeatureFlag.IRequest,
  });
  typia.assert(res);
  TestValidator.equals("page 2 current", res.pagination.current, 2);
  TestValidator.equals("page 2 limit", res.pagination.limit, 2);
  TestValidator.predicate(
    "page 2 records >= 0 and <=2",
    0 <= res.data.length && res.data.length <= 2,
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IShoppingAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingAuthorizationToken";
import type { IShoppingCustomer } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingCustomer";
import type { IShoppingOrder } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingOrder";
import type { IShoppingOrderAddress } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingOrderAddress";
import type { IShoppingOrderLine } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingOrderLine";
import type { IShoppingOrderLineFulfillment } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingOrderLineFulfillment";
import type { IShoppingOrderPaymentAttempt } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingOrderPaymentAttempt";
import type { IShoppingOrderShipment } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingOrderShipment";
import type { IShoppingOrderSplit } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingOrderSplit";
import type { IShoppingOrderStatusHistory } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingOrderStatusHistory";
import type { IShoppingRefundActor } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingRefundActor";
import type { IShoppingRefundAdminOverride } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingRefundAdminOverride";
import type { IShoppingRefundApproval } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingRefundApproval";
import type { IShoppingRefundAttachment } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingRefundAttachment";
import type { IShoppingRefundRequest } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingRefundRequest";
import type { IShoppingRefundRequestItem } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingRefundRequestItem";
import type { IShoppingRefundStatusHistory } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingRefundStatusHistory";
import type { IShoppingSeller } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingSeller";
import type { IShoppingSku } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingSku";

/**
 * Test updating a customer refund request and enforcing status-based update
 * rules.
 *
 * This test covers the workflow in which:
 *
 * - A new customer is created and authenticated.
 * - The customer creates a new order with a single order line in order to have a
 *   valid order for refund.
 * - The customer submits a new refund request for their order.
 * - While the refund request is still open (editable status), the customer
 *   updates the business_reason and request_context fields using the refund
 *   update endpoint.
 * - The response is validated to confirm that the updates are reflected and
 *   allowed in the editable state.
 * - The status of the refund request is then set to a finalized/locked value to
 *   simulate non-editable state (e.g., by calling the update endpoint and
 *   setting status to 'approved' or 'completed', depending on what the API
 *   allows).
 * - After status is finalized, the customer attempts to update the refund reason
 *   again and expects a rejection (business rule prohibition on updates after
 *   finalization).
 * - The test specifically checks that the update endpoint allows modification in
 *   open status but blocks further changes when locked.
 * - All entity responses are validated for type safety using typia.assert().
 * - Tests include assertions for business_reason and request_context update
 *   success as well as error handling for rejected update attempts after
 *   finalization.
 */
export async function test_api_customer_refund_update_workflow(
  connection: api.IConnection,
) {
  // 1. Register and authenticate a new customer
  const customerCreate = {
    email: typia.random<string & tags.Format<"email">>(),
    password: RandomGenerator.alphaNumeric(12),
    name: RandomGenerator.name(),
    phone: RandomGenerator.mobile(),
    href: "https://test.example.com/register",
    referrer: "https://test.example.com/landing",
  } satisfies IShoppingCustomer.ICreate;
  const customerAuth: IShoppingCustomer.IAuthorized =
    await api.functional.auth.customer.join(connection, {
      body: customerCreate,
    });
  typia.assert(customerAuth);

  // 2. Create a new order for the customer with a single line
  const skuId = typia.random<string & tags.Format<"uuid">>();
  const orderLine = {
    shopping_sku_id: skuId,
    quantity: 1 as number & tags.Type<"int32"> & tags.Minimum<1>,
    unit_price: 10000,
  } satisfies IShoppingOrderLine.ICreate;
  const address = {
    type: "shipping",
    recipient_name: customerCreate.name,
    recipient_phone: customerCreate.phone,
    zip_code: "12345",
    base_address: "123 Main St",
    detail_address: null,
    city: "Seoul",
    state_province: "Seoul",
    country: "KR",
  } satisfies IShoppingOrderAddress.ICreate;
  const orderCreate = {
    total_price: 10000,
    order_lines: [orderLine],
    shipping_addresses: [address],
    payment_method: "card",
    coupon_code: null,
  } satisfies IShoppingOrder.ICreate;
  const order: IShoppingOrder =
    await api.functional.shopping.customer.orders.create(connection, {
      body: orderCreate,
    });
  typia.assert(order);

  // 3. Submit a new refund request for the order
  const refundItem = {
    shopping_order_id: order.id,
    shopping_order_line_id: order.order_lines[0].id,
    quantity: 1 as number & tags.Type<"int32">,
  } satisfies IShoppingRefundRequestItem.ICreate;
  const refundCreate = {
    shopping_order_id: order.id,
    request_type: "refund",
    business_reason: "Initial refund reason",
    request_context: "Initial context for refund request.",
    items: [refundItem],
  } satisfies IShoppingRefundRequest.ICreate;
  const refund: IShoppingRefundRequest =
    await api.functional.shopping.customer.refunds.create(connection, {
      body: refundCreate,
    });
  typia.assert(refund);

  // 4. Update refund request while status is open
  const updatedReason = "Updated reason for refund.";
  const updatedContext = "Updated context to provide more details.";
  const updatedRefund: IShoppingRefundRequest =
    await api.functional.shopping.customer.refunds.update(connection, {
      refundRequestId: refund.id,
      body: {
        business_reason: updatedReason,
        request_context: updatedContext,
      } satisfies IShoppingRefundRequest.IUpdate,
    });
  typia.assert(updatedRefund);
  TestValidator.equals(
    "business_reason updated when editable",
    updatedRefund.business_reason,
    updatedReason,
  );
  TestValidator.equals(
    "request_context updated when editable",
    updatedRefund.request_context,
    updatedContext,
  );

  // 5. Finalize refund status (simulate lock/final state)
  const updatedFinal: IShoppingRefundRequest =
    await api.functional.shopping.customer.refunds.update(connection, {
      refundRequestId: refund.id,
      body: {
        status: "approved",
      } satisfies IShoppingRefundRequest.IUpdate,
    });
  typia.assert(updatedFinal);
  TestValidator.equals(
    "refund is finalized/locked",
    updatedFinal.status,
    "approved",
  );

  // 6. Attempt to update after status is finalized/locked (should fail)
  await TestValidator.error(
    "business rule prohibits update of finalized refund",
    async () => {
      await api.functional.shopping.customer.refunds.update(connection, {
        refundRequestId: refund.id,
        body: {
          business_reason: "Attempt to update after locked",
          request_context: "Should not succeed.",
        } satisfies IShoppingRefundRequest.IUpdate,
      });
    },
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IShoppingAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingAuthorizationToken";
import type { IShoppingCustomer } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingCustomer";
import type { IShoppingOrder } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingOrder";
import type { IShoppingRefundActor } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingRefundActor";
import type { IShoppingRefundAdminOverride } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingRefundAdminOverride";
import type { IShoppingRefundApproval } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingRefundApproval";
import type { IShoppingRefundAttachment } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingRefundAttachment";
import type { IShoppingRefundRequest } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingRefundRequest";
import type { IShoppingRefundRequestItem } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingRefundRequestItem";
import type { IShoppingRefundStatusHistory } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingRefundStatusHistory";
import type { IShoppingSeller } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingSeller";

/**
 * Test update workflow for seller refund requests, covering both success and
 * permitted error paths.
 *
 * 1. Register a new seller (with random email/contact data).
 * 2. Create a refund request using "refund" request_type and at least one item.
 * 3. Update the business_reason, request_context fields and optionally status,
 *    verifying success.
 * 4. Confirm the entity is updated (fresh response).
 * 5. Set refund status to a typical final status (e.g., "completed") and then
 *    attempt update again; expect error.
 */
export async function test_api_seller_refund_update_workflow(
  connection: api.IConnection,
) {
  // 1. Register seller for authentication
  const sellerJoin = {
    email: typia.random<string & tags.Format<"email">>(),
    password: RandomGenerator.alphaNumeric(12),
    display_name: RandomGenerator.name(),
    contact_phone: RandomGenerator.mobile(),
    status: "pending",
  } satisfies IShoppingSeller.IJoin;
  const seller: IShoppingSeller.IAuthorized =
    await api.functional.auth.seller.join(connection, { body: sellerJoin });
  typia.assert(seller);

  // 2. Create refund request (minimal, required props only)
  // Generate a mock order summary: (simulate a paid or completed order)
  const mockOrderId = typia.random<string & tags.Format<"uuid">>();
  const mockOrderLineId = typia.random<string & tags.Format<"uuid">>();
  const refundCreate = {
    shopping_order_id: mockOrderId,
    request_type: "refund",
    business_reason: "Initial product defect claim",
    items: [
      {
        shopping_order_id: mockOrderId,
        shopping_order_line_id: mockOrderLineId,
        quantity: 1 satisfies number,
      } satisfies IShoppingRefundRequestItem.ICreate,
    ],
  } satisfies IShoppingRefundRequest.ICreate;
  const refund = await api.functional.shopping.seller.refunds.create(
    connection,
    { body: refundCreate },
  );
  typia.assert(refund);

  // 3. Update business_reason/request_context successfully, assuming current status is updatable
  const updatedBusinessReason = RandomGenerator.paragraph({ sentences: 2 });
  const updatedRequestContext = RandomGenerator.content({ paragraphs: 1 });
  const updateBody = {
    business_reason: updatedBusinessReason,
    request_context: updatedRequestContext,
  } satisfies IShoppingRefundRequest.IUpdate;
  const updatedRefund = await api.functional.shopping.seller.refunds.update(
    connection,
    {
      refundRequestId: refund.id,
      body: updateBody,
    },
  );
  typia.assert(updatedRefund);
  TestValidator.equals(
    "business_reason updated",
    updatedRefund.business_reason,
    updatedBusinessReason,
  );
  TestValidator.equals(
    "request_context updated",
    updatedRefund.request_context,
    updatedRequestContext,
  );

  // 4. Set refund status to 'completed' (simulate final) and try update again; expect error
  const finalStatusBody = {
    status: "completed",
  } satisfies IShoppingRefundRequest.IUpdate;
  const finalRefund = await api.functional.shopping.seller.refunds.update(
