import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IShoppingAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingAuthorizationToken";
import type { IShoppingCustomer } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingCustomer";
import type { IShoppingOrder } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingOrder";
import type { IShoppingOrderAddress } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingOrderAddress";
import type { IShoppingOrderLine } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingOrderLine";
import type { IShoppingOrderLineFulfillment } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingOrderLineFulfillment";
import type { IShoppingOrderPaymentAttempt } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingOrderPaymentAttempt";
import type { IShoppingOrderShipment } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingOrderShipment";
import type { IShoppingOrderSplit } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingOrderSplit";
import type { IShoppingOrderStatusHistory } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingOrderStatusHistory";
import type { IShoppingSeller } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingSeller";
import type { IShoppingSku } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingSku";

/**
 * Validates that a seller can soft-delete (cancel) their own order before
 * fulfillment, and that ownership, state, authentication, and audit log
 * constraints are enforced.
 *
 * 1. Register a seller with random credentials using
 *    api.functional.auth.seller.join (which also authenticates the seller).
 * 2. Simulate an order belonging to the seller (for test demonstration, use
 *    typia.random<IShoppingOrder>(), as order creation API is not accessible,
 *    and extract a valid 'order_code' and seller to use for further
 *    validation).
 * 3. Soft-delete the order by calling api.functional.shopping.seller.orders.erase
 *    with the valid orderCode.
 * 4. Validate that the returned IShoppingOrder object has a non-null deleted_at
 *    value (soft deletion, not hard removal).
 * 5. Verify that the status of the order reflects deletion/cancellation.
 * 6. Verify there is at least one status_history with a transition to a
 *    cancellation/deleted state and that it's attributed to the seller actor
 *    (status_history.to_status and .triggered_by validation).
 * 7. Validate all type constraints using typia.assert().
 * 8. Attempt to erase an order with an orderCode not owned by the seller; confirm
 *    that an error is thrown (TestValidator.error).
 * 9. Attempt to call erase endpoint unauthenticated; verify that access is denied.
 */
export async function test_api_seller_order_soft_delete_by_owner(
  connection: api.IConnection,
) {
  // 1. Register seller
  const joinInput = {
    email: typia.random<string & tags.Format<"email">>(),
    password: RandomGenerator.alphaNumeric(12),
    display_name: RandomGenerator.name(),
    contact_phone: RandomGenerator.mobile(),
    status: "pending",
  } satisfies IShoppingSeller.IJoin;
  const authorizedSeller = await api.functional.auth.seller.join(connection, {
    body: joinInput,
  });
  typia.assert(authorizedSeller);

  // 2. Simulate an order belonging to this seller
  // Since order creation API is inaccessible, use typia.random and patch keys for validation
  let testOrder = typia.random<IShoppingOrder>();
  testOrder = { ...testOrder, order_code: RandomGenerator.alphaNumeric(10) };
  // (optional: patch order_lines, order_splits with matching seller info if needed)

  // 3. Soft-delete the seller's order
  const erased = await api.functional.shopping.seller.orders.erase(connection, {
    orderCode: testOrder.order_code,
  });
  typia.assert(erased);

  // 4. Validate soft deletion
  TestValidator.predicate(
    "order deleted_at is non-null after erase",
    erased.deleted_at !== null && erased.deleted_at !== undefined,
  );

  // 5. Check cancellation state
  TestValidator.predicate(
    "order status is cancellation or deletion",
    erased.status === "cancelled" ||
      erased.status === "deleted" ||
      erased.status === "canceled",
  );

  // 6. Validate status history includes soft-delete event attributed to seller
  TestValidator.predicate(
    "order status history contains deletion event by seller",
    erased.status_history.some(
      (h) =>
        (h.to_status === "cancelled" ||
          h.to_status === "deleted" ||
          h.to_status === "canceled") &&
        (h.triggered_by === "seller" || h.triggered_by === authorizedSeller.id),
    ),
  );

  // 7. Type assertion on full object (returns)
  typia.assert(erased);

  // 8. Attempt to delete ineligible order (not owned by seller)
  const notOwnersOrderCode = RandomGenerator.alphaNumeric(10);
  await TestValidator.error("erase fails for not-owned order", async () => {
    await api.functional.shopping.seller.orders.erase(connection, {
      orderCode: notOwnersOrderCode,
    });
  });

  // 9. Attempt deletion without authentication
  const unauthConn: api.IConnection = { ...connection, headers: {} };
  await TestValidator.error("unauthenticated erase is denied", async () => {
    await api.functional.shopping.seller.orders.erase(unauthConn, {
      orderCode: testOrder.order_code,
    });
  });
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IShoppingAdmin } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingAdmin";
import type { IShoppingAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingAuthorizationToken";
import type { IShoppingPasswordReset } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingPasswordReset";

/**
 * Validate update operations for admin-managed password reset requests.
 *
 * This scenario tests: (1) updating the expires_at field for an existing reset,
 * (2) marking the reset as consumed, (3) verifying that no update is allowed on
 * consumed or expired resets, (4) auditability via returned entity state.
 * Steps:
 *
 * 1. Admin registers and authenticates
 * 2. A password reset request is created (direct DTO instantiation)
 * 3. Update the expires_at and check that it's changed
 * 4. Mark the reset as consumed (set consumed_at)
 * 5. Attempt to update after consumption (expect business error)
 * 6. Simulate expiry, attempt update (expect business error)
 *
 * Note: No explicit audit log fetch; audit verification is by update
 * time/history
 */
export async function test_api_admin_password_reset_update_audit_trail(
  connection: api.IConnection,
) {
  // 1. Register and authenticate as new admin
  const adminJoinBody = {
    email: typia.random<string & tags.Format<"email">>(),
    password: RandomGenerator.alphaNumeric(12) as string &
      tags.MinLength<8> &
      tags.MaxLength<128>,
    name: RandomGenerator.name(),
    role: RandomGenerator.pick([
      "super",
      "support",
      "compliance",
      "operator",
    ] as const),
    status: "active" as string & tags.MinLength<3> & tags.MaxLength<20>,
  } satisfies IShoppingAdmin.IJoin;
  const admin = await api.functional.auth.admin.join(connection, {
    body: adminJoinBody,
  });
  typia.assert(admin);

  // 2. Prepare a password reset request DTO in memory
  const resetOrigin = {
    id: typia.random<string & tags.Format<"uuid">>(),
    request_email: adminJoinBody.email,
    reset_code: RandomGenerator.alphaNumeric(32),
    shopping_customer_id: undefined,
    shopping_seller_id: undefined,
    shopping_admin_id: admin.id,
    expires_at: new Date(Date.now() + 1000 * 60 * 60 * 3).toISOString(), // 3 hours from now
    consumed_at: null,
    created_at: new Date().toISOString(),
    updated_at: new Date().toISOString(),
  } satisfies IShoppingPasswordReset;

  // 3. Successful update: extend expires_at by 1 hour
  const newExpires = new Date(Date.now() + 1000 * 60 * 60 * 4).toISOString();
  const update1Body = {
    expires_at: newExpires,
  } satisfies IShoppingPasswordReset.IUpdate;
  const updated1 = await api.functional.shopping.admin.passwordResets.update(
    connection,
    {
      passwordResetId: resetOrigin.id,
      body: update1Body,
    },
  );
  typia.assert(updated1);
  TestValidator.equals("expires_at updated", updated1.expires_at, newExpires);
  TestValidator.equals("reset not consumed yet", updated1.consumed_at, null);

  // 4. Mark as consumed
  const nowConsumed = new Date().toISOString();
  const update2Body = {
    expires_at: newExpires,
    consumed_at: nowConsumed,
  } satisfies IShoppingPasswordReset.IUpdate;
  const updated2 = await api.functional.shopping.admin.passwordResets.update(
    connection,
    {
      passwordResetId: resetOrigin.id,
      body: update2Body,
    },
  );
  typia.assert(updated2);
  TestValidator.equals("consumed_at set", updated2.consumed_at, nowConsumed);

  // 5. Attempt update after consumed: should fail
  await TestValidator.error("cannot update when consumed_at set", async () => {
    await api.functional.shopping.admin.passwordResets.update(connection, {
      passwordResetId: resetOrigin.id,
      body: {
        expires_at: newExpires,
        consumed_at: nowConsumed,
      },
    });
  });

  // 6. Simulate expiry: move past expires_at and try update (should fail)
  const expiredResetId = typia.random<string & tags.Format<"uuid">>();
  const expiredExpires = new Date(Date.now() - 1000 * 60).toISOString(); // 1min ago
  const expiredReset = {
    ...resetOrigin,
    id: expiredResetId,
    expires_at: expiredExpires,
    consumed_at: null,
  } satisfies IShoppingPasswordReset;
  await TestValidator.error("cannot update when expired", async () => {
    await api.functional.shopping.admin.passwordResets.update(connection, {
      passwordResetId: expiredResetId,
      body: {
        expires_at: new Date(Date.now() + 1000 * 60 * 60 * 5).toISOString(),
      },
    });
  });
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IShoppingAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingAuthorizationToken";
import type { IShoppingCustomer } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingCustomer";
import type { IShoppingPasswordReset } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingPasswordReset";

/**
 * Validate password reset update by the owner (authenticated customer).
 *
 * This scenario simulates the password reset flow for shopping customers,
 * including proper account creation, reset request, updating reset details, and
 * enforcement of security rules. It covers successful update of a still-active
 * reset (expiry extension), as well as business error cases for updating after
 * consumption or expiration.
 *
 * Steps:
 *
 * 1. Customer registers and authenticates.
 * 2. Customer creates a password reset request.
 * 3. Search for the newly created password reset entity (simulate admin access if
 *    needed for lookup).
 * 4. As the owning customer, update the reset (refresh expires_at) BEFORE
 *    expiration or consumption.
 * 5. Confirm expires_at has been updated; verify ownership.
 * 6. Mark the reset as consumed (set consumed_at).
 * 7. Attempt further update after consumption and expect business error.
 * 8. Attempt update from a different (unauthorized) customer; expect error due to
 *    strict authorization.
 */
export async function test_api_customer_password_reset_update_by_owner(
  connection: api.IConnection,
) {
  // 1. Register customer
  const customerEmail = typia.random<string & tags.Format<"email">>();
  const customerBody = {
    email: customerEmail,
    password: RandomGenerator.alphaNumeric(12),
    name: RandomGenerator.name(),
    phone: RandomGenerator.mobile(),
    href: "https://shop.example.com/register",
    referrer: "https://shop.example.com/landing",
    ip: undefined,
  } satisfies IShoppingCustomer.ICreate;

  const customer: IShoppingCustomer.IAuthorized =
    await api.functional.auth.customer.join(connection, { body: customerBody });
  typia.assert(customer);

  // 2. Initiate password reset
  const resetReq = {
    request_email: customerEmail,
  } satisfies IShoppingCustomer.IRequestPasswordReset;
  const resetResp =
    await api.functional.auth.customer.password.reset_request.requestPasswordReset(
      connection,
      { body: resetReq },
    );
  typia.assert(resetResp);

  // --- Test infra note: We need to fetch the reset by admin means for test (assume last created reset for email).
  // For this test, simulate that we can retrieve the reset entity for this email (in real test environments, we should have a direct fetch API for the reset, but here we'll mock).

  // Simulate password reset lookup (in a real setup, an API would provide this).
  // We'll emulate by creating a new reset and acting immediately.
  // Construct a password reset object for test purposes:
  // Use expiration 20 minutes from now on creation.
  const expiresInMinutes = 20;
  const now = new Date();
  const futureExpires = new Date(
    now.getTime() + expiresInMinutes * 60 * 1000,
  ).toISOString();

  // Artificially create a password reset entry using the known format and ID for this session (simulate as if we know the ID, test scenario only).
  // We'll simulate getting the reset ID as if from admin tools.
  // Generate a reset UUID for test.
  const passwordResetId: string & tags.Format<"uuid"> = typia.random<
    string & tags.Format<"uuid">
  >();

  // 4. Update reset (as customer, extend expiration)
  const updateBody1 = {
    expires_at: new Date(now.getTime() + 90 * 60 * 1000).toISOString(),
  } satisfies IShoppingPasswordReset.IUpdate;
  const updateResp1 =
    await api.functional.shopping.customer.passwordResets.update(connection, {
      passwordResetId,
      body: updateBody1,
    });
  typia.assert(updateResp1);
  TestValidator.predicate(
    "expires_at was updated",
    updateResp1.expires_at === updateBody1.expires_at,
  );
  TestValidator.equals(
    "ownership verified: reset owned by customer",
    updateResp1.shopping_customer_id,
    customer.id,
  );

  // 5. Mark reset as consumed
  const consumptionTime = new Date(
    now.getTime() + 95 * 60 * 1000,
  ).toISOString();
  const updateBody2 = {
    expires_at: updateBody1.expires_at,
    consumed_at: consumptionTime,
  } satisfies IShoppingPasswordReset.IUpdate;
  const updateResp2 =
    await api.functional.shopping.customer.passwordResets.update(connection, {
      passwordResetId,
      body: updateBody2,
    });
  typia.assert(updateResp2);
  TestValidator.equals(
    "reset is now consumed",
    updateResp2.consumed_at,
    consumptionTime,
  );

  // 6. Attempt to update after consumption; expect error
  const updateBody3 = {
    expires_at: new Date(now.getTime() + 120 * 60 * 1000).toISOString(),
    consumed_at: consumptionTime,
  } satisfies IShoppingPasswordReset.IUpdate;
  await TestValidator.error(
    "update after consumed reset should fail",
    async () => {
      await api.functional.shopping.customer.passwordResets.update(connection, {
        passwordResetId,
        body: updateBody3,
      });
    },
  );

  // 7. Register a different customer and try updating the same reset (should fail)
  const otherEmail = typia.random<string & tags.Format<"email">>();
  const otherBody = {
    email: otherEmail,
    password: RandomGenerator.alphaNumeric(12),
    name: RandomGenerator.name(),
    phone: RandomGenerator.mobile(),
    href: "https://shop.example.com/register2",
    referrer: "https://shop.example.com/landing2",
    ip: undefined,
  } satisfies IShoppingCustomer.ICreate;

  const otherCustomer: IShoppingCustomer.IAuthorized =
    await api.functional.auth.customer.join(connection, { body: otherBody });
  typia.assert(otherCustomer);
  // Now as another customer, try to update the first user's reset
  const updateBodyOther = {
    expires_at: new Date(now.getTime() + 180 * 60 * 1000).toISOString(),
  } satisfies IShoppingPasswordReset.IUpdate;
  await TestValidator.error(
    "unauthorized update by other customer should fail",
    async () => {
      await api.functional.shopping.customer.passwordResets.update(connection, {
        passwordResetId,
        body: updateBodyOther,
      });
    },
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IShoppingAttributeDimension } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingAttributeDimension";
import type { IShoppingAttributeValue } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingAttributeValue";
import type { IShoppingAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingAuthorizationToken";
import type { IShoppingCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingCategory";
import type { IShoppingCustomer } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingCustomer";
import type { IShoppingOrder } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingOrder";
import type { IShoppingOrderAddress } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingOrderAddress";
import type { IShoppingOrderLine } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingOrderLine";
import type { IShoppingOrderLineFulfillment } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingOrderLineFulfillment";
import type { IShoppingOrderPaymentAttempt } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingOrderPaymentAttempt";
import type { IShoppingOrderShipment } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingOrderShipment";
import type { IShoppingOrderSplit } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingOrderSplit";
import type { IShoppingOrderStatusHistory } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingOrderStatusHistory";
import type { IShoppingProduct } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingProduct";
import type { IShoppingProductAttribute } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingProductAttribute";
import type { IShoppingProductImage } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingProductImage";
import type { IShoppingSeller } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingSeller";
import type { IShoppingSku } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingSku";
import type { IShoppingSkuImage } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingSkuImage";
import type { IShoppingSkuVariant } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingSkuVariant";
import type { IShoppingTag } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingTag";

/**
 * Validate successful customer checkout with order creation and all dependent
 * business logic, inventory checks, and security.
 *
 * 1. Seller joins and is authenticated.
 * 2. Seller creates a new product for sale.
 * 3. Seller creates an active, in-stock SKU for the new product.
 * 4. Customer joins and is authenticated.
 * 5. Customer prepares a complete, valid order with the seller's SKU. Includes
 *    inventory, addresses, payment method (string value, e.g. "card"), and
 *    total price.
 * 6. Customer successfully submits /shopping/customer/orders (checkout API) with
 *    authenticated session.
 * 7. The created order is returned and validated: order_code is nonempty, lines
 *    are created and match request, correct address and payment attempt exist,
 *    and initial status is valid.
 * 8. Repeat the request as an unauthenticated customer: API must reject the
 *    request.
 * 9. Attempt to place an order with excessive quantity (greater than available);
 *    API must reject the request.
 */
export async function test_api_customer_order_creation_successful_checkout(
  connection: api.IConnection,
) {
  // Seller joins and is authenticated
  const sellerEmail = typia.random<string & tags.Format<"email">>();
  const seller = await api.functional.auth.seller.join(connection, {
    body: {
      email: sellerEmail,
      password: RandomGenerator.alphaNumeric(12),
      display_name: RandomGenerator.name(),
      contact_phone: RandomGenerator.mobile(),
      status: "pending",
    },
  });
  typia.assert(seller);

  // Seller creates a new product
  const productCode = RandomGenerator.alphaNumeric(10);
  const product = await api.functional.shopping.seller.products.create(
    connection,
    {
      body: {
        code: productCode,
        name: RandomGenerator.paragraph({ sentences: 2 }),
        description: RandomGenerator.content({ paragraphs: 2 }),
        main_image_uri: `https://img.example.com/${RandomGenerator.alphaNumeric(8)}.jpg`,
        status: "active",
        business_status: "in_review",
        shipping_weight_grams: 250,
        shipping_length_cm: 20,
        shipping_width_cm: 15,
        shipping_height_cm: 5,
        shipping_options: "Standard Shipping",
      },
    },
  );
  typia.assert(product);

  // Seller creates an active SKU
  const skuCode = RandomGenerator.alphaNumeric(10);
  const attrValueId = typia.random<string & tags.Format<"uuid">>();
  const sku = await api.functional.shopping.seller.products.skus.create(
    connection,
    {
      productCode,
      body: {
        sku_code: skuCode,
        price: 10000,
        is_active: true,
        barcode: null,
        status: "in_stock",
        variant_attribute_value_ids: [attrValueId],
      },
    },
  );
  typia.assert(sku);

  // Customer joins and is authenticated
  const customerEmail = typia.random<string & tags.Format<"email">>();
  const customer = await api.functional.auth.customer.join(connection, {
    body: {
      email: customerEmail,
      password: RandomGenerator.alphaNumeric(12),
      name: RandomGenerator.name(),
      phone: RandomGenerator.mobile(),
      href: `https://shop.example.com/join/${RandomGenerator.alphaNumeric(8)}`,
      referrer: `https://shop.example.com/landing`,
      ip: null,
    },
  });
  typia.assert(customer);

  // Prepare shipping address
  const shippingAddress = {
    type: "shipping",
    recipient_name: RandomGenerator.name(),
    recipient_phone: RandomGenerator.mobile(),
    zip_code: RandomGenerator.alphaNumeric(5),
    base_address: RandomGenerator.paragraph({ sentences: 1, wordMin: 5 }),
    detail_address: "Apt 101",
    city: RandomGenerator.paragraph({ sentences: 1 }),
    state_province: "Seoul",
    country: "South Korea",
  } satisfies IShoppingOrderAddress.ICreate;

  // Order line for valid checkout
  const quantity = 1;
  const orderLine = {
    shopping_sku_id: sku.id,
    quantity,
    unit_price: sku.price,
  } satisfies IShoppingOrderLine.ICreate;
  // Total price calculation for 1 unit
  const total_price = sku.price * quantity;

  // Customer places order successfully
  const orderBody = {
    total_price,
    order_lines: [orderLine],
    shipping_addresses: [shippingAddress],
    payment_method: "card",
    coupon_code: null,
  } satisfies IShoppingOrder.ICreate;

  const order = await api.functional.shopping.customer.orders.create(
    connection,
    {
      body: orderBody,
    },
  );
  typia.assert(order);
  TestValidator.predicate(
    "order_code should be non-empty",
    order.order_code.length > 0,
  );
  TestValidator.equals(
    "total_price matches input",
    order.total_price,
    orderBody.total_price,
  );
  TestValidator.equals(
    "order_lines length matches",
    order.order_lines.length,
    1,
  );
  TestValidator.equals("sku id matches", order.order_lines[0].sku.id, sku.id);
  TestValidator.equals(
    "order address created",
    order.addresses[0].recipient_name,
    shippingAddress.recipient_name,
  );
  TestValidator.equals(
    "customer in order matches",
    order.customer.email,
    customer.email,
  );
  TestValidator.predicate(
    "initial status valid",
    ["pending", "paid"].includes(order.status),
  );
  TestValidator.predicate(
    "payment_attempts present",
    order.payment_attempts.length >= 1,
  );
  TestValidator.equals(
    "first order line unit_price",
    order.order_lines[0].unit_price,
    sku.price,
  );

  // Unauthenticated order attempt should fail
  const unauthConn: api.IConnection = { ...connection, headers: {} };
  await TestValidator.error(
    "order placement must be rejected for unauthenticated customer",
    async () => {
      await api.functional.shopping.customer.orders.create(unauthConn, {
        body: orderBody,
      });
    },
  );

  // Attempt to order greater quantity than inventory should fail
  const excessiveOrderLine = {
    shopping_sku_id: sku.id,
    quantity: 99999,
    unit_price: sku.price,
  } satisfies IShoppingOrderLine.ICreate;
  const excessiveOrderBody = {
    total_price: sku.price * 99999,
    order_lines: [excessiveOrderLine],
    shipping_addresses: [shippingAddress],
    payment_method: "card",
    coupon_code: null,
  } satisfies IShoppingOrder.ICreate;
  await TestValidator.error(
    "order must fail for excessive quantity",
    async () => {
      await api.functional.shopping.customer.orders.create(connection, {
        body: excessiveOrderBody,
      });
    },
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IShoppingAttributeDimension } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingAttributeDimension";
import type { IShoppingAttributeValue } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingAttributeValue";
import type { IShoppingAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingAuthorizationToken";
import type { IShoppingCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingCategory";
import type { IShoppingCustomer } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingCustomer";
import type { IShoppingOrder } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingOrder";
import type { IShoppingOrderAddress } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingOrderAddress";
import type { IShoppingOrderLine } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingOrderLine";
import type { IShoppingOrderLineFulfillment } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingOrderLineFulfillment";
import type { IShoppingOrderPaymentAttempt } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingOrderPaymentAttempt";
import type { IShoppingOrderShipment } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingOrderShipment";
import type { IShoppingOrderSplit } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingOrderSplit";
import type { IShoppingOrderStatusHistory } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingOrderStatusHistory";
import type { IShoppingProduct } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingProduct";
import type { IShoppingProductAttribute } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingProductAttribute";
import type { IShoppingProductImage } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingProductImage";
import type { IShoppingSeller } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingSeller";
import type { IShoppingSku } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingSku";
import type { IShoppingSkuImage } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingSkuImage";
import type { IShoppingSkuVariant } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingSkuVariant";
import type { IShoppingTag } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingTag";

/**
 * Validates permitted customer-side order updates before fulfillment/shipment.
 *
 * This test covers the following critical flows and edge cases:
 *
 * 1. Seller registers and creates a product and an SKU.
 * 2. Customer self-registers and creates an order using the SKU.
 * 3. Customer can update allowed modifiable fields of the order while order is
 *    pending (such as address or certain statuses).
 * 4. After order reaches fulfillment (mocked by status change), further updates
 *    are rejected.
 * 5. Unauthorized update attempts (other users or unauthenticated) are rejected.
 * 6. Audit logs/status transitions reflect each update.
 *
 * The test verifies that only allowed fields are updated, audit fields are
 * read-only, business rules are enforced, and all API responses are type-safe
 * and correct.
 */
export async function test_api_customer_order_update_before_fulfillment(
  connection: api.IConnection,
) {
  // 1. Seller registers & creates product
  const sellerEmail = typia.random<string & tags.Format<"email">>();
  const seller = await api.functional.auth.seller.join(connection, {
    body: {
      email: sellerEmail,
      password: "password-123",
      display_name: RandomGenerator.name(),
      contact_phone: RandomGenerator.mobile(),
      status: "pending",
    } satisfies IShoppingSeller.IJoin,
  });
  typia.assert(seller);

  // 2. Seller creates product
  const productCode = RandomGenerator.alphaNumeric(8);
  const product = await api.functional.shopping.seller.products.create(
    connection,
    {
      body: {
        code: productCode,
        name: RandomGenerator.paragraph({
          sentences: 3,
          wordMin: 4,
          wordMax: 8,
        }),
        description: RandomGenerator.content({
          paragraphs: 1,
          sentenceMin: 5,
          sentenceMax: 10,
          wordMin: 4,
          wordMax: 10,
        }),
        main_image_uri:
          "https://example.com/img/" + RandomGenerator.alphaNumeric(8) + ".jpg",
        status: "draft",
        business_status: "in_review",
      } satisfies IShoppingProduct.ICreate,
    },
  );
  typia.assert(product);

  // 3. Seller creates SKU
  const sku = await api.functional.shopping.seller.products.skus.create(
    connection,
    {
      productCode: productCode,
      body: {
        sku_code: RandomGenerator.alphaNumeric(14),
        price: 8999,
        is_active: true,
        barcode: RandomGenerator.alphaNumeric(12),
        status: "in_stock",
        variant_attribute_value_ids:
          Array.isArray(product.attributes) && product.attributes.length > 0
            ? [product.attributes[0].attribute_value.id]
            : [typia.random<string & tags.Format<"uuid">>()],
      } satisfies IShoppingSku.ICreate,
    },
  );
  typia.assert(sku);

  // 4. Customer registers and creates order
  const customerEmail = typia.random<string & tags.Format<"email">>();
  const customer = await api.functional.auth.customer.join(connection, {
    body: {
      email: customerEmail,
      password: "password-789",
      name: RandomGenerator.name(),
      phone: RandomGenerator.mobile(),
      href: "https://test-mall.local/checkout",
      referrer: "https://test-mall.local/promotion/ref?src=test",
    } satisfies IShoppingCustomer.ICreate,
  });
  typia.assert(customer);

  const orderCreateInput = {
    total_price: sku.price,
    order_lines: [
      {
        shopping_sku_id: sku.id,
        quantity: 1,
        unit_price: sku.price,
      } satisfies IShoppingOrderLine.ICreate,
    ],
    shipping_addresses: [
      {
        type: "shipping",
        recipient_name: RandomGenerator.name(),
        recipient_phone: RandomGenerator.mobile(),
        zip_code: String(10000 + Math.floor(Math.random() * 90000)),
        base_address: "123 Test Ave",
        detail_address: "Suite 42C",
        city: "Seoul",
        state_province: "Seoul",
        country: "KR",
      } satisfies IShoppingOrderAddress.ICreate,
    ],
    payment_method: "bank_transfer",
  } satisfies IShoppingOrder.ICreate;

  const order = await api.functional.shopping.customer.orders.create(
    connection,
    {
      body: orderCreateInput,
    },
  );
  typia.assert(order);
  const orderCode = order.order_code;

  // 5. Update permitted fields: shipping_addresses
  const newRecipient = RandomGenerator.name();
  const updateInput = {
    shipping_addresses: [
      {
        recipient_name: newRecipient,
      } satisfies IShoppingOrderAddress.IUpdate,
    ],
  } satisfies IShoppingOrder.IUpdate;

  const updatedOrder = await api.functional.shopping.customer.orders.update(
    connection,
    {
      orderCode,
      body: updateInput,
    },
  );
  typia.assert(updatedOrder);
  TestValidator.equals(
    "order shipping address recipient updated",
    updatedOrder.addresses[0].recipient_name,
    newRecipient,
  );
  TestValidator.equals(
    "order_code not changed on update",
    updatedOrder.order_code,
    order.order_code,
  );

  // 6. Simulate fulfillment (mock: change status to 'fulfilled'), then update attempt is rejected
  const fulfilledOrder = await api.functional.shopping.customer.orders.update(
    connection,
    {
      orderCode,
      body: {
        status: "fulfilled",
      } satisfies IShoppingOrder.IUpdate,
    },
  );
  typia.assert(fulfilledOrder);
  TestValidator.equals(
    "order now in fulfilled status",
    fulfilledOrder.status,
    "fulfilled",
  );
  await TestValidator.error("update after fulfillment is blocked", async () => {
    await api.functional.shopping.customer.orders.update(connection, {
      orderCode,
      body: {
        status: "pending",
      } satisfies IShoppingOrder.IUpdate,
    });
  });

  // 7. Unauthorized update attempt (seller, not order owner)
  await api.functional.auth.seller.join(connection, {
    body: {
      email: "second.seller." + RandomGenerator.alphaNumeric(6) + "@test.com",
      password: "password-456",
      display_name: RandomGenerator.name(),
      contact_phone: RandomGenerator.mobile(),
      status: "pending",
    } satisfies IShoppingSeller.IJoin,
  });
  await TestValidator.error(
    "non-customer cannot update customer order",
    async () => {
      await api.functional.shopping.customer.orders.update(connection, {
        orderCode,
        body: {
          status: "pending",
        } satisfies IShoppingOrder.IUpdate,
      });
    },
  );

  // 8. Unauthenticated update attempt
  const unauthConn: api.IConnection = { ...connection, headers: {} };
  await TestValidator.error(
    "unauthenticated user update is rejected",
    async () => {
      await api.functional.shopping.customer.orders.update(unauthConn, {
        orderCode,
        body: {
          status: "pending",
        } satisfies IShoppingOrder.IUpdate,
      });
    },
  );

  // 9. Confirm audit history reflects the changes
  TestValidator.predicate(
    "status history includes the fulfilled transition",
    updatedOrder.status_history.some(
      (history) => history.to_status === "fulfilled",
    ),
  );
  TestValidator.predicate(
    "updated_at reflects latest update after modification",
    new Date(updatedOrder.updated_at) >= new Date(order.updated_at),
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IShoppingAdmin } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingAdmin";
import type { IShoppingAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingAuthorizationToken";
import type { IShoppingInventoryAlert } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingInventoryAlert";

/**
 * Validate admin detail access to inventory alert and full audit trail.
 *
 * 1. Admin joins using valid business email and strong password to obtain
 *    authorization token.
 * 2. Create inventory alert test data (random alert with valid SKU and UUID alert
 *    id) via typia.random.
 * 3. Fetch alert detail via admin endpoint using correct skuCode/alertId.
 * 4. Assert all alert fields are present and valid per IShoppingInventoryAlert
 *    (id, shopping_sku_id, alert_type, resolved, triggered_at, resolved_at,
 *    resolved_actor_type, resolved_actor_id, context_note).
 * 5. Validate audit/compliance data: actor fields for resolution, context note (if
 *    present), all timestamps, alert type among allowed values.
 * 6. Ensure all returned metadata aligns with compliance and root-cause analysis
 *    expectations. Fail if any critical field missing or mismatched.
 */
export async function test_api_admin_inventory_alert_detail_access_and_audit_trail(
  connection: api.IConnection,
) {
  // 1. Join as admin to get authorization
  const adminInput = {
    email: typia.random<string & tags.Format<"email">>(),
    password: typia.random<string & tags.MinLength<8> & tags.MaxLength<128>>(),
    name: RandomGenerator.name(),
    role: RandomGenerator.pick([
      "super",
      "support",
      "compliance",
      "operator",
    ] as const),
    status: RandomGenerator.pick([
      "active",
      "pending",
      "suspended",
      "locked",
    ] as const),
  } satisfies IShoppingAdmin.IJoin;
  const admin: IShoppingAdmin.IAuthorized =
    await api.functional.auth.admin.join(connection, { body: adminInput });
  typia.assert(admin);

  // 2. Generate test alert data
  const alert: IShoppingInventoryAlert =
    typia.random<IShoppingInventoryAlert>();
  typia.assert(alert);

  // 3. Fetch alert detail as admin
  const detail: IShoppingInventoryAlert =
    await api.functional.shopping.admin.inventory.alerts.at(connection, {
      skuCode: alert.shopping_sku_id, // using shopping_sku_id as skuCode as per schema
      alertId: alert.id,
    });
  typia.assert(detail);

  // 4. Assert main alert field presence and values
  TestValidator.equals("alert id matches", detail.id, alert.id);
  TestValidator.equals(
    "sku id matches",
    detail.shopping_sku_id,
    alert.shopping_sku_id,
  );
  TestValidator.predicate(
    "alert_type is one of allowed business constants",
    ["low_stock", "out_of_stock", "anomaly", "manual"].includes(
      detail.alert_type,
    ),
  );

  // 5. Scope: resolved, actor, and context fields
  TestValidator.predicate(
    "resolved is boolean",
    typeof detail.resolved === "boolean",
  );
  TestValidator.predicate(
    "triggered_at is ISO date string",
    typeof detail.triggered_at === "string" && detail.triggered_at.length > 0,
  );

  if (detail.resolved) {
    TestValidator.predicate(
      "resolved_at present and string",
      typeof detail.resolved_at === "string" && detail.resolved_at.length > 0,
    );
    TestValidator.predicate(
      "resolved_actor_type is allowed actor domain or null",
      ["admin", "seller", "system"].includes(detail.resolved_actor_type!) ||
        detail.resolved_actor_type === null,
    );
    TestValidator.predicate(
      "resolved_actor_id is uuid or null",
      typeof detail.resolved_actor_id === "string" ||
        detail.resolved_actor_id === null,
    );
  } else {
    TestValidator.equals(
      "resolved_at is null or undefined",
      detail.resolved_at,
      null,
    );
    TestValidator.equals(
      "resolved_actor_type is null or undefined",
      detail.resolved_actor_type,
      null,
    );
    TestValidator.equals(
      "resolved_actor_id is null or undefined",
      detail.resolved_actor_id,
      null,
    );
  }

  // 6. Optional context_note, audit business expectations
  if (detail.context_note !== null && detail.context_note !== undefined) {
    TestValidator.predicate(
      "context_note is non-empty string",
      typeof detail.context_note === "string" && detail.context_note.length > 0,
    );
  }

  // Final: all expected timeline/audit metadata present
  TestValidator.predicate(
    "all audit and compliance fields are present for compliance",
    typeof detail.id === "string" &&
      typeof detail.shopping_sku_id === "string" &&
      typeof detail.alert_type === "string" &&
      typeof detail.resolved === "boolean" &&
      typeof detail.triggered_at === "string",
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IPageIShoppingCart } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIShoppingCart";
import type { IShoppingAdmin } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingAdmin";
import type { IShoppingAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingAuthorizationToken";
import type { IShoppingCart } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingCart";
import type { IShoppingCartItem } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingCartItem";
import type { IShoppingSku } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingSku";

/**
 * Validate admin cart index API for paginated retrieval and activity audit,
 * including authentication, filters, sort order, access control, and pagination
 * handling.
 *
 * 1. Register an admin and login to obtain admin context.
 * 2. List first page of carts with default query.
 * 3. For next pages, confirm pagination metadata and non-overlap of records.
 * 4. Pick a real customer cart from results and re-query with customer ID filter:
 *    must match only that cart/customer.
 * 5. Filter by created_from, created_to, updated_from, updated_to (using known
 *    cart timestamps), validating inclusion/exclusion of target cart.
 * 6. Test sort_by and sort_order (created_at asc/desc and updated_at asc/desc);
 *    records should be in correct order per page.
 * 7. Confirm cart summary DTO structure, that relationship information is limited
 *    (customer UUID and items/SKU summaries), and verify no sensitive customer
 *    info is present.
 * 8. Attempt access with unauthenticated context to confirm forbidden error.
 * 9. For large result sets, set limit low (e.g., 2) and iterate multiple pages,
 *    confirming page/limit/records/pages fields work and no duplicate carts
 *    returned between pages.
 */
export async function test_api_admin_cart_index_full_text_search_and_activity_audit(
  connection: api.IConnection,
) {
  // 1. Admin registration and login
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const adminName = RandomGenerator.name();
  const role = RandomGenerator.pick([
    "operator",
    "support",
    "compliance",
    "super",
  ] as const);
  const status = RandomGenerator.pick([
    "active",
    "pending",
    "suspended",
    "locked",
  ] as const);
  const adminJoinResult: IShoppingAdmin.IAuthorized =
    await api.functional.auth.admin.join(connection, {
      body: {
        email: adminEmail,
        password: RandomGenerator.alphaNumeric(12),
        name: adminName,
        role,
        status,
      } satisfies IShoppingAdmin.IJoin,
    });
  typia.assert(adminJoinResult);

  // 2. Default paginated query for carts as admin
  const initialPage: IPageIShoppingCart.ISummary =
    await api.functional.shopping.admin.carts.index(connection, {
      body: { page: 1, limit: 5 } satisfies IShoppingCart.IRequest,
    });
  typia.assert(initialPage);
  TestValidator.predicate(
    "carts page has data or zero cart is allowed",
    Array.isArray(initialPage.data),
  );
  TestValidator.equals(
    "pagination info exists",
    typeof initialPage.pagination,
    "object",
  );
  TestValidator.equals("page per limit", initialPage.pagination.limit, 5);
  TestValidator.equals("current page", initialPage.pagination.current, 1);

  // 3. Page-by-page - test pagination mechanics
  if (initialPage.pagination.pages > 1) {
    const pages: IPageIShoppingCart.ISummary[] = [initialPage];
    for (let pg = 2; pg <= Math.min(initialPage.pagination.pages, 5); ++pg) {
      const pageN = await api.functional.shopping.admin.carts.index(
        connection,
        {
          body: { page: pg, limit: 5 } satisfies IShoppingCart.IRequest,
        },
      );
      typia.assert(pageN);
      TestValidator.equals("unique page", pageN.pagination.current, pg);
      pages.push(pageN);
      // All returned cart IDs must be unique across pages
      for (const prev of pages.slice(0, -1)) {
        for (const cart of pageN.data) {
          TestValidator.predicate(
            "no cart duplicated across pages",
            !prev.data.find((x) => x.id === cart.id),
          );
        }
      }
    }
  }

  // 4. Search by customer cart
  if (initialPage.data.length > 0) {
    const sampleCart = RandomGenerator.pick(initialPage.data);
    // Filter by shopping_customer_id
    const customerCartPage: IPageIShoppingCart.ISummary =
      await api.functional.shopping.admin.carts.index(connection, {
        body: {
          shopping_customer_id: sampleCart.shopping_customer_id,
          limit: 10,
        } satisfies IShoppingCart.IRequest,
      });
    typia.assert(customerCartPage);
    TestValidator.predicate(
      "all carts have target customer",
      customerCartPage.data.every(
        (x) => x.shopping_customer_id === sampleCart.shopping_customer_id,
      ),
    );

    // 5. Filter by created_from/created_to (inclusion/exclusion)
    const createdAt = sampleCart.created_at;
    const createdBefore = new Date(
      new Date(createdAt).getTime() - 24 * 60 * 60 * 1000,
    ).toISOString();
    const createdAfter = new Date(
      new Date(createdAt).getTime() + 24 * 60 * 60 * 1000,
    ).toISOString();
    const filterInclude: IPageIShoppingCart.ISummary =
      await api.functional.shopping.admin.carts.index(connection, {
        body: {
          created_from: createdBefore,
          created_to: createdAfter,
          shopping_customer_id: sampleCart.shopping_customer_id,
        } satisfies IShoppingCart.IRequest,
      });
    typia.assert(filterInclude);
    TestValidator.predicate(
      "filtered page includes sample cart",
      filterInclude.data.some((x) => x.id === sampleCart.id),
    );
    // Restrict to before createdAt (should *not* include sampleCart)
    const filterExclude: IPageIShoppingCart.ISummary =
      await api.functional.shopping.admin.carts.index(connection, {
        body: {
          created_to: createdBefore,
          shopping_customer_id: sampleCart.shopping_customer_id,
        } satisfies IShoppingCart.IRequest,
      });
    typia.assert(filterExclude);
    TestValidator.predicate(
      "filtered page does not include sample cart",
      !filterExclude.data.some((x) => x.id === sampleCart.id),
    );

    // 6. Filter by updated_from/updated_to (activity)
    const updatedAt = sampleCart.updated_at;
    const updatedBefore = new Date(
      new Date(updatedAt).getTime() - 24 * 60 * 60 * 1000,
    ).toISOString();
    const updatedAfter = new Date(
      new Date(updatedAt).getTime() + 24 * 60 * 60 * 1000,
    ).toISOString();
    const activityInclude: IPageIShoppingCart.ISummary =
      await api.functional.shopping.admin.carts.index(connection, {
        body: {
          updated_from: updatedBefore,
          updated_to: updatedAfter,
          shopping_customer_id: sampleCart.shopping_customer_id,
        } satisfies IShoppingCart.IRequest,
      });
    typia.assert(activityInclude);
    TestValidator.predicate(
      "activity filter includes sample cart",
      activityInclude.data.some((x) => x.id === sampleCart.id),
    );
    const activityExclude: IPageIShoppingCart.ISummary =
      await api.functional.shopping.admin.carts.index(connection, {
        body: {
          updated_to: updatedBefore,
          shopping_customer_id: sampleCart.shopping_customer_id,
        } satisfies IShoppingCart.IRequest,
      });
    typia.assert(activityExclude);
    TestValidator.predicate(
      "activity filter excludes sample cart",
      !activityExclude.data.some((x) => x.id === sampleCart.id),
    );
  }

  // 7. Sorting scenarios
  for (const sort_by of ["created_at", "updated_at"] as const) {
    for (const sort_order of ["asc", "desc"] as const) {
      const sortedPage = await api.functional.shopping.admin.carts.index(
        connection,
        {
          body: {
            sort_by,
            sort_order,
            limit: 10,
          } satisfies IShoppingCart.IRequest,
        },
      );
      typia.assert(sortedPage);
      if (sortedPage.data.length > 1) {
        for (let i = 1; i < sortedPage.data.length; ++i) {
          const prev = sortedPage.data[i - 1][sort_by];
          const curr = sortedPage.data[i][sort_by];
          if (sort_order === "asc") {
            TestValidator.predicate(
              `sorted ascending by ${sort_by}`,
              prev <= curr,
            );
          } else {
            TestValidator.predicate(
              `sorted descending by ${sort_by}`,
              prev >= curr,
            );
          }
        }
      }
    }
  }

  // 8. Validate DTO structure and permissions
  for (const cart of initialPage.data) {
    typia.assert<IShoppingCart.ISummary>(cart);
    TestValidator.equals(
      "cart exposes customer UUID (not expanded)",
      typeof cart.shopping_customer_id,
      "string",
    );
    TestValidator.predicate(
      "cart has item summaries array",
      Array.isArray(cart.items),
    );
    for (const item of cart.items) {
      typia.assert<IShoppingCartItem.ISummary>(item);
      typia.assert<IShoppingSku.ISummary>(item.sku);
      TestValidator.equals(
        "cart item exposes SKU",
        typeof item.sku.id,
        "string",
      );
    }
    // Ensure no forbidden properties leaked
    TestValidator.predicate(
      "cart does not expose customer email/name",
      Object.keys(cart).every(
        (key) =>
          key === "id" ||
          key === "shopping_customer_id" ||
          key === "created_at" ||
          key === "updated_at" ||
          key === "items",
      ),
    );
  }

  // 9. Unauthorized access scenario - create a connection with empty headers (no admin token)
  const unauthConn: api.IConnection = { ...connection, headers: {} };
  await TestValidator.error(
    "admin carts index forbidden without auth",
    async () => {
      await api.functional.shopping.admin.carts.index(unauthConn, {
        body: { page: 1, limit: 2 } satisfies IShoppingCart.IRequest,
      });
    },
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IPageIShoppingProductTag } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIShoppingProductTag";
import type { IShoppingAdmin } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingAdmin";
import type { IShoppingAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingAuthorizationToken";
import type { IShoppingProductTag } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingProductTag";

/**
 * E2E test for admin search and pagination of product tags.
 *
 * This test verifies that an authenticated admin can retrieve and filter
 * product tags using the advanced search capabilities in the
 * /shopping/admin/productTags endpoint.
 *
 * Steps:
 *
 * 1. Register a new admin user.
 * 2. Perform an advanced tag listing (search/query) as the admin.
 * 3. Validate response structure and pagination correctness.
 * 4. Exercise filtering (tag_code, display_value, description), search, pagination
 *    and sorting logic.
 * 5. Attempt access with an unauthorized/unauthenticated connection, expecting
 *    error.
 */
export async function test_api_product_tag_admin_search_and_pagination(
  connection: api.IConnection,
) {
  // 1. Register admin
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const admin: IShoppingAdmin.IAuthorized =
    await api.functional.auth.admin.join(connection, {
      body: {
        email: adminEmail,
        password: RandomGenerator.alphabets(12),
        name: RandomGenerator.name(),
        role: "super", // fixed for test, must match RBAC constraint
        status: "active",
      } satisfies IShoppingAdmin.IJoin,
    });
  typia.assert(admin);

  // 2. Create product tags (simulate indirect creation by search, since no create API is available)
  //    We do not have a direct API to add tags, so assume that tags already exist in the database.
  //    We'll fetch a list and use one as a reference for filtering.

  // 3. Search with no filters/pagination (default all)
  const listAll: IPageIShoppingProductTag.ISummary =
    await api.functional.shopping.admin.productTags.index(connection, {
      body: {} satisfies IShoppingProductTag.IRequest,
    });
  typia.assert(listAll);
  TestValidator.predicate(
    "admin can get at least one tag",
    listAll.data.length > 0,
  );
  const refTag = listAll.data[0];

  // 4. Test tag_code filter
  const filterByCode = await api.functional.shopping.admin.productTags.index(
    connection,
    {
      body: {
        tag_code: refTag.tag_code,
      } satisfies IShoppingProductTag.IRequest,
    },
  );
  typia.assert(filterByCode);
  TestValidator.predicate(
    "tag_code filter returns only expected tag(s)",
    filterByCode.data.every((t) => t.tag_code === refTag.tag_code),
  );

  // 5. Test display_value filter
  const filterByDisplayValue =
    await api.functional.shopping.admin.productTags.index(connection, {
      body: {
        display_value: refTag.display_value,
      } satisfies IShoppingProductTag.IRequest,
    });
  typia.assert(filterByDisplayValue);
  TestValidator.predicate(
    "display_value filter returns only expected tags",
    filterByDisplayValue.data.every(
      (t) => t.display_value === refTag.display_value,
    ),
  );

  // 6. Test description (if any description exists; else skip)
  if (
    refTag.description !== null &&
    refTag.description !== undefined &&
    refTag.description.length > 0
  ) {
    const filterByDesc = await api.functional.shopping.admin.productTags.index(
      connection,
      {
        body: {
          description: refTag.description,
        } satisfies IShoppingProductTag.IRequest,
      },
    );
    typia.assert(filterByDesc);
    TestValidator.predicate(
      "description filter returns only tags with matching description",
      filterByDesc.data.every((t) => t.description === refTag.description),
    );
  }

  // 7. Test basic search (partial string from display_value)
  const partial = refTag.display_value.slice(
    0,
    Math.max(1, Math.floor(refTag.display_value.length / 2)),
  );
  const searchResult = await api.functional.shopping.admin.productTags.index(
    connection,
    {
      body: { search: partial } satisfies IShoppingProductTag.IRequest,
    },
  );
  typia.assert(searchResult);
  TestValidator.predicate(
    "search returns tags with display_value containing partial",
    searchResult.data.some((t) => t.display_value.includes(partial)),
  );

  // 8. Test pagination: get first page with limit 2, then page 2 with same limit
  const firstPage = await api.functional.shopping.admin.productTags.index(
    connection,
    {
      body: {
        page: 1 as number & tags.Type<"int32">,
        limit: 2 as number & tags.Type<"int32">,
      } satisfies IShoppingProductTag.IRequest,
    },
  );
  typia.assert(firstPage);
  TestValidator.equals(
    "pagination: limit 2",
    firstPage.data.length,
    Math.min(2, listAll.pagination.records),
  );
  const secondPage = await api.functional.shopping.admin.productTags.index(
    connection,
    {
      body: {
        page: 2 as number & tags.Type<"int32">,
        limit: 2 as number & tags.Type<"int32">,
      } satisfies IShoppingProductTag.IRequest,
    },
  );
  typia.assert(secondPage);
  TestValidator.equals(
    "pagination: second page returns valid data array",
    Array.isArray(secondPage.data),
    true,
  );

  // 9. Sorting: sort_by display_value ascending
  const sortedAsc = await api.functional.shopping.admin.productTags.index(
    connection,
    {
      body: {
        sort_by: "display_value",
        order: "asc",
      } satisfies IShoppingProductTag.IRequest,
    },
  );
  typia.assert(sortedAsc);
  for (let i = 1; i < sortedAsc.data.length; ++i) {
    TestValidator.predicate(
      `sorting ascending: ${sortedAsc.data[i - 1].display_value} <= ${sortedAsc.data[i].display_value}`,
      sortedAsc.data[i - 1].display_value <= sortedAsc.data[i].display_value,
    );
  }
  // sort_by display_value descending
  const sortedDesc = await api.functional.shopping.admin.productTags.index(
    connection,
    {
      body: {
        sort_by: "display_value",
        order: "desc",
      } satisfies IShoppingProductTag.IRequest,
