          dimensionCode,
          body: nextPageReq,
        },
      );
    typia.assert(page2);
    TestValidator.equals("pagination page is 2", page2.pagination.current, 2);
    TestValidator.predicate(
      "data array exists on page 2",
      Array.isArray(page2.data),
    );
  }
}

