import type { IShoppingCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingCategory";
import type { IShoppingProduct } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingProduct";
import type { IShoppingProductAttribute } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingProductAttribute";
import type { IShoppingProductImage } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingProductImage";
import type { IShoppingSeller } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingSeller";
import type { IShoppingSku } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingSku";
import type { IShoppingSkuImage } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingSkuImage";
import type { IShoppingSkuVariant } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingSkuVariant";
import type { IShoppingTag } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingTag";

/**
 * Test that an admin can update SKU details for an existing product SKU and
 * that modifications are properly reflected.
 *
 * Steps:
 *
 * 1. Register a new admin account via /auth/admin/join (establishes admin auth
 *    context)
 * 2. Create a product via admin endpoint
 * 3. Create an SKU under the created product as admin
 * 4. Update the SKU fields (such as price, is_active, barcode, or status) via SKU
 *    update endpoint
 * 5. Confirm the SKUs are updated as expected
 * 6. Attempt to update a non-existent SKU and expect failure (error validation)
 *
 * Business rules enforced: only authorized admin can update SKUs; update must
 * change fields; cannot update non-existent SKUs.
 */
export async function test_api_sku_update_by_admin(
  connection: api.IConnection,
) {
  // 1. Register new admin and authenticate
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const adminPassword = RandomGenerator.alphaNumeric(12);
  const admin: IShoppingAdmin.IAuthorized =
    await api.functional.auth.admin.join(connection, {
      body: {
        email: adminEmail,
        password: adminPassword,
        name: RandomGenerator.name(),
        role: RandomGenerator.pick(["super", "operator", "support"] as const),
        status: "active",
      } satisfies IShoppingAdmin.IJoin,
    });
  typia.assert(admin);

  // 2. Create a new product as admin
  const productCode = RandomGenerator.alphaNumeric(10);
  const product: IShoppingProduct =
    await api.functional.shopping.admin.products.create(connection, {
      body: {
        code: productCode,
        name: RandomGenerator.paragraph({ sentences: 3 }),
        description: RandomGenerator.content({ paragraphs: 2 }),
        main_image_uri:
          "https://cdn.example.com/product/" +
          RandomGenerator.alphaNumeric(8) +
          ".jpg",
        status: "active",
        business_status: "approved",
        shipping_weight_grams: typia.random<
          number & tags.Type<"uint32"> & tags.Minimum<10> & tags.Maximum<10000>
        >() satisfies number as number,
        shipping_length_cm: typia.random<
          number & tags.Type<"uint32"> & tags.Minimum<5> & tags.Maximum<200>
        >() satisfies number as number,
        shipping_width_cm: typia.random<
          number & tags.Type<"uint32"> & tags.Minimum<5> & tags.Maximum<200>
        >() satisfies number as number,
        shipping_height_cm: typia.random<
          number & tags.Type<"uint32"> & tags.Minimum<5> & tags.Maximum<200>
        >() satisfies number as number,
        shipping_options: RandomGenerator.paragraph({ sentences: 2 }),
      } satisfies IShoppingProduct.ICreate,
    });
  typia.assert(product);

  // 3. Create SKU for the product as admin
  // The variant_attribute_value_ids array must have at least 1 string, so use a random uuid string.
  const originalSkuCode = RandomGenerator.alphaNumeric(12);
  const variantAttributeValueId = typia.random<string & tags.Format<"uuid">>();
  const sku: IShoppingSku =
    await api.functional.shopping.admin.products.skus.create(connection, {
      productCode: productCode,
      body: {
        sku_code: originalSkuCode,
        price: 19900,
        is_active: true,
        barcode: RandomGenerator.alphaNumeric(10),
        status: "in_stock",
        variant_attribute_value_ids: [variantAttributeValueId],
      } satisfies IShoppingSku.ICreate,
    });
  typia.assert(sku);

  // 4. Update the SKU: change price, activation status, status and barcode
  const updateBody = {
    price: 29900,
    is_active: false,
    barcode: RandomGenerator.alphaNumeric(12),
    status: "discontinued",
  } satisfies IShoppingSku.IUpdate;
  const updatedSku: IShoppingSku =
    await api.functional.shopping.admin.products.skus.update(connection, {
      productCode: productCode,
      skuCode: originalSkuCode,
      body: updateBody,
    });
  typia.assert(updatedSku);
  TestValidator.equals(
    "sku is updated by admin",
    updatedSku.sku_code,
    originalSkuCode,
  );
  TestValidator.equals("price updated", updatedSku.price, updateBody.price);
  TestValidator.equals(
    "is_active updated",
    updatedSku.is_active,
    updateBody.is_active,
  );
  TestValidator.equals(
    "barcode updated",
    updatedSku.barcode,
    updateBody.barcode,
  );
  TestValidator.equals("status updated", updatedSku.status, updateBody.status);

  // 5. Attempt to update a non-existent SKU and expect error
  await TestValidator.error("updating non-existent sku fails", async () => {
    await api.functional.shopping.admin.products.skus.update(connection, {
      productCode: productCode,
      skuCode: "NOT_FOUND_SKU" + RandomGenerator.alphaNumeric(4),
      body: { price: 12345 } satisfies IShoppingSku.IUpdate,
    });
  });
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IShoppingAttributeDimension } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingAttributeDimension";
import type { IShoppingAttributeValue } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingAttributeValue";
import type { IShoppingAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingAuthorizationToken";
import type { IShoppingCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingCategory";
import type { IShoppingProduct } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingProduct";
import type { IShoppingProductAttribute } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingProductAttribute";
import type { IShoppingProductImage } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingProductImage";
import type { IShoppingSeller } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingSeller";
import type { IShoppingSku } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingSku";
import type { IShoppingSkuImage } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingSkuImage";
import type { IShoppingSkuVariant } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingSkuVariant";
import type { IShoppingTag } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingTag";

/**
 * Validates that a seller can soft delete their own SKU, but not those owned by
 * others, and that deleted SKUs have a deleted_at value.
 *
 * 1. Seller A registers and creates a product
 * 2. Seller A creates a valid SKU on the product, using a random attribute UUID
 * 3. Seller A deletes the SKU and verifies the soft delete (deleted_at is set)
 * 4. Attempting to delete the same SKU again fails
 * 5. Seller B registers, creates own product/SKU, then attempts to delete Seller
 *    A's SKU and fails
 */
export async function test_api_sku_soft_delete_by_seller(
  connection: api.IConnection,
) {
  // 1. Seller A signs up
  const sellerAEmail = typia.random<string & tags.Format<"email">>();
  const sellerA = await api.functional.auth.seller.join(connection, {
    body: {
      email: sellerAEmail,
      password: "password123!",
      display_name: RandomGenerator.name(1),
      contact_phone: RandomGenerator.mobile(),
      status: "pending",
    } satisfies IShoppingSeller.IJoin,
  });
  typia.assert(sellerA);

  // 2. Seller A creates a product
  const productCodeA = RandomGenerator.alphaNumeric(12);
  const productA = await api.functional.shopping.seller.products.create(
    connection,
    {
      body: {
        code: productCodeA,
        name: RandomGenerator.paragraph({ sentences: 2 }),
        description: RandomGenerator.content({ paragraphs: 1 }),
        main_image_uri: "https://dummyimage.com/600x400/000/fff",
        status: "draft",
        business_status: "in_review",
      } satisfies IShoppingProduct.ICreate,
    },
  );
  typia.assert(productA);
  TestValidator.equals("product code matches", productA.code, productCodeA);

  // 3. Seller A creates a SKU under productA
  // For attribute/variant, just generate one fake attribute value id for required spec
  const fakeAttributeValueId: string & tags.Format<"uuid"> = typia.random<
    string & tags.Format<"uuid">
  >();
  const skuCodeA = RandomGenerator.alphaNumeric(14);
  const skuA = await api.functional.shopping.seller.products.skus.create(
    connection,
    {
      productCode: productCodeA,
      body: {
        sku_code: skuCodeA,
        price: 9990,
        is_active: true,
        status: "in_stock",
        variant_attribute_value_ids: [fakeAttributeValueId],
      } satisfies IShoppingSku.ICreate,
    },
  );
  typia.assert(skuA);
  TestValidator.equals("sku code matches", skuA.sku_code, skuCodeA);
  TestValidator.equals(
    "sku deleted_at is not set initially",
    skuA.deleted_at,
    null,
  );

  // 4. Seller A soft deletes the SKU
  await api.functional.shopping.seller.products.skus.erase(connection, {
    productCode: productCodeA,
    skuCode: skuCodeA,
  });

  // No direct GET to fetch the SKU--simulate by attempting to delete again, which should fail
  await TestValidator.error("cannot delete SKU twice", async () => {
    await api.functional.shopping.seller.products.skus.erase(connection, {
      productCode: productCodeA,
      skuCode: skuCodeA,
    });
  });

  // 5. Another seller (seller B) registers and creates product/SKU
  const sellerBEmail = typia.random<string & tags.Format<"email">>();
  const sellerB = await api.functional.auth.seller.join(connection, {
    body: {
      email: sellerBEmail,
      password: "password123!",
      display_name: RandomGenerator.name(1),
      contact_phone: RandomGenerator.mobile(),
      status: "pending",
    } satisfies IShoppingSeller.IJoin,
  });
  typia.assert(sellerB);

  const productCodeB = RandomGenerator.alphaNumeric(12);
  const productB = await api.functional.shopping.seller.products.create(
    connection,
    {
      body: {
        code: productCodeB,
        name: RandomGenerator.paragraph({ sentences: 2 }),
        description: RandomGenerator.content({ paragraphs: 1 }),
        main_image_uri: "https://dummyimage.com/600x400/000/fff",
        status: "draft",
        business_status: "in_review",
      } satisfies IShoppingProduct.ICreate,
    },
  );
  typia.assert(productB);

  // Seller B creates a SKU (not used for test, but shows seller B's own SKUs)
  const skuCodeB = RandomGenerator.alphaNumeric(14);
  const skuB = await api.functional.shopping.seller.products.skus.create(
    connection,
    {
      productCode: productCodeB,
      body: {
        sku_code: skuCodeB,
        price: 5000,
        is_active: true,
        status: "in_stock",
        variant_attribute_value_ids: [fakeAttributeValueId],
      } satisfies IShoppingSku.ICreate,
    },
  );
  typia.assert(skuB);

  // Seller B attempts to delete Seller A's (already archived) SKU - should FAIL
  await TestValidator.error(
    "other seller cannot delete SKU that is not theirs",
    async () => {
      await api.functional.shopping.seller.products.skus.erase(connection, {
        productCode: productCodeA,
        skuCode: skuCodeA,
      });
    },
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IPageIShoppingProduct } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIShoppingProduct";
import type { IShoppingAdmin } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingAdmin";
import type { IShoppingAttributeDimension } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingAttributeDimension";
import type { IShoppingAttributeValue } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingAttributeValue";
import type { IShoppingAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingAuthorizationToken";
import type { IShoppingCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingCategory";
import type { IShoppingProduct } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingProduct";
import type { IShoppingProductAttribute } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingProductAttribute";
import type { IShoppingProductImage } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingProductImage";
import type { IShoppingSeller } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingSeller";
import type { IShoppingSku } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingSku";
import type { IShoppingSkuImage } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingSkuImage";
import type { IShoppingSkuVariant } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingSkuVariant";
import type { IShoppingTag } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingTag";

/**
 * Validates search and filter of catalog products as seen by a customer.
 * Ensures only active and non-deleted products are shown and that filters
 * behave as expected for all documented parameters.
 *
 * 1. Register admin and create various types of products (active, archived, etc.)
 * 2. Test general keyword search and specific attribute-based filters
 * 3. Test pagination and sorting
 * 4. Ensure invisible products (archived, deleted, inactive) are excluded
 */
export async function test_api_catalog_product_search_by_customer(
  connection: api.IConnection,
) {
  // 1. Register admin to gain privileges for product creation.
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const adminName = RandomGenerator.name();
  const admin: IShoppingAdmin.IAuthorized =
    await api.functional.auth.admin.join(connection, {
      body: {
        email: adminEmail,
        password: RandomGenerator.alphaNumeric(12),
        name: adminName,
        role: "super",
        status: "active",
      } satisfies IShoppingAdmin.IJoin,
    });
  typia.assert(admin);

  // 2. Create multiple products of various types: one visible (active), one hidden (archived), one with different attributes.
  const activeCode = RandomGenerator.alphaNumeric(8);
  const activeName = RandomGenerator.paragraph({ sentences: 2 });
  const activeDesc = RandomGenerator.paragraph({ sentences: 4 });
  const activeMainImage = `https://img.example.com/${RandomGenerator.alphaNumeric(10)}.jpg`;
  const activeStatus = "active";
  const activeBusinessStatus = "approved";
  const activePrice = 24900;
  const activeProduct: IShoppingProduct =
    await api.functional.shopping.admin.products.create(connection, {
      body: {
        code: activeCode,
        name: activeName,
        description: activeDesc,
        main_image_uri: activeMainImage,
        status: activeStatus,
        business_status: activeBusinessStatus,
        shipping_weight_grams: 400,
        shipping_length_cm: 50,
        shipping_width_cm: 20,
        shipping_height_cm: 10,
        shipping_options: "Standard shipping",
      } satisfies IShoppingProduct.ICreate,
    });
  typia.assert(activeProduct);

  // Create a product with status "archived" (should NOT be visible)
  const archivedProduct: IShoppingProduct =
    await api.functional.shopping.admin.products.create(connection, {
      body: {
        code: RandomGenerator.alphaNumeric(8),
        name: RandomGenerator.paragraph({ sentences: 2 }),
        description: RandomGenerator.paragraph({ sentences: 5 }),
        main_image_uri: `https://img.example.com/${RandomGenerator.alphaNumeric(10)}.jpg`,
        status: "archived",
        business_status: "approved",
      } satisfies IShoppingProduct.ICreate,
    });
  typia.assert(archivedProduct);

  // 3. Test keyword search matches product name
  {
    const keyword = RandomGenerator.substring(activeName);
    const req = {
      page: 1 as number & tags.Type<"int32">,
      limit: 10 as number & tags.Type<"int32">,
      keyword,
    } satisfies IShoppingProduct.IRequest;
    const result = await api.functional.shopping.products.index(connection, {
      body: req,
    });
    typia.assert(result);
    TestValidator.predicate(
      "active product appears in keyword search",
      result.data.some((p) => p.code === activeProduct.code),
    );
    TestValidator.predicate(
      "archived does not appear in search",
      !result.data.some((p) => p.code === archivedProduct.code),
    );
    TestValidator.predicate(
      "all returned are active",
      result.data.every((p) => p.status === "active"),
    );
  }

  // 4. Filter by product code
  {
    const req = {
      page: 1 as number & tags.Type<"int32">,
      limit: 10 as number & tags.Type<"int32">,
      code: activeProduct.code,
    } satisfies IShoppingProduct.IRequest;
    const result = await api.functional.shopping.products.index(connection, {
      body: req,
    });
    typia.assert(result);
    TestValidator.equals(
      "filtered returns only the correct product",
      result.data.length,
      1,
    );
    TestValidator.equals(
      "returns correct product code",
      result.data[0].code,
      activeProduct.code,
    );
  }

  // 5. Filter by status (should only get active)
  {
    const req = {
      page: 1 as number & tags.Type<"int32">,
      limit: 10 as number & tags.Type<"int32">,
      status: "active",
    } satisfies IShoppingProduct.IRequest;
    const result = await api.functional.shopping.products.index(connection, {
      body: req,
    });
    typia.assert(result);
    TestValidator.predicate(
      "all status filtered products are active",
      result.data.every((p) => p.status === "active"),
    );
    TestValidator.predicate(
      "archived not included in status filtered",
      !result.data.some((p) => p.code === archivedProduct.code),
    );
  }

  // 6. Pagination: limit 1, expect single result and pagination matches
  {
    const req = {
      page: 1 as number & tags.Type<"int32">,
      limit: 1 as number & tags.Type<"int32">,
    } satisfies IShoppingProduct.IRequest;
    const result = await api.functional.shopping.products.index(connection, {
      body: req,
    });
    typia.assert(result);
    TestValidator.equals(
      "paginated result respects limit",
      result.data.length,
      1,
    );
    TestValidator.equals(
      "pagination.limit matches",
      result.pagination.limit,
      1,
    );
    TestValidator.predicate(
      "all paginated products are active",
      result.data.every((p) => p.status === "active"),
    );
  }

  // 7. Sorting: test sort_by name ascending and descending
  {
    for (const sort_direction of ["asc", "desc"] as const) {
      const req = {
        page: 1 as number & tags.Type<"int32">,
        limit: 10 as number & tags.Type<"int32">,
        sort_by: "name",
        sort_direction,
      } satisfies IShoppingProduct.IRequest;
      const result = await api.functional.shopping.products.index(connection, {
        body: req,
      });
      typia.assert(result);
      TestValidator.predicate(
        `all sorted products are active (${sort_direction})`,
        result.data.every((p) => p.status === "active"),
      );
      // Just check sorted array monotonicity, if at least two entries
      if (result.data.length >= 2) {
        const compare =
          sort_direction === "asc"
            ? (a: string, b: string) => a.localeCompare(b) <= 0
            : (a: string, b: string) => a.localeCompare(b) >= 0;
        for (let i = 1; i < result.data.length; ++i) {
          TestValidator.predicate(
            `sorted order correct at index ${i} (${sort_direction})`,
            compare(result.data[i - 1].name, result.data[i].name),
          );
        }
      }
    }
  }

  // 8. Negative: filter code for archived product (should not appear)
  {
    const req = {
      page: 1 as number & tags.Type<"int32">,
      limit: 10 as number & tags.Type<"int32">,
      code: archivedProduct.code,
    } satisfies IShoppingProduct.IRequest;
    const result = await api.functional.shopping.products.index(connection, {
      body: req,
    });
    typia.assert(result);
    TestValidator.equals(
      "archived product is never visible to customer search",
      result.data.length,
      0,
    );
  }
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IShoppingAttributeDimension } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingAttributeDimension";
import type { IShoppingAttributeValue } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingAttributeValue";
