  // 7. Find any available status event entry
  const statusHistory = order.status_history.find(
    (evt) => typeof evt.id === "string" && typeof evt.to_status === "string",
  );
  typia.assertGuard<IShoppingOrderStatusHistory>(statusHistory!);

