/**
 * Validate public retrieval of a SKU detail.
 *
 * Business Flow:
 *
 * 1. Register as platform admin
 * 2. Create a product as admin
 * 3. Create two attribute dimensions: color and size (simulate, since attribute
 *    API isn't present)
 * 4. Generate two fake attribute values for variant (
 *
 *    - Color: blue, size: L) (simulate attribute assignment since no attribute
 *         creation API is given)
 * 5. Create and attach a SKU to the product using one attribute value each
 *    (variant_attribute_value_ids)
 * 6. Retrieve the SKU publicly and verify all properties, parent product summary
 *    and variants are included and match, and status is active
 * 7. Test retrieval for non-existent SKU code (expect error)
 * 8. (Optional) Could simulate inactive/deleted SKUs if there was an API to change
 *    these states, but such APIs are not provided, so only valid/existence path
 *    is checked.
 */
export async function test_api_sku_detail_public_retrieval(
  connection: api.IConnection,
) {
  // Platform admin join
  const adminEmail = RandomGenerator.alphaNumeric(8) + "@admin.com";
  const adminJoin = await api.functional.auth.admin.join(connection, {
    body: {
      email: adminEmail,
      password: RandomGenerator.alphaNumeric(12),
      name: RandomGenerator.name(),
      role: "super",
      status: "active",
    } satisfies IShoppingAdmin.IJoin,
  });
  typia.assert(adminJoin);

  // Create a product as admin
  const productCode = "P-" + RandomGenerator.alphaNumeric(6);
  const createProduct = await api.functional.shopping.admin.products.create(
    connection,
    {
      body: {
        code: productCode,
        name: RandomGenerator.name(3),
        description: RandomGenerator.content({
          paragraphs: 1,
          sentenceMin: 3,
          sentenceMax: 8,
        }),
        main_image_uri:
          "https://example.com/images/" + RandomGenerator.alphaNumeric(10),
        status: "active",
        business_status: "in_review",
      } satisfies IShoppingProduct.ICreate,
    },
  );
  typia.assert(createProduct);
  TestValidator.equals("productCode matches", createProduct.code, productCode);

  // Simulate attribute values (simulate since no create API):
  // Fake value1 = color-blue (uuid), value2 = size-L (uuid)
  // These are not referenced in SKU but needed to satisfy DTO contract.
  // We'll generate random UUIDs and use them in variant_attribute_value_ids
  const attrValueColorId = typia.random<string & tags.Format<"uuid">>();
  const attrValueSizeId = typia.random<string & tags.Format<"uuid">>();

  // Create SKU
  const skuCode = "SKU-" + RandomGenerator.alphaNumeric(8);
  const skuPrice = Math.floor(Math.random() * 10000) + 1000;
  const skuStatus = "in_stock";
  const skuBarcode = RandomGenerator.alphaNumeric(12);
  const createSku = await api.functional.shopping.admin.products.skus.create(
    connection,
    {
      productCode: productCode,
      body: {
        sku_code: skuCode,
        price: skuPrice,
        is_active: true,
        barcode: skuBarcode,
        status: skuStatus,
        variant_attribute_value_ids: [
          attrValueColorId,
          attrValueSizeId,
        ] satisfies string[],
      } satisfies IShoppingSku.ICreate,
    },
  );
  typia.assert(createSku);
  TestValidator.equals("skuCode matches", createSku.sku_code, skuCode);

  // --- Public retrieval path: ---
  // Retrieve the SKU publicly by product and SKU code
  const pubSku = await api.functional.shopping.products.skus.at(connection, {
    productCode: productCode,
    skuCode: skuCode,
  });
  typia.assert(pubSku);
  // Validate basics
  TestValidator.equals("sku_code matches", pubSku.sku_code, skuCode);
  TestValidator.equals(
    "product code in summary matches",
    pubSku.product.code,
    productCode,
  );
  TestValidator.equals("SKU is active", pubSku.is_active, true);
  TestValidator.equals("SKU price matches", pubSku.price, skuPrice);
  TestValidator.equals("SKU status matches", pubSku.status, skuStatus);
  TestValidator.equals("barcode matches", pubSku.barcode, skuBarcode);
  // Variant attribute IDs match
  const variantIds = pubSku.variant_attributes.map(
    (v) => v.shopping_attribute_value_id,
  );
  TestValidator.equals("variant IDs match", variantIds, [
    attrValueColorId,
    attrValueSizeId,
  ]);
  // Product summary matches
  TestValidator.equals(
    "parent product code in summary",
    pubSku.product.code,
    createProduct.code,
  );
  TestValidator.equals(
    "parent product name in summary",
    pubSku.product.name,
    createProduct.name,
  );
  // Now test retrieval of a non-existent SKU code (should error)
  await TestValidator.error(
    "retrieving nonexistent SKU should fail",
    async () => {
      await api.functional.shopping.products.skus.at(connection, {
        productCode: productCode,
        skuCode: "nonexist-sku-" + RandomGenerator.alphaNumeric(4),
      });
    },
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IShoppingAttributeDimension } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingAttributeDimension";
import type { IShoppingAttributeValue } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingAttributeValue";
import type { IShoppingAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingAuthorizationToken";
import type { IShoppingCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingCategory";
import type { IShoppingProduct } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingProduct";
import type { IShoppingProductAttribute } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingProductAttribute";
import type { IShoppingProductImage } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingProductImage";
import type { IShoppingSeller } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingSeller";
import type { IShoppingSku } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingSku";
import type { IShoppingSkuImage } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingSkuImage";
import type { IShoppingSkuVariant } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingSkuVariant";
import type { IShoppingTag } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingTag";

/**
 * Test that a seller can create a SKU under their own product.
 *
 * 1. Seller registers and logs in.
 * 2. Seller creates a product with minimal valid fields.
 * 3. Seller creates a SKU under the product, using all required fields.
 * 4. Confirm that the SKU creation response includes all audit fields, correct
 *    references, and business logic is enforced.
 * 5. Attempt to create a SKU with the same sku_code, must fail (uniqueness
 *    enforced).
 * 6. Attempt to create a SKU under another seller's product, must fail (ownership
 *    enforced).
 * 7. Attempt to create a SKU with no attributes, must fail
 *    (variant_attribute_value_ids required).
 * 8. Create a SKU with is_active false, confirm activation is tracked.
 */
export async function test_api_sku_creation_by_seller(
  connection: api.IConnection,
) {
  // 1. Seller registers and logs in
  const sellerEmail = typia.random<string & tags.Format<"email">>();
  const sellerReg: IShoppingSeller.IAuthorized =
    await api.functional.auth.seller.join(connection, {
      body: {
        email: sellerEmail,
        password: RandomGenerator.alphaNumeric(12),
        display_name: RandomGenerator.name(1),
        contact_phone: RandomGenerator.mobile(),
        status: "pending",
      },
    });
  typia.assert(sellerReg);

  // 2. Seller creates a product
  const productCode = RandomGenerator.alphaNumeric(10);
  const productReq = {
    code: productCode,
    name: RandomGenerator.paragraph({ sentences: 2 }),
    description: RandomGenerator.content({
      paragraphs: 1,
      sentenceMin: 8,
      sentenceMax: 14,
      wordMin: 3,
      wordMax: 8,
    }),
    main_image_uri: "https://example.com/product.jpg",
    status: "draft",
    business_status: "in_review",
  } satisfies IShoppingProduct.ICreate;
  const product: IShoppingProduct =
    await api.functional.shopping.seller.products.create(connection, {
      body: productReq,
    });
  typia.assert(product);

  // 3. Prepare variant attribute value ids — use first value from product attributes if available
  let attributeValueId = undefined as string | undefined;
  if (product.attributes.length > 0) {
    attributeValueId = product.attributes[0].attribute_value.id;
  } else {
    // If attributes are empty, create a dummy attribute value id (simulate, as we cannot create real attributes here)
    // For a real test, this should be dynamically retrieved via a prior catalog setup, but we use a random UUID for now
    attributeValueId = typia.random<string & tags.Format<"uuid">>();
  }

  // 4. Seller creates a SKU
  const skuCode = RandomGenerator.alphaNumeric(8);
  const skuReq = {
    sku_code: skuCode,
    price: Math.floor(Math.random() * 100000) + 1000,
    is_active: true,
    status: "in_stock",
    variant_attribute_value_ids: [attributeValueId],
  } satisfies IShoppingSku.ICreate;
  const sku: IShoppingSku =
    await api.functional.shopping.seller.products.skus.create(connection, {
      productCode: product.code,
      body: skuReq,
    });
  typia.assert(sku);

  // 5. Confirm response includes correct references, audit fields, product, and matches request
  TestValidator.equals(
    "SKU productCode matches",
    sku.product.code,
    product.code,
  );
  TestValidator.equals("SKU code matches", sku.sku_code, skuCode);
  TestValidator.equals("SKU is_active matches", sku.is_active, true);
  TestValidator.equals("SKU status matches", sku.status, "in_stock");
  TestValidator.predicate(
    "SKU id is UUID",
    typeof sku.id === "string" && /^[0-9a-f-]{36}$/i.test(sku.id),
  );
  TestValidator.predicate(
    "SKU shopping_product_id is UUID",
    typeof sku.shopping_product_id === "string" &&
      /^[0-9a-f-]{36}$/i.test(sku.shopping_product_id),
  );
  TestValidator.predicate(
    "SKU created_at is date-time format",
    typeof sku.created_at === "string" &&
      /\d{4}-[0-9]{2}-[0-9]{2}T[0-9]{2}:[0-9]{2}:[0-9]{2}/.test(sku.created_at),
  );
  TestValidator.predicate(
    "SKU updated_at is date-time format",
    typeof sku.updated_at === "string" &&
      /\d{4}-[0-9]{2}-[0-9]{2}T[0-9]{2}:[0-9]{2}:[0-9]{2}/.test(sku.updated_at),
  );
  TestValidator.equals(
    "SKU has at least 1 variant attribute",
    sku.variant_attributes.length >= 1,
    true,
  );

  // 6. Attempt to create a SKU with same sku_code, expect error (uniqueness enforced)
  await TestValidator.error("duplicated SKU code rejected", async () => {
    await api.functional.shopping.seller.products.skus.create(connection, {
      productCode: product.code,
      body: {
        sku_code: skuCode,
        price: Math.floor(Math.random() * 50000) + 500,
        is_active: true,
        status: "in_stock",
        variant_attribute_value_ids: [attributeValueId],
      } satisfies IShoppingSku.ICreate,
    });
  });

  // 7. Simulate another seller and try unauthorized SKU creation
  const seller2Email = typia.random<string & tags.Format<"email">>();
  const seller2: IShoppingSeller.IAuthorized =
    await api.functional.auth.seller.join(connection, {
      body: {
        email: seller2Email,
        password: RandomGenerator.alphaNumeric(12),
        display_name: RandomGenerator.name(1),
        contact_phone: RandomGenerator.mobile(),
        status: "pending",
      },
    });
  typia.assert(seller2);
  // This switches the connection's token to seller2
  await TestValidator.error(
    "Unauthorized seller cannot create SKU for product they don't own",
    async () => {
      await api.functional.shopping.seller.products.skus.create(connection, {
        productCode: product.code,
        body: {
          sku_code: RandomGenerator.alphaNumeric(8),
          price: Math.floor(Math.random() * 10000) + 1234,
          is_active: true,
          status: "in_stock",
          variant_attribute_value_ids: [attributeValueId],
        } satisfies IShoppingSku.ICreate,
      });
    },
  );

  // 8. Switch back to original seller (to restore token)
  await api.functional.auth.seller.join(connection, {
    body: {
      email: sellerEmail,
      password: sellerReg.token.access, // Re-using registration password would normally be stored, but not accessible in current flow; assume it's the same as registration above
      display_name: sellerReg.display_name,
      contact_phone: sellerReg.contact_phone,
      status: "pending",
    },
  });

  // 9. Attempt to create a SKU with no variant_attribute_value_ids, expect failure
  await TestValidator.error(
    "SKU variant_attribute_value_ids must not be empty",
    async () => {
      await api.functional.shopping.seller.products.skus.create(connection, {
        productCode: product.code,
        body: {
          sku_code: RandomGenerator.alphaNumeric(8),
          price: Math.floor(Math.random() * 80000) + 777,
          is_active: true,
          status: "in_stock",
          variant_attribute_value_ids: [],
        } satisfies IShoppingSku.ICreate,
      });
    },
  );

  // 10. Create an inactive SKU and check is_active property in response
  const skuCodeInactive = RandomGenerator.alphaNumeric(8);
  const skuInactive = await api.functional.shopping.seller.products.skus.create(
    connection,
    {
      productCode: product.code,
      body: {
        sku_code: skuCodeInactive,
        price: Math.floor(Math.random() * 100000) + 2000,
        is_active: false,
        status: "in_stock",
        variant_attribute_value_ids: [attributeValueId],
      } satisfies IShoppingSku.ICreate,
    },
  );
  typia.assert(skuInactive);
  TestValidator.equals(
    "SKU inactive is_active matches",
    skuInactive.is_active,
    false,
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IShoppingAdmin } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingAdmin";
import type { IShoppingAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingAuthorizationToken";

/**
 * Verifies permanent deletion of an abuse report for a product review by an
 * admin.
 *
 * 1. Registers a new admin account, confirming that administrative privileges are
 *    active and a valid admin JWT is issued.
 * 2. (Mocked in this test scope) Prepares random UUIDs for reviewId and
 *    abuseReportId to simulate a review and its abuse report. Real creation
 *    flows are skipped due to missing API coverage for those resources in the
 *    provided SDK. In a full system, these resources would be created up
 *    front.
 * 3. As an authenticated admin, calls the DELETE
 *    /shopping/admin/reviews/{reviewId}/abuseReports/{abuseReportId} endpoint
 *    to permanently delete the abuse report. Confirms request succeeds without
 *    error (void response).
 * 4. Immediately attempts the delete call again using the same IDs, asserting that
 *    a proper error (not found/forbidden) is thrown, indicating the report was
 *    indeed deleted in the first operation.
 * 5. Tries deletion with totally invalid random UUIDs to assert not
 *    found/forbidden errors are thrown for non-existent resources.
 * 6. There is no visible retrieval API for confirming deletion of abuse reports,
 *    so further validation of system state or audit records is out of scope for
 *    this test due to API limitations.
 */
export async function test_api_admin_abuse_report_permanent_deletion(
  connection: api.IConnection,
) {
  // 1. Register a new admin and verify privileges
  const adminInput = {
    email: typia.random<string & tags.Format<"email">>(),
    password: RandomGenerator.alphaNumeric(16),
    name: RandomGenerator.name(),
    role: RandomGenerator.pick([
      "super",
      "support",
      "compliance",
      "operator",
    ] as const),
    status: "active",
  } satisfies IShoppingAdmin.IJoin;
  const admin = await api.functional.auth.admin.join(connection, {
    body: adminInput,
  });
  typia.assert(admin);
  TestValidator.equals("registered admin email", admin.email, adminInput.email);
  TestValidator.equals("admin account status active", admin.status, "active");
  TestValidator.equals("admin privilege correct", admin.role, adminInput.role);
  TestValidator.predicate(
    "admin has authorization token",
    typeof admin.token.access === "string" && admin.token.access.length > 0,
  );

  // 2. Prepare random UUIDs for reviewId and abuseReportId
  const reviewId = typia.random<string & tags.Format<"uuid">>();
  const abuseReportId = typia.random<string & tags.Format<"uuid">>();

  // 3. Delete the abuse report (assumes IDs exist in real system/context)
  await api.functional.shopping.admin.reviews.abuseReports.erase(connection, {
    reviewId,
    abuseReportId,
  });

  // 4. Try to delete again to confirm proper error is thrown for non-existence
  await TestValidator.error(
    "second delete with same IDs should fail",
    async () => {
      await api.functional.shopping.admin.reviews.abuseReports.erase(
        connection,
        {
          reviewId,
          abuseReportId,
        },
      );
    },
  );

  // 5. Attempt deletion using totally unrelated random UUIDs
  await TestValidator.error(
    "delete with unrelated random IDs should fail",
    async () => {
      await api.functional.shopping.admin.reviews.abuseReports.erase(
        connection,
        {
          reviewId: typia.random<string & tags.Format<"uuid">>(),
          abuseReportId: typia.random<string & tags.Format<"uuid">>(),
        },
      );
    },
  );
  // 6. No API to verify audit log or fetch deleted report, so test ends here
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
