/**
 * Validates the full customer order line creation workflow, ensuring only the
 * order owner can add lines and all prerequisites are met.
 *
 * Steps:
 *
 * 1. Seller registers.
 * 2. Seller creates a product.
 * 3. Seller adds at least one SKU with at least one variant attribute.
 * 4. Customer registers/authenticates.
 * 5. Customer creates an order referencing the SKU (at least one line).
 * 6. Customer adds an additional order line using the same SKU with valid
 *    quantity/price—verify linkage and structure.
 * 7. Ensure only customer can add lines—fail if seller/other customer tries
 *    (TestValidator.error).
 * 8. Fail to add a line for non-existent SKU (invalid SKU ID).
 * 9. Fail to add a line for out-of-stock SKU (simulate by disabling
 *    is_active/status on SKU and attempting add).
 */
export async function test_api_customer_order_line_creation_workflow(
  connection: api.IConnection,
) {
  // 1. Seller registers
  const sellerEmail = typia.random<string & tags.Format<"email">>();
  const seller: IShoppingSeller.IAuthorized =
    await api.functional.auth.seller.join(connection, {
      body: {
        email: sellerEmail,
        password: "SuperSecure!1234",
        display_name: RandomGenerator.name(),
        contact_phone: RandomGenerator.mobile(),
        status: "pending",
      } satisfies IShoppingSeller.IJoin,
    });
  typia.assert(seller);

  // 2. Seller creates a product
  const productCode = RandomGenerator.alphaNumeric(10);
  const product = await api.functional.shopping.seller.products.create(
    connection,
    {
      body: {
        code: productCode,
        name: RandomGenerator.name(),
        description: RandomGenerator.content(),
        main_image_uri:
          "https://picsum.photos/600/600?random=" +
          RandomGenerator.alphaNumeric(5),
        status: "active",
        business_status: "approved",
        shipping_weight_grams: 200,
        shipping_length_cm: 10,
        shipping_width_cm: 12,
        shipping_height_cm: 5,
        shipping_options: "free",
      } satisfies IShoppingProduct.ICreate,
    },
  );
  typia.assert(product);

  // 3. Seller creates a SKU (with at least one variant attribute; here a random id is used for attribute dummy)
  const variantAttributeValueId = typia.random<string & tags.Format<"uuid">>();
  const skuCode = RandomGenerator.alphaNumeric(12);
  const sku = await api.functional.shopping.seller.products.skus.create(
    connection,
    {
      productCode,
      body: {
        sku_code: skuCode,
        price: 13900,
        is_active: true,
        barcode: RandomGenerator.alphaNumeric(13),
        status: "in_stock",
        variant_attribute_value_ids: [
          variantAttributeValueId,
        ] satisfies string[] & tags.MinItems<1>,
      } satisfies IShoppingSku.ICreate,
    },
  );
  typia.assert(sku);

  // 4. Customer registers
  const customerEmail = typia.random<string & tags.Format<"email">>();
  const customer: IShoppingCustomer.IAuthorized =
    await api.functional.auth.customer.join(connection, {
      body: {
        email: customerEmail,
        password: "CustPassword!123",
        name: RandomGenerator.name(),
        phone: RandomGenerator.mobile(),
        href: "https://shopper.local/signup",
        referrer: "https://ad.landing.page/",
        ip: null,
      } satisfies IShoppingCustomer.ICreate,
    });
  typia.assert(customer);

  // 5. Customer creates an order with initial order line referencing the SKU
  const shippingAddress: IShoppingOrderAddress.ICreate = {
    type: "shipping",
    recipient_name: RandomGenerator.name(),
    recipient_phone: RandomGenerator.mobile(),
    zip_code: "04551",
    base_address: "123 Main St",
    detail_address: "Apt 24F",
    city: "Seoul",
    state_province: "Seoul",
    country: "Korea",
  };
  const orderLine1: IShoppingOrderLine.ICreate = {
    shopping_sku_id: sku.id,
    quantity: 1,
    unit_price: sku.price,
  };
  const order: IShoppingOrder =
    await api.functional.shopping.customer.orders.create(connection, {
      body: {
        total_price: sku.price,
        order_lines: [orderLine1],
        shipping_addresses: [shippingAddress],
        payment_method: "CARD",
      } satisfies IShoppingOrder.ICreate,
    });
  typia.assert(order);
  const orderCode = order.order_code;

  // 6. Customer adds another order line for the same SKU
  const addLineBody: IShoppingOrderLine.ICreate = {
    shopping_sku_id: sku.id,
    quantity: 2,
    unit_price: sku.price,
  };
  const addedLine: IShoppingOrderLine =
    await api.functional.shopping.customer.orders.lines.create(connection, {
      orderCode,
      body: addLineBody,
    });
  typia.assert(addedLine);
  TestValidator.equals(
    "SKU reference in added line matches",
    addedLine.sku.id,
    sku.id,
  );
  TestValidator.equals("Added line quantity correct", addedLine.quantity, 2);
  TestValidator.equals(
    "Added line unit_price correct",
    addedLine.unit_price,
    sku.price,
  );
  TestValidator.equals(
    "Order line seller is correct",
    addedLine.seller.id,
    seller.id,
  );

  // 7. Seller attempts to add line - should fail
  await TestValidator.error(
    "Seller may not add order line to customer order",
    async () => {
      await api.functional.shopping.customer.orders.lines.create(connection, {
        orderCode,
        body: addLineBody,
      });
    },
  );

  // 8. Cannot add line for nonexistent SKU
  await TestValidator.error(
    "Cannot add order line for nonexistent SKU",
    async () => {
      await api.functional.shopping.customer.orders.lines.create(connection, {
        orderCode,
        body: {
          shopping_sku_id: typia.random<string & tags.Format<"uuid">>(),
          quantity: 1,
          unit_price: sku.price,
        },
      });
    },
  );

  // 9. Cannot add line for out-of-stock or inactive SKU (simulate with is_active: false and invalid status)
  const inactiveSku = await api.functional.shopping.seller.products.skus.create(
    connection,
    {
      productCode,
      body: {
        sku_code: RandomGenerator.alphaNumeric(14),
        price: 9900,
        is_active: false,
        status: "discontinued",
        variant_attribute_value_ids: [
          typia.random<string & tags.Format<"uuid">>(),
        ] satisfies string[] & tags.MinItems<1>,
      } satisfies IShoppingSku.ICreate,
    },
  );
  typia.assert(inactiveSku);
  await TestValidator.error(
    "Cannot add line for inactive/discontinued SKU",
    async () => {
      await api.functional.shopping.customer.orders.lines.create(connection, {
        orderCode,
        body: {
          shopping_sku_id: inactiveSku.id,
          quantity: 1,
          unit_price: inactiveSku.price,
        },
      });
    },
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IPageIShoppingGuestCartItem } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIShoppingGuestCartItem";
import type { IShoppingAdmin } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingAdmin";
import type { IShoppingAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingAuthorizationToken";
import type { IShoppingGuestCartItem } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingGuestCartItem";

/**
 * Validates admin access and privacy guarantees for guest shopping cart index
 * operation.
 *
 * 1. Register a new admin with permitted status/role.
 * 2. Assert successful authentication by checking response.
 * 3. Prepare a random set of cart session search filters and sorted paginated
 *    request.
 * 4. Request PATCH /shopping/admin/guestCarts as authenticated admin.
 * 5. Validate that result is paginated summary about session, and no PII or cart
 *    item detail is included.
 * 6. Check fields: session_key, created_at, updated_at, expires_at, items[].
 *    Ensure guest-only data is present, not customer info, and number of
 *    results matches pagination.
 * 7. Confirm admin-only endpoint returns correct data shape for various page/limit
 *    combos.
 */
export async function test_api_guest_cart_index_admin_access(
  connection: api.IConnection,
) {
  // 1. Register a new admin
  const adminJoin = await api.functional.auth.admin.join(connection, {
    body: {
      email: typia.random<string & tags.Format<"email">>(),
      password: RandomGenerator.alphaNumeric(12),
      name: RandomGenerator.name(),
      role: "superadmin",
      status: "active",
    } satisfies IShoppingAdmin.IJoin,
  });
  typia.assert(adminJoin);
  // 2. Prepare random paginated & filtered request
  const now = new Date();
  const created_from = new Date(now.getTime() - 7 * 86400000).toISOString(); // 7 days ago
  const created_to = now.toISOString();
  const sort_by: string = RandomGenerator.pick([
    "updated_at",
    "created_at",
    "expires_at",
  ] as const);
  const sort_order: "asc" | "desc" = RandomGenerator.pick([
    "asc",
    "desc",
  ] as const);
  const page: number = 1;
  const limit: number = 10;
  // 3. Search for guest cart sessions (as admin)
  const response = await api.functional.shopping.admin.guestCarts.index(
    connection,
    {
      body: {
        created_from,
        created_to,
        sort_by,
        sort_order,
        page,
        limit,
      } satisfies IShoppingGuestCartItem.IRequest,
    },
  );
  typia.assert(response);
  // 4. Validate response shape and privacy
  TestValidator.predicate(
    "response has pagination and data",
    response.pagination !== undefined && Array.isArray(response.data),
  );
  // Every cart must have only session key, timestamps, and items (no PII, no customerId, etc)
  for (const cart of response.data) {
    TestValidator.predicate(
      "cart summary fields",
      typeof cart.session_key === "string" &&
        typeof cart.created_at === "string" &&
        typeof cart.updated_at === "string" &&
        typeof cart.expires_at === "string" &&
        Array.isArray(cart.items),
    );
    // No customer PII or identity in guest cart summary
    TestValidator.equals(
      "no customer id",
      (cart as any).customer_id,
      undefined,
    );
    TestValidator.equals(
      "no customer email",
      (cart as any).customer_email,
      undefined,
    );
    // Items must be summary only (item structure not containing sensitive fields)
    for (const item of cart.items) {
      TestValidator.predicate("item summary fields", typeof item === "object");
      // Just check some basic expected structure (must not include price, customer-specific fields, etc)
      TestValidator.equals(
        "no customer field in item",
        (item as any).customer_id,
        undefined,
      );
      TestValidator.equals(
        "no price field in item",
        (item as any).price,
        undefined,
      );
    }
  }
  // 5. Validate pagination matches request
  TestValidator.equals("limit as requested", response.pagination.limit, limit);
  TestValidator.equals(
    "current page as requested",
    response.pagination.current,
    page,
  );
}

