/**
 * Test admin session list security audit for seller.
 *
 * 1. Register admin
 * 2. Register seller by creating a product
 * 3. Register address for seller
 * 4. As admin, list seller sessions, verify structure and info
 * 5. Test error on invalid/non-existent sellerId
 * 6. Test non-admin/anonymous access is denied
 */
export async function test_api_admin_seller_sessions_list_security_audit(
  connection: api.IConnection,
) {
  // 1. Register admin
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const adminInput = {
    email: adminEmail,
    password: RandomGenerator.alphaNumeric(10) + "!Ab1",
    name: RandomGenerator.name(),
    role: "superadmin",
    status: "active",
  } satisfies IShoppingAdmin.IJoin;
  const admin = await api.functional.auth.admin.join(connection, {
    body: adminInput,
  });
  typia.assert(admin);

  // 2. Register seller by creating a product
  // (This test suite does not have an explicit seller registration API, so use product creation)
  const productInput = {
    code: RandomGenerator.alphaNumeric(12),
    name: RandomGenerator.paragraph({ sentences: 3 }),
    description: RandomGenerator.content({ paragraphs: 2 }),
    main_image_uri:
      "https://cdn.example.com/image/" + RandomGenerator.alphaNumeric(15),
    status: "draft",
    business_status: "in_review",
  } satisfies IShoppingProduct.ICreate;
  const sellerProduct = await api.functional.shopping.seller.products.create(
    connection,
    { body: productInput },
  );
  typia.assert(sellerProduct);
  const sellerId = sellerProduct.seller.id;

  // 3. Register at least one address for the seller via admin
  const sellerAddressInput = {
    address_line1: RandomGenerator.paragraph({ sentences: 2 }),
    address_line2: RandomGenerator.paragraph({ sentences: 1 }),
    city: "Seoul",
    state: "Seoul",
    postal_code: RandomGenerator.alphaNumeric(6),
    country: "South Korea",
    is_primary: true,
    is_return_address: true,
    phone: RandomGenerator.mobile(),
    recipient_name: RandomGenerator.name(),
  } satisfies IShoppingSellerAddress.ICreate;
  const sellerAddress =
    await api.functional.shopping.admin.sellers.addresses.create(connection, {
      sellerId,
      body: sellerAddressInput,
    });
  typia.assert(sellerAddress);

  // 4. As admin, retrieve sessions list for seller and validate
  const sessionRequest = {
    limit: 20,
    page: 1,
    expired: undefined,
    created_after: undefined,
    created_before: undefined,
    ip: undefined,
    href: undefined,
    referrer: undefined,
  } satisfies IShoppingSellerSession.IRequest;
  const sessionsPage =
    await api.functional.shopping.admin.sellers.sessions.index(connection, {
      sellerId,
      body: sessionRequest,
    });
  typia.assert(sessionsPage);

  // Sessions list checks
  TestValidator.predicate(
    "seller sessions list should not be empty",
    Array.isArray(sessionsPage.data) && sessionsPage.data.length > 0,
  );
  for (const session of sessionsPage.data) {
    typia.assert(session);
    TestValidator.predicate(
      "session.id is a uuid",
      typeof session.id === "string" && session.id.length > 0,
    );
    TestValidator.predicate(
      "session.shopping_seller_id matches",
      session.shopping_seller_id === sellerId,
    );
    TestValidator.predicate(
      "session.ip is not empty",
      typeof session.ip === "string" && session.ip.length > 0,
    );
    TestValidator.predicate(
      "session.href is not empty",
      typeof session.href === "string" && session.href.length > 0,
    );
    TestValidator.predicate(
      "session.referrer is not empty",
      typeof session.referrer === "string" && session.referrer.length > 0,
    );
    TestValidator.predicate(
      "session.created_at is ISO date",
      typeof session.created_at === "string" && session.created_at.length > 0,
    );
    if (session.expired_at !== null && session.expired_at !== undefined) {
      TestValidator.predicate(
        "session.expired_at is ISO date",
        typeof session.expired_at === "string" && session.expired_at.length > 0,
      );
    }
  }

  // 5. Attempt to list sessions of invalid/non-existent seller id
  const randomSellerId = typia.random<string & tags.Format<"uuid">>();
  await TestValidator.error(
    "listing sessions with non-existent sellerId should throw",
    async () => {
      await api.functional.shopping.admin.sellers.sessions.index(connection, {
        sellerId: randomSellerId,
        body: sessionRequest,
      });
    },
  );

  // 6. Attempt to access as non-admin (simulate with unauthenticated connection)
  const unauthConn: api.IConnection = { ...connection, headers: {} };
  await TestValidator.error(
    "unauthenticated/non-admin should be forbidden from admin endpoint",
    async () => {
      await api.functional.shopping.admin.sellers.sessions.index(unauthConn, {
        sellerId,
        body: sessionRequest,
      });
    },
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IPageIShoppingAdmin } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIShoppingAdmin";
import type { IShoppingAdmin } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingAdmin";
import type { IShoppingAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingAuthorizationToken";

/**
 * Validate admin listing API with pagination and filtering by email, name,
 * role, and status.
 *
 * This test ensures that only signed-in admin users can retrieve the platform
 * administrator list. It first creates and authenticates an admin account, then
 * tests the admin listing endpoint with and without filters. It verifies
 * pagination metadata, ensures summaries are present and valid, and tests that
 * non-admin users are denied access.
 *
 * Steps:
 *
 * 1. Create a new admin account for authentication.
 * 2. As the authenticated admin, retrieve the admin list (no filters) and validate
 *    pagination and summary structure.
 * 3. Retrieve the admin list with various filters for email, name, role, status,
 *    and verify filtered results.
 * 4. Attempt admin list retrieval with an unauthenticated/unauthorized connection
 *    and expect an authorization error.
 */
export async function test_api_admin_admins_pagination_and_search(
  connection: api.IConnection,
) {
  // 1. Create new admin account and authenticate
  const adminJoin: IShoppingAdmin.IJoin = {
    email: typia.random<string & tags.Format<"email">>(),
    password: typia.random<string & tags.MinLength<8> & tags.MaxLength<128>>(),
    name: RandomGenerator.name(),
    role: RandomGenerator.pick([
      "super",
      "support",
      "operator",
      "compliance",
    ] as const),
    status: RandomGenerator.pick([
      "active",
      "suspended",
      "pending",
      "locked",
    ] as const),
  };
  const adminOutput: IShoppingAdmin.IAuthorized =
    await api.functional.auth.admin.join(connection, { body: adminJoin });
  typia.assert(adminOutput);

  // 2. As authenticated admin, list admins with no filters
  const requestBasic = {
    page: 1 as number & tags.Type<"int32">,
    limit: 10 as number & tags.Type<"int32">,
  } satisfies IShoppingAdmin.IRequest;
  const pageBasic = await api.functional.shopping.admin.admins.index(
    connection,
    { body: requestBasic },
  );
  typia.assert(pageBasic);
  TestValidator.predicate(
    "pagination contains at least one admin",
    pageBasic.data.length > 0,
  );
  typia.assert(pageBasic.data[0]);
  TestValidator.equals(
    "found admin email matches join email or is present in platform",
    pageBasic.data.some((a) => a.email === adminJoin.email),
    true,
  );

  // 3. Paginated search with filters (email, name, role, status)
  // Email filter
  const pageEmail = await api.functional.shopping.admin.admins.index(
    connection,
    {
      body: {
        ...requestBasic,
        search: adminJoin.email,
      } satisfies IShoppingAdmin.IRequest,
    },
  );
  typia.assert(pageEmail);
  TestValidator.predicate(
    "all admins have matching email in search filter",
    pageEmail.data.every(
      (a) =>
        a.email.includes(adminJoin.email) || adminJoin.email.includes(a.email),
    ),
  );
  // Name filter
  const pageName = await api.functional.shopping.admin.admins.index(
    connection,
    {
      body: {
        ...requestBasic,
        search: adminJoin.name,
      } satisfies IShoppingAdmin.IRequest,
    },
  );
  typia.assert(pageName);
  TestValidator.predicate(
    "all admins have matching name in search filter",
    pageName.data.every(
      (a) => a.name.includes(adminJoin.name) || adminJoin.name.includes(a.name),
    ),
  );
  // Role filter
  const pageRole = await api.functional.shopping.admin.admins.index(
    connection,
    {
      body: {
        ...requestBasic,
        role: adminJoin.role,
      } satisfies IShoppingAdmin.IRequest,
    },
  );
  typia.assert(pageRole);
  TestValidator.predicate(
    "all admins have matching role in filter",
    pageRole.data.every((a) => a.role === adminJoin.role),
  );
  // Status filter
  const pageStatus = await api.functional.shopping.admin.admins.index(
    connection,
    {
      body: {
        ...requestBasic,
        status: adminJoin.status,
      } satisfies IShoppingAdmin.IRequest,
    },
  );
  typia.assert(pageStatus);
  TestValidator.predicate(
    "all admins have matching status in filter",
    pageStatus.data.every((a) => a.status === adminJoin.status),
  );
  // 4. Attempt to retrieve admin list as non-admin, expect authorization error
  const unauthConn: api.IConnection = { ...connection, headers: {} };
  await TestValidator.error(
    "non-admin or unauthenticated actor cannot retrieve admin list",
    async () => {
      await api.functional.shopping.admin.admins.index(unauthConn, {
        body: requestBasic,
      });
    },
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IShoppingAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingAuthorizationToken";
import type { IShoppingCustomer } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingCustomer";
import type { IShoppingReview } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingReview";
import type { IShoppingReviewAbuseReport } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingReviewAbuseReport";
import type { IShoppingReviewAttachment } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingReviewAttachment";
import type { IShoppingReviewModeration } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingReviewModeration";
import type { IShoppingSeller } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingSeller";
import type { IShoppingSku } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingSku";

/**
 * Validates that a seller can access attachments for reviews related to their
 * own products and that access is correctly restricted in other scenarios.
 *
 * Steps:
 *
 * 1. Register a seller (owning a product).
 * 2. Register a customer and have them create a review (simulate customer flow;
 *    assume SKU/order/line already exists).
 * 3. Customer uploads an attachment to their review.
 * 4. Switch authentication to seller and request the attachment metadata through
 *    the seller-specific endpoint.
 * 5. Validate that metadata is returned correctly, and content matches
 *    expectations.
 * 6. Attempt to access a soft-deleted attachment and confirm access is denied.
 */
export async function test_api_seller_review_attachment_access_by_owner(
  connection: api.IConnection,
) {
  // Step 1: Seller registration
  const sellerJoin: IShoppingSeller.IAuthorized =
    await api.functional.auth.seller.join(connection, {
      body: {
        email: typia.random<string & tags.Format<"email">>(),
        password: RandomGenerator.alphaNumeric(12),
        display_name: RandomGenerator.paragraph({ sentences: 2 }),
        contact_phone: RandomGenerator.mobile(),
        status: "pending",
      },
    });
  typia.assert(sellerJoin);

  // Step 2: Customer registration
  const customerJoin: IShoppingCustomer.IAuthorized =
    await api.functional.auth.customer.join(connection, {
      body: {
        email: typia.random<string & tags.Format<"email">>(),
        password: RandomGenerator.alphaNumeric(12),
        name: RandomGenerator.name(),
        phone: RandomGenerator.mobile(),
        href: "https://customer-join.test/", // static context
        referrer: "https://referrer-site.test/",
      },
    });
  typia.assert(customerJoin);

  // Step 3: Customer creates review (simulate existing SKU, order, and line)
  const reviewCreateBody = {
    shopping_sku_id: typia.random<string & tags.Format<"uuid">>(),
    shopping_order_line_id: typia.random<string & tags.Format<"uuid">>(),
    rating: 4,
    comment: RandomGenerator.paragraph({ sentences: 12 }),
  } satisfies IShoppingReview.ICreate;
  const review: IShoppingReview =
    await api.functional.shopping.customer.reviews.create(connection, {
      body: reviewCreateBody,
    });
  typia.assert(review);

  // Step 4: Customer adds an attachment to the review
  const attachmentRequest = {
    file_uri: `https://cdn.attachedfiles.com/image/${RandomGenerator.alphaNumeric(12)}.jpg`,
    file_type: "image/jpeg",
    file_size: 1024 * 128,
  } satisfies IShoppingReviewAttachment.ICreate;
  const attachment: IShoppingReviewAttachment =
    await api.functional.shopping.customer.reviews.attachments.create(
      connection,
      {
        reviewId: review.id,
        body: attachmentRequest,
      },
    );
  typia.assert(attachment);
  TestValidator.equals(
    "attachment belongs to correct review",
    attachment.shopping_review_id,
    review.id,
  );
  // Validate file uri and type
  TestValidator.equals(
    "attachment file_type matches",
    attachment.file_type,
    attachmentRequest.file_type,
  );
  TestValidator.equals(
    "attachment file_size matches",
    attachment.file_size,
    attachmentRequest.file_size,
  );

  // Step 5: Switch to seller context (current connection is already authenticated as seller)
  // (SDK auto-updates connection headers on last join)
  // Request the attachment as seller
  const attachmentBySeller: IShoppingReviewAttachment =
    await api.functional.shopping.seller.reviews.attachments.at(connection, {
      reviewId: review.id,
      attachmentId: attachment.id,
    });
  typia.assert(attachmentBySeller);
  TestValidator.equals(
    "seller can fetch own product review attachment metadata",
    attachmentBySeller.id,
    attachment.id,
  );
  TestValidator.equals(
    "seller receives correct file_uri",
    attachmentBySeller.file_uri,
    attachment.file_uri,
  );
  TestValidator.equals(
    "seller receives correct file_type",
    attachmentBySeller.file_type,
    attachment.file_type,
  );

  // Step 6: Simulate soft-delete on the attachment by manually setting deleted_at (simulate business rule for test)
  // (Since no API is given for soft-delete, test that deleted_at blocks access)
  // The only way to simulate is a negative test: try random uuid values as non-existent/deleted
  await TestValidator.error(
    "seller cannot access soft-deleted/non-existent attachment",
    async () => {
      await api.functional.shopping.seller.reviews.attachments.at(connection, {
        reviewId: review.id,
        attachmentId: typia.random<string & tags.Format<"uuid">>(), // non-existent/deleted uuid
      });
    },
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IShoppingAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingAuthorizationToken";
import type { IShoppingCustomer } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingCustomer";
import type { IShoppingReview } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingReview";
import type { IShoppingReviewAbuseReport } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingReviewAbuseReport";
import type { IShoppingReviewAttachment } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingReviewAttachment";
import type { IShoppingReviewModeration } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingReviewModeration";
import type { IShoppingSku } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingSku";

/**
 * Test successful upload/association of an attachment to a review by its
 * customer author, and rejection by unauthorized actors.
 *
 * 1. Register a new customer (author).
 * 2. Customer creates a review for a product SKU they "own" (using random UUIDs
 *    for test).
 * 3. Customer attaches a valid file to the review with compliant metadata.
 * 4. Verify the attachment appears in the review/attachment retrieval.
 * 5. Attempt to attach an attachment as an unauthorized actor (simulate by using
 *    unauthenticated connection or non-author customer).
 * 6. Validate that unauthorized attachment attempt fails.
 */
export async function test_api_customer_review_attachment_upload(
  connection: api.IConnection,
) {
  // 1. Register a customer
  const customerEmail = typia.random<string & tags.Format<"email">>();
  const customerBody = {
    email: customerEmail,
    password: RandomGenerator.alphaNumeric(12),
    name: RandomGenerator.name(),
    phone: RandomGenerator.mobile(),
    href: "https://test-case.local/register",
    referrer: "https://test-case.local/login",
    ip: undefined,
  } satisfies IShoppingCustomer.ICreate;
  const customer = await api.functional.auth.customer.join(connection, {
    body: customerBody,
  });
  typia.assert(customer);

  // 2. Customer creates a review (using random SKU/order IDs for demo)
  const reviewBody = {
    shopping_sku_id: typia.random<string & tags.Format<"uuid">>(),
    shopping_order_line_id: typia.random<string & tags.Format<"uuid">>(),
    rating: 5,
    comment: RandomGenerator.paragraph({ sentences: 15 }),
    attachments: [],
  } satisfies IShoppingReview.ICreate;
  const review = await api.functional.shopping.customer.reviews.create(
    connection,
    { body: reviewBody },
  );
  typia.assert(review);

  // 3. Customer uploads an attachment
  const attachmentBody = {
    file_uri: `https://files.test-case.local/${RandomGenerator.alphaNumeric(16)}.jpg`,
    file_type: "image/jpeg",
    file_size: 4096,
  } satisfies IShoppingReviewAttachment.ICreate;
  const attachment =
    await api.functional.shopping.customer.reviews.attachments.create(
      connection,
      {
        reviewId: review.id,
        body: attachmentBody,
      },
    );
  typia.assert(attachment);
  TestValidator.equals(
    "Attachment is linked to correct review",
    attachment.shopping_review_id,
    review.id,
  );
  TestValidator.equals(
    "Attachment metadata matches",
    {
      file_uri: attachment.file_uri,
      file_type: attachment.file_type,
      file_size: attachment.file_size,
    },
    {
      file_uri: attachmentBody.file_uri,
      file_type: attachmentBody.file_type,
      file_size: attachmentBody.file_size,
    },
  );

  // 4. Confirm attachment appears in review retrieval
  const updatedReview = await api.functional.shopping.customer.reviews.create(
    connection,
    { body: reviewBody },
  );
  typia.assert(updatedReview);
  // Because this test re-creates a review above (no 'at' function), focus on single attachment and proper API return shape
  // 5. Attempt upload as unauthorized actor (simulate unauthenticated)
  const unauthConn: api.IConnection = { ...connection, headers: {} };
  await TestValidator.error(
    "Non-customer cannot upload review attachment",
    async () => {
      await api.functional.shopping.customer.reviews.attachments.create(
        unauthConn,
        {
          reviewId: review.id,
          body: attachmentBody,
        },
      );
    },
  );
}

