import type { IShoppingBusinessConstraint } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingBusinessConstraint";

/**
 * Validate admin business constraint creation workflow and enforcement.
 *
 * 1. Registers a new admin to obtain valid authentication
 * 2. Creates a unique constraint (with random constraint_name and scope) and
 *    verifies all required fields, activation and auditability
 * 3. Asserts response contains: correct constraint_name, scope, limit_value, unit,
 *    description, is active, audit timestamps, no deletion marker
 * 4. Attempts to create a duplicate (same constraint_name+scope) and checks that a
 *    uniqueness error is thrown
 * 5. Confirms only admins may perform the creation (admin context already
 *    established by join)
 */
export async function test_api_business_constraint_creation_admin_success(
  connection: api.IConnection,
) {
  // 1. Register admin and authenticate
  const adminJoinBody = {
    email: `${RandomGenerator.alphabets(8)}@admin.test.com`,
    password: RandomGenerator.alphaNumeric(12),
    name: RandomGenerator.name(),
    role: "superadmin", // use valid role string
    status: "active", // ensure admin is ready immediately
  } satisfies IShoppingAdmin.IJoin;
  const admin = await api.functional.auth.admin.join(connection, {
    body: adminJoinBody,
  });
  typia.assert(admin);
  TestValidator.equals("admin email matches", admin.email, adminJoinBody.email);
  TestValidator.equals("admin name matches", admin.name, adminJoinBody.name);
  TestValidator.equals("admin role matches", admin.role, adminJoinBody.role);
  TestValidator.equals(
    "admin status is active",
    admin.status,
    adminJoinBody.status,
  );
  TestValidator.predicate("admin token present", Boolean(admin.token?.access));
  TestValidator.predicate(
    "admin id is uuid",
    typeof admin.id === "string" && admin.id.length > 0,
  );
  TestValidator.predicate(
    "admin created_at is ISO string",
    typeof admin.created_at === "string",
  );

  // 2. Create a unique random constraint
  const uniqueConstraintName = `max_order_qty_test_${RandomGenerator.alphaNumeric(6)}`;
  const createConstraintBody = {
    constraint_name: uniqueConstraintName,
    scope: "cart",
    limit_value: "10",
    unit: "count",
    description: RandomGenerator.paragraph({ sentences: 5 }),
    active: true,
  } satisfies IShoppingBusinessConstraint.ICreate;

  const constraint =
    await api.functional.shopping.admin.businessConstraints.create(connection, {
      body: createConstraintBody,
    });
  typia.assert(constraint);
  TestValidator.equals(
    "constraint_name matches request",
    constraint.constraint_name,
    createConstraintBody.constraint_name,
  );
  TestValidator.equals(
    "scope matches",
    constraint.scope,
    createConstraintBody.scope,
  );
  TestValidator.equals(
    "limit_value matches",
    constraint.limit_value,
    createConstraintBody.limit_value,
  );
  TestValidator.equals(
    "unit matches",
    constraint.unit,
    createConstraintBody.unit,
  );
  TestValidator.equals(
    "description matches",
    constraint.description,
    createConstraintBody.description,
  );
  TestValidator.equals("active true", constraint.active, true);
  TestValidator.predicate(
    "id is uuid",
    typeof constraint.id === "string" && constraint.id.length > 0,
  );
  TestValidator.predicate(
    "created_at is ISO string",
    typeof constraint.created_at === "string",
  );
  TestValidator.predicate(
    "updated_at is ISO string",
    typeof constraint.updated_at === "string",
  );
  TestValidator.equals(
    "deleted_at is null/undefined",
    constraint.deleted_at,
    null,
  );

  // 3. Attempt to create a duplicate with exact same constraint_name and scope
  await TestValidator.error(
    "duplicate constraint creation must fail",
    async () => {
      await api.functional.shopping.admin.businessConstraints.create(
        connection,
        {
          body: createConstraintBody,
        },
      );
    },
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IShoppingAdmin } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingAdmin";
import type { IShoppingAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingAuthorizationToken";
import type { IShoppingBusinessConstraint } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingBusinessConstraint";

/**
 * E2E test for admin updating an existing business constraint via
 * /shopping/admin/businessConstraints/{constraintName} PUT endpoint.
 *
 * Scenario:
 *
 * 1. Register a new admin for authentication (admin only operation).
 * 2. Create a unique business constraint (constraintA) for update testing.
 * 3. Update constraintA with new limit_value, unit, and active fields; verify
 *    response matches updates and preserves audit fields.
 * 4. Create a second distinct business constraint (constraintB).
 * 5. Attempt to update constraintA to have the same constraint_name and scope as
 *    constraintB, assert uniqueness constraint violation (expect error).
 * 6. Try updating constraintA without admin (simulate unauthenticated); expect
 *    access denied.
 */
export async function test_api_business_constraint_update_admin(
  connection: api.IConnection,
) {
  // 1. Register admin
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const adminRegister = await api.functional.auth.admin.join(connection, {
    body: {
      email: adminEmail,
      password: RandomGenerator.alphabets(12),
      name: RandomGenerator.name(),
      role: RandomGenerator.pick(["super", "operator", "compliance"] as const),
      status: "active",
    } satisfies IShoppingAdmin.IJoin,
  });
  typia.assert(adminRegister);

  // 2. Create constraintA
  const constraintA_create = {
    constraint_name: `ctrA_${RandomGenerator.alphaNumeric(10)}`,
    scope: `scopeA_${RandomGenerator.alphaNumeric(6)}`,
    limit_value: "100",
    unit: "count",
    description: "Original constraint A.",
    active: true,
  } satisfies IShoppingBusinessConstraint.ICreate;
  const constraintA =
    await api.functional.shopping.admin.businessConstraints.create(connection, {
      body: constraintA_create,
    });
  typia.assert(constraintA);

  // 3. Update constraintA fields
  const constraintA_update = {
    constraint_name: constraintA.constraint_name,
    scope: constraintA.scope,
    limit_value: "250",
    unit: "items",
    active: false,
    description: "Updated constraint A.",
  } satisfies IShoppingBusinessConstraint.IUpdate;
  const updatedA =
    await api.functional.shopping.admin.businessConstraints.update(connection, {
      constraintName: constraintA.constraint_name,
      body: constraintA_update,
    });
  typia.assert(updatedA);
  TestValidator.equals("updated limit_value", updatedA.limit_value, "250");
  TestValidator.equals("updated unit", updatedA.unit, "items");
  TestValidator.equals("updated active", updatedA.active, false);
  TestValidator.equals(
    "updated description",
    updatedA.description,
    "Updated constraint A.",
  );

  // Audit: id stays the same, updated_at has changed
  TestValidator.equals("id not changed by update", updatedA.id, constraintA.id);
  TestValidator.notEquals(
    "updated_at updated",
    updatedA.updated_at,
    constraintA.updated_at,
  );

  // 4. Create constraintB
  const constraintB_create = {
    constraint_name: `ctrB_${RandomGenerator.alphaNumeric(10)}`,
    scope: `scopeB_${RandomGenerator.alphaNumeric(6)}`,
    limit_value: "42",
    unit: "hours",
    description: "Constraint B.",
    active: true,
  } satisfies IShoppingBusinessConstraint.ICreate;
  const constraintB =
    await api.functional.shopping.admin.businessConstraints.create(connection, {
      body: constraintB_create,
    });
  typia.assert(constraintB);

  // 5. Attempt uniqueness violation: update A to have B's name+scope
  await TestValidator.error(
    "uniqueness constraint_name+scope violation triggers error",
    async () => {
      await api.functional.shopping.admin.businessConstraints.update(
        connection,
        {
          constraintName: constraintA.constraint_name,
          body: {
            constraint_name: constraintB.constraint_name,
            scope: constraintB.scope,
            limit_value: "777",
            unit: "dup_unit",
            active: true,
            description: "Trying collision update.",
          } satisfies IShoppingBusinessConstraint.IUpdate,
        },
      );
    },
  );

  // 6. Negative: Try updating constraint as unauthenticated
  // Simulate unauthenticated connection by removing headers
  const unauthConn: api.IConnection = { ...connection, headers: {} };
  await TestValidator.error(
    "non-admin unauthorized update attempt should fail",
    async () => {
      await api.functional.shopping.admin.businessConstraints.update(
        unauthConn,
        {
          constraintName: constraintA.constraint_name,
          body: constraintA_update,
        },
      );
    },
  );
}

