        barcode: null,
        status: "in_stock",
        variant_attribute_value_ids: [
          typia.random<string & tags.Format<"uuid">>(),
        ],
      } satisfies IShoppingSku.ICreate,
    });
  typia.assert(sku);

  // 5. Register a Customer
  const customerEmail = typia.random<string & tags.Format<"email">>();
  const customer: IShoppingCustomer.IAuthorized =
    await api.functional.auth.customer.join(connection, {
      body: {
        email: customerEmail,
        password: RandomGenerator.alphaNumeric(12),
        name: RandomGenerator.name(),
        phone: RandomGenerator.mobile(),
        href: "https://www.customer-landing.com/auth",
        referrer: "https://www.google.com/search?q=shop+test",
        ip: undefined,
      } satisfies IShoppingCustomer.ICreate,
    });
  typia.assert(customer);

  // 6. Customer places the Order (which will cause payment attempts to be generated)
  const order: IShoppingOrder =
    await api.functional.shopping.customer.orders.create(connection, {
      body: {
        total_price: sku.price,
        order_lines: [
          {
            shopping_sku_id: sku.id,
            quantity: 1,
            unit_price: sku.price,
          } satisfies IShoppingOrderLine.ICreate,
        ],
        shipping_addresses: [
          {
            type: "shipping",
            recipient_name: RandomGenerator.name(),
            recipient_phone: RandomGenerator.mobile(),
            zip_code: RandomGenerator.alphaNumeric(6),
            base_address: RandomGenerator.paragraph({ sentences: 2 }),
            city: "Seoul",
            state_province: "Seoul",
            country: "South Korea",
          } satisfies IShoppingOrderAddress.ICreate,
        ],
        payment_method: "test_card",
        coupon_code: undefined,
      } satisfies IShoppingOrder.ICreate,
    });
  typia.assert(order);

  // 7. Admin requests all payment attempts for the order
  const paymentAttemptsPage =
    await api.functional.shopping.admin.orders.payment_attempts.index(
      connection,
      {
        orderCode: order.order_code,
        body: {
          page: 1 as number & tags.Type<"int32"> & tags.Minimum<1>,
          limit: 10 as number &
            tags.Type<"int32"> &
            tags.Minimum<1> &
            tags.Maximum<100>,
        } satisfies IShoppingPaymentAttempt.IRequest,
      },
    );
  typia.assert(paymentAttemptsPage);

  // 8. Validate presence and diversity of payment attempt statuses
  TestValidator.predicate(
    "should list at least one payment attempt",
    paymentAttemptsPage.data.length > 0,
  );
  const statuses = paymentAttemptsPage.data.map(
    (attempt) => attempt.attempt_status,
  );
  TestValidator.predicate(
    "should include at least one completed or pending attempt (success)",
    statuses.includes("completed") || statuses.includes("pending"),
  );
  TestValidator.predicate(
    "should include at least one attempt that is not completed (failure, retry, or cancelled)",
    statuses.some((status) => status === "failed" || status === "cancelled"),
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IShoppingAttributeDimension } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingAttributeDimension";
import type { IShoppingAttributeValue } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingAttributeValue";
import type { IShoppingAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingAuthorizationToken";
import type { IShoppingCartItem } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingCartItem";
import type { IShoppingCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingCategory";
import type { IShoppingCustomer } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingCustomer";
import type { IShoppingProduct } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingProduct";
import type { IShoppingProductAttribute } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingProductAttribute";
import type { IShoppingProductImage } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingProductImage";
import type { IShoppingSeller } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingSeller";
import type { IShoppingSku } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingSku";
import type { IShoppingSkuImage } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingSkuImage";
import type { IShoppingSkuVariant } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingSkuVariant";
import type { IShoppingTag } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingTag";

/**
 * Validate update of quantity for a cart item by customer, including changes up
 * and down and boundary cases. Also validate (by business logic) that only
 * active/allowed SKUs can be set as reference for replace. Test unauthorized
 * access as well.
 *
 * Steps:
 *
 * 1. Register seller (to enable product and SKU creation)
 * 2. Register customer (cart owner)
 * 3. Seller creates a product
 * 4. Seller creates multiple SKUs for the product (at least 2, with different
 *    codes and prices)
 * 5. Customer adds SKU1 to a new cart as a cart item (simulate cart creation by
 *    first insert)
 * 6. Update cart item to new quantity (increase, decrease, set max - e.g., 10, 2,
 *    or platform max)
 * 7. Update cart item to another valid active SKU2 (SKU substitution)
 * 8. Try referencing an inactive SKU or exceeding max quantity - expect error
 * 9. Try updating as unauthorized user - expect error
 * 10. After each update, validate returned cart item (quantity, SKU, updated_at,
 *     error_flags)
 */
export async function test_api_customer_cart_item_update_quantity_and_sku(
  connection: api.IConnection,
) {
  // 1. Register a seller
  const sellerEmail = typia.random<string & tags.Format<"email">>();
  const sellerJoin = await api.functional.auth.seller.join(connection, {
    body: {
      email: sellerEmail,
      password: RandomGenerator.alphaNumeric(10),
      display_name: RandomGenerator.name(),
      contact_phone: RandomGenerator.mobile(),
      status: "pending",
    } satisfies IShoppingSeller.IJoin,
  });
  typia.assert(sellerJoin);

  // 2. Register a customer
  const customerEmail = typia.random<string & tags.Format<"email">>();
  const customerJoin = await api.functional.auth.customer.join(connection, {
    body: {
      email: customerEmail,
      password: RandomGenerator.alphaNumeric(12),
      name: RandomGenerator.name(),
      phone: RandomGenerator.mobile(),
      href: "https://test-origin.example.com/signup",
      referrer: "https://test-referrer.example.com/ref",
    } satisfies IShoppingCustomer.ICreate,
  });
  typia.assert(customerJoin);

  // 3. Seller creates a product
  const productCode = RandomGenerator.alphaNumeric(12);
  const product = await api.functional.shopping.seller.products.create(
    connection,
    {
      body: {
        code: productCode,
        name: RandomGenerator.paragraph({ sentences: 2 }),
        description: RandomGenerator.content({ paragraphs: 2 }),
        main_image_uri:
          "https://images.example.com/" +
          RandomGenerator.alphaNumeric(8) +
          ".jpg",
        status: "active",
        business_status: "in_review",
      } satisfies IShoppingProduct.ICreate,
    },
  );
  typia.assert(product);

  // 4. Seller creates multiple SKUs
  // We'll prepare two attribute values to use as variant attributes for the SKUs
  // Since attribute creation APIs are not provided, variants will be arbitrary UUIDs (simulate as string&tags.Format<"uuid">)
  const attr1 = typia.random<string & tags.Format<"uuid">>();
  const attr2 = typia.random<string & tags.Format<"uuid">>();
  const sku1Code = "SKU-" + RandomGenerator.alphaNumeric(8);
  const sku2Code = "SKU-" + RandomGenerator.alphaNumeric(8);
  // SKU 1 (active)
  const sku1 = await api.functional.shopping.seller.products.skus.create(
    connection,
    {
      productCode: product.code,
      body: {
        sku_code: sku1Code,
        price: 10000,
        is_active: true,
        status: "in_stock",
        variant_attribute_value_ids: [attr1],
      } satisfies IShoppingSku.ICreate,
    },
  );
  typia.assert(sku1);

  // SKU 2 (also active, higher price)
  const sku2 = await api.functional.shopping.seller.products.skus.create(
    connection,
    {
      productCode: product.code,
      body: {
        sku_code: sku2Code,
        price: 12000,
        is_active: true,
        status: "in_stock",
        variant_attribute_value_ids: [attr2],
      } satisfies IShoppingSku.ICreate,
    },
  );
  typia.assert(sku2);

  // SKU 3 (inactive, cannot be referenced for substitution)
  const attr3 = typia.random<string & tags.Format<"uuid">>();
  const sku3Code = "SKU-" + RandomGenerator.alphaNumeric(8);
  const sku3 = await api.functional.shopping.seller.products.skus.create(
    connection,
    {
      productCode: product.code,
      body: {
        sku_code: sku3Code,
        price: 15000,
        is_active: false,
        status: "discontinued",
        variant_attribute_value_ids: [attr3],
      } satisfies IShoppingSku.ICreate,
    },
  );
  typia.assert(sku3);

  // 5. Customer adds SKU1 to a new cart as cart item (simulate cart creation by first insert).
  // There is no API for adding cart items; only update, so we simulate the pre-existing item: Assume cartId/itemId are needed (simulate with random UUIDs)
  const cartId = typia.random<string & tags.Format<"uuid">>();
  const itemId = typia.random<string & tags.Format<"uuid">>();

  // Insert the starting cart item (simulate as if already exists): Only update endpoint exists
  // We create it with initial quantity 1 with the active SKU1
  let cartItem = await api.functional.shopping.customer.carts.items.update(
    connection,
    {
      cartId,
      itemId,
      body: {
        quantity: 1,
      } satisfies IShoppingCartItem.IUpdate,
    },
  );
  typia.assert(cartItem);
  TestValidator.equals(
    "initial cart item sku_id matches",
    cartItem.sku.id,
    sku1.id,
  );
  TestValidator.equals("initial cart item quantity", cartItem.quantity, 1);

  // 6. Update cart item to new quantity (increase to 5)
  cartItem = await api.functional.shopping.customer.carts.items.update(
    connection,
    {
      cartId,
      itemId,
      body: {
        quantity: 5,
      } satisfies IShoppingCartItem.IUpdate,
    },
  );
  typia.assert(cartItem);
  TestValidator.equals("increase quantity", cartItem.quantity, 5);

  // Decrease quantity to 2
  cartItem = await api.functional.shopping.customer.carts.items.update(
    connection,
    {
      cartId,
      itemId,
      body: {
        quantity: 2,
      } satisfies IShoppingCartItem.IUpdate,
    },
  );
  typia.assert(cartItem);
  TestValidator.equals("decrease quantity", cartItem.quantity, 2);

  // Set to high quantity (simulate platform max as 10)
  cartItem = await api.functional.shopping.customer.carts.items.update(
    connection,
    {
      cartId,
      itemId,
      body: {
        quantity: 10,
      } satisfies IShoppingCartItem.IUpdate,
    },
  );
  typia.assert(cartItem);
  TestValidator.equals("set max quantity", cartItem.quantity, 10);

  // 7. Attempt to update cart item SKU (simulate substitution to SKU2)
  // As IShoppingCartItem.IUpdate only allows quantity (no sku change), this part cannot be implemented, so skip.

  // 8. Try referencing an inactive SKU (SKU3) or exceeding max quantity (simulate)
  // Since API doesn't let us specify sku, and can only update quantity, test quantity boundary
  await TestValidator.error("exceed max quantity should fail", async () => {
    await api.functional.shopping.customer.carts.items.update(connection, {
      cartId,
      itemId,
      body: {
        quantity: 9999, // arbitrarily large
      } satisfies IShoppingCartItem.IUpdate,
    });
  });

  // 9. Try updating as unauthorized user (register another customer)
  const attackerEmail = typia.random<string & tags.Format<"email">>();
  const attackerJoin = await api.functional.auth.customer.join(connection, {
    body: {
      email: attackerEmail,
      password: RandomGenerator.alphaNumeric(12),
      name: RandomGenerator.name(),
      phone: RandomGenerator.mobile(),
      href: "https://test-origin.example.com/hack",
      referrer: "https://test-referrer.example.com/hackref",
    } satisfies IShoppingCustomer.ICreate,
  });
  typia.assert(attackerJoin);
  // Attempt to update cart belonging to previous customer
  await TestValidator.error(
    "unauthorized user cannot update other's cart item",
    async () => {
      await api.functional.shopping.customer.carts.items.update(connection, {
        cartId,
        itemId,
        body: {
          quantity: 2,
        } satisfies IShoppingCartItem.IUpdate,
      });
    },
  );

  // 10. After each update, validate returned cart item (quantity, SKU, updated_at, error_flags are either undefined or empty)
  TestValidator.equals("sku exists after update", !!cartItem.sku, true);
  TestValidator.equals(
    "cart owner is active",
    cartItem.cart_owner.is_active,
    true,
  );
  TestValidator.equals(
    "error_flags are empty or undefined",
    cartItem.error_flags ?? [],
    [],
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IShoppingAttributeDimension } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingAttributeDimension";
import type { IShoppingAttributeValue } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingAttributeValue";
import type { IShoppingAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingAuthorizationToken";
import type { IShoppingCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingCategory";
import type { IShoppingCustomer } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingCustomer";
import type { IShoppingProduct } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingProduct";
import type { IShoppingProductAttribute } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingProductAttribute";
import type { IShoppingProductImage } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingProductImage";
import type { IShoppingSeller } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingSeller";
import type { IShoppingSku } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingSku";
import type { IShoppingSkuImage } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingSkuImage";
import type { IShoppingSkuVariant } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingSkuVariant";
import type { IShoppingTag } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingTag";

/**
 * Validate permanent deletion (erase) of an item from a customer's shopping
 * cart by its itemId.
 *
 * This test:
 *
 * 1. Registers a seller and adds a product with an SKU to the catalog.
 * 2. Registers a customer (and authenticates them).
 * 3. Customer simulates adding an item (SKU, simulated as cart item context) to a
 *    cart (mocked cart context).
 * 4. Directly deletes the provided cart item using the DELETE endpoint.
 * 5. Attempts to delete the same item again; expects error behavior (not
 *    found/forbidden as per business logic).
 * 6. Optionally checks that this item is no longer accessible.
 * 7. Optionally, tries deleting an item of another customer to verify forbidden
 *    access.
 * 8. Focuses on ownership enforcement, referential integrity, and error codes for
 *    edge cases.
 */
export async function test_api_customer_cart_item_delete(
  connection: api.IConnection,
) {
  // 1. Register a seller
  const sellerEmail = typia.random<string & tags.Format<"email">>();
  const seller: IShoppingSeller.IAuthorized =
    await api.functional.auth.seller.join(connection, {
      body: {
        email: sellerEmail,
        password: RandomGenerator.alphaNumeric(12),
        display_name: RandomGenerator.name(),
        contact_phone: RandomGenerator.mobile(),
        status: "pending",
      } satisfies IShoppingSeller.IJoin,
    });
  typia.assert(seller);

  // 2. Seller adds a product
  const productCode = RandomGenerator.alphaNumeric(10);
  const product: IShoppingProduct =
    await api.functional.shopping.seller.products.create(connection, {
      body: {
        code: productCode,
        name: RandomGenerator.paragraph({ sentences: 2 }),
        description: RandomGenerator.content({ paragraphs: 1 }),
        main_image_uri: "https://test.com/image.png",
        status: "active",
        business_status: "approved",
      } satisfies IShoppingProduct.ICreate,
    });
  typia.assert(product);

  // 3. Seller registers an attribute dimension/value and creates SKU
  // (simulate attribute value id from one that already exists in product)
  // Here, we take first attribute from product.attributes if present.
  let attributeValueId: string;
  if (product.attributes && product.attributes.length > 0) {
    attributeValueId = product.attributes[0].attribute_value.id;
  } else {
    // fallback: random UUID-format string, if not present (should ideally come from product.attributes)
    attributeValueId = typia.random<string & tags.Format<"uuid">>();
  }
  const skuCode = RandomGenerator.alphaNumeric(10);
  const sku: IShoppingSku =
    await api.functional.shopping.seller.products.skus.create(connection, {
      productCode: product.code,
      body: {
        sku_code: skuCode,
        price: 9000,
        is_active: true,
        status: "in_stock",
        variant_attribute_value_ids: [attributeValueId],
      } satisfies IShoppingSku.ICreate,
    });
  typia.assert(sku);

  // 4. Register customer
  const customerEmail = typia.random<string & tags.Format<"email">>();
  const customer: IShoppingCustomer.IAuthorized =
    await api.functional.auth.customer.join(connection, {
      body: {
        email: customerEmail,
        password: RandomGenerator.alphaNumeric(12),
        name: RandomGenerator.name(),
        phone: RandomGenerator.mobile(),
        href: "https://shopper.test/join",
        referrer: "https://shopper.test/landing",
      } satisfies IShoppingCustomer.ICreate,
    });
  typia.assert(customer);

  // 5. Simulate: Create cart and add (mock) item for cartId/itemId
  const cartId = typia.random<string & tags.Format<"uuid">>();
  const itemId = typia.random<string & tags.Format<"uuid">>(); // Normally API creates these. Here we test endpoint access.

  // 6. Perform DELETE for non-existent but plausible item (should be allowed or error)
  await TestValidator.error(
    "delete a non-existent cart item should error",
    async () => {
      await api.functional.shopping.customer.carts.items.erase(connection, {
        cartId,
        itemId,
      });
    },
  );

  // 7. Simulate that item exists: assume itemId now valid (for API demonstration, but no endpoint for creation is provided)
  // There is no cart item creation API, so this test focuses on error behavior (which is realistic from business context since erase should error for missing item)

  // 8. Attempt to delete same item again -- should also error
  await TestValidator.error(
    "delete the same cart item again yields error",
    async () => {
      await api.functional.shopping.customer.carts.items.erase(connection, {
        cartId,
        itemId,
      });
    },
  );

  // 9. Attempt to delete an item from a different user's cart (simulate another customer's cartId)
  const otherCustomerCartId = typia.random<string & tags.Format<"uuid">>();
  const otherItemId = typia.random<string & tags.Format<"uuid">>();
  await TestValidator.error(
    "delete other user's cart item should error or be forbidden",
    async () => {
      await api.functional.shopping.customer.carts.items.erase(connection, {
        cartId: otherCustomerCartId,
        itemId: otherItemId,
      });
    },
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IPageIShoppingInventoryAlert } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIShoppingInventoryAlert";
import type { IShoppingAttributeDimension } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingAttributeDimension";
import type { IShoppingAttributeValue } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingAttributeValue";
import type { IShoppingAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingAuthorizationToken";
import type { IShoppingCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingCategory";
import type { IShoppingInventoryAlert } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingInventoryAlert";
import type { IShoppingProduct } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingProduct";
import type { IShoppingProductAttribute } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingProductAttribute";
import type { IShoppingProductImage } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingProductImage";
import type { IShoppingSeller } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingSeller";
import type { IShoppingSku } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingSku";
import type { IShoppingSkuImage } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingSkuImage";
import type { IShoppingSkuVariant } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingSkuVariant";
import type { IShoppingTag } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingTag";

/**
 * This test covers the scenario where an authenticated seller searches for all
 * inventory alerts (active and resolved) for a SKU that they own.
 *
 * Steps:
 *
 * 1. Register a new seller (with valid unique fake info).
 * 2. Create a new product with all required onboarding fields for the seller.
 * 3. Create a SKU under the new product (assign fake attribute values for required
 *    field).
 * 4. Search inventory alerts for the SKU (filter by various alert types and
 *    resolved status).
 * 5. Assert correct response structure, pagination, and that all returned alerts
 *    belong to the correct SKU.
 * 6. Attempt to search alerts as another seller (should yield forbidden/empty
 *    results).
 * 7. Check filtering with combinations of alert_type, resolved, and date ranges.
 */
export async function test_api_inventory_alerts_search_by_seller_for_sku(
  connection: api.IConnection,
) {
  // 1. Register new seller
  const sellerEmail = typia.random<string & tags.Format<"email">>();
  const seller = await api.functional.auth.seller.join(connection, {
    body: {
      email: sellerEmail,
      password: RandomGenerator.alphaNumeric(12),
      display_name: RandomGenerator.name(),
      contact_phone: RandomGenerator.mobile(),
      status: "pending",
    } satisfies IShoppingSeller.IJoin,
  });
  typia.assert(seller);

  // 2. Create new product for the seller
  const productBody = {
    code: RandomGenerator.alphaNumeric(10),
    name: RandomGenerator.paragraph({ sentences: 3 }),
    description: RandomGenerator.content({ paragraphs: 1 }),
    main_image_uri:
      "https://cdn.test.com/img/" + RandomGenerator.alphaNumeric(6) + ".png",
    status: "draft",
    business_status: "in_review",
  } satisfies IShoppingProduct.ICreate;
  const product = await api.functional.shopping.seller.products.create(
    connection,
    { body: productBody },
  );
  typia.assert(product);

  // 3. Create single SKU for the product
  // Use the first attribute in product.attributes if available, else use random
  let attributeValueId: string;
  if (Array.isArray(product.attributes) && product.attributes.length > 0) {
    attributeValueId = typia.assert<IShoppingProductAttribute>(
      product.attributes[0],
    ).attribute_value.id;
  } else {
    // Fallback: make up a random UUID for test coverage (fake, but type-compatible)
    attributeValueId = typia.random<string & tags.Format<"uuid">>();
  }
  const skuBody = {
    sku_code: RandomGenerator.alphaNumeric(8),
    price: 10000,
    is_active: true,
    barcode: null,
    status: "in_stock",
    variant_attribute_value_ids: [attributeValueId],
  } satisfies IShoppingSku.ICreate;
  const sku = await api.functional.shopping.seller.products.skus.create(
    connection,
    {
      productCode: product.code,
      body: skuBody,
    },
  );
  typia.assert(sku);

  // 4. Search for all alerts for this SKU
  // Use default pagination/sorting
  const page1 = await api.functional.shopping.seller.inventory.alerts.index(
    connection,
    {
      skuCode: sku.sku_code,
      body: {
        page: 1,
        limit: 20,
        sort_by: "triggered_at",
        sort_order: "desc",
      } satisfies IShoppingInventoryAlert.IRequest,
    },
  );
  typia.assert(page1);
  TestValidator.equals(
    "all alerts belong to the SKU",
    true,
    page1.data.every((alert) => alert.shopping_sku_id === sku.id),
  );

  // 5. Try filtering by alert_type and resolved status combinations
  for (const alertType of [
    "low_stock",
    "out_of_stock",
    "anomaly",
    "manual",
  ] as const) {
    const filtered =
      await api.functional.shopping.seller.inventory.alerts.index(connection, {
        skuCode: sku.sku_code,
        body: {
          alert_type: alertType,
          page: 1,
          limit: 10,
          sort_by: "triggered_at",
          sort_order: "desc",
        } satisfies IShoppingInventoryAlert.IRequest,
      });
    typia.assert(filtered);
    TestValidator.equals(
      `alerts filtered by type=${alertType} belong to the SKU`,
      true,
      filtered.data.every(
        (alert) =>
          alert.shopping_sku_id === sku.id && alert.alert_type === alertType,
      ),
    );
  }

  // 6. Filter by resolved only
  const resolvedOnly =
    await api.functional.shopping.seller.inventory.alerts.index(connection, {
      skuCode: sku.sku_code,
      body: {
        resolved: true,
        page: 1,
        limit: 5,
        sort_by: "triggered_at",
        sort_order: "desc",
      } satisfies IShoppingInventoryAlert.IRequest,
    });
  typia.assert(resolvedOnly);
  TestValidator.equals(
    "all resolved alerts have resolved_at timestamp",
    true,
    resolvedOnly.data.every(
      (alert) =>
        alert.resolved === true &&
        alert.resolved_at !== null &&
        alert.resolved_at !== undefined,
    ),
  );

  // 7. Filter by unresolved only
  const unresolvedOnly =
    await api.functional.shopping.seller.inventory.alerts.index(connection, {
      skuCode: sku.sku_code,
      body: {
        resolved: false,
        page: 1,
        limit: 5,
        sort_by: "triggered_at",
        sort_order: "desc",
      } satisfies IShoppingInventoryAlert.IRequest,
    });
  typia.assert(unresolvedOnly);
  TestValidator.equals(
    "all unresolved alerts are unresolved",
    true,
    unresolvedOnly.data.every((alert) => alert.resolved === false),
  );

  // 8. Date range filtering: triggered_at_from and triggered_at_to
  // Use the triggered_at date from any alert found, or a random date in the last 30 days if none
  let rangeStart: string | undefined;
  let rangeEnd: string | undefined;
  if (page1.data.length > 0) {
    const firstAlert = page1.data[0];
    rangeStart = firstAlert.triggered_at;
    rangeEnd = firstAlert.triggered_at;
  } else {
    // No data, use current date/time as range
    rangeStart = new Date().toISOString();
    rangeEnd = new Date().toISOString();
  }
  const rangeFiltered =
    await api.functional.shopping.seller.inventory.alerts.index(connection, {
      skuCode: sku.sku_code,
      body: {
        triggered_at_from: rangeStart,
        triggered_at_to: rangeEnd,
        page: 1,
        limit: 10,
        sort_by: "triggered_at",
        sort_order: "desc",
      } satisfies IShoppingInventoryAlert.IRequest,
    });
  typia.assert(rangeFiltered);
  TestValidator.equals(
    "date range filtered alerts belong to SKU",
    true,
    rangeFiltered.data.every((alert) => alert.shopping_sku_id === sku.id),
  );

  // 9. Attempt as another (unauthorized) seller
  const otherSeller = await api.functional.auth.seller.join(connection, {
    body: {
      email: typia.random<string & tags.Format<"email">>(),
      password: RandomGenerator.alphaNumeric(12),
      display_name: RandomGenerator.name(),
      contact_phone: RandomGenerator.mobile(),
      status: "pending",
    } satisfies IShoppingSeller.IJoin,
  });
  typia.assert(otherSeller);
  // Search for the original SKU using the new seller (should get no alerts or denied)
  const unauthorizedResult =
    await api.functional.shopping.seller.inventory.alerts.index(connection, {
      skuCode: sku.sku_code,
      body: {
        page: 1,
        limit: 10,
        sort_by: "triggered_at",
        sort_order: "desc",
      } satisfies IShoppingInventoryAlert.IRequest,
    });
  typia.assert(unauthorizedResult);
  TestValidator.equals(
    "unauthorized seller sees no alerts",
    0,
    unauthorizedResult.data.length,
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IPageIShoppingWishlistItem } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIShoppingWishlistItem";
import type { IShoppingAttributeDimension } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingAttributeDimension";
import type { IShoppingAttributeValue } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingAttributeValue";
import type { IShoppingAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingAuthorizationToken";
import type { IShoppingCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingCategory";
import type { IShoppingCustomer } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingCustomer";
import type { IShoppingProduct } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingProduct";
import type { IShoppingProductAttribute } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingProductAttribute";
import type { IShoppingProductImage } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingProductImage";
import type { IShoppingSeller } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingSeller";
import type { IShoppingSku } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingSku";
import type { IShoppingSkuImage } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingSkuImage";
import type { IShoppingSkuVariant } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingSkuVariant";
import type { IShoppingTag } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingTag";
import type { IShoppingWishlist } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingWishlist";
import type { IShoppingWishlistItem } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingWishlistItem";

/**
 * Validate retrieval and filtering of a customer's wishlist, focusing on
 * pagination, filtering, SKU status, and privacy.
 *
 * This test covers:
 *
 * 1. Customer registration (simulated as unauthenticated join)
 * 2. Product and SKU creation (by seller, assumed already set up, as no seller
 *    API/join available)
 * 3. Manual assignment of several SKUs to the wishlist by invoking index API
 *    indirectly
 * 4. Pagination correctness (limit, total, navigation, empty page)
 * 5. Filter by product name, category, in-stock/out-of-stock statuses
 * 6. Each wishlist item's SKU summary must refer to valid product summary
 * 7. No access to other customers' wishlists
 * 8. Unavailable/archived SKUs are reflected in results
 * 9. Edge case: wishlist with no items returns empty result
 */
export async function test_api_customer_wishlist_retrieve_and_filter(
  connection: api.IConnection,
) {
  // 1. Register new customer
  const customerEmail = typia.random<string & tags.Format<"email">>();
  const customerHref = "https://testhost/customer/signup";
  const customerReferrer = "https://testhost/landing";
  const joinBody = {
    email: customerEmail,
    password: "passwordtest",
    name: RandomGenerator.name(),
    phone: RandomGenerator.mobile(),
    href: customerHref,
    referrer: customerReferrer,
  } satisfies IShoppingCustomer.ICreate;
  const customer = await api.functional.auth.customer.join(connection, {
    body: joinBody,
  });
  typia.assert(customer);

  // 2. Create products (3 active, 1 archived, 1 out-of-stock/discontinued). No seller API, so just create via API (simulates admin or seller already logged in).
  const productNames = [
    RandomGenerator.name(),
    RandomGenerator.name(),
    RandomGenerator.name(),
    RandomGenerator.name(),
    RandomGenerator.name(),
  ];
  const products: IShoppingProduct[] = [];
  for (let i = 0; i < 3; ++i) {
    const p = await api.functional.shopping.seller.products.create(connection, {
      body: {
        code: RandomGenerator.alphaNumeric(8),
        name: productNames[i],
        description: RandomGenerator.paragraph({ sentences: 8 }),
        main_image_uri: `https://testhost/img/${RandomGenerator.alphaNumeric(12)}.jpg`,
        status: "active",
        business_status: "approved",
      } satisfies IShoppingProduct.ICreate,
    });
    typia.assert(p);
    products.push(p);
  }
  // Now create an archived product as out-of-stock
  const archivedProduct = await api.functional.shopping.seller.products.create(
    connection,
    {
      body: {
        code: RandomGenerator.alphaNumeric(8),
        name: productNames[3],
        description: RandomGenerator.paragraph({ sentences: 6 }),
        main_image_uri: `https://testhost/img/${RandomGenerator.alphaNumeric(10)}.jpg`,
        status: "archived",
        business_status: "archived",
      } satisfies IShoppingProduct.ICreate,
    },
  );
  typia.assert(archivedProduct);
  products.push(archivedProduct);

  const discontinuedProduct =
    await api.functional.shopping.seller.products.create(connection, {
      body: {
        code: RandomGenerator.alphaNumeric(8),
        name: productNames[4],
        description: RandomGenerator.paragraph({ sentences: 7 }),
        main_image_uri: `https://testhost/img/${RandomGenerator.alphaNumeric(10)}.jpeg`,
        status: "active",
        business_status: "discontinued",
      } satisfies IShoppingProduct.ICreate,
    });
  typia.assert(discontinuedProduct);
  products.push(discontinuedProduct);

  // 3. Prepare a set of SKUs - gather one SKU from each product
  const sampleSKUs = products.map((p) => p.skus[0]);
  // 4. (PRETEND) Add those SKUs to the wishlist by defining as expected wishlist items (API does not provide an "add to wishlist", index just reads wishlist)
  // 5. Test: Edge case - Empty wishlist must return zero data
  const emptyPage = await api.functional.shopping.customer.wishlists.index(
    connection,
    {
      body: { page: 1, limit: 10 } satisfies IShoppingWishlist.IRequest,
    },
  );
  typia.assert(emptyPage);
  TestValidator.equals("empty wishlist returns zero", emptyPage.data.length, 0);
  TestValidator.equals(
    "pagination for empty wishlist",
    emptyPage.pagination.current,
    1,
  );
  TestValidator.equals(
    "pagination for empty wishlist",
    emptyPage.pagination.pages,
    0,
  );

  // 6. (PRETEND) Now, manually associate produced SKUs for test. In real test, insert into DB or use API to add (omitted for lack of endpoint)
  // 7. Test: Pagination
  for (let pagelimit = 2; pagelimit <= 3; ++pagelimit) {
    const page = await api.functional.shopping.customer.wishlists.index(
      connection,
      {
        body: {
          page: 1,
          limit: pagelimit,
        } satisfies IShoppingWishlist.IRequest,
      },
    );
    typia.assert(page);
    TestValidator.equals(
      "pagination limit maintained",
      page.pagination.limit,
      pagelimit,
    );
    TestValidator.equals("pagination page 1", page.pagination.current, 1);
    // Since wishlist is empty, expect always zero data as no add-wishlist operation exists (cannot actually test add case realistically here)
    TestValidator.equals("pagination is empty", page.data.length, 0);
  }
  // 8. Test: Special filters (search, in_stock_only, category_codes), expect always empty as above
  const filterQueries: Partial<IShoppingWishlist.IRequest>[] = [
    { search: productNames[0] },
    { in_stock_only: true },
    { category_codes: ["fake_category_code_123"] },
  ];
  for (const q of filterQueries) {
    const res = await api.functional.shopping.customer.wishlists.index(
      connection,
      {
        body: { page: 1, limit: 10, ...q } satisfies IShoppingWishlist.IRequest,
      },
    );
    typia.assert(res);
    TestValidator.equals("filtered wishlist is empty", res.data.length, 0);
  }
  // 9. (No cross-account privacy case possible as there is no API to read another wishlist or to impersonate another customer)
}

