import { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import { SellerPayload } from "../decorators/payload/SellerPayload";

export async function patchShoppingSellerInventorySkuCodeAdjustments(props: {
  seller: SellerPayload;
  skuCode: string;
  body: IShoppingInventoryAdjustment.IRequest;
}): Promise<IPageIShoppingInventoryAdjustment> {
  const { seller, skuCode, body } = props;
  // Step 1: Lookup SKU and enforce seller ownership
  const sku = await MyGlobal.prisma.shopping_skus.findFirst({
    where: {
      sku_code: skuCode,
      deleted_at: null,
    },
  });
  if (!sku) {
    throw new HttpException("SKU not found", 404);
  }
  // Check ownership: get parent product, verify seller
  const product = await MyGlobal.prisma.shopping_products.findFirst({
    where: { id: sku.shopping_product_id, shopping_seller_id: seller.id },
  });
  if (!product) {
    throw new HttpException("Unauthorized - seller does not own this SKU", 403);
  }
  // Step 2: Build Prisma where clause for adjustment filters
  const baseWhere: Record<string, any> = { shopping_sku_id: sku.id };
  if (body.actor_type !== undefined) baseWhere.actor_type = body.actor_type;
  if (body.reason_code !== undefined) baseWhere.reason_code = body.reason_code;
  if (body.context !== undefined)
    baseWhere.context_note = { contains: body.context };

  // Date range filter
  if (body.date_from !== undefined && body.date_to !== undefined) {
    baseWhere.created_at = { gte: body.date_from, lte: body.date_to };
  } else if (body.date_from !== undefined) {
    baseWhere.created_at = { gte: body.date_from };
  } else if (body.date_to !== undefined) {
    baseWhere.created_at = { lte: body.date_to };
  }
  // Adjustment min/max
  if (body.adjustment_min !== undefined && body.adjustment_max !== undefined) {
    baseWhere.adjustment_amount = {
      gte: body.adjustment_min,
      lte: body.adjustment_max,
    };
  } else if (body.adjustment_min !== undefined) {
    baseWhere.adjustment_amount = { gte: body.adjustment_min };
  } else if (body.adjustment_max !== undefined) {
    baseWhere.adjustment_amount = { lte: body.adjustment_max };
  }
  // Sorting
  const sortField =
    body.sort_by === "adjustment_amount" ? "adjustment_amount" : "created_at";
  const sortDirection = body.sort_direction === "asc" ? "asc" : "desc";
  // Pagination
  const page = Number(body.page ?? 1);
  const limit = Number(body.limit ?? 20);
  const skip = (page - 1) * limit;
  // Step 3: Query adjustments and count
  const [rows, total] = await Promise.all([
    MyGlobal.prisma.shopping_inventory_adjustments.findMany({
      where: baseWhere,
      orderBy: { [sortField]: sortDirection },
      skip,
      take: limit,
    }),
    MyGlobal.prisma.shopping_inventory_adjustments.count({ where: baseWhere }),
  ]);
  // Step 4: Format adjustments as DTOs
  return {
    pagination: {
      current: page,
      limit: limit,
      records: total,
      pages: Math.ceil(total / limit),
    },
    data: rows.map((row) => ({
      id: row.id,
      shopping_inventory_id: row.shopping_inventory_id,
      shopping_sku_id: row.shopping_sku_id,
      actor_type: row.actor_type,
      actor_id: row.actor_id,
      reason_code: row.reason_code,
      quantity_before: row.quantity_before,
      quantity_after: row.quantity_after,
      adjustment_amount: row.adjustment_amount,
      context_note: row.context_note ?? null,
      created_at: toISOStringSafe(row.created_at),
    })),
  };
}

import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/client";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";
import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

import { IShoppingRefundRequest } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingRefundRequest";
import { IPageIShoppingRefundRequest } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIShoppingRefundRequest";
import { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import { IShoppingOrder } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingOrder";
import { IShoppingCustomer } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingCustomer";
import { IShoppingRefundActor } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingRefundActor";
import { IShoppingRefundRequestItem } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingRefundRequestItem";
import { SellerPayload } from "../decorators/payload/SellerPayload";

export async function patchShoppingSellerRefunds(props: {
  seller: SellerPayload;
  body: IShoppingRefundRequest.IRequest;
}): Promise<IPageIShoppingRefundRequest.ISummary> {
  const { seller, body } = props;

  const page = typeof body.page === "number" && body.page > 0 ? body.page : 1;
  const limit =
    typeof body.limit === "number" && body.limit > 0 ? body.limit : 20;
  const offset = (page - 1) * limit;

  const sellerOrderLines = await MyGlobal.prisma.shopping_order_lines.findMany({
    where: { shopping_seller_id: seller.id },
    select: { id: true },
  });
  const sellerOrderLineIds = sellerOrderLines.map((l) => l.id);
  if (sellerOrderLineIds.length === 0) {
    return {
      pagination: {
        current: Number(page),
        limit: Number(limit),
        records: 0,
        pages: 0,
      },
      data: [],
    };
  }

  const matchingRefundItems =
    await MyGlobal.prisma.shopping_refund_request_items.findMany({
      where: { shopping_order_line_id: { in: sellerOrderLineIds } },
      select: { shopping_refund_request_id: true },
    });
  const relevantRefundRequestIds = [
    ...new Set(matchingRefundItems.map((i) => i.shopping_refund_request_id)),
  ];
  if (relevantRefundRequestIds.length === 0) {
    return {
      pagination: {
        current: Number(page),
        limit: Number(limit),
        records: 0,
        pages: 0,
      },
      data: [],
    };
  }

  const where: Record<string, unknown> = {
    id: { in: relevantRefundRequestIds },
    deleted_at: null,
    ...(body.request_type ? { request_type: body.request_type } : {}),
    ...(body.status ? { status: body.status } : {}),
    ...(body.actor_type ? { actor_type: body.actor_type } : {}),
    ...(body.actor_id ? { shopping_actor_id: body.actor_id } : {}),
    ...(body.order_id ? { shopping_order_id: body.order_id } : {}),
    ...(body.from_date ? { created_at: { gte: body.from_date } } : {}),
    ...(body.to_date
      ? {
          created_at: {
            ...(body.from_date ? { gte: body.from_date } : {}),
            lte: body.to_date,
          },
        }
      : {}),
  };

  let orderByField = "created_at";
  if (
    body.order_by &&
    ["created_at", "updated_at", "status", "request_type"].includes(
      body.order_by,
    )
  ) {
    orderByField = body.order_by;
  }
  const orderDirection = body.order_direction === "asc" ? "asc" : "desc";

  const total = await MyGlobal.prisma.shopping_refund_requests.count({ where });

  const refundRequests =
    await MyGlobal.prisma.shopping_refund_requests.findMany({
      where,
      orderBy: { [orderByField]: orderDirection },
      skip: offset,
      take: limit,
      select: {
        id: true,
        shopping_order_id: true,
        shopping_actor_id: true,
        actor_type: true,
        request_type: true,
        business_reason: true,
        request_context: true,
        status: true,
        created_at: true,
        updated_at: true,
      },
    });

  const orderIds = [...new Set(refundRequests.map((r) => r.shopping_order_id))];
  const actorIdsByType: Record<string, Set<string>> = {};
  for (const r of refundRequests) {
    if (!actorIdsByType[r.actor_type]) actorIdsByType[r.actor_type] = new Set();
    actorIdsByType[r.actor_type].add(r.shopping_actor_id);
  }

  const orders = await MyGlobal.prisma.shopping_orders.findMany({
    where: { id: { in: orderIds } },
    select: {
      id: true,
      order_code: true,
      total_price: true,
      status: true,
      created_at: true,
      updated_at: true,
      shopping_customer_id: true,
    },
  });
  const customerIds = [...new Set(orders.map((o) => o.shopping_customer_id))];
  const customers = await MyGlobal.prisma.shopping_customers.findMany({
    where: { id: { in: customerIds } },
    select: {
      id: true,
      name: true,
      email: true,
      is_active: true,
      created_at: true,
      deleted_at: true,
    },
  });
  const sellerActorIds = actorIdsByType["seller"]
    ? Array.from(actorIdsByType["seller"])
    : [];
  const sellers = sellerActorIds.length
    ? await MyGlobal.prisma.shopping_sellers.findMany({
        where: { id: { in: sellerActorIds } },
        select: { id: true, display_name: true },
      })
    : [];
  const adminActorIds = actorIdsByType["admin"]
    ? Array.from(actorIdsByType["admin"])
    : [];
  const admins = adminActorIds.length
    ? await MyGlobal.prisma.shopping_admins.findMany({
        where: { id: { in: adminActorIds } },
        select: { id: true, name: true },
      })
    : [];

  const refundRequestIds = refundRequests.map((r) => r.id);
  const allItems = await MyGlobal.prisma.shopping_refund_request_items.findMany(
    {
      where: { shopping_refund_request_id: { in: refundRequestIds } },
      select: {
        id: true,
        shopping_refund_request_id: true,
        shopping_order_line_id: true,
        quantity: true,
        item_business_reason: true,
        created_at: true,
        updated_at: true,
      },
    },
  );

  const orderMap = Object.fromEntries(orders.map((o) => [o.id, o]));
  const customerMap = Object.fromEntries(customers.map((c) => [c.id, c]));
  const sellerMap = Object.fromEntries(sellers.map((s) => [s.id, s]));
  const adminMap = Object.fromEntries(admins.map((a) => [a.id, a]));
  const itemsByRefundRequest: Record<string, typeof allItems> = {};
  for (const item of allItems) {
    if (!itemsByRefundRequest[item.shopping_refund_request_id])
      itemsByRefundRequest[item.shopping_refund_request_id] = [];
    itemsByRefundRequest[item.shopping_refund_request_id].push(item);
  }

  const data = refundRequests
    .map((r) => {
      const order = orderMap[r.shopping_order_id];
      const customer = order
        ? customerMap[order.shopping_customer_id]
        : undefined;
      const orderSummary =
        order && customer
          ? {
              id: order.id,
              order_code: order.order_code,
              total_price: order.total_price,
              status: order.status,
              created_at: toISOStringSafe(order.created_at),
              updated_at: toISOStringSafe(order.updated_at),
              customer: {
                id: customer.id,
                name: customer.name,
                email: customer.email,
                is_active: customer.is_active,
                created_at: toISOStringSafe(customer.created_at),
                deleted_at:
                  customer.deleted_at !== null
                    ? toISOStringSafe(customer.deleted_at)
                    : null,
              },
            }
          : undefined;
      let actorSummary: IShoppingRefundActor.ISummary | undefined = undefined;
      if (r.actor_type === "customer" && customerMap[r.shopping_actor_id]) {
        const ac = customerMap[r.shopping_actor_id];
        actorSummary = { actor_type: "customer", id: ac.id, name: ac.name };
      } else if (r.actor_type === "seller" && sellerMap[r.shopping_actor_id]) {
        const ac = sellerMap[r.shopping_actor_id];
        actorSummary = {
          actor_type: "seller",
          id: ac.id,
          name: ac.display_name,
        };
      } else if (r.actor_type === "admin" && adminMap[r.shopping_actor_id]) {
        const ac = adminMap[r.shopping_actor_id];
        actorSummary = { actor_type: "admin", id: ac.id, name: ac.name };
      }
      const itemSummaries = (itemsByRefundRequest[r.id] ?? []).map((item) => ({
        id: item.id,
        shopping_refund_request_id: item.shopping_refund_request_id,
        order_line_id: item.shopping_order_line_id,
        quantity: item.quantity,
        item_business_reason: item.item_business_reason ?? undefined,
        created_at: toISOStringSafe(item.created_at),
        updated_at: toISOStringSafe(item.updated_at),
      }));
      if (!orderSummary || !actorSummary) return undefined;
      return {
        id: r.id,
        order: orderSummary,
        actor: actorSummary,
        request_type: r.request_type,
        business_reason: r.business_reason,
        request_context: r.request_context ?? undefined,
        status: r.status,
        created_at: toISOStringSafe(r.created_at),
        updated_at: toISOStringSafe(r.updated_at),
        items: itemSummaries,
      };
    })
    .filter(Boolean) as IShoppingRefundRequest.ISummary[];

  return {
    pagination: {
      current: Number(page),
      limit: Number(limit),
      records: total,
      pages: Math.ceil(total / limit),
    },
    data,
  };
}

import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/client";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";
import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

import { IShoppingRefundApproval } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingRefundApproval";
import { IPageIShoppingRefundApproval } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIShoppingRefundApproval";
import { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import { SellerPayload } from "../decorators/payload/SellerPayload";

export async function patchShoppingSellerRefundsRefundRequestIdApprovals(props: {
  seller: SellerPayload;
  refundRequestId: string & tags.Format<"uuid">;
  body: IShoppingRefundApproval.IRequest;
}): Promise<IPageIShoppingRefundApproval.ISummary> {
  const { seller, refundRequestId, body } = props;

  // Check: Refund request exists and is linked to at least one order line for this seller
  const refundRequest =
    await MyGlobal.prisma.shopping_refund_requests.findUnique({
      where: { id: refundRequestId, deleted_at: null },
      include: {
        shopping_refund_request_items: {
          select: { shopping_order_line_id: true },
        },
      },
    });
  if (!refundRequest) throw new HttpException("Refund request not found", 404);
  const orderLineIds = refundRequest.shopping_refund_request_items.map(
    (item) => item.shopping_order_line_id,
  );
  if (orderLineIds.length === 0)
    throw new HttpException("No order lines in refund request", 404);
  const orderLines = await MyGlobal.prisma.shopping_order_lines.findMany({
    where: { id: { in: orderLineIds } },
    select: { shopping_seller_id: true },
  });
  const related = orderLines.some(
    (line) => line.shopping_seller_id === seller.id,
  );
  if (!related)
    throw new HttpException(
      "Forbidden: you are not related to this refund request",
      403,
    );

  // Pagination
  const page = body.page > 0 ? Number(body.page) : 1;
  const pageSize = Math.min(Math.max(Number(body.pageSize), 1), 100);

  // Build where filter
  const where: Record<string, unknown> = {
    shopping_refund_request_id: refundRequestId,
  };
  if (body.actor_type !== undefined) where.actor_type = body.actor_type;
  if (body.actor_id !== undefined) where.shopping_actor_id = body.actor_id;
  if (body.action !== undefined) where.action = body.action;
  if (body.fromCreatedAt !== undefined || body.toCreatedAt !== undefined) {
    where.created_at = {};
    if (body.fromCreatedAt !== undefined)
      (where.created_at as Record<string, unknown>).gte = body.fromCreatedAt;
    if (body.toCreatedAt !== undefined)
      (where.created_at as Record<string, unknown>).lte = body.toCreatedAt;
  }
  if (body.has_note === true) {
    where.note = { not: null };
  } else if (body.has_note === false) {
    where.note = null;
  }

  // Query total
  const total = await MyGlobal.prisma.shopping_refund_approvals.count({
    where,
  });
  // Query approval list
  const resultRows = await MyGlobal.prisma.shopping_refund_approvals.findMany({
    where,
    orderBy: [{ created_at: "desc" }, { id: "desc" }],
    skip: (page - 1) * pageSize,
    take: pageSize,
  });
  // Map to ISummary[]
  const data = resultRows.map((r) => ({
    id: r.id,
    shopping_refund_request_id: r.shopping_refund_request_id,
    shopping_refund_status_history_id: r.shopping_refund_status_history_id,
    shopping_actor_id: r.shopping_actor_id,
    actor_type: typia.assert<"admin" | "seller">(
      r.actor_type === "admin" ? "admin" : "seller",
    ),
    action: r.action,
    note: r.note !== null && r.note !== undefined ? r.note : undefined,
    created_at: toISOStringSafe(r.created_at),
  }));
  const pages = Math.ceil(total / pageSize);
  return {
    pagination: {
      current: Number(page),
      limit: Number(pageSize),
      records: Number(total),
      pages: Number(pages),
    },
    data,
  };
}

import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/client";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";
import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

import { IShoppingRefundStatusHistory } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingRefundStatusHistory";
import { IPageIShoppingRefundStatusHistory } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIShoppingRefundStatusHistory";
import { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import { SellerPayload } from "../decorators/payload/SellerPayload";

export async function patchShoppingSellerRefundsRefundRequestIdStatuses(props: {
  seller: SellerPayload;
  refundRequestId: string & tags.Format<"uuid">;
  body: IShoppingRefundStatusHistory.IRequest;
}): Promise<IPageIShoppingRefundStatusHistory> {
  const { seller, refundRequestId, body } = props;

  // Validate refund request exists
  const refundRequest =
    await MyGlobal.prisma.shopping_refund_requests.findFirst({
      where: { id: refundRequestId, deleted_at: null },
      select: { shopping_order_id: true },
    });
  if (!refundRequest) {
    throw new HttpException("Refund request not found", 404);
  }

  // Ensure the seller owns at least one SKU in the order
  const sellerOrderLine = await MyGlobal.prisma.shopping_order_lines.findFirst({
    where: {
      shopping_order_id: refundRequest.shopping_order_id,
      shopping_seller_id: seller.id,
      deleted_at: null,
    },
    select: { id: true },
  });
  if (!sellerOrderLine) {
    throw new HttpException(
      "Forbidden: Seller does not own any SKUs in this refund request's order.",
      403,
    );
  }

  const pageNum = Number(body.page);
  const pageLimit = Number(body.limit);

  // Build filters
  const filters: {
    shopping_refund_request_id: string & tags.Format<"uuid">;
    actor_type?: "customer" | "seller" | "admin";
    timestamp?: {
      gte?: string & tags.Format<"date-time">;
      lte?: string & tags.Format<"date-time">;
    };
  } = { shopping_refund_request_id: refundRequestId };
  if (body.actor_type) {
    filters.actor_type = body.actor_type;
  }
  if (body.from_date || body.to_date) {
    filters.timestamp = {};
    if (body.from_date) filters.timestamp.gte = body.from_date;
    if (body.to_date) filters.timestamp.lte = body.to_date;
  }

  // Fetch all histories, we'll filter status_transition in application (accurate pagination/total)
  const allHistories =
    await MyGlobal.prisma.shopping_refund_status_histories.findMany({
      where: filters,
      orderBy: { timestamp: body.sort === "desc" ? "desc" : "asc" },
    });

  // status_transition is app logic: previous_status + '_to_' + new_status
  let filtered = allHistories;
  if (body.status_transition) {
    filtered = allHistories.filter(
      (row) =>
        row.previous_status + "_to_" + row.new_status ===
        body.status_transition,
    );
  }

  const total = filtered.length;
  const pages = pageLimit > 0 ? Math.ceil(total / pageLimit) : 1;
  const offset = (pageNum - 1) * pageLimit;
  const paginated = filtered.slice(offset, offset + pageLimit);

  return {
    pagination: {
      current: pageNum,
      limit: pageLimit,
      records: total,
      pages: pages,
    },
    data: paginated.map((row) => {
      const result: IShoppingRefundStatusHistory = {
        id: row.id,
        shopping_refund_request_id: row.shopping_refund_request_id,
        shopping_actor_id: row.shopping_actor_id,
        actor_type: typia.assert<"customer" | "seller" | "admin">(
          row.actor_type,
        ),
        previous_status: row.previous_status,
        new_status: row.new_status,
        timestamp: toISOStringSafe(row.timestamp),
      };
      if (row.change_context !== undefined && row.change_context !== null) {
        result.change_context = row.change_context;
      }
      return result;
    }),
  };
}

import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/client";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";
import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

import { IShoppingShipmentTracking } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingShipmentTracking";
import { IPageIShoppingShipmentTracking } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIShoppingShipmentTracking";
import { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import { SellerPayload } from "../decorators/payload/SellerPayload";

export async function patchShoppingSellerShipmentsCodePackagesPackageLabelTrackings(props: {
  seller: SellerPayload;
  code: string;
  packageLabel: string;
  body: IShoppingShipmentTracking.IRequest;
}): Promise<IPageIShoppingShipmentTracking> {
  const { seller, code, packageLabel, body } = props;

  // 1. Find shipment by code & seller (soft-delete aware)
  const shipment = await MyGlobal.prisma.shopping_shipments.findFirst({
    where: {
      code,
      shopping_seller_id: seller.id,
      deleted_at: null,
    },
    select: { id: true },
  });
  if (!shipment)
    throw new HttpException("Shipment not found or access denied", 404);

  // 2. Find package by label & shipment (soft-delete aware)
  const pkg = await MyGlobal.prisma.shopping_shipment_packages.findFirst({
    where: {
      shopping_shipment_id: shipment.id,
      package_label: packageLabel,
      deleted_at: null,
    },
    select: { id: true },
  });
  if (!pkg) throw new HttpException("Package not found", 404);

  // 3. Build filters for tracking instances
  const filter = {
    shopping_shipment_package_id: pkg.id,
    ...(body.tracking_source ? { tracking_source: body.tracking_source } : {}),
    ...(body.status ? { status: body.status } : {}),
    ...(body.event_start_at || body.event_end_at
      ? {
          last_update_at: {
            ...(body.event_start_at ? { gte: body.event_start_at } : {}),
            ...(body.event_end_at ? { lte: body.event_end_at } : {}),
          },
        }
      : {}),
    deleted_at: null,
  };

  // 4. Pagination
  const page = body.page ?? 1;
  const limit = body.limit ?? 20;
  const skip = (page - 1) * limit;

  // 5. Sorting
  const allowedSortFields = ["last_update_at", "status", "created_at"];
  const sort_by = allowedSortFields.includes(body.sort_by ?? "")
    ? body.sort_by!
    : "last_update_at";
  const order: "asc" | "desc" = body.sort_order === "asc" ? "asc" : "desc";

  // 6. Query for paging data
  const [rows, total] = await Promise.all([
    MyGlobal.prisma.shopping_shipment_trackings.findMany({
      where: filter,
      orderBy: { [sort_by]: order },
      skip,
      take: limit,
    }),
    MyGlobal.prisma.shopping_shipment_trackings.count({ where: filter }),
  ]);

  // 7. Map to DTO
  const data: IShoppingShipmentTracking[] = rows.map((row) => ({
    id: row.id,
    shopping_shipment_package_id: row.shopping_shipment_package_id,
    tracking_source: row.tracking_source,
    external_tracking_id: row.external_tracking_id ?? undefined,
    status: row.status,
    status_detail: row.status_detail ?? undefined,
    last_update_at: toISOStringSafe(row.last_update_at),
    estimated_delivery_at: row.estimated_delivery_at
      ? toISOStringSafe(row.estimated_delivery_at)
      : undefined,
    created_at: toISOStringSafe(row.created_at),
    updated_at: toISOStringSafe(row.updated_at),
    deleted_at: row.deleted_at ? toISOStringSafe(row.deleted_at) : undefined,
  }));

  return {
    pagination: {
      current: Number(page),
      limit: Number(limit),
      records: total,
      pages: Math.ceil(total / limit),
    },
    data,
  };
}

import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/client";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";
import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

import { IShoppingAdmin } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingAdmin";
import { IShoppingAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingAuthorizationToken";

export async function postAuthAdminRefresh(props: {
  body: IShoppingAdmin.IRefresh;
}): Promise<IShoppingAdmin.IAuthorized> {
  let decoded: { id: string; session_id: string; type: string };
  try {
    const verified = jwt.verify(
      props.body.refresh_token,
      MyGlobal.env.JWT_SECRET_KEY,
      { issuer: "autobe" },
    );
    if (typeof verified === "string") {
      throw new HttpException("Invalid or expired refresh token", 401);
    }
    decoded = verified as { id: string; session_id: string; type: string };
  } catch (_) {
    throw new HttpException("Invalid or expired refresh token", 401);
  }

  // Check actor type
  if (decoded.type !== "admin") {
    throw new HttpException("Invalid token type for admin refresh", 403);
  }

  // Load session and admin
  const session = await MyGlobal.prisma.shopping_admin_sessions.findFirst({
    where: {
      id: decoded.session_id,
      shopping_admin_id: decoded.id,
    },
    include: {
      admin: true,
    },
  });
  if (!session) {
    throw new HttpException("Session expired or revoked", 401);
  }
  if (session.admin.deleted_at !== null) {
    throw new HttpException("Admin account is deleted", 403);
  }
  if (session.admin.status !== "active") {
    throw new HttpException("Admin account is not active", 403);
  }

  // Issue tokens
  const now = Date.now();
  const access_expires = now + 60 * 60 * 1000;
  const refresh_expires = now + 7 * 24 * 60 * 60 * 1000;
  const access = jwt.sign(
    {
      type: "admin",
      id: session.admin.id,
      session_id: session.id,
      created_at: toISOStringSafe(new Date()),
    },
    MyGlobal.env.JWT_SECRET_KEY,
    { expiresIn: "1h", issuer: "autobe" },
  );
  const refresh = jwt.sign(
    {
      type: "admin",
      id: session.admin.id,
      session_id: session.id,
      tokenType: "refresh",
      created_at: toISOStringSafe(new Date()),
    },
    MyGlobal.env.JWT_SECRET_KEY,
    { expiresIn: "7d", issuer: "autobe" },
  );

  // Update session expiry
  await MyGlobal.prisma.shopping_admin_sessions.update({
    where: { id: session.id },
    data: { expired_at: toISOStringSafe(new Date(refresh_expires)) },
  });

  // Response mapping (all date fields as string)
  return {
    id: session.admin.id,
    email: session.admin.email,
    name: session.admin.name,
    role: session.admin.role,
    status: session.admin.status,
    created_at: toISOStringSafe(session.admin.created_at),
    updated_at: toISOStringSafe(session.admin.updated_at),
    deleted_at:
      session.admin.deleted_at === null
        ? null
        : toISOStringSafe(session.admin.deleted_at),
    token: {
      access,
      refresh,
      expired_at: toISOStringSafe(new Date(access_expires)),
      refreshable_until: toISOStringSafe(new Date(refresh_expires)),
    },
  };
}

import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/client";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";
import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

import { IShoppingCustomer } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingCustomer";
import { IShoppingAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingAuthorizationToken";

export async function postAuthCustomerJoin(props: {
  body: IShoppingCustomer.ICreate;
}): Promise<IShoppingCustomer.IAuthorized> {
  // Step 1: Check for duplicate email or phone
  const dup = await MyGlobal.prisma.shopping_customers.findFirst({
    where: {
      OR: [{ email: props.body.email }, { phone: props.body.phone }],
    },
    select: { email: true, phone: true },
  });
  if (dup?.email === props.body.email)
    throw new HttpException("Email already registered.", 409);
  if (dup?.phone === props.body.phone)
    throw new HttpException("Phone already registered.", 409);

  // Step 2: Hash password
  const hashedPassword = await PasswordUtil.hash(props.body.password);

  // Step 3: Create customer
  const now = toISOStringSafe(new Date());
  const customerId = v4();
  const customer = await MyGlobal.prisma.shopping_customers.create({
    data: {
      id: customerId,
      email: props.body.email,
      password_hash: hashedPassword,
      name: props.body.name,
      phone: props.body.phone,
      is_active: true,
      created_at: now,
      updated_at: now,
    },
  });

  // Step 4: Create session
  const sessionId = v4();
  const accessExpires = new Date(Date.now() + 60 * 60 * 1000);
  const refreshExpires = new Date(Date.now() + 7 * 24 * 60 * 60 * 1000);
  const session = await MyGlobal.prisma.shopping_customer_sessions.create({
    data: {
      id: sessionId,
      shopping_customer_id: customerId,
      ip:
        props.body.ip === undefined || props.body.ip === null
          ? ""
          : props.body.ip,
      href: props.body.href,
      referrer: props.body.referrer,
      created_at: now,
      expired_at: toISOStringSafe(accessExpires),
    },
  });

  // Step 5: Generate JWT tokens
  const token = {
    access: jwt.sign(
      {
        type: "customer",
        id: customerId,
        session_id: sessionId,
        created_at: now,
      },
      MyGlobal.env.JWT_SECRET_KEY,
      { expiresIn: "1h", issuer: "autobe" },
    ),
    refresh: jwt.sign(
      {
        type: "customer",
        id: customerId,
        session_id: sessionId,
        tokenType: "refresh",
        created_at: now,
      },
      MyGlobal.env.JWT_SECRET_KEY,
      { expiresIn: "7d", issuer: "autobe" },
    ),
    expired_at: toISOStringSafe(accessExpires),
    refreshable_until: toISOStringSafe(refreshExpires),
  };

  // Step 6: Return authorized customer object
  return {
    id: customer.id,
    email: customer.email,
    name: customer.name,
    phone: customer.phone,
    is_active: customer.is_active,
    deleted_at: customer.deleted_at
      ? toISOStringSafe(customer.deleted_at)
      : null,
    created_at: toISOStringSafe(customer.created_at),
    updated_at: toISOStringSafe(customer.updated_at),
    token,
    role: "customer",
  };
}

