      created_at: now,
      updated_at: now,
      deleted_at: undefined,
    },
  });

  // 4. Return API DTO
  return {
    id: created.id,
    shopping_review_id: created.shopping_review_id,
    reporter_customer_id: created.reporter_customer_id,
    report_type: created.report_type,
