    id: created.id,
    sku: {
      id: sku.id,
      sku_code: sku.sku_code,
      price: sku.price,
      is_active: sku.is_active,
      status: sku.status,
    },
    added_at: toISOStringSafe(created.added_at),
    // note: undefined (optional)
  };
