import { IShoppingCustomer } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingCustomer";
import { IShoppingOrderLine } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingOrderLine";
import { IShoppingSku } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingSku";
import { IShoppingSeller } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingSeller";
import { IShoppingOrderLineFulfillment } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingOrderLineFulfillment";
import { IShoppingOrderSplit } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingOrderSplit";
import { IShoppingOrderStatusHistory } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingOrderStatusHistory";
import { IShoppingOrderPaymentAttempt } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingOrderPaymentAttempt";
import { IShoppingOrderShipment } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingOrderShipment";
import { AdminPayload } from "../decorators/payload/AdminPayload";

export async function putShoppingAdminOrdersOrderCode(props: {
  admin: AdminPayload;
  orderCode: string;
  body: IShoppingOrder.IUpdate;
}): Promise<IShoppingOrder> {
  const { admin, orderCode, body } = props;

  // 1. Find order by order_code
  const order = await MyGlobal.prisma.shopping_orders.findFirst({
    where: { order_code: orderCode, deleted_at: null },
  });
  if (!order) throw new HttpException("Order not found", 404);

  // 2. Mutable fields processing
  const now = toISOStringSafe(new Date());
  const orderUpdate: Record<string, unknown> = { updated_at: now };
  if (typeof body.status === "string") orderUpdate.status = body.status;
  await MyGlobal.prisma.shopping_orders.update({
    where: { id: order.id },
    data: orderUpdate,
  });

  // 3. Update shipping addresses if present
  if (body.shipping_addresses && Array.isArray(body.shipping_addresses)) {
    const existingAddresses =
      await MyGlobal.prisma.shopping_order_addresses.findMany({
        where: { shopping_order_id: order.id },
      });
    for (let i = 0; i < body.shipping_addresses.length; ++i) {
      const inputAddr = body.shipping_addresses[i];
      const existing = existingAddresses[i];
      if (existing) {
        await MyGlobal.prisma.shopping_order_addresses.update({
          where: { id: existing.id },
          data: {
            ...(typeof inputAddr.type === "string"
              ? { type: inputAddr.type }
              : {}),
            ...(typeof inputAddr.recipient_name === "string"
              ? { recipient_name: inputAddr.recipient_name }
              : {}),
            ...(typeof inputAddr.recipient_phone === "string"
              ? { recipient_phone: inputAddr.recipient_phone }
              : {}),
            ...(typeof inputAddr.zip_code === "string"
              ? { zip_code: inputAddr.zip_code }
              : {}),
            ...(typeof inputAddr.base_address === "string"
              ? { base_address: inputAddr.base_address }
              : {}),
            ...(typeof inputAddr.detail_address !== "undefined"
              ? { detail_address: inputAddr.detail_address }
              : {}),
            ...(typeof inputAddr.city === "string"
              ? { city: inputAddr.city }
              : {}),
            ...(typeof inputAddr.state_province === "string"
              ? { state_province: inputAddr.state_province }
              : {}),
            ...(typeof inputAddr.country === "string"
              ? { country: inputAddr.country }
              : {}),
            updated_at: now,
          },
        });
      } else {
        await MyGlobal.prisma.shopping_order_addresses.create({
          data: {
            id: v4(),
            shopping_order_id: order.id,
            type: inputAddr.type ?? "shipping",
            recipient_name: inputAddr.recipient_name ?? "",
            recipient_phone: inputAddr.recipient_phone ?? "",
            zip_code: inputAddr.zip_code ?? "",
            base_address: inputAddr.base_address ?? "",
            detail_address:
              typeof inputAddr.detail_address !== "undefined"
                ? inputAddr.detail_address
                : null,
            city: inputAddr.city ?? "",
            state_province: inputAddr.state_province ?? "",
            country: inputAddr.country ?? "",
            created_at: now,
            updated_at: now,
          },
        });
      }
    }
  }

  // 4. If order status changed, add status history
  if (typeof body.status === "string" && body.status !== order.status) {
    await MyGlobal.prisma.shopping_order_status_histories.create({
      data: {
        id: v4(),
        shopping_order_id: order.id,
        shopping_order_split_id: null,
        from_status: order.status,
        to_status: body.status,
        triggered_by: "admin",
        event_note: null,
        occurred_at: now,
      },
    });
  }

  // 5. Audit log
  await MyGlobal.prisma.shopping_audit_logs.create({
    data: {
      id: v4(),
      admin_id: admin.id,
      seller_id: null,
      customer_id: null,
      category: "order",
      event_type: "ORDER_UPDATE",
      ip: null,
      description: "Admin updated order via API",
      created_at: now,
      updated_at: now,
      deleted_at: null,
    },
  });

  // 6. Return full order with necessary joins
  // customer summary
  const customerRow =
    await MyGlobal.prisma.shopping_customers.findUniqueOrThrow({
      where: { id: order.shopping_customer_id },
    });
  const customer: IShoppingCustomer.ISummary = {
    id: customerRow.id,
    name: customerRow.name,
    email: customerRow.email,
    is_active: customerRow.is_active,
    created_at: toISOStringSafe(customerRow.created_at),
    deleted_at:
      customerRow.deleted_at === null
        ? null
        : toISOStringSafe(customerRow.deleted_at),
  };
  // addresses
  const addressesRows = await MyGlobal.prisma.shopping_order_addresses.findMany(
    {
      where: { shopping_order_id: order.id },
    },
  );
  const addresses: IShoppingOrderAddress[] = addressesRows.map((addr) => ({
    id: addr.id,
    shopping_order_id: addr.shopping_order_id,
    type: addr.type,
    recipient_name: addr.recipient_name,
    recipient_phone: addr.recipient_phone,
    zip_code: addr.zip_code,
    base_address: addr.base_address,
    detail_address:
      typeof addr.detail_address !== "undefined"
        ? addr.detail_address
        : undefined,
    city: addr.city,
    state_province: addr.state_province,
    country: addr.country,
    created_at: toISOStringSafe(addr.created_at),
    updated_at: toISOStringSafe(addr.updated_at),
  }));
  // order_lines
  const orderLinesRows = await MyGlobal.prisma.shopping_order_lines.findMany({
    where: { shopping_order_id: order.id },
  });
  const skus = await MyGlobal.prisma.shopping_skus.findMany({
    where: { id: { in: orderLinesRows.map((x) => x.shopping_sku_id) } },
  });
  const skusMap: Record<string, IShoppingSku.ISummary> = {};
  skus.forEach((sku) => {
    skusMap[sku.id] = {
      id: sku.id,
      sku_code: sku.sku_code,
      price: sku.price,
      is_active: sku.is_active,
      status: sku.status,
    };
  });
  const sellers = await MyGlobal.prisma.shopping_sellers.findMany({
    where: { id: { in: orderLinesRows.map((x) => x.shopping_seller_id) } },
  });
  const sellersMap: Record<string, IShoppingSeller.ISummary> = {};
  sellers.forEach((seller) => {
    sellersMap[seller.id] = {
      id: seller.id,
      display_name: seller.display_name,
      status: seller.status,
    };
  });
  // Fulfillments
  const orderLineIds = orderLinesRows.map((line) => line.id);
  const fulfillmentsRows =
    await MyGlobal.prisma.shopping_order_fulfillments.findMany({
      where: { shopping_order_line_id: { in: orderLineIds } },
    });
  const fulfillmentsPerLine: Record<
    string,
    IShoppingOrderLineFulfillment.ISummary[]
  > = {};
  fulfillmentsRows.forEach((f) => {
    const summary = {
      id: f.id,
      fulfillment_code: f.fulfillment_code,
      quantity_fulfilled: f.quantity_fulfilled,
      status: f.status,
      fulfilled_at: toISOStringSafe(f.fulfilled_at),
      seller_address_id: f.shopping_seller_address_id,
    };
    if (!fulfillmentsPerLine[f.shopping_order_line_id])
      fulfillmentsPerLine[f.shopping_order_line_id] = [];
    fulfillmentsPerLine[f.shopping_order_line_id].push(summary);
  });
  const order_lines: IShoppingOrderLine[] = orderLinesRows.map((line) => ({
    id: line.id,
    sku: skusMap[line.shopping_sku_id],
    quantity: line.quantity,
    unit_price: line.unit_price,
    status: line.status,
    seller: sellersMap[line.shopping_seller_id],
    fulfillments: fulfillmentsPerLine[line.id],
    created_at: toISOStringSafe(line.created_at),
    updated_at: toISOStringSafe(line.updated_at),
    deleted_at:
      line.deleted_at === null ? null : toISOStringSafe(line.deleted_at),
  }));
  // splits
  const splitsRows = await MyGlobal.prisma.shopping_order_splits.findMany({
    where: { shopping_order_id: order.id },
  });
  const splitSellers = await MyGlobal.prisma.shopping_sellers.findMany({
    where: { id: { in: splitsRows.map((x) => x.shopping_seller_id) } },
  });
  const splitSellersMap: Record<string, IShoppingSeller.ISummary> = {};
  splitSellers.forEach((s) => {
    splitSellersMap[s.id] = {
      id: s.id,
      display_name: s.display_name,
      status: s.status,
    };
  });
  const order_splits: IShoppingOrderSplit[] = splitsRows.map((split) => ({
    id: split.id,
    split_code: split.split_code,
    subtotal_price: split.subtotal_price,
    status: split.status,
    created_at: toISOStringSafe(split.created_at),
    updated_at: split.updated_at
      ? toISOStringSafe(split.updated_at)
      : undefined,
    order_id: split.shopping_order_id,
    seller: splitSellersMap[split.shopping_seller_id],
  }));
  // status_history
  const statusHistRows =
    await MyGlobal.prisma.shopping_order_status_histories.findMany({
      where: { shopping_order_id: order.id },
    });
  const status_history: IShoppingOrderStatusHistory[] = statusHistRows.map(
    (sh) => ({
      id: sh.id,
      shopping_order_id: sh.shopping_order_id,
      shopping_order_split_id: sh.shopping_order_split_id ?? undefined,
      from_status: sh.from_status,
      to_status: sh.to_status,
      triggered_by: sh.triggered_by,
      event_note: sh.event_note ?? undefined,
      occurred_at: toISOStringSafe(sh.occurred_at),
    }),
  );
  // payment_attempts
  const paymentRows = await MyGlobal.prisma.shopping_payment_attempts.findMany({
    where: { shopping_order_id: order.id },
  });
  const payment_attempts: IShoppingOrderPaymentAttempt[] = paymentRows.map(
    (pa) => ({
      id: pa.id,
      payment_reference: pa.payment_reference ?? undefined,
      attempt_status: typia.assert<
        "pending" | "completed" | "failed" | "cancelled"
      >(pa.attempt_status),
      amount: pa.amount,
      attempted_at: toISOStringSafe(pa.attempted_at),
      completed_at: pa.completed_at
        ? toISOStringSafe(pa.completed_at)
        : undefined,
    }),
  );
  // shipments
  const shipmentsRows = await MyGlobal.prisma.shopping_shipments.findMany({
    where: { shopping_order_id: order.id },
  });
  const shipmentSellers = await MyGlobal.prisma.shopping_sellers.findMany({
    where: { id: { in: shipmentsRows.map((shr) => shr.shopping_seller_id) } },
  });
  const shipmentSellersMap: Record<string, IShoppingSeller.ISummary> = {};
  shipmentSellers.forEach((ss) => {
    shipmentSellersMap[ss.id] = {
      id: ss.id,
      display_name: ss.display_name,
      status: ss.status,
    };
  });
  const shipments: IShoppingOrderShipment[] = shipmentsRows.map((s) => ({
    id: s.id,
    seller: shipmentSellersMap[s.shopping_seller_id],
    code: s.code,
    status: s.status,
    carrier_company: s.carrier_company,
    scheduled_dispatch_at: s.scheduled_dispatch_at
      ? toISOStringSafe(s.scheduled_dispatch_at)
      : undefined,
    dispatched_at: s.dispatched_at
      ? toISOStringSafe(s.dispatched_at)
      : undefined,
    delivered_at: s.delivered_at ? toISOStringSafe(s.delivered_at) : undefined,
    canceled_at: s.canceled_at ? toISOStringSafe(s.canceled_at) : undefined,
    created_at: toISOStringSafe(s.created_at),
    updated_at: toISOStringSafe(s.updated_at),
  }));
  return {
    id: order.id,
    order_code: order.order_code,
    total_price: order.total_price,
    status: body.status ?? order.status,
    created_at: toISOStringSafe(order.created_at),
    updated_at: now,
    deleted_at:
      order.deleted_at === null ? null : toISOStringSafe(order.deleted_at),
    customer,
    order_lines,
    order_splits,
    addresses,
    status_history,
    payment_attempts,
    shipments,
  };
}

import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/client";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";
import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

import { IShoppingPasswordReset } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingPasswordReset";
import { CustomerPayload } from "../decorators/payload/CustomerPayload";

export async function putShoppingCustomerPasswordResetsPasswordResetId(props: {
  customer: CustomerPayload;
  passwordResetId: string & tags.Format<"uuid">;
  body: IShoppingPasswordReset.IUpdate;
}): Promise<IShoppingPasswordReset> {
  const { customer, passwordResetId, body } = props;

  // Step 1: Fetch reset request
  const reset = await MyGlobal.prisma.shopping_password_resets.findUnique({
    where: { id: passwordResetId },
  });
  if (reset === null) {
    throw new HttpException("Password reset request not found", 404);
  }

  // Step 2: Authorization
  if (reset.shopping_customer_id !== customer.id) {
    throw new HttpException(
      "You are not authorized to update this password reset request",
      403,
    );
  }

  // Step 3: Business validation
  const nowISOString = toISOStringSafe(new Date());
  if (reset.consumed_at !== null) {
    throw new HttpException(
      "Cannot update an already consumed reset request",
      400,
    );
  }
  if (toISOStringSafe(reset.expires_at) < nowISOString) {
    throw new HttpException(
      "Cannot update an already expired reset request",
      400,
    );
  }

  // Step 4: Update expire/consumed fields
  const updated = await MyGlobal.prisma.shopping_password_resets.update({
    where: { id: passwordResetId },
    data: {
      expires_at: body.expires_at,
      consumed_at: body.consumed_at ?? undefined,
      updated_at: nowISOString,
    },
  });

  // Step 5: Response object
  return {
    id: updated.id,
    shopping_customer_id: updated.shopping_customer_id ?? undefined,
    shopping_seller_id: updated.shopping_seller_id ?? undefined,
    shopping_admin_id: updated.shopping_admin_id ?? undefined,
    request_email: updated.request_email,
    reset_code: updated.reset_code,
    expires_at: toISOStringSafe(updated.expires_at),
    consumed_at: updated.consumed_at
      ? toISOStringSafe(updated.consumed_at)
      : undefined,
    created_at: toISOStringSafe(updated.created_at),
    updated_at: toISOStringSafe(updated.updated_at),
  };
}

import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/client";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";
import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

import { IShoppingRefundRequest } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingRefundRequest";
import { IShoppingOrder } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingOrder";
import { IShoppingCustomer } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingCustomer";
import { IShoppingRefundActor } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingRefundActor";
import { IShoppingRefundRequestItem } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingRefundRequestItem";
import { IShoppingRefundAttachment } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingRefundAttachment";
import { IShoppingRefundStatusHistory } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingRefundStatusHistory";
import { IShoppingRefundApproval } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingRefundApproval";
import { IShoppingRefundAdminOverride } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingRefundAdminOverride";
import { CustomerPayload } from "../decorators/payload/CustomerPayload";

export async function putShoppingCustomerRefundsRefundRequestId(props: {
  customer: CustomerPayload;
  refundRequestId: string & tags.Format<"uuid">;
  body: IShoppingRefundRequest.IUpdate;
}): Promise<IShoppingRefundRequest> {
  // Fetch and verify refund ownership, editable status, and existence
  const refund = await MyGlobal.prisma.shopping_refund_requests.findFirst({
    where: {
      id: props.refundRequestId,
      deleted_at: null,
      actor_type: "customer",
      shopping_actor_id: props.customer.id,
    },
    include: {
      order: true,
    },
  });
  if (!refund) {
    throw new HttpException(
      "Refund request not found, does not belong to you, or already deleted",
      404,
    );
  }
  const finalizedStatuses = ["approved", "completed", "declined"];
  if (finalizedStatuses.includes(refund.status)) {
    throw new HttpException(
      "Cannot update refund/cancellation request once finalized.",
      400,
    );
  }

  // Update updatable fields only
  const updated = await MyGlobal.prisma.shopping_refund_requests.update({
    where: { id: props.refundRequestId },
    data: {
      business_reason: props.body.business_reason ?? undefined,
      status: props.body.status ?? undefined,
      request_context: props.body.request_context ?? undefined,
      updated_at: toISOStringSafe(new Date()),
    },
    include: {
      order: true,
    },
  });

  // Retrieve all relation data needed for the DTO
  const [
    customerRec,
    items,
    attachments,
    statusHistories,
    approvals,
    adminOverrides,
  ] = await Promise.all([
    MyGlobal.prisma.shopping_customers.findUniqueOrThrow({
      where: { id: updated.shopping_actor_id },
    }),
    MyGlobal.prisma.shopping_refund_request_items.findMany({
      where: { shopping_refund_request_id: updated.id },
    }),
    MyGlobal.prisma.shopping_refund_attachments.findMany({
      where: { shopping_refund_request_id: updated.id },
    }),
    MyGlobal.prisma.shopping_refund_status_histories.findMany({
      where: { shopping_refund_request_id: updated.id },
    }),
    MyGlobal.prisma.shopping_refund_approvals.findMany({
      where: { shopping_refund_request_id: updated.id },
    }),
    MyGlobal.prisma.shopping_refund_admin_overrides.findMany({
      where: { shopping_refund_request_id: updated.id },
    }),
  ]);

  // Compose order summary
  const orderSummary = {
    id: updated.order.id,
    order_code: updated.order.order_code,
    total_price: updated.order.total_price,
    status: updated.order.status,
    created_at: toISOStringSafe(updated.order.created_at),
    updated_at: toISOStringSafe(updated.order.updated_at),
    customer: {
      id: customerRec.id,
      name: customerRec.name,
      email: customerRec.email,
      is_active: customerRec.is_active,
      created_at: toISOStringSafe(customerRec.created_at),
      deleted_at: customerRec.deleted_at
        ? toISOStringSafe(customerRec.deleted_at)
        : null,
    },
  };

  // Compose actor summary
  const actorSummary = {
    actor_type: typia.assert<"customer" | "seller" | "admin">("customer"),
    id: customerRec.id,
    name: customerRec.name,
  };

  // Map refund items array (with inline attachments per item)
  const itemsArr = items.map((item) => {
    const itemAttachments = attachments
      .filter((att) => att.shopping_refund_request_item_id === item.id)
      .map((att) => ({
        id: att.id,
        shopping_refund_request_id: att.shopping_refund_request_id,
        shopping_refund_request_item_id:
          att.shopping_refund_request_item_id ?? undefined,
        attachment_file_id: att.attachment_file_id,
        attachment_type: att.attachment_type,
        description: att.description ?? undefined,
        uploaded_at: toISOStringSafe(att.uploaded_at),
        file_uri: "", // details unavailable, must be patched externally
        file_type: "",
        file_size: 0,
      }));
    return {
      id: item.id,
      shopping_refund_request_id: item.shopping_refund_request_id,
      shopping_order_id: item.shopping_order_id,
      shopping_order_line_id: item.shopping_order_line_id,
      quantity: item.quantity,
      item_business_reason: item.item_business_reason ?? undefined,
      created_at: toISOStringSafe(item.created_at),
      updated_at: toISOStringSafe(item.updated_at),
      attachments: itemAttachments.length > 0 ? itemAttachments : undefined,
    };
  });

  // Top-level (non-item) attachments
  const topLevelAttachments = attachments
    .filter((att) => att.shopping_refund_request_item_id == null)
    .map((att) => ({
      id: att.id,
      shopping_refund_request_id: att.shopping_refund_request_id,
      shopping_refund_request_item_id:
        att.shopping_refund_request_item_id ?? undefined,
      attachment_file_id: att.attachment_file_id,
      attachment_type: att.attachment_type,
      description: att.description ?? undefined,
      uploaded_at: toISOStringSafe(att.uploaded_at),
      file_uri: "",
      file_type: "",
      file_size: 0,
    }));

  // Status histories
  const statusHistoriesArr = statusHistories.map((h) => ({
    id: h.id,
    shopping_refund_request_id: h.shopping_refund_request_id,
    shopping_actor_id: h.shopping_actor_id,
    actor_type: typia.assert<"customer" | "seller" | "admin">(h.actor_type),
    previous_status: h.previous_status,
    new_status: h.new_status,
    timestamp: toISOStringSafe(h.timestamp),
    change_context: h.change_context ?? undefined,
  }));

  // Approvals
  const approvalsArr = approvals.map((a) => ({
    id: a.id,
    shopping_refund_request_id: a.shopping_refund_request_id,
    shopping_refund_status_history_id: a.shopping_refund_status_history_id,
    actor_type: typia.assert<"customer" | "seller" | "admin">(a.actor_type),
    actor_id: a.shopping_actor_id,
    action: a.action,
    note: a.note ?? undefined,
    created_at: toISOStringSafe(a.created_at),
  }));

  // Admin overrides
  const adminOverridesArr = adminOverrides.map((ao) => ({
    id: ao.id,
    shopping_refund_request_id: ao.shopping_refund_request_id,
    shopping_admin_id: ao.shopping_admin_id,
    override_type: ao.override_type,
    reason: ao.reason,
    detailed_context: ao.detailed_context ?? undefined,
    created_at: toISOStringSafe(ao.created_at),
  }));

  return {
    id: updated.id,
    order: orderSummary,
    actor: actorSummary,
    request_type: typia.assert<"refund" | "return" | "cancellation">(
      updated.request_type,
    ),
    business_reason: updated.business_reason,
    request_context: updated.request_context ?? undefined,
    status: updated.status,
    created_at: toISOStringSafe(updated.created_at),
    updated_at: toISOStringSafe(updated.updated_at),
    deleted_at: updated.deleted_at
      ? toISOStringSafe(updated.deleted_at)
      : undefined,
    items: itemsArr,
    attachments: topLevelAttachments,
    status_histories: statusHistoriesArr,
    approvals: approvalsArr,
    admin_overrides: adminOverridesArr,
  };
}

import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/client";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";
import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

import { IShoppingPasswordReset } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingPasswordReset";
import { SellerPayload } from "../decorators/payload/SellerPayload";

export async function putShoppingSellerPasswordResetsPasswordResetId(props: {
  seller: SellerPayload;
  passwordResetId: string & tags.Format<"uuid">;
  body: IShoppingPasswordReset.IUpdate;
}): Promise<IShoppingPasswordReset> {
  // Fetch the password reset record belonging to this seller
  const record = await MyGlobal.prisma.shopping_password_resets.findUnique({
    where: { id: props.passwordResetId },
  });
  if (!record || record.shopping_seller_id !== props.seller.id) {
    throw new HttpException(
      "Password reset not found or you do not have permission.",
      404,
    );
  }
  // Disallow updates if expired or already consumed
  const now = toISOStringSafe(new Date());
  if (toISOStringSafe(record.expires_at) < now) {
    throw new HttpException("Cannot update expired password reset.", 400);
  }
  if (record.consumed_at) {
    throw new HttpException(
      "Cannot update an already consumed password reset.",
      400,
    );
  }
  // Update fields
  const updated = await MyGlobal.prisma.shopping_password_resets.update({
    where: { id: props.passwordResetId },
    data: {
      expires_at: props.body.expires_at,
      consumed_at: props.body.consumed_at ?? undefined,
      updated_at: now,
    },
  });
  return {
    id: updated.id,
    shopping_customer_id: updated.shopping_customer_id ?? undefined,
    shopping_seller_id: updated.shopping_seller_id ?? undefined,
    shopping_admin_id: updated.shopping_admin_id ?? undefined,
    request_email: updated.request_email,
    reset_code: updated.reset_code,
    expires_at: toISOStringSafe(updated.expires_at),
    consumed_at: updated.consumed_at
      ? toISOStringSafe(updated.consumed_at)
      : undefined,
    created_at: toISOStringSafe(updated.created_at),
    updated_at: toISOStringSafe(updated.updated_at),
  };
}

import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/client";
