import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/client";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";
import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

import { IShoppingOrder } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingOrder";
import { IShoppingCustomer } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingCustomer";
import { IShoppingOrderLine } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingOrderLine";
import { IShoppingSku } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingSku";
import { IShoppingSeller } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingSeller";
import { IShoppingOrderLineFulfillment } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingOrderLineFulfillment";
import { IShoppingOrderSplit } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingOrderSplit";
import { IShoppingOrderStatusHistory } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingOrderStatusHistory";
import { IShoppingOrderAddress } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingOrderAddress";
import { IShoppingOrderPaymentAttempt } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingOrderPaymentAttempt";
import { IShoppingOrderShipment } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingOrderShipment";
import { AdminPayload } from "../decorators/payload/AdminPayload";

export async function getShoppingAdminOrdersOrderCode(props: {
  admin: AdminPayload;
  orderCode: string;
}): Promise<IShoppingOrder> {
  const { orderCode } = props;

  const order = await MyGlobal.prisma.shopping_orders.findUnique({
    where: { order_code: orderCode },
  });
  if (!order) throw new HttpException("Order not found", 404);

  const [
    customer,
    order_lines,
    splits,
    addresses,
    status_histories,
    payment_attempts,
    shipments,
  ] = await Promise.all([
    MyGlobal.prisma.shopping_customers.findUnique({
      where: { id: order.shopping_customer_id },
    }),
    MyGlobal.prisma.shopping_order_lines.findMany({
      where: { shopping_order_id: order.id },
    }),
    MyGlobal.prisma.shopping_order_splits.findMany({
      where: { shopping_order_id: order.id },
    }),
    MyGlobal.prisma.shopping_order_addresses.findMany({
      where: { shopping_order_id: order.id },
    }),
    MyGlobal.prisma.shopping_order_status_histories.findMany({
      where: { shopping_order_id: order.id },
    }),
    MyGlobal.prisma.shopping_payment_attempts.findMany({
      where: { shopping_order_id: order.id },
    }),
    MyGlobal.prisma.shopping_shipments.findMany({
      where: { shopping_order_id: order.id },
    }),
  ]);

  const customerSummary: IShoppingCustomer.ISummary = {
    id: customer!.id,
    name: customer!.name,
    email: customer!.email,
    is_active: customer!.is_active,
    created_at: toISOStringSafe(customer!.created_at),
    deleted_at: customer!.deleted_at
      ? toISOStringSafe(customer!.deleted_at)
      : null,
  };

  const skuIds = order_lines.map(
    (l: (typeof order_lines)[number]) => l.shopping_sku_id,
  );
  const sellerIds = order_lines.map(
    (l: (typeof order_lines)[number]) => l.shopping_seller_id,
  );
  const [skus, sellers] = await Promise.all([
    MyGlobal.prisma.shopping_skus.findMany({ where: { id: { in: skuIds } } }),
    MyGlobal.prisma.shopping_sellers.findMany({
      where: { id: { in: sellerIds } },
    }),
  ]);
  const fulFillmentsByLine = await Promise.all(
    order_lines.map((l: (typeof order_lines)[number]) =>
      MyGlobal.prisma.shopping_order_fulfillments.findMany({
        where: { shopping_order_line_id: l.id },
      }),
    ),
  );

  const orderLines: IShoppingOrderLine[] = order_lines.map(
    (line: (typeof order_lines)[number], i: number) => {
      const sku = skus.find((s) => s.id === line.shopping_sku_id)!;
      const seller = sellers.find((s) => s.id === line.shopping_seller_id)!;
      const fulfillments = fulFillmentsByLine[i].map(
        (f: (typeof fulFillmentsByLine)[number][number]) => ({
          id: f.id,
          fulfillment_code: f.fulfillment_code,
          quantity_fulfilled: f.quantity_fulfilled,
          status: f.status,
          fulfilled_at: toISOStringSafe(f.fulfilled_at),
          seller_address_id: f.shopping_seller_address_id,
        }),
      );
      return {
        id: line.id,
        sku: {
          id: sku.id,
          sku_code: sku.sku_code,
          price: sku.price,
          is_active: sku.is_active,
          status: sku.status,
        },
        quantity: line.quantity,
        unit_price: line.unit_price,
        status: line.status,
        seller: {
          id: seller.id,
          display_name: seller.display_name,
          status: seller.status,
        },
        fulfillments: fulfillments.length > 0 ? fulfillments : undefined,
        created_at: toISOStringSafe(line.created_at),
        updated_at: toISOStringSafe(line.updated_at),
        deleted_at: line.deleted_at
          ? toISOStringSafe(line.deleted_at)
          : undefined,
      };
    },
  );

  const splitSellerIds = splits.map(
    (s: (typeof splits)[number]) => s.shopping_seller_id,
  );
  const splitSellers = await MyGlobal.prisma.shopping_sellers.findMany({
    where: { id: { in: splitSellerIds } },
  });
  const splitStatusHistories = await Promise.all(
    splits.map((s: (typeof splits)[number]) =>
      MyGlobal.prisma.shopping_order_status_histories.findMany({
        where: { shopping_order_split_id: s.id },
      }),
    ),
  );
  const orderSplits: IShoppingOrderSplit[] = splits.map(
    (split: (typeof splits)[number], i: number) => {
      const seller = splitSellers.find(
        (s) => s.id === split.shopping_seller_id,
      )!;
      const statusHistories = splitStatusHistories[i].map(
        (history: (typeof splitStatusHistories)[number][number]) => ({
          id: history.id,
          from_status: history.from_status,
          to_status: history.to_status,
          triggered_by: history.triggered_by,
          event_note: history.event_note ?? undefined,
          occurred_at: toISOStringSafe(history.occurred_at),
        }),
      );
      return {
        id: split.id,
        split_code: split.split_code,
        subtotal_price: split.subtotal_price,
        status: split.status,
        created_at: toISOStringSafe(split.created_at),
        updated_at: split.updated_at
          ? toISOStringSafe(split.updated_at)
          : undefined,
        order_id: split.shopping_order_id,
        seller: {
          id: seller.id,
          display_name: seller.display_name,
          status: seller.status,
        },
        order_status_histories:
          statusHistories.length > 0 ? statusHistories : undefined,
      };
    },
  );

  const orderAddresses: IShoppingOrderAddress[] = addresses.map(
    (address: (typeof addresses)[number]) => ({
      id: address.id,
      shopping_order_id: address.shopping_order_id,
      type: address.type,
      recipient_name: address.recipient_name,
      recipient_phone: address.recipient_phone,
      zip_code: address.zip_code,
      base_address: address.base_address,
      detail_address: address.detail_address ?? undefined,
      city: address.city,
      state_province: address.state_province,
      country: address.country,
      created_at: toISOStringSafe(address.created_at),
      updated_at: toISOStringSafe(address.updated_at),
    }),
  );

  const orderStatusHistory: IShoppingOrderStatusHistory[] =
    status_histories.map((history: (typeof status_histories)[number]) => ({
      id: history.id,
      shopping_order_id: history.shopping_order_id,
      shopping_order_split_id: history.shopping_order_split_id ?? undefined,
      from_status: history.from_status,
      to_status: history.to_status,
      triggered_by: history.triggered_by,
      event_note: history.event_note ?? undefined,
      occurred_at: toISOStringSafe(history.occurred_at),
    }));

  const orderPaymentAttempts: IShoppingOrderPaymentAttempt[] =
    payment_attempts.map((attempt: (typeof payment_attempts)[number]) => ({
      id: attempt.id,
      payment_reference: attempt.payment_reference ?? undefined,
      attempt_status: attempt.attempt_status as
        | "pending"
        | "completed"
        | "failed"
        | "cancelled",
      amount: attempt.amount,
      attempted_at: toISOStringSafe(attempt.attempted_at),
      completed_at: attempt.completed_at
        ? toISOStringSafe(attempt.completed_at)
        : undefined,
    }));

  const shipmentSellerIds = shipments.map(
    (s: (typeof shipments)[number]) => s.shopping_seller_id,
  );
  const shipmentSellers = await MyGlobal.prisma.shopping_sellers.findMany({
    where: { id: { in: shipmentSellerIds } },
  });
  const orderShipments: IShoppingOrderShipment[] = shipments.map(
    (shipment: (typeof shipments)[number]) => {
      const seller = shipmentSellers.find(
        (s) => s.id === shipment.shopping_seller_id,
      )!;
      return {
        id: shipment.id,
        seller: {
          id: seller.id,
          display_name: seller.display_name,
          status: seller.status,
        },
        code: shipment.code,
        status: shipment.status,
        carrier_company: shipment.carrier_company,
        scheduled_dispatch_at: shipment.scheduled_dispatch_at
          ? toISOStringSafe(shipment.scheduled_dispatch_at)
          : undefined,
        dispatched_at: shipment.dispatched_at
          ? toISOStringSafe(shipment.dispatched_at)
          : undefined,
        delivered_at: shipment.delivered_at
          ? toISOStringSafe(shipment.delivered_at)
          : undefined,
        canceled_at: shipment.canceled_at
          ? toISOStringSafe(shipment.canceled_at)
          : undefined,
        created_at: toISOStringSafe(shipment.created_at),
        updated_at: toISOStringSafe(shipment.updated_at),
      };
    },
  );

  return {
    id: order.id,
    order_code: order.order_code,
    total_price: order.total_price,
    status: order.status,
    created_at: toISOStringSafe(order.created_at),
    updated_at: toISOStringSafe(order.updated_at),
    deleted_at: order.deleted_at
      ? toISOStringSafe(order.deleted_at)
      : undefined,
    customer: customerSummary,
    order_lines: orderLines,
    order_splits: orderSplits,
    addresses: orderAddresses,
    status_history: orderStatusHistory,
    payment_attempts: orderPaymentAttempts,
    shipments: orderShipments,
  };
}

import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/client";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";
import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

import { IShoppingOrderFulfillment } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingOrderFulfillment";
import { AdminPayload } from "../decorators/payload/AdminPayload";

export async function getShoppingAdminOrdersOrderCodeFulfillmentsFulfillmentCode(props: {
  admin: AdminPayload;
  orderCode: string;
  fulfillmentCode: string;
}): Promise<IShoppingOrderFulfillment> {
  // Step 1: Find order by code, ensure not soft-deleted
  const order = await MyGlobal.prisma.shopping_orders.findFirst({
    where: {
      order_code: props.orderCode,
      deleted_at: null,
    },
    select: { id: true },
  });
  if (!order) throw new HttpException("Order not found", 404);

  // Step 2: Find order lines for the order
  const orderLines = await MyGlobal.prisma.shopping_order_lines.findMany({
    where: { shopping_order_id: order.id },
    select: { id: true },
  });
  const orderLineIds = orderLines.map((l) => l.id);

  if (orderLineIds.length === 0)
    throw new HttpException("No fulfillments for this order", 404);

  // Step 3: Find the fulfillment for the order by fulfillment_code and order_line_id
  const fulfillment =
    await MyGlobal.prisma.shopping_order_fulfillments.findFirst({
      where: {
        fulfillment_code: props.fulfillmentCode,
        shopping_order_line_id: { in: orderLineIds },
      },
      select: {
        id: true,
        shopping_order_line_id: true,
        shopping_seller_id: true,
        shopping_seller_address_id: true,
        fulfillment_code: true,
        quantity_fulfilled: true,
        fulfilled_at: true,
        status: true,
        note: true,
        created_at: true,
        updated_at: true,
      },
    });
  if (!fulfillment)
    throw new HttpException("Fulfillment not found for this order", 404);

  return {
    id: fulfillment.id,
    shopping_order_line_id: fulfillment.shopping_order_line_id,
    shopping_seller_id: fulfillment.shopping_seller_id,
    shopping_seller_address_id: fulfillment.shopping_seller_address_id,
    fulfillment_code: fulfillment.fulfillment_code,
    quantity_fulfilled: fulfillment.quantity_fulfilled,
    fulfilled_at: toISOStringSafe(fulfillment.fulfilled_at),
    status: fulfillment.status,
    note: fulfillment.note ?? undefined,
    created_at: toISOStringSafe(fulfillment.created_at),
    updated_at: toISOStringSafe(fulfillment.updated_at),
  };
}

import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/client";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";
import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

import { IShoppingOrderLine } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingOrderLine";
import { IShoppingSku } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingSku";
import { IShoppingSeller } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingSeller";
import { IShoppingOrderLineFulfillment } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingOrderLineFulfillment";
import { AdminPayload } from "../decorators/payload/AdminPayload";

export async function getShoppingAdminOrdersOrderCodeLinesOrderLineId(props: {
  admin: AdminPayload;
  orderCode: string;
  orderLineId: string & tags.Format<"uuid">;
}): Promise<IShoppingOrderLine> {
  // 1. Lookup order by orderCode
  const order = await MyGlobal.prisma.shopping_orders.findUnique({
    where: { order_code: props.orderCode },
    select: { id: true },
  });
  if (!order) throw new HttpException("Order not found", 404);

  // 2. Lookup order line without relations
  const orderLine = await MyGlobal.prisma.shopping_order_lines.findUnique({
    where: { id: props.orderLineId },
  });
  if (!orderLine || orderLine.shopping_order_id !== order.id) {
    throw new HttpException("Order line not found for this order", 404);
  }

  // 3. Fetch SKU info
  const sku = await MyGlobal.prisma.shopping_skus.findUnique({
    where: { id: orderLine.shopping_sku_id },
    select: {
      id: true,
      sku_code: true,
      price: true,
      is_active: true,
      status: true,
    },
  });
  if (!sku) throw new HttpException("SKU not found for order line", 404);

  // 4. Fetch Seller info
  const seller = await MyGlobal.prisma.shopping_sellers.findUnique({
    where: { id: orderLine.shopping_seller_id },
    select: {
      id: true,
      display_name: true,
      status: true,
    },
  });
  if (!seller) throw new HttpException("Seller not found for order line", 404);

  // 5. Fetch fulfillments
  const fulfillments =
    await MyGlobal.prisma.shopping_order_fulfillments.findMany({
      where: { shopping_order_line_id: orderLine.id },
      select: {
        id: true,
        fulfillment_code: true,
        quantity_fulfilled: true,
        status: true,
        fulfilled_at: true,
        shopping_seller_address_id: true,
      },
      orderBy: { fulfilled_at: "asc" },
    });

  return {
    id: orderLine.id as string & tags.Format<"uuid">,
    sku: {
      id: sku.id as string & tags.Format<"uuid">,
      sku_code: sku.sku_code,
      price: sku.price,
      is_active: sku.is_active,
      status: sku.status,
    },
    quantity: orderLine.quantity as number &
      tags.Type<"int32"> &
      tags.Minimum<1>,
    unit_price: orderLine.unit_price,
    status: orderLine.status,
    seller: {
      id: seller.id as string & tags.Format<"uuid">,
      display_name: seller.display_name,
      status: seller.status,
    },
    fulfillments:
      fulfillments.length > 0
        ? fulfillments.map(
            (f): IShoppingOrderLineFulfillment.ISummary => ({
              id: f.id as string & tags.Format<"uuid">,
              fulfillment_code: f.fulfillment_code,
              quantity_fulfilled: f.quantity_fulfilled as number &
                tags.Type<"int32">,
              status: f.status,
              fulfilled_at: toISOStringSafe(f.fulfilled_at),
              seller_address_id: f.shopping_seller_address_id as string &
                tags.Format<"uuid">,
            }),
          )
        : undefined,
    created_at: toISOStringSafe(orderLine.created_at),
    updated_at: toISOStringSafe(orderLine.updated_at),
    deleted_at:
      orderLine.deleted_at !== null && orderLine.deleted_at !== undefined
        ? toISOStringSafe(orderLine.deleted_at)
        : undefined,
  };
}

import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/client";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";
import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

import { IShoppingRefundRequest } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingRefundRequest";
import { IShoppingOrder } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingOrder";
import { IShoppingCustomer } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingCustomer";
import { IShoppingRefundActor } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingRefundActor";
import { IShoppingRefundRequestItem } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingRefundRequestItem";
import { IShoppingRefundAttachment } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingRefundAttachment";
import { IShoppingRefundStatusHistory } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingRefundStatusHistory";
import { IShoppingRefundApproval } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingRefundApproval";
import { IShoppingRefundAdminOverride } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingRefundAdminOverride";
import { AdminPayload } from "../decorators/payload/AdminPayload";

export async function getShoppingAdminRefundsRefundRequestId(props: {
  admin: AdminPayload;
  refundRequestId: string & tags.Format<"uuid">;
}): Promise<IShoppingRefundRequest> {
  const refund = await MyGlobal.prisma.shopping_refund_requests.findFirst({
    where: { id: props.refundRequestId, deleted_at: null },
    include: {
      order: { include: { customer: true } },
    },
  });
  if (!refund) throw new HttpException("Refund request not found", 404);

  const [
    items,
    dbAttachments,
    dbAttachmentMetas,
    statusHistories,
    approvals,
    adminOverrides,
  ] = await Promise.all([
    MyGlobal.prisma.shopping_refund_request_items.findMany({
      where: { shopping_refund_request_id: refund.id },
      orderBy: { created_at: "asc" },
    }),
    MyGlobal.prisma.shopping_refund_attachments.findMany({
      where: { shopping_refund_request_id: refund.id },
      orderBy: { uploaded_at: "asc" },
    }),
    MyGlobal.prisma.shopping_product_images.findMany({
      where: {
        id: {
          in: (
            await MyGlobal.prisma.shopping_refund_attachments.findMany({
              where: { shopping_refund_request_id: refund.id },
              select: { attachment_file_id: true },
            })
          ).map((a) => a.attachment_file_id),
        },
      },
    }),
    MyGlobal.prisma.shopping_refund_status_histories.findMany({
      where: { shopping_refund_request_id: refund.id },
      orderBy: { timestamp: "asc" },
    }),
    MyGlobal.prisma.shopping_refund_approvals.findMany({
      where: { shopping_refund_request_id: refund.id },
      orderBy: { created_at: "asc" },
    }),
    MyGlobal.prisma.shopping_refund_admin_overrides.findMany({
      where: { shopping_refund_request_id: refund.id },
      orderBy: { created_at: "asc" },
    }),
  ]);

  // Map meta file info for attachments
  const imageMap = new Map(dbAttachmentMetas.map((img) => [img.id, img]));
  const resolveAttachmentMeta = (a: any) => {
    const meta = imageMap.get(a.attachment_file_id);
    return {
      id: a.id,
      shopping_refund_request_id: a.shopping_refund_request_id,
      shopping_refund_request_item_id:
        a.shopping_refund_request_item_id ?? undefined,
      attachment_file_id: a.attachment_file_id,
      attachment_type: a.attachment_type,
      description: a.description ?? undefined,
      uploaded_at: toISOStringSafe(a.uploaded_at),
      file_uri: meta ? meta.image_uri : "",
      file_type: meta ? "image/jpeg" : "image/jpeg",
      file_size: 0,
    } satisfies IShoppingRefundAttachment;
  };

  // Attachments per item
  const attachmentsByItem = new Map<string, IShoppingRefundAttachment[]>();
  const allAttachments = dbAttachments.map(resolveAttachmentMeta);
  for (const att of allAttachments) {
    const key = att.shopping_refund_request_item_id ?? "";
    if (!attachmentsByItem.has(key)) attachmentsByItem.set(key, []);
    attachmentsByItem.get(key)!.push(att);
  }

  // Actor summary with type guard
  let actor: IShoppingRefundActor.ISummary;
  if (refund.actor_type === "customer") {
    const customer = await MyGlobal.prisma.shopping_customers.findUnique({
      where: { id: refund.shopping_actor_id },
    });
    if (!customer)
      throw new HttpException("Refund actor (customer) not found", 404);
    actor = { actor_type: "customer", id: customer.id, name: customer.name };
  } else if (refund.actor_type === "seller") {
    const seller = await MyGlobal.prisma.shopping_sellers.findUnique({
      where: { id: refund.shopping_actor_id },
    });
    if (!seller)
      throw new HttpException("Refund actor (seller) not found", 404);
    actor = { actor_type: "seller", id: seller.id, name: seller.display_name };
  } else {
    const admin = await MyGlobal.prisma.shopping_admins.findUnique({
      where: { id: refund.shopping_actor_id },
    });
    if (!admin) throw new HttpException("Refund actor (admin) not found", 404);
    actor = { actor_type: "admin", id: admin.id, name: admin.name };
  }

  const orderCustomer = refund.order?.customer;
  if (!orderCustomer)
    throw new HttpException("Order's customer info missing", 500);

  return {
    id: refund.id,
    order: {
      id: refund.order.id,
      order_code: refund.order.order_code,
      total_price: refund.order.total_price,
      status: refund.order.status,
      created_at: toISOStringSafe(refund.order.created_at),
      updated_at: toISOStringSafe(refund.order.updated_at),
      customer: {
        id: orderCustomer.id,
        name: orderCustomer.name,
        email: orderCustomer.email,
        is_active: orderCustomer.is_active,
        created_at: toISOStringSafe(orderCustomer.created_at),
        deleted_at:
          orderCustomer.deleted_at !== null
            ? toISOStringSafe(orderCustomer.deleted_at)
            : null,
      },
    },
    actor,
    request_type: (["refund", "return", "cancellation"] as const).includes(
      refund.request_type as any,
    )
      ? (refund.request_type as "refund" | "return" | "cancellation")
      : "refund",
    business_reason: refund.business_reason,
    request_context: refund.request_context ?? undefined,
    status: refund.status,
    created_at: toISOStringSafe(refund.created_at),
    updated_at: toISOStringSafe(refund.updated_at),
    deleted_at:
      refund.deleted_at !== null
        ? toISOStringSafe(refund.deleted_at)
        : undefined,
    items: items.map(
      (item): IShoppingRefundRequestItem => ({
        id: item.id,
        shopping_refund_request_id: item.shopping_refund_request_id,
        shopping_order_id: item.shopping_order_id,
        shopping_order_line_id: item.shopping_order_line_id,
        quantity: item.quantity,
        item_business_reason: item.item_business_reason ?? undefined,
        created_at: toISOStringSafe(item.created_at),
        updated_at: toISOStringSafe(item.updated_at),
        attachments: attachmentsByItem.get(item.id) ?? [],
      }),
    ),
    attachments: allAttachments,
    status_histories: statusHistories.map(
      (st): IShoppingRefundStatusHistory => ({
        id: st.id,
        shopping_refund_request_id: st.shopping_refund_request_id,
        shopping_actor_id: st.shopping_actor_id,
        actor_type: st.actor_type as "customer" | "seller" | "admin",
        previous_status: st.previous_status,
        new_status: st.new_status,
        timestamp: toISOStringSafe(st.timestamp),
        change_context: st.change_context ?? undefined,
      }),
    ),
    approvals: approvals.map(
      (app): IShoppingRefundApproval => ({
        id: app.id,
        shopping_refund_request_id: app.shopping_refund_request_id,
        shopping_refund_status_history_id:
          app.shopping_refund_status_history_id,
        actor_type: app.actor_type,
        actor_id: app.shopping_actor_id,
        action: app.action,
        note: app.note ?? undefined,
        created_at: toISOStringSafe(app.created_at),
      }),
    ),
    admin_overrides: adminOverrides.map(
      (adm): IShoppingRefundAdminOverride => ({
        id: adm.id,
        shopping_refund_request_id: adm.shopping_refund_request_id,
        shopping_admin_id: adm.shopping_admin_id,
        override_type: adm.override_type,
        reason: adm.reason,
        detailed_context: adm.detailed_context ?? undefined,
        created_at: toISOStringSafe(adm.created_at),
      }),
    ),
  };
}

