import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/client";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";
import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

import { IShoppingRefundRequestItem } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingRefundRequestItem";
import { IShoppingRefundAttachment } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingRefundAttachment";
import { CustomerPayload } from "../decorators/payload/CustomerPayload";

export async function getShoppingCustomerRefundsRefundRequestIdItemsItemId(props: {
  customer: CustomerPayload;
  refundRequestId: string & tags.Format<"uuid">;
  itemId: string & tags.Format<"uuid">;
}): Promise<IShoppingRefundRequestItem> {
  // Fetch the refund request item and join parent refund request for ownership check
  const item = await MyGlobal.prisma.shopping_refund_request_items.findUnique({
    where: { id: props.itemId },
    include: {
      refundRequest: true,
    },
  });
  if (!item || item.shopping_refund_request_id !== props.refundRequestId) {
    throw new HttpException("Refund request item not found", 404);
  }
  if (
    !item.refundRequest ||
    item.refundRequest.actor_type !== "customer" ||
    item.refundRequest.shopping_actor_id !== props.customer.id
  ) {
    throw new HttpException(
      "You are not authorized to access this refund request item",
      403,
    );
  }
  // Get attachments for this item
  const attachments =
    await MyGlobal.prisma.shopping_refund_attachments.findMany({
      where: {
        shopping_refund_request_id: props.refundRequestId,
        shopping_refund_request_item_id: props.itemId,
      },
      select: {
        id: true,
        shopping_refund_request_id: true,
        shopping_refund_request_item_id: true,
        attachment_file_id: true,
        attachment_type: true,
        description: true,
        uploaded_at: true,
      },
    });
  // Get image metadata from shopping_product_images for all attachment_file_ids
  const fileIds = attachments.map((att) => att.attachment_file_id);
  const files = await MyGlobal.prisma.shopping_product_images.findMany({
    where: { id: { in: fileIds } },
    select: {
      id: true,
      image_uri: true,
    },
  });
  const filesMap = new Map(files.map((f) => [f.id, f]));

  return {
    id: item.id,
    shopping_refund_request_id: item.shopping_refund_request_id,
    shopping_order_id: item.shopping_order_id,
    shopping_order_line_id: item.shopping_order_line_id,
    quantity: item.quantity,
    item_business_reason:
      typeof item.item_business_reason === "string"
        ? item.item_business_reason
        : item.item_business_reason === null
          ? null
          : undefined,
    created_at: toISOStringSafe(item.created_at),
    updated_at: toISOStringSafe(item.updated_at),
    attachments:
      attachments.length > 0
        ? attachments.map((att) => {
            const file = filesMap.get(att.attachment_file_id);
            return {
              id: att.id,
              shopping_refund_request_id: att.shopping_refund_request_id,
              shopping_refund_request_item_id:
                att.shopping_refund_request_item_id === null
                  ? null
                  : att.shopping_refund_request_item_id,
              attachment_file_id: att.attachment_file_id,
              attachment_type: att.attachment_type,
              description:
                typeof att.description === "string"
                  ? att.description
                  : att.description === null
                    ? null
                    : undefined,
              uploaded_at: toISOStringSafe(att.uploaded_at),
              file_uri: file?.image_uri ?? "",
              file_type: "", // Not present in schema, default empty
              file_size: 0, // Not present in schema, default zero
            };
          })
        : undefined,
  };
}

import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/client";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";
import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

import { IShoppingWishlist } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingWishlist";
import { IShoppingWishlistItem } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingWishlistItem";
import { IShoppingSku } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingSku";
import { CustomerPayload } from "../decorators/payload/CustomerPayload";

export async function getShoppingCustomerWishlistsWishlistId(props: {
  customer: CustomerPayload;
  wishlistId: string & tags.Format<"uuid">;
}): Promise<IShoppingWishlist> {
  // Fetch wishlist by ID, verify ownership
  const wishlist = await MyGlobal.prisma.shopping_wishlists.findUnique({
    where: { id: props.wishlistId },
    select: {
      id: true,
      shopping_customer_id: true,
      created_at: true,
      updated_at: true,
      // REMOVED deleted_at field (does not exist)
    },
  });
  if (!wishlist || wishlist.shopping_customer_id !== props.customer.id) {
    throw new HttpException("Wishlist not found or not accessible", 404);
  }

  // Fetch wishlist items, ordered by added_at asc
  const wishlistItems = await MyGlobal.prisma.shopping_wishlist_items.findMany({
    where: { shopping_wishlist_id: props.wishlistId },
    orderBy: { added_at: "asc" },
  });

  // Get all relevant SKUs for summary
  const skuIds = wishlistItems.map((item) => item.shopping_sku_id);
  const skus = await MyGlobal.prisma.shopping_skus.findMany({
    where: { id: { in: skuIds } },
  });

  // Map SKU summaries by ID
  const skuMap: Record<string, IShoppingSku.ISummary> = {};
  for (const sku of skus) {
    skuMap[sku.id] = {
      id: sku.id,
      sku_code: sku.sku_code,
      price: sku.price,
      is_active: sku.is_active,
      status: sku.status,
    };
  }

  // Build item list for response
  const items: IShoppingWishlistItem[] = wishlistItems.map((item) => {
    return {
      id: item.id,
      sku: skuMap[item.shopping_sku_id],
      added_at: toISOStringSafe(item.added_at),
      // note: wishlist item 'note' does not exist in schema
    };
  });

  // Return assembled response
  return {
    id: wishlist.id,
    shopping_customer_id: wishlist.shopping_customer_id,
    created_at: toISOStringSafe(wishlist.created_at),
    updated_at: toISOStringSafe(wishlist.updated_at),
    items,
  };
}

import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/client";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";
import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

import { IShoppingGuestCartItem } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingGuestCartItem";

export async function getShoppingGuestCartsGuestCartIdItemsItemId(props: {
  guestCartId: string;
  itemId: string;
}): Promise<IShoppingGuestCartItem> {
  // Fetch the guest cart
  const cart = await MyGlobal.prisma.shopping_guest_carts.findUnique({
    where: { id: props.guestCartId },
    select: {
      id: true,
      session_key: true,
      created_at: true,
      updated_at: true,
      expires_at: true,
    },
  });
  if (!cart) {
    throw new HttpException("Guest cart not found", 404);
  }

  // Check not expired
  if (cart.expires_at < new Date()) {
    throw new HttpException("Guest cart is expired", 404);
  }

  // Fetch the specific guest cart item
  const item = await MyGlobal.prisma.shopping_guest_cart_items.findUnique({
    where: { id: props.itemId },
  });
  if (!item || item.shopping_guest_cart_id !== props.guestCartId) {
    throw new HttpException("Cart item not found in guest cart", 404);
  }

  return {
    id: cart.id as string & tags.Format<"uuid">,
    session_key: cart.session_key,
    created_at: toISOStringSafe(cart.created_at),
    updated_at: toISOStringSafe(cart.updated_at),
    expires_at: toISOStringSafe(cart.expires_at),
    items: [
      {
        session_key: cart.session_key,
        created_at: toISOStringSafe(cart.created_at),
        updated_at: toISOStringSafe(cart.updated_at),
        expires_at: toISOStringSafe(cart.expires_at),
        items: [],
      },
    ],
  };
}

