  // 6. Map results to ISummary
  const data = rows.map((pkg) => ({
    id: pkg.id,
    shopping_shipment_id: pkg.shopping_shipment_id,
    sequence: pkg.sequence,
    package_label: pkg.package_label,
    tracking_number: pkg.tracking_number,
