import { IShoppingShipmentTrackingEvent } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingShipmentTrackingEvent";
import { IPageIShoppingShipmentTrackingEvent } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIShoppingShipmentTrackingEvent";
import { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import { SellerPayload } from "../decorators/payload/SellerPayload";

export async function patchShoppingSellerShipmentsCodePackagesPackageLabelTrackingsTrackingSourceEvents(props: {
  seller: SellerPayload;
  code: string;
  packageLabel: string;
  trackingSource: string;
  body: IShoppingShipmentTrackingEvent.IRequest;
}): Promise<IPageIShoppingShipmentTrackingEvent> {
  const { seller, code, packageLabel, trackingSource, body } = props;
  const shipment = await MyGlobal.prisma.shopping_shipments.findFirst({
    where: { code, deleted_at: null, shopping_seller_id: seller.id },
    select: { id: true },
  });
  if (!shipment)
    throw new HttpException("Shipment not found or access denied", 404);

  const shipmentPackage =
    await MyGlobal.prisma.shopping_shipment_packages.findFirst({
      where: {
        shopping_shipment_id: shipment.id,
        package_label: packageLabel,
        deleted_at: null,
      },
      select: { id: true },
    });
  if (!shipmentPackage) throw new HttpException("Package not found", 404);

  const tracking = await MyGlobal.prisma.shopping_shipment_trackings.findFirst({
    where: {
      shopping_shipment_package_id: shipmentPackage.id,
      tracking_source: trackingSource,
      deleted_at: null,
    },
    select: { id: true },
  });
  if (!tracking) throw new HttpException("Tracking source not found", 404);

  const page = body.page ?? 1;
  const limit = body.limit ?? 20;
  const skip = (page - 1) * limit;
  const allowedSortFields = ["event_time", "event_code", "location"];
  const sortBy = allowedSortFields.includes(body.sort_by ?? "")
    ? body.sort_by
    : "event_time";
  const sortOrder = body.order === "asc" ? "asc" : "desc";

  const where = {
    shopping_shipment_tracking_id: tracking.id,
    deleted_at: null,
    ...(body.event_code !== undefined && { event_code: body.event_code }),
    ...(body.location !== undefined && {
      location: { contains: body.location },
    }),
    ...(body.from_datetime !== undefined || body.to_datetime !== undefined
      ? {
          event_time: {
            ...(body.from_datetime !== undefined && {
              gte: body.from_datetime,
            }),
            ...(body.to_datetime !== undefined && { lte: body.to_datetime }),
          },
        }
      : {}),
    ...(body.search !== undefined && body.search.trim().length > 0
      ? {
          OR: [
            { event_code: { contains: body.search } },
            { location: { contains: body.search } },
            { raw_status: { contains: body.search } },
          ],
        }
      : {}),
  };

  // Directly construct orderBy inline to avoid computed property issues
  let orderBy: Record<string, Prisma.SortOrder> = { event_time: "desc" };
  if (
    sortBy === "event_time" ||
    sortBy === "event_code" ||
    sortBy === "location"
  ) {
    orderBy = { [sortBy]: sortOrder as Prisma.SortOrder };
  }

  const [events, total] = await Promise.all([
    MyGlobal.prisma.shopping_shipment_tracking_events.findMany({
      where,
      orderBy,
      skip,
      take: limit,
    }),
    MyGlobal.prisma.shopping_shipment_tracking_events.count({ where }),
  ]);

  return {
    pagination: {
      current: Number(page),
      limit: Number(limit),
      records: total,
      pages: Math.ceil(total / Number(limit)),
    },
    data: events.map((ev) => ({
      id: ev.id,
      shopping_shipment_tracking_id: ev.shopping_shipment_tracking_id,
      event_time: toISOStringSafe(ev.event_time),
      event_code: ev.event_code,
      location: ev.location ?? null,
      raw_status: ev.raw_status,
      external_ref: ev.external_ref ?? null,
      ingested_at: toISOStringSafe(ev.ingested_at),
      created_at: toISOStringSafe(ev.created_at),
      deleted_at: ev.deleted_at ? toISOStringSafe(ev.deleted_at) : undefined,
    })),
  };
}

import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/client";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";
import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

import { IShoppingSeller } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingSeller";
import { IShoppingAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingAuthorizationToken";

export async function postAuthSellerLogin(props: {
  body: IShoppingSeller.ILogin;
}): Promise<IShoppingSeller.IAuthorized> {
  // 1. Find the seller by email (do not distinguish not found, for anti-enumeration)
  const seller = await MyGlobal.prisma.shopping_sellers.findFirst({
    where: {
      email: props.body.email,
      deleted_at: null,
    },
  });
  // 2. Validate credentials (generic failure for invalid)
  const isActive =
    !!seller && seller.deleted_at === null && seller.status !== "suspended";
  if (!seller || !isActive) {
    throw new HttpException("Invalid credentials", 401);
  }
  const passwordOk = await PasswordUtil.verify(
    props.body.password,
    seller.password_hash,
  );
  if (!passwordOk) {
    throw new HttpException("Invalid credentials", 401);
  }
  // 3. Create new session
  const accessExpiredAt = toISOStringSafe(
    new Date(Date.now() + 60 * 60 * 1000),
  );
  const refreshExpiredAt = toISOStringSafe(
    new Date(Date.now() + 7 * 24 * 60 * 60 * 1000),
  );
  const now = toISOStringSafe(new Date());
  const session = await MyGlobal.prisma.shopping_seller_sessions.create({
    data: {
      id: v4(),
      shopping_seller_id: seller.id,
      ip: props.body.ip ?? "", // fallback to empty string if missing
      href: props.body.href,
      referrer: props.body.referrer,
      created_at: now,
      expired_at: accessExpiredAt,
    },
  });
  // 4. Generate tokens
  const token = {
    access: jwt.sign(
      {
        type: "seller",
        id: seller.id,
        session_id: session.id,
        created_at: now,
      },
      MyGlobal.env.JWT_SECRET_KEY,
      {
        expiresIn: "1h",
        issuer: "autobe",
      },
    ),
    refresh: jwt.sign(
      {
        type: "seller",
        id: seller.id,
        session_id: session.id,
        created_at: now,
        tokenType: "refresh",
      },
      MyGlobal.env.JWT_SECRET_KEY,
      {
        expiresIn: "7d",
        issuer: "autobe",
      },
    ),
    expired_at: accessExpiredAt,
    refreshable_until: refreshExpiredAt,
  };
  // 5. Return authorized DTO
  return {
    id: seller.id,
    email: seller.email,
    display_name: seller.display_name,
    contact_phone: seller.contact_phone,
    status: seller.status,
    is_active: isActive,
    created_at: toISOStringSafe(seller.created_at),
    updated_at: toISOStringSafe(seller.updated_at),
    token,
  };
}

import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/client";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";
import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

import { IShoppingSeller } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingSeller";
import { IShoppingAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingAuthorizationToken";

export async function postAuthSellerRefresh(props: {
  body: IShoppingSeller.IRefresh;
}): Promise<IShoppingSeller.IAuthorized> {
  let decoded: { id: string; session_id: string; type: "seller" };
  try {
    decoded = jwt.verify(
      props.body.refresh_token,
      MyGlobal.env.JWT_SECRET_KEY,
      { issuer: "autobe" },
    ) as { id: string; session_id: string; type: "seller" };
  } catch {
    throw new HttpException("Invalid or expired refresh token", 401);
  }
  if (decoded.type !== "seller") {
    throw new HttpException("Token does not belong to a seller", 403);
  }
  const session = await MyGlobal.prisma.shopping_seller_sessions.findFirst({
    where: {
      id: decoded.session_id,
      shopping_seller_id: decoded.id,
    },
    include: {
      seller: true,
    },
  });
  if (!session) {
    throw new HttpException("Session expired or revoked", 401);
  }
  if (
    session.expired_at &&
    new Date(session.expired_at).getTime() <= Date.now()
  ) {
    throw new HttpException(
      "Session is no longer valid (expired/revoked)",
      401,
    );
  }
  if (!session.seller || session.seller.deleted_at !== null) {
    throw new HttpException("Seller account is no longer active", 403);
  }
  const nowISO = toISOStringSafe(new Date());
  const access_expiry = toISOStringSafe(new Date(Date.now() + 60 * 60 * 1000));
  const refresh_expiry = toISOStringSafe(
    new Date(Date.now() + 7 * 24 * 60 * 60 * 1000),
  );
  const accessToken = jwt.sign(
    {
      type: "seller",
      id: session.seller.id,
      session_id: session.id,
      created_at: nowISO,
    },
    MyGlobal.env.JWT_SECRET_KEY,
    {
      expiresIn: "1h",
      issuer: "autobe",
    },
  );
  const refreshToken = jwt.sign(
    {
      type: "seller",
      id: session.seller.id,
      session_id: session.id,
      tokenType: "refresh",
      created_at: nowISO,
    },
    MyGlobal.env.JWT_SECRET_KEY,
    {
      expiresIn: "7d",
      issuer: "autobe",
    },
  );
  await MyGlobal.prisma.shopping_seller_sessions.update({
    where: { id: session.id },
    data: { expired_at: refresh_expiry },
  });
  return {
    id: session.seller.id,
    email: session.seller.email,
    display_name: session.seller.display_name,
    contact_phone: session.seller.contact_phone,
    status: session.seller.status,
    is_active:
      session.seller.status === "active" && session.seller.deleted_at === null,
    created_at: toISOStringSafe(session.seller.created_at),
    updated_at: toISOStringSafe(session.seller.updated_at),
    token: {
      access: accessToken,
      refresh: refreshToken,
      expired_at: access_expiry,
      refreshable_until: refresh_expiry,
    },
  };
}

