import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/client";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";
import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

import { IShoppingOrder } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingOrder";
import { IShoppingOrderLine } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingOrderLine";
import { IShoppingOrderAddress } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingOrderAddress";
import { IShoppingCustomer } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingCustomer";
import { IShoppingSku } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingSku";
import { IShoppingSeller } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingSeller";
import { IShoppingOrderLineFulfillment } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingOrderLineFulfillment";
import { IShoppingOrderSplit } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingOrderSplit";
import { IShoppingOrderStatusHistory } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingOrderStatusHistory";
import { IShoppingOrderPaymentAttempt } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingOrderPaymentAttempt";
import { IShoppingOrderShipment } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingOrderShipment";
import { CustomerPayload } from "../decorators/payload/CustomerPayload";

export async function postShoppingCustomerOrders(props: {
  customer: CustomerPayload;
  body: IShoppingOrder.ICreate;
}): Promise<IShoppingOrder> {
  const now = toISOStringSafe(new Date());
  const { customer, body } = props;

  // Validate SKUs and sufficient inventory
  const skuIds = body.order_lines.map((l) => l.shopping_sku_id);
  const skus = await MyGlobal.prisma.shopping_skus.findMany({
    where: { id: { in: skuIds }, is_active: true, deleted_at: null },
  });
  if (skus.length !== skuIds.length) {
    throw new HttpException(
      "One or more SKUs are invalid, inactive, or deleted",
      400,
    );
  }
  // Fetch products in batch and resolve seller mapping
  const productIds = Array.from(
    new Set(skus.map((sku) => sku.shopping_product_id)),
  );
  const products = await MyGlobal.prisma.shopping_products.findMany({
    where: { id: { in: productIds }, deleted_at: null },
    select: {
      id: true,
      shopping_seller_id: true,
    },
  });
  const productMap = new Map(products.map((p) => [p.id, p]));
  // Build map from sku id to seller id via product
  const skuToSellerId = new Map<string, string>();
  for (const sku of skus) {
    const prod = productMap.get(sku.shopping_product_id);
    if (!prod)
      throw new HttpException("SKU product invalid or unavailable", 400);
    skuToSellerId.set(sku.id, prod.shopping_seller_id);
  }
  // Collect unique sellers
  const sellerIds: string[] = Array.from(
    new Set(Array.from(skuToSellerId.values())),
  );
  const sellers = await MyGlobal.prisma.shopping_sellers.findMany({
    where: { id: { in: sellerIds }, deleted_at: null },
  });
  const sellerMap = new Map(sellers.map((s) => [s.id, s]));

  // Inventory check
  const inventoryRecords = await MyGlobal.prisma.shopping_inventory.findMany({
    where: { shopping_sku_id: { in: skuIds } },
  });
  const invMap = new Map(
    inventoryRecords.map((inv) => [inv.shopping_sku_id, inv]),
  );
  for (const line of body.order_lines) {
    const inventory = invMap.get(line.shopping_sku_id);
    if (!inventory || inventory.quantity < line.quantity) {
      throw new HttpException(
        "Insufficient inventory for SKU " + line.shopping_sku_id,
        409,
      );
    }
  }

  // Prepare splits (per seller)
  const splits: Array<{
    seller_id: string;
    order_lines: typeof body.order_lines;
    subtotal: number;
  }> = sellerIds.map((sid) => {
    const sellerLines = body.order_lines.filter(
      (l) => skuToSellerId.get(l.shopping_sku_id) === sid,
    );
    return {
      seller_id: sid,
      order_lines: sellerLines,
      subtotal: sellerLines.reduce(
        (sum, l) => sum + l.unit_price * l.quantity,
        0,
      ),
    };
  });

  // Generate IDs and codes
  const orderId = v4();
  const orderCodeSeq = Math.floor(Math.random() * 100000)
    .toString()
    .padStart(5, "0");
  const orderCode = `ORD-${now.slice(0, 10).replace(/-/g, "")}-${orderCodeSeq}`;

  // Transaction: Create all and decrement inventory
  const order = await MyGlobal.prisma.$transaction(async (tx) => {
    const createdOrder = await tx.shopping_orders.create({
      data: {
        id: orderId,
        shopping_customer_id: customer.id,
        order_code: orderCode,
        total_price: body.total_price,
        status: "pending",
        created_at: now,
        updated_at: now,
      },
    });
    for (const line of body.order_lines) {
      const seller_id = skuToSellerId.get(line.shopping_sku_id)!;
      const orderLineId = v4();
      await tx.shopping_order_lines.create({
        data: {
          id: orderLineId,
          shopping_order_id: orderId,
          shopping_sku_id: line.shopping_sku_id,
          shopping_seller_id: seller_id,
          quantity: line.quantity,
          unit_price: line.unit_price,
          status: "pending",
          created_at: now,
          updated_at: now,
        },
      });
      const inv = invMap.get(line.shopping_sku_id);
      await tx.shopping_inventory.update({
        where: { id: inv!.id },
        data: { quantity: inv!.quantity - line.quantity, updated_at: now },
      });
      await tx.shopping_inventory_adjustments.create({
        data: {
          id: v4(),
          shopping_inventory_id: inv!.id,
          shopping_sku_id: line.shopping_sku_id,
          actor_type: "customer",
          actor_id: customer.id,
          reason_code: "order",
          quantity_before: inv!.quantity,
          quantity_after: inv!.quantity - line.quantity,
          adjustment_amount: -line.quantity,
          created_at: now,
        },
      });
    }
    for (const addr of body.shipping_addresses) {
      await tx.shopping_order_addresses.create({
        data: {
          id: v4(),
          shopping_order_id: orderId,
          type: addr.type,
          recipient_name: addr.recipient_name,
          recipient_phone: addr.recipient_phone,
          zip_code: addr.zip_code,
          base_address: addr.base_address,
          detail_address: addr.detail_address ?? null,
          city: addr.city,
          state_province: addr.state_province,
          country: addr.country,
          created_at: now,
          updated_at: now,
        },
      });
    }
    for (const s of splits) {
      await tx.shopping_order_splits.create({
        data: {
          id: v4(),
          shopping_order_id: orderId,
          shopping_seller_id: s.seller_id,
          split_code: `${orderCode}-${v4().slice(0, 6)}`,
          subtotal_price: s.subtotal,
          status: "pending",
          created_at: now,
          updated_at: now,
        },
      });
    }
    await tx.shopping_payment_attempts.create({
      data: {
        id: v4(),
        shopping_order_id: orderId,
        payment_reference: null,
        attempt_status: "pending",
        amount: body.total_price,
        attempted_at: now,
        completed_at: null,
      },
    });
    await tx.shopping_order_status_histories.create({
      data: {
        id: v4(),
        shopping_order_id: orderId,
        shopping_order_split_id: null,
        from_status: "",
        to_status: "pending",
        triggered_by: "customer",
        event_note: null,
        occurred_at: now,
      },
    });
    return createdOrder;
  });

  // Fetch order and join all response data
  const dbOrder = await MyGlobal.prisma.shopping_orders.findUniqueOrThrow({
    where: { id: orderId },
    include: {
      customer: true,
      shopping_order_lines: true,
      shopping_order_splits: true,
      shopping_order_addresses: true,
      shopping_order_status_histories: true,
      shopping_payment_attempts: true,
      shopping_shipments: true,
    },
  });

  const customerSummary = {
    id: dbOrder.customer.id,
    name: dbOrder.customer.name,
    email: dbOrder.customer.email,
    is_active: dbOrder.customer.is_active,
    created_at: toISOStringSafe(dbOrder.customer.created_at),
    deleted_at: dbOrder.customer.deleted_at
      ? toISOStringSafe(dbOrder.customer.deleted_at)
      : null,
  };
  // Rebuild skuMap for response composition
  const dbSkuIds = dbOrder.shopping_order_lines.map((l) => l.shopping_sku_id);
  const dbSkus = await MyGlobal.prisma.shopping_skus.findMany({
    where: { id: { in: dbSkuIds } },
  });
  const skuMap = new Map(dbSkus.map((sku) => [sku.id, sku]));

  const orderLines = dbOrder.shopping_order_lines.map((line) => {
    const sku = skuMap.get(line.shopping_sku_id)!;
    const sellerId = skuToSellerId.get(line.shopping_sku_id)!;
    const seller = sellerMap.get(sellerId)!;
    return {
      id: line.id,
      sku: {
        id: sku.id,
        sku_code: sku.sku_code,
        price: sku.price,
        is_active: sku.is_active,
        status: sku.status,
      },
      quantity: line.quantity,
      unit_price: line.unit_price,
      status: line.status,
      seller: {
        id: seller.id,
        display_name: seller.display_name,
        status: seller.status,
      },
      fulfillments: [],
      created_at: toISOStringSafe(line.created_at),
      updated_at: toISOStringSafe(line.updated_at),
      deleted_at: line.deleted_at
        ? toISOStringSafe(line.deleted_at)
        : undefined,
    };
  });
  const splitsFull = dbOrder.shopping_order_splits.map((split) => {
    const seller = sellerMap.get(split.shopping_seller_id)!;
    const splitStatusHistories = dbOrder.shopping_order_status_histories
      .filter((h) => h.shopping_order_split_id === split.id)
      .map((h) => ({
        id: h.id,
        from_status: h.from_status,
        to_status: h.to_status,
        triggered_by: h.triggered_by,
        event_note: h.event_note ?? undefined,
        occurred_at: toISOStringSafe(h.occurred_at),
      }));
    return {
      id: split.id,
      split_code: split.split_code,
      subtotal_price: split.subtotal_price,
      status: split.status,
      created_at: toISOStringSafe(split.created_at),
      updated_at: split.updated_at
        ? toISOStringSafe(split.updated_at)
        : undefined,
      order_id: split.shopping_order_id,
      seller: {
        id: seller.id,
        display_name: seller.display_name,
        status: seller.status,
      },
      order_status_histories:
        splitStatusHistories.length > 0 ? splitStatusHistories : undefined,
    };
  });
  const addresses = dbOrder.shopping_order_addresses.map((addr) => ({
    id: addr.id,
    shopping_order_id: addr.shopping_order_id,
    type: addr.type,
    recipient_name: addr.recipient_name,
    recipient_phone: addr.recipient_phone,
    zip_code: addr.zip_code,
    base_address: addr.base_address,
    detail_address: addr.detail_address ?? undefined,
    city: addr.city,
    state_province: addr.state_province,
    country: addr.country,
    created_at: toISOStringSafe(addr.created_at),
    updated_at: toISOStringSafe(addr.updated_at),
  }));
  const statusHistory = dbOrder.shopping_order_status_histories.map((h) => ({
    id: h.id,
    shopping_order_id: h.shopping_order_id,
    shopping_order_split_id: h.shopping_order_split_id ?? undefined,
    from_status: h.from_status,
    to_status: h.to_status,
    triggered_by: h.triggered_by,
    event_note: h.event_note ?? undefined,
    occurred_at: toISOStringSafe(h.occurred_at),
  }));
  const paymentAttempts = dbOrder.shopping_payment_attempts.map((pa) => ({
    id: pa.id,
    payment_reference: pa.payment_reference ?? undefined,
    attempt_status: pa.attempt_status as
      | "pending"
      | "completed"
      | "failed"
      | "cancelled",
    amount: pa.amount,
    attempted_at: toISOStringSafe(pa.attempted_at),
    completed_at: pa.completed_at
      ? toISOStringSafe(pa.completed_at)
      : undefined,
  }));
  const shipments = dbOrder.shopping_shipments.map((sh) => ({
    id: sh.id,
    seller: {
      id: sh.shopping_seller_id,
      display_name: sellerMap.get(sh.shopping_seller_id)?.display_name ?? "",
      status: sellerMap.get(sh.shopping_seller_id)?.status ?? "",
    },
    code: sh.code,
    status: sh.status,
    carrier_company: sh.carrier_company,
    scheduled_dispatch_at: sh.scheduled_dispatch_at
      ? toISOStringSafe(sh.scheduled_dispatch_at)
      : undefined,
    dispatched_at: sh.dispatched_at
      ? toISOStringSafe(sh.dispatched_at)
      : undefined,
    delivered_at: sh.delivered_at
      ? toISOStringSafe(sh.delivered_at)
      : undefined,
    canceled_at: sh.canceled_at ? toISOStringSafe(sh.canceled_at) : undefined,
    created_at: toISOStringSafe(sh.created_at),
    updated_at: toISOStringSafe(sh.updated_at),
  }));
  return {
    id: dbOrder.id,
    order_code: dbOrder.order_code,
    total_price: dbOrder.total_price,
    status: dbOrder.status,
    created_at: toISOStringSafe(dbOrder.created_at),
    updated_at: toISOStringSafe(dbOrder.updated_at),
    deleted_at: dbOrder.deleted_at
      ? toISOStringSafe(dbOrder.deleted_at)
      : undefined,
    customer: customerSummary,
    order_lines: orderLines,
    order_splits: splitsFull,
    addresses,
    status_history: statusHistory,
    payment_attempts: paymentAttempts,
    shipments,
  };
}

import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/client";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";
import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

import { IShoppingSku } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingSku";
import { IShoppingSkuVariant } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingSkuVariant";
import { IShoppingAttributeValue } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingAttributeValue";
import { IShoppingProduct } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingProduct";
import { IShoppingSkuImage } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingSkuImage";
import { SellerPayload } from "../decorators/payload/SellerPayload";

export async function postShoppingSellerProductsProductCodeSkus(props: {
  seller: SellerPayload;
  productCode: string;
  body: IShoppingSku.ICreate;
}): Promise<IShoppingSku> {
  const { seller, productCode, body } = props;
  // 1. Fetch product, check seller owns it & not deleted
  const product = await MyGlobal.prisma.shopping_products.findFirst({
    where: { code: productCode, deleted_at: null },
    select: {
      id: true,
      code: true,
      name: true,
      main_image_uri: true,
      status: true,
      shopping_seller_id: true,
    },
  });
  if (!product) throw new HttpException("Product not found", 404);
  if (product.shopping_seller_id !== seller.id)
    throw new HttpException("Forbidden: You do not own this product", 403);

  // 2. Validate at least one variant attribute value
  if (
    !body.variant_attribute_value_ids ||
    body.variant_attribute_value_ids.length < 1
  ) {
    throw new HttpException(
      "At least one variant attribute value ID required",
      400,
    );
  }

  // 3. Enforce SKU code uniqueness (active SKUs only)
  const skuExists = await MyGlobal.prisma.shopping_skus.findFirst({
    where: { sku_code: body.sku_code, deleted_at: null },
    select: { id: true },
  });
  if (skuExists) throw new HttpException("SKU code already exists", 409);

  // 4. Create SKU
  const now = toISOStringSafe(new Date());
  const createdSku = await MyGlobal.prisma.shopping_skus.create({
    data: {
      id: v4(),
      shopping_product_id: product.id,
      sku_code: body.sku_code,
      price: body.price,
      is_active: body.is_active,
      barcode: body.barcode === undefined ? undefined : body.barcode,
      status: body.status,
      created_at: now,
      updated_at: now,
      deleted_at: null,
    },
    select: {
      id: true,
      shopping_product_id: true,
      sku_code: true,
      price: true,
      is_active: true,
      barcode: true,
      status: true,
      created_at: true,
      updated_at: true,
      deleted_at: true,
    },
  });

  // 5. Insert variant attribute assignments, build output variants array
  const variants: IShoppingSkuVariant[] = [];
  for (let idx = 0; idx < body.variant_attribute_value_ids.length; ++idx) {
    const attrValueId = body.variant_attribute_value_ids[idx];
    const variantRow = await MyGlobal.prisma.shopping_sku_variants.create({
      data: {
        id: v4(),
        shopping_sku_id: createdSku.id,
        shopping_attribute_value_id: attrValueId,
        order_index: idx,
      },
      select: {
        id: true,
        shopping_attribute_value_id: true,
        order_index: true,
        attributeValue: {
          select: {
            id: true,
            shopping_attribute_dimension_id: true,
            value_code: true,
            display_value: true,
            display_order: true,
            created_at: true,
          },
        },
      },
    });
    variants.push({
      id: variantRow.id,
      shopping_attribute_value_id: variantRow.shopping_attribute_value_id,
      order_index: variantRow.order_index,
      attribute_value: {
        id: variantRow.attributeValue.id,
        shopping_attribute_dimension_id:
          variantRow.attributeValue.shopping_attribute_dimension_id,
        value_code: variantRow.attributeValue.value_code,
        display_value: variantRow.attributeValue.display_value,
        display_order: variantRow.attributeValue.display_order ?? undefined,
        // IShoppingAttributeValue.description is optional so we provide undefined
        description: undefined,
        created_at: toISOStringSafe(variantRow.attributeValue.created_at),
      },
    });
  }

  // 6. Compose product summary object
  const productSummary: IShoppingProduct.ISummary = {
    id: product.id,
    code: product.code,
    name: product.name,
    main_image_uri: product.main_image_uri ?? undefined,
    status: product.status,
  };

  // 7. Final SKU DTO output
  return {
    id: createdSku.id,
    shopping_product_id: createdSku.shopping_product_id,
    sku_code: createdSku.sku_code,
    price: createdSku.price,
    is_active: createdSku.is_active,
    barcode:
      createdSku.barcode === null || createdSku.barcode === undefined
        ? undefined
        : createdSku.barcode,
    status: createdSku.status,
    created_at: toISOStringSafe(createdSku.created_at),
    updated_at: toISOStringSafe(createdSku.updated_at),
    deleted_at:
      createdSku.deleted_at === null || createdSku.deleted_at === undefined
        ? undefined
        : toISOStringSafe(createdSku.deleted_at),
    variant_attributes: variants,
    product: productSummary,
    images: [],
  };
}

import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/client";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";
import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

import { IShoppingAttributeDimension } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingAttributeDimension";
import { AdminPayload } from "../decorators/payload/AdminPayload";

export async function putShoppingAdminAttributeDimensionsDimensionCode(props: {
  admin: AdminPayload;
  dimensionCode: string;
  body: IShoppingAttributeDimension.IUpdate;
}): Promise<IShoppingAttributeDimension> {
  const existing =
    await MyGlobal.prisma.shopping_attribute_dimensions.findUnique({
      where: { dimension_code: props.dimensionCode },
    });
  if (!existing) {
    throw new HttpException("Attribute dimension not found", 404);
  }
  const updated = await MyGlobal.prisma.shopping_attribute_dimensions.update({
    where: { dimension_code: props.dimensionCode },
    data: {
      name: props.body.name,
      description: props.body.description,
      // updated_at removed; not allowed by schema
    },
  });
  return {
    id: updated.id,
    dimension_code: updated.dimension_code,
    name: updated.name,
    description: updated.description,
    created_at: toISOStringSafe(updated.created_at),
  };
}

import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/client";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";
import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

import { IShoppingOrderLine } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingOrderLine";
import { IShoppingSku } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingSku";
import { IShoppingSeller } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingSeller";
import { IShoppingOrderLineFulfillment } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingOrderLineFulfillment";
import { AdminPayload } from "../decorators/payload/AdminPayload";

export async function putShoppingAdminOrdersOrderCodeLinesOrderLineId(props: {
  admin: AdminPayload;
  orderCode: string;
  orderLineId: string & tags.Format<"uuid">;
  body: IShoppingOrderLine.IUpdate;
}): Promise<IShoppingOrderLine> {
  // 1. Fetch order by orderCode
  const order = await MyGlobal.prisma.shopping_orders.findFirst({
    where: {
      order_code: props.orderCode,
      deleted_at: null,
    },
    select: {
      id: true,
      status: true,
    },
  });
  if (!order) throw new HttpException("Order not found", 404);
  if (["paid", "fulfilled", "canceled", "completed"].includes(order.status))
    throw new HttpException("Order is finalized and cannot be edited", 409);

  // 2. Fetch order line by orderLineId and order.id
  const orderLine = await MyGlobal.prisma.shopping_order_lines.findFirst({
    where: {
      id: props.orderLineId,
      shopping_order_id: order.id,
      deleted_at: null,
    },
  });
  if (!orderLine) throw new HttpException("Order line not found", 404);

  // 3. Prepare update fields
  const updateFields: Record<string, unknown> = {};
  if (typeof props.body.shopping_sku_id !== "undefined") {
    // Validate that given SKU exists and is active
    const sku = await MyGlobal.prisma.shopping_skus.findFirst({
      where: {
        id: props.body.shopping_sku_id,
        is_active: true,
        deleted_at: null,
      },
      select: {
        id: true,
        shopping_product_id: true,
      },
    });
    if (!sku) throw new HttpException("SKU does not exist or is inactive", 400);
    // Lookup product to find seller
    const product = await MyGlobal.prisma.shopping_products.findFirst({
      where: { id: sku.shopping_product_id },
      select: { shopping_seller_id: true },
    });
    if (!product) throw new HttpException("Product for SKU not found", 500);
    updateFields.shopping_sku_id = props.body.shopping_sku_id;
    updateFields.shopping_seller_id = product.shopping_seller_id;
  }
  if (typeof props.body.quantity !== "undefined") {
    updateFields.quantity = props.body.quantity;
  }
  if (typeof props.body.unit_price !== "undefined") {
    updateFields.unit_price = props.body.unit_price;
  }
  // Always update updated_at
  updateFields.updated_at = toISOStringSafe(new Date());

  // 4. Update the order line
  const updated = await MyGlobal.prisma.shopping_order_lines.update({
    where: { id: props.orderLineId },
    data: updateFields,
  });
  // 5. Fetch SKU summary
  const skuRow = await MyGlobal.prisma.shopping_skus.findFirst({
    where: { id: updated.shopping_sku_id },
    select: {
      id: true,
      sku_code: true,
      price: true,
      is_active: true,
      status: true,
      shopping_product_id: true,
    },
  });
  if (!skuRow) throw new HttpException("SKU not found after update", 500);
  // 6. Get seller id from product
  const productRow = await MyGlobal.prisma.shopping_products.findFirst({
    where: { id: skuRow.shopping_product_id },
    select: { shopping_seller_id: true },
  });
  if (!productRow)
    throw new HttpException("Product for SKU not found after update", 500);
  // 7. Fetch seller summary
  const seller = await MyGlobal.prisma.shopping_sellers.findFirst({
    where: { id: productRow.shopping_seller_id },
    select: { id: true, display_name: true, status: true },
  });
  if (!seller) throw new HttpException("Seller not found after update", 500);
  // 8. Fetch fulfillments (optional)
  const fulfillments =
    await MyGlobal.prisma.shopping_order_fulfillments.findMany({
      where: { shopping_order_line_id: updated.id },
      select: {
        id: true,
        fulfillment_code: true,
        quantity_fulfilled: true,
        status: true,
        fulfilled_at: true,
        shopping_seller_address_id: true,
      },
      orderBy: { fulfilled_at: "asc" },
    });
  // 9. Compose response
  return {
    id: updated.id,
    sku: {
      id: skuRow.id,
      sku_code: skuRow.sku_code,
      price: skuRow.price,
      is_active: skuRow.is_active,
      status: skuRow.status,
    },
    quantity: updated.quantity,
    unit_price: updated.unit_price,
    status: updated.status,
    seller: {
      id: seller.id,
      display_name: seller.display_name,
      status: seller.status,
    },
    fulfillments:
      fulfillments.length > 0
        ? fulfillments.map((f) => ({
            id: f.id,
            fulfillment_code: f.fulfillment_code,
            quantity_fulfilled: f.quantity_fulfilled,
            status: f.status,
            fulfilled_at: toISOStringSafe(f.fulfilled_at),
            seller_address_id: f.shopping_seller_address_id,
          }))
        : undefined,
    created_at: toISOStringSafe(updated.created_at),
    updated_at: toISOStringSafe(updated.updated_at),
    deleted_at:
      typeof updated.deleted_at === "object" && updated.deleted_at !== null
        ? toISOStringSafe(updated.deleted_at)
        : typeof updated.deleted_at === "string"
          ? updated.deleted_at
          : undefined,
  };
}

import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/client";
