export async function putShoppingAdminProductsProductCode(props: {
  admin: AdminPayload;
  productCode: string;
  body: IShoppingProduct.IUpdate;
}): Promise<IShoppingProduct> {
  const { productCode, body } = props;
  // Find product by code
  const product = await MyGlobal.prisma.shopping_products.findUnique({
    where: { code: productCode },
  });
  if (!product) {
    throw new HttpException("Product not found", 404);
  }
  // Perform update
  const now = toISOStringSafe(new Date());
  const updated = await MyGlobal.prisma.shopping_products.update({
    where: { id: product.id },
    data: {
      name: body.name ?? undefined,
      description: body.description ?? undefined,
      main_image_uri: body.main_image_uri ?? undefined,
      status: body.status ?? undefined,
      business_status: body.business_status ?? undefined,
      updated_at: now,
    },
  });
  // Fetch related data
  const [seller, categories, skus, images, tags, attributes] =
    await Promise.all([
      MyGlobal.prisma.shopping_sellers.findUniqueOrThrow({
        where: { id: updated.shopping_seller_id },
      }),
      MyGlobal.prisma.shopping_category_product_assignments.findMany({
        where: { shopping_product_id: updated.id },
        include: {
          category: true,
        },
      }),
      MyGlobal.prisma.shopping_skus.findMany({
        where: { shopping_product_id: updated.id, deleted_at: null },
      }),
      MyGlobal.prisma.shopping_product_images.findMany({
        where: { shopping_product_id: updated.id },
        orderBy: { order_index: "asc" },
      }),
      MyGlobal.prisma.shopping_product_tag_assignments.findMany({
        where: { shopping_product_id: updated.id },
        include: { tag: true },
      }),
      MyGlobal.prisma.shopping_product_attributes.findMany({
        where: { shopping_product_id: updated.id },
      }),
    ]);
  return {
    id: updated.id,
    shopping_seller_id: updated.shopping_seller_id,
    code: updated.code,
    name: updated.name,
    description: updated.description,
    main_image_uri:
      typeof updated.main_image_uri === "string"
        ? updated.main_image_uri
        : undefined,
    status: updated.status,
    business_status: updated.business_status,
    created_at: toISOStringSafe(updated.created_at),
    updated_at: toISOStringSafe(updated.updated_at),
    deleted_at: updated.deleted_at
      ? toISOStringSafe(updated.deleted_at)
      : undefined,
    seller: {
      id: seller.id,
      display_name: seller.display_name,
      status: seller.status,
    },
    categories: categories.map((ca) => ({
      id: ca.category.id,
      category_code: ca.category.category_code,
      category_name: ca.category.category_name,
    })),
    skus: skus.map((sku) => ({
      id: sku.id,
      shopping_product_id: sku.shopping_product_id,
      sku_code: sku.sku_code,
      price: sku.price,
      is_active: sku.is_active,
      barcode: typeof sku.barcode === "string" ? sku.barcode : undefined,
      status: sku.status,
      created_at: toISOStringSafe(sku.created_at),
      updated_at: toISOStringSafe(sku.updated_at),
      deleted_at: sku.deleted_at ? toISOStringSafe(sku.deleted_at) : undefined,
      variant_attributes: [],
      product: {
        id: updated.id,
        code: updated.code,
        name: updated.name,
        main_image_uri:
          typeof updated.main_image_uri === "string"
            ? updated.main_image_uri
            : undefined,
        status: updated.status,
      },
      images: [],
    })),
    images: images.map((img) => ({
      id: img.id,
      shopping_product_id: img.shopping_product_id,
      image_uri: img.image_uri,
      order_index:
        typeof img.order_index === "number" ? img.order_index : undefined,
      created_at: toISOStringSafe(img.created_at),
    })),
    tags: tags.map((t) => ({
      id: t.tag.id,
      tag_code: t.tag.tag_code,
      display_value: t.tag.display_value,
    })),
    attributes: attributes.map((attr) => ({
      id: attr.id,
      attribute_dimension: {
        id: attr.shopping_attribute_value_id,
        dimension_code: "",
        name: "",
        description: undefined,
      },
      attribute_value: {
        id: attr.shopping_attribute_value_id,
        value_code: "",
        display_value: "",
        dimension: {
          id: "",
          dimension_code: "",
          name: "",
        },
      },
    })),
  };
}

import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/client";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";
import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

import { IShoppingSku } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingSku";
import { IShoppingSkuVariant } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingSkuVariant";
import { IShoppingAttributeValue } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingAttributeValue";
import { IShoppingProduct } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingProduct";
import { IShoppingSkuImage } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingSkuImage";
import { AdminPayload } from "../decorators/payload/AdminPayload";

export async function putShoppingAdminProductsProductCodeSkusSkuCode(props: {
  admin: AdminPayload;
  productCode: string;
  skuCode: string;
  body: IShoppingSku.IUpdate;
}): Promise<IShoppingSku> {
  // 1. Find the product by code
  const product = await MyGlobal.prisma.shopping_products.findUnique({
    where: { code: props.productCode },
  });
  if (!product) {
    throw new HttpException("Product not found", 404);
  }

  // 2. Find the SKU by code & product FK
  const sku = await MyGlobal.prisma.shopping_skus.findUnique({
    where: { sku_code: props.skuCode },
  });
  if (!sku || sku.shopping_product_id !== product.id) {
    throw new HttpException("SKU not found for this product", 404);
  }

  // 3. Update SKU only with allowed mutable fields
  const updated = await MyGlobal.prisma.shopping_skus.update({
    where: { id: sku.id },
    data: {
      price: props.body.price ?? undefined,
      is_active: props.body.is_active ?? undefined,
      barcode:
        props.body.barcode === undefined ? undefined : props.body.barcode,
      status: props.body.status ?? undefined,
      updated_at: toISOStringSafe(new Date()),
    },
  });

  // 4. Resolve variant attributes for this SKU (variant attributes list)
  const variantAttributes =
    await MyGlobal.prisma.shopping_sku_variants.findMany({
      where: { shopping_sku_id: sku.id },
      orderBy: { order_index: "asc" },
      include: {
        attributeValue: true,
      },
    });

  // 5. Resolve images for this SKU
  const images = await MyGlobal.prisma.shopping_sku_images.findMany({
    where: { shopping_sku_id: sku.id },
    orderBy: { created_at: "asc" },
  });

  // 6. Compose product summary
  const productSummary = {
    id: product.id,
    code: product.code,
    name: product.name,
    main_image_uri: product.main_image_uri ?? undefined,
    status: product.status,
  };

  // 7. Compose IShoppingSku object for return
  return {
    id: updated.id,
    shopping_product_id: updated.shopping_product_id,
    sku_code: updated.sku_code,
    price: updated.price,
    is_active: updated.is_active,
    barcode:
      typeof updated.barcode === "string"
        ? updated.barcode
        : updated.barcode === null
          ? null
          : undefined,
    status: updated.status,
    created_at: toISOStringSafe(updated.created_at),
    updated_at: toISOStringSafe(updated.updated_at),
    deleted_at: updated.deleted_at
      ? toISOStringSafe(updated.deleted_at)
      : undefined,
    variant_attributes: variantAttributes.map((va) => ({
      id: va.id,
      shopping_attribute_value_id: va.shopping_attribute_value_id,
      order_index: va.order_index,
      attribute_value: {
        id: va.attributeValue.id,
        shopping_attribute_dimension_id:
          va.attributeValue.shopping_attribute_dimension_id,
        value_code: va.attributeValue.value_code,
        display_value: va.attributeValue.display_value,
        display_order: va.attributeValue.display_order ?? undefined,
        created_at: toISOStringSafe(va.attributeValue.created_at),
      },
    })),
    product: productSummary,
    images: images.map((img) => ({
      id: img.id,
      shopping_sku_id: img.shopping_sku_id,
      image_uri: img.image_uri,
      created_at: toISOStringSafe(img.created_at),
    })),
  };
}

