import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/client";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";
import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

import { IShoppingShipment } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingShipment";
import { IShoppingOrder } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingOrder";
import { IShoppingCustomer } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingCustomer";
import { IShoppingSeller } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingSeller";
import { IShoppingShipmentPackage } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingShipmentPackage";
import { SellerPayload } from "../decorators/payload/SellerPayload";

export async function putShoppingSellerShipmentsCode(props: {
  seller: SellerPayload;
  code: string;
  body: IShoppingShipment.IUpdate;
}): Promise<IShoppingShipment> {
  // Step 1: Find the shipment by business code, not soft-deleted
  const shipment = await MyGlobal.prisma.shopping_shipments.findFirst({
    where: {
      code: props.code,
      deleted_at: null,
    },
  });
  if (!shipment) {
    throw new HttpException("Shipment not found or has been deleted.", 404);
  }

  // Step 2: Check seller owns the shipment
  if (shipment.shopping_seller_id !== props.seller.id) {
    throw new HttpException("Forbidden: You do not own this shipment.", 403);
  }

  // Step 3: Perform the update (only allowed fields)
  const updated = await MyGlobal.prisma.shopping_shipments.update({
    where: { code: props.code },
    data: {
      status: props.body.status ?? undefined,
      carrier_company: props.body.carrier_company ?? undefined,
      carrier_service_type: props.body.carrier_service_type ?? undefined,
      scheduled_dispatch_at: props.body.scheduled_dispatch_at ?? undefined,
      dispatched_at: props.body.dispatched_at ?? undefined,
      delivered_at: props.body.delivered_at ?? undefined,
      canceled_at: props.body.canceled_at ?? undefined,
      updated_at: toISOStringSafe(new Date()),
    },
  });

  // Step 4: Get shopping_order info
  const order = await MyGlobal.prisma.shopping_orders.findFirst({
    where: { id: updated.shopping_order_id },
    select: {
      id: true,
      order_code: true,
      total_price: true,
      status: true,
      created_at: true,
      updated_at: true,
      shopping_customer_id: true,
    },
  });
  if (!order) {
    throw new HttpException("Order not found.", 500);
  }

  // Step 4b: Get customer info by shopping_customer_id
  const customer = await MyGlobal.prisma.shopping_customers.findFirst({
    where: { id: order.shopping_customer_id },
    select: {
      id: true,
      name: true,
      email: true,
      is_active: true,
      created_at: true,
      deleted_at: true,
    },
  });
  if (!customer) {
    throw new HttpException("Customer not found.", 500);
  }

  // Step 5: Get shopping_seller info
  const seller = await MyGlobal.prisma.shopping_sellers.findFirst({
    where: { id: updated.shopping_seller_id },
    select: {
      id: true,
      display_name: true,
      status: true,
    },
  });
  if (!seller) {
    throw new HttpException("Seller not found.", 500);
  }

  // Step 6: Get packages
  const packages = await MyGlobal.prisma.shopping_shipment_packages.findMany({
    where: { shopping_shipment_id: updated.id },
  });

  return {
    id: updated.id,
    code: updated.code,
    shopping_order_id: updated.shopping_order_id,
    shopping_seller_id: updated.shopping_seller_id,
    status: updated.status,
    carrier_company: updated.carrier_company,
    carrier_service_type:
      typeof updated.carrier_service_type === "string"
        ? updated.carrier_service_type
        : null,
    scheduled_dispatch_at: updated.scheduled_dispatch_at
      ? toISOStringSafe(updated.scheduled_dispatch_at)
      : null,
    dispatched_at: updated.dispatched_at
      ? toISOStringSafe(updated.dispatched_at)
      : null,
    delivered_at: updated.delivered_at
      ? toISOStringSafe(updated.delivered_at)
      : null,
    canceled_at: updated.canceled_at
      ? toISOStringSafe(updated.canceled_at)
      : null,
    created_at: toISOStringSafe(updated.created_at),
    updated_at: toISOStringSafe(updated.updated_at),
    shopping_order: {
      id: order.id,
      order_code: order.order_code,
      total_price: order.total_price,
      status: order.status,
      created_at: toISOStringSafe(order.created_at),
      updated_at: toISOStringSafe(order.updated_at),
      customer: {
        id: customer.id,
        name: customer.name,
        email: customer.email,
        is_active: customer.is_active,
        created_at: toISOStringSafe(customer.created_at),
        deleted_at: customer.deleted_at
          ? toISOStringSafe(customer.deleted_at)
          : null,
      },
    },
    shopping_seller: {
      id: seller.id,
      display_name: seller.display_name,
      status: seller.status,
    },
    packages: packages.map((pkg) => ({
      id: pkg.id,
      shopping_shipment_id: pkg.shopping_shipment_id,
      sequence: pkg.sequence,
      package_label: pkg.package_label,
      tracking_number: pkg.tracking_number,
      package_weight_grams: pkg.package_weight_grams,
      length_cm: pkg.length_cm,
      width_cm: pkg.width_cm,
      height_cm: pkg.height_cm,
      status: pkg.status,
      delivered_at: pkg.delivered_at ? toISOStringSafe(pkg.delivered_at) : null,
      lost_at: pkg.lost_at ? toISOStringSafe(pkg.lost_at) : null,
      damaged_at: pkg.damaged_at ? toISOStringSafe(pkg.damaged_at) : null,
      created_at: toISOStringSafe(pkg.created_at),
      updated_at: toISOStringSafe(pkg.updated_at),
      deleted_at: pkg.deleted_at ? toISOStringSafe(pkg.deleted_at) : null,
    })),
    deleted_at: updated.deleted_at ? toISOStringSafe(updated.deleted_at) : null,
  };
}

import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/client";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";
import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

import { IShoppingSellerAddress } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingSellerAddress";
import { SellerPayload } from "../decorators/payload/SellerPayload";

export async function deleteShoppingSellerSellersSellerIdAddressesAddressId(props: {
  seller: SellerPayload;
  sellerId: string & tags.Format<"uuid">;
  addressId: string & tags.Format<"uuid">;
}): Promise<IShoppingSellerAddress> {
  // 1. Fetch the address to delete
  const address = await MyGlobal.prisma.shopping_seller_addresses.findUnique({
    where: { id: props.addressId },
  });
  if (!address) throw new HttpException("Address not found", 404);

  // 2. Authorization check: seller must own the address
  if (address.shopping_seller_id !== props.seller.id) {
    throw new HttpException(
      "Forbidden: You may only delete your own addresses",
      403,
    );
  }

  // 3. Already deleted -> soft delete idempotence
  if (address.deleted_at) {
    // Return transformed address with deleted_at
    return {
      id: address.id,
      shopping_seller_id: address.shopping_seller_id,
      address_line1: address.address_line1,
      address_line2: address.address_line2 ?? undefined,
      city: address.city,
      state: address.state,
      postal_code: address.postal_code,
      country: address.country,
      is_return_address: address.is_return_address,
      is_primary: address.is_primary,
      phone: address.phone,
      recipient_name: "",
      created_at: toISOStringSafe(address.created_at),
      updated_at: toISOStringSafe(address.updated_at),
      deleted_at: address.deleted_at
        ? toISOStringSafe(address.deleted_at)
        : undefined,
    };
  }

  // 4. Prevent if this is the only primary or only return address
  const otherAddresses =
    await MyGlobal.prisma.shopping_seller_addresses.findMany({
      where: {
        shopping_seller_id: props.seller.id,
        id: { not: props.addressId },
        deleted_at: null,
      },
    });
  const hasOtherPrimary = otherAddresses.some((addr) => addr.is_primary);
  const hasOtherReturn = otherAddresses.some((addr) => addr.is_return_address);
  if (
    (!hasOtherPrimary && address.is_primary) ||
    (!hasOtherReturn && address.is_return_address)
  ) {
    throw new HttpException(
      "Cannot delete the only primary or only return address",
      409,
    );
  }

  // 5. Prevent deletion if there are active fulfillments referencing this address
  const activeFulfillment =
    await MyGlobal.prisma.shopping_order_fulfillments.findFirst({
      where: {
        shopping_seller_address_id: props.addressId,
        status: { notIn: ["cancelled"] },
      },
    });
  if (activeFulfillment) {
    throw new HttpException("Address is in use by active fulfillment(s)", 409);
  }

  // 6. Soft delete the address
  const deletedAt = toISOStringSafe(new Date());
  const updated = await MyGlobal.prisma.shopping_seller_addresses.update({
    where: { id: props.addressId },
    data: {
      deleted_at: deletedAt,
      updated_at: deletedAt,
    },
  });

  // 7. Return the updated address DTO
  return {
    id: updated.id,
    shopping_seller_id: updated.shopping_seller_id,
    address_line1: updated.address_line1,
    address_line2:
      typeof updated.address_line2 === "string"
        ? updated.address_line2
        : undefined,
    city: updated.city,
    state: updated.state,
    postal_code: updated.postal_code,
    country: updated.country,
    is_return_address: updated.is_return_address,
    is_primary: updated.is_primary,
    phone: updated.phone,
    recipient_name: "",
    created_at: toISOStringSafe(updated.created_at),
    updated_at: toISOStringSafe(updated.updated_at),
    deleted_at: deletedAt,
  };
}

import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/client";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";
import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

import { IShoppingAttributeValue } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingAttributeValue";
import { IPageIShoppingAttributeValue } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIShoppingAttributeValue";
import { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import { AdminPayload } from "../decorators/payload/AdminPayload";

export async function patchShoppingAdminAttributeDimensionsDimensionCodeValues(props: {
  admin: AdminPayload;
  dimensionCode: string;
  body: IShoppingAttributeValue.IRequest;
}): Promise<IPageIShoppingAttributeValue> {
  const { dimensionCode, body } = props;
  // 1. Lookup attribute dimension (by code, ensure not soft-deleted)
  const dimension =
    await MyGlobal.prisma.shopping_attribute_dimensions.findFirst({
      where: {
        dimension_code: dimensionCode,
      },
    });
  if (!dimension) {
    throw new HttpException("Attribute dimension not found", 404);
  }

  // 2. Extract search/filter/sort/pagination
  const search = body.search?.trim() ? body.search.trim() : undefined;
  const sortBy = body.sort_by || "display_order";
  const sortOrder = body.sort_order === "desc" ? "desc" : "asc";
  const page = body.page ?? 1;
  const limit = body.limit ?? 20;
  const skip = (Number(page) - 1) * Number(limit);

  // 3. Build where clause
  const where = {
    shopping_attribute_dimension_id: dimension.id,
    deleted_at: null,
    ...(search && {
      OR: [
        { display_value: { contains: search } },
        { value_code: { contains: search } },
      ],
    }),
  };

  // 4. Build orderBy clause
  const orderBy = (() => {
    switch (sortBy) {
      case "display_order":
        return { display_order: sortOrder as Prisma.SortOrder };
      case "display_value":
        return { display_value: sortOrder as Prisma.SortOrder };
      case "value_code":
        return { value_code: sortOrder as Prisma.SortOrder };
      case "created_at":
        return { created_at: sortOrder as Prisma.SortOrder };
      default:
        return { display_order: "asc" as Prisma.SortOrder };
    }
  })();

  // 5. Query paginated data and count total
  const [rows, total] = await Promise.all([
    MyGlobal.prisma.shopping_attribute_values.findMany({
      where,
      orderBy,
      skip,
      take: Number(limit),
    }),
    MyGlobal.prisma.shopping_attribute_values.count({ where }),
  ]);

  // 6. Map to DTO
  const data = rows.map((row) => ({
    id: row.id,
    shopping_attribute_dimension_id: row.shopping_attribute_dimension_id,
    value_code: row.value_code,
    display_value: row.display_value,
    display_order: row.display_order ?? null,
    // description: row.description ?? null, // removed: field does not exist
    created_at: toISOStringSafe(row.created_at),
  }));

  // 7. Compose pagination result
  return {
    pagination: {
      current: Number(page),
      limit: Number(limit),
      records: total,
      pages: Math.ceil(total / Number(limit)),
    },
    data,
  };
}

import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/client";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";
import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

import { IShoppingSellerAddress } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingSellerAddress";
import { IPageIShoppingSellerAddress } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIShoppingSellerAddress";
import { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import { AdminPayload } from "../decorators/payload/AdminPayload";

export async function patchShoppingAdminSellersSellerIdAddresses(props: {
  admin: AdminPayload;
  sellerId: string & tags.Format<"uuid">;
  body: IShoppingSellerAddress.IRequest;
}): Promise<IPageIShoppingSellerAddress> {
  const { sellerId, body } = props;

  // 1. Verify seller exists (reject 404 if not)
  const seller = await MyGlobal.prisma.shopping_sellers.findUnique({
    where: { id: sellerId },
  });
  if (!seller) {
    throw new HttpException("Seller not found", 404);
  }

  // 2. Prepare pagination
  const page = body.page ?? 1;
  const limit = body.limit ?? 20;
  const skip = (page - 1) * limit;

  // 3. Prepare filters
  const where = {
    shopping_seller_id: sellerId,
    ...(body.is_primary !== undefined ? { is_primary: body.is_primary } : {}),
    ...(body.is_return_address !== undefined
      ? { is_return_address: body.is_return_address }
      : {}),
    ...(body.city !== undefined ? { city: { contains: body.city } } : {}),
    ...(body.state !== undefined ? { state: { contains: body.state } } : {}),
    ...(body.country !== undefined
      ? { country: { contains: body.country } }
      : {}),
    deleted_at: null,
  };

  // 4. Prepare sorting
  let orderBy: { [key: string]: "asc" | "desc" } = { updated_at: "desc" };
  if (body.sort_by) {
    orderBy = { [body.sort_by]: body.sort_order ?? "desc" };
  }

  // 5. Query records and total count in parallel
  const [rows, total] = await Promise.all([
    MyGlobal.prisma.shopping_seller_addresses.findMany({
      where,
      orderBy,
      skip,
      take: limit,
    }),
    MyGlobal.prisma.shopping_seller_addresses.count({ where }),
  ]);

  // 6. Map results to IShoppingSellerAddress[]
  const data = rows.map((row) => ({
    id: row.id,
    shopping_seller_id: row.shopping_seller_id,
    address_line1: row.address_line1,
    address_line2: row.address_line2 ?? undefined,
    city: row.city,
    state: row.state,
    postal_code: row.postal_code,
    country: row.country,
    is_return_address: row.is_return_address,
    is_primary: row.is_primary,
    phone: row.phone,
    recipient_name: "", // Provide empty fallback since prisma doesn't populate it
    created_at: toISOStringSafe(row.created_at),
    updated_at: toISOStringSafe(row.updated_at),
    deleted_at: row.deleted_at ? toISOStringSafe(row.deleted_at) : undefined,
  }));

  // 7. Construct pagination info
  const pages = Math.ceil(total / limit);

  return {
    pagination: {
      current: page satisfies number as number,
      limit: limit satisfies number as number,
      records: total,
      pages: pages,
    },
    data,
  };
}

import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/client";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";
import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

import { IShoppingCustomer } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingCustomer";

export async function postAuthCustomerPasswordReset(props: {
  body: IShoppingCustomer.ICompletePasswordReset;
}): Promise<IShoppingCustomer.IPasswordResetCompleted> {
  const { reset_code, new_password } = props.body;

  // Step 1: Lookup password reset record by code
  const reset = await MyGlobal.prisma.shopping_password_resets.findUnique({
    where: { reset_code },
  });
  if (!reset) throw new HttpException("Invalid or expired reset token", 404);
  if (reset.consumed_at !== null)
    throw new HttpException("Reset token has already been used", 400);
  const now = toISOStringSafe(new Date());
  if (new Date(reset.expires_at) < new Date(now))
    throw new HttpException("Reset token has expired", 400);

  // Step 2: Password strength validation (min 8 chars, upper, lower, number, symbol)
  if (
    !/^.*(?=.{8,})(?=.*[a-z])(?=.*[A-Z])(?=.*\d)(?=.*[^A-Za-z0-9]).*$/.test(
      new_password,
    )
  ) {
    throw new HttpException(
      "Password does not meet complexity requirements",
      400,
    );
  }

  // Step 3: Find customer
  const customerId = reset.shopping_customer_id;
  const customer = await MyGlobal.prisma.shopping_customers.findUnique({
    where: { id: customerId ?? undefined },
  });
  if (!customer)
    throw new HttpException("Customer not found for password reset", 404);

  // Step 4: Securely hash new password
  const hash = await PasswordUtil.hash(new_password);

  // Step 5 (atomic): Update password and mark reset token consumed
  await MyGlobal.prisma.$transaction([
    MyGlobal.prisma.shopping_customers.update({
      where: { id: customerId ?? undefined },
      data: { password_hash: hash, updated_at: now },
    }),
    MyGlobal.prisma.shopping_password_resets.update({
      where: { reset_code },
      data: { consumed_at: now, updated_at: now },
    }),
  ]);

  return {
    success: true,
    customer_id: (customerId ?? "") satisfies string as string &
      tags.Format<"uuid">,
    reset_token_consumed_at: now,
  };
}

import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/client";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";
import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

import { IShoppingAdminSuspension } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingAdminSuspension";
import { AdminPayload } from "../decorators/payload/AdminPayload";

export async function postShoppingAdminAdminSuspensions(props: {
  admin: AdminPayload;
  body: IShoppingAdminSuspension.ICreate;
}): Promise<IShoppingAdminSuspension> {
  const { admin, body } = props;
  if (!admin || !admin.id) {
    throw new HttpException("Unauthorized: Admin login required", 401);
  }
  const suspendedIds = [
    body.suspended_admin_id,
    body.suspended_seller_id,
    body.suspended_customer_id,
  ];
  const setCount = suspendedIds.filter(
    (x) => x !== null && x !== undefined,
  ).length;
  if (setCount !== 1) {
    throw new HttpException(
      "Exactly one of suspended_admin_id, suspended_seller_id, or suspended_customer_id must be provided",
      400,
    );
  }
  if (body.suspended_admin_id && admin.id === body.suspended_admin_id) {
    throw new HttpException("Cannot suspend oneself", 400);
  }
  const where = {
    ...(body.suspended_admin_id !== undefined &&
      body.suspended_admin_id !== null && {
        suspended_admin_id: body.suspended_admin_id,
      }),
    ...(body.suspended_seller_id !== undefined &&
      body.suspended_seller_id !== null && {
        suspended_seller_id: body.suspended_seller_id,
      }),
    ...(body.suspended_customer_id !== undefined &&
      body.suspended_customer_id !== null && {
        suspended_customer_id: body.suspended_customer_id,
      }),
    status: { notIn: ["revoked", "expired"] },
    deleted_at: null,
  };
  const duplicate = await MyGlobal.prisma.shopping_admin_suspensions.findFirst({
    where,
  });
  if (duplicate) {
    throw new HttpException(
      "Duplicate suspension: There is already an active or pending suspension for this actor.",
      409,
    );
  }
  const id = v4();
  const now = toISOStringSafe(new Date());
  const created = await MyGlobal.prisma.shopping_admin_suspensions.create({
    data: {
      id,
      admin_id: body.admin_id,
      suspended_admin_id: body.suspended_admin_id ?? null,
      suspended_seller_id: body.suspended_seller_id ?? null,
      suspended_customer_id: body.suspended_customer_id ?? null,
      suspension_type: body.suspension_type,
      reason: body.reason,
      start_at: body.start_at,
      end_at: body.end_at ?? null,
      status: body.status,
      created_at: now,
      updated_at: now,
      deleted_at: null,
    },
  });
  return {
    id: created.id,
    admin_id: created.admin_id,
    suspended_admin_id: created.suspended_admin_id ?? undefined,
    suspended_seller_id: created.suspended_seller_id ?? undefined,
    suspended_customer_id: created.suspended_customer_id ?? undefined,
    suspension_type: created.suspension_type,
    reason: created.reason,
    start_at: toISOStringSafe(created.start_at),
    end_at:
      created.end_at != null ? toISOStringSafe(created.end_at) : undefined,
    status: created.status,
    created_at: toISOStringSafe(created.created_at),
    updated_at: toISOStringSafe(created.updated_at),
    deleted_at:
      created.deleted_at != null
        ? toISOStringSafe(created.deleted_at)
        : undefined,
  };
}

import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/client";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";
import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

import { IShoppingRefundRequestItem } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingRefundRequestItem";
import { IShoppingRefundAttachment } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingRefundAttachment";
import { CustomerPayload } from "../decorators/payload/CustomerPayload";

export async function postShoppingCustomerRefundsRefundRequestIdItems(props: {
  customer: CustomerPayload;
  refundRequestId: string & tags.Format<"uuid">;
  body: IShoppingRefundRequestItem.ICreate;
}): Promise<IShoppingRefundRequestItem> {
  const now = toISOStringSafe(new Date());
  const refund = await MyGlobal.prisma.shopping_refund_requests.findUnique({
    where: { id: props.refundRequestId },
    select: {
      id: true,
      shopping_order_id: true,
      shopping_actor_id: true,
      actor_type: true,
      status: true,
      deleted_at: true,
    },
  });
  if (!refund || refund.deleted_at !== null) {
    throw new HttpException("Refund request not found.", 404);
  }
  if (
    refund.shopping_actor_id !== props.customer.id ||
    refund.actor_type !== "customer"
  ) {
    throw new HttpException(
      "Not authorized to add to this refund request.",
      403,
    );
  }
  if (["completed", "closed", "declined"].includes(refund.status)) {
    throw new HttpException(
      "Refund request is not open for modification.",
      409,
    );
  }
  const exists = await MyGlobal.prisma.shopping_refund_request_items.findFirst({
    where: {
      shopping_refund_request_id: props.refundRequestId,
      shopping_order_line_id: props.body.shopping_order_line_id,
    },
    select: { id: true },
  });
  if (exists) {
    throw new HttpException("Duplicate refund item for this order line.", 409);
  }
  const orderLine = await MyGlobal.prisma.shopping_order_lines.findUnique({
    where: { id: props.body.shopping_order_line_id },
    select: {
      id: true,
      shopping_order_id: true,
      quantity: true,
      deleted_at: true,
    },
  });
  if (!orderLine || orderLine.deleted_at !== null) {
    throw new HttpException("Order line not found.", 404);
  }
  if (orderLine.shopping_order_id !== props.body.shopping_order_id) {
    throw new HttpException("Order line does not belong to given order.", 400);
  }
  if (refund.shopping_order_id !== orderLine.shopping_order_id) {
    throw new HttpException(
      "Refund request does not match the order of the line item.",
      400,
    );
  }
  const requested =
    await MyGlobal.prisma.shopping_refund_request_items.aggregate({
      where: {
        shopping_order_line_id: orderLine.id,
        shopping_order_id: orderLine.shopping_order_id,
        shopping_refund_request_id: props.refundRequestId,
      },
      _sum: { quantity: true },
    });
  const alreadyRequested = requested._sum.quantity ?? 0;
  if (
    props.body.quantity < 1 ||
    props.body.quantity + alreadyRequested > orderLine.quantity
  ) {
    throw new HttpException(
      "Requested quantity exceeds available for refund.",
      400,
    );
  }
  const refundItem = await MyGlobal.prisma.shopping_refund_request_items.create(
    {
      data: {
        id: v4(),
        shopping_refund_request_id: props.refundRequestId,
        shopping_order_id: orderLine.shopping_order_id,
        shopping_order_line_id: orderLine.id,
        quantity: props.body.quantity,
        item_business_reason: props.body.item_business_reason ?? null,
        created_at: now,
        updated_at: now,
      },
      select: {
        id: true,
        shopping_refund_request_id: true,
        shopping_order_id: true,
        shopping_order_line_id: true,
        quantity: true,
        item_business_reason: true,
        created_at: true,
        updated_at: true,
      },
    },
  );
  let attachments: IShoppingRefundAttachment[] | undefined = undefined;
  if (props.body.attachments && props.body.attachments.length > 0) {
    const attachRecords = await Promise.all(
      props.body.attachments.map(async (att) => {
        const attNow = toISOStringSafe(new Date());
        const record = await MyGlobal.prisma.shopping_refund_attachments.create(
          {
            data: {
              id: v4(),
              shopping_refund_request_id: props.refundRequestId,
              shopping_refund_request_item_id: refundItem.id,
              attachment_file_id: att.attachment_file_id,
              attachment_type: att.attachment_type,
              description: att.description ?? null,
              uploaded_at: attNow,
            },
            select: {
              id: true,
              shopping_refund_request_id: true,
              shopping_refund_request_item_id: true,
              attachment_file_id: true,
              attachment_type: true,
              description: true,
              uploaded_at: true,
            },
          },
        );
        return {
          id: record.id,
          shopping_refund_request_id: record.shopping_refund_request_id,
          shopping_refund_request_item_id:
            record.shopping_refund_request_item_id,
          attachment_file_id: record.attachment_file_id,
          attachment_type: record.attachment_type,
          description: record.description,
          uploaded_at: toISOStringSafe(record.uploaded_at),
          file_uri: att.file_uri ?? "",
          file_type: att.file_type ?? "",
          file_size: att.file_size ?? 0,
        } satisfies IShoppingRefundAttachment;
      }),
    );
    attachments = attachRecords;
  }
  return {
    id: refundItem.id,
    shopping_refund_request_id: refundItem.shopping_refund_request_id,
    shopping_order_id: refundItem.shopping_order_id,
    shopping_order_line_id: refundItem.shopping_order_line_id,
    quantity: refundItem.quantity,
    item_business_reason: refundItem.item_business_reason ?? null,
    created_at: toISOStringSafe(refundItem.created_at),
    updated_at: toISOStringSafe(refundItem.updated_at),
    attachments,
  };
}

import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/client";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";
import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

import { IShoppingRefundRequest } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingRefundRequest";
import { IShoppingRefundRequestItem } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingRefundRequestItem";
import { IShoppingRefundAttachment } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingRefundAttachment";
import { IShoppingOrder } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingOrder";
import { IShoppingCustomer } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingCustomer";
import { IShoppingRefundActor } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingRefundActor";
import { IShoppingRefundStatusHistory } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingRefundStatusHistory";
import { IShoppingRefundApproval } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingRefundApproval";
import { IShoppingRefundAdminOverride } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingRefundAdminOverride";
import { SellerPayload } from "../decorators/payload/SellerPayload";

export async function postShoppingSellerRefunds(props: {
  seller: SellerPayload;
  body: IShoppingRefundRequest.ICreate;
}): Promise<IShoppingRefundRequest> {
  const { seller, body } = props;
  // Get order info
  const order = await MyGlobal.prisma.shopping_orders.findFirst({
    where: { id: body.shopping_order_id, deleted_at: null },
    include: { customer: true },
  });
  if (!order) throw new HttpException("Order not found", 404);
  // Get all order lines for this order belonging to seller
  const sellerOrderLines = await MyGlobal.prisma.shopping_order_lines.findMany({
    where: {
      shopping_order_id: body.shopping_order_id,
      shopping_seller_id: seller.id,
      deleted_at: null,
    },
  });
  const validOrderLineIds = new Set(sellerOrderLines.map((l) => l.id));
  // Validate every item in body.items is for a line belonging to this seller
  for (const item of body.items) {
    if (!validOrderLineIds.has(item.shopping_order_line_id)) {
      throw new HttpException(
        "Refund request item does not belong to seller's order lines",
        400,
      );
    }
    // Check if duplicate refund request already exists for this order line
    const dup = await MyGlobal.prisma.shopping_refund_request_items.findFirst({
      where: {
        shopping_order_line_id: item.shopping_order_line_id,
        refundRequest: { order: { id: body.shopping_order_id } },
      },
    });
    if (dup) {
      throw new HttpException(
        "A refund request for this order line already exists",
        409,
      );
    }
  }
  const now = toISOStringSafe(new Date());
  const refundRequestId = v4();
  // Create refund request
  const createdRefund = await MyGlobal.prisma.shopping_refund_requests.create({
    data: {
      id: refundRequestId,
      shopping_order_id: body.shopping_order_id,
      shopping_actor_id: seller.id,
      actor_type: "seller",
      request_type: body.request_type,
      business_reason: body.business_reason,
      request_context: body.request_context ?? null,
      status: "pending",
      created_at: now,
      updated_at: now,
      deleted_at: null,
    },
  });
  // Create all refund request items
  const refundRequestItemsResults = await Promise.all(
    body.items.map(async (item) => {
      const itemId = v4();
      const createdItem =
        await MyGlobal.prisma.shopping_refund_request_items.create({
          data: {
            id: itemId,
            shopping_refund_request_id: refundRequestId,
            shopping_order_id: body.shopping_order_id,
            shopping_order_line_id: item.shopping_order_line_id,
            quantity: item.quantity,
            item_business_reason: item.item_business_reason ?? null,
            created_at: now,
            updated_at: now,
          },
        });
      return { ...createdItem, attachments: [] };
    }),
  );
  // Prepare all attachments list (attachments for request & those for each item)
  const allAttachments: Array<IShoppingRefundAttachment> = [];
  // Attachments for request (no shopping_refund_request_item_id)
  if (body.attachments && body.attachments.length) {
    for (const att of body.attachments) {
      const attId = v4();
      const newAtt = await MyGlobal.prisma.shopping_refund_attachments.create({
        data: {
          id: attId,
          shopping_refund_request_id: refundRequestId,
          shopping_refund_request_item_id: null,
          attachment_file_id: att.attachment_file_id,
          attachment_type: att.attachment_type,
          description: att.description ?? null,
          uploaded_at: now,
        },
      });
      allAttachments.push({
        ...newAtt,
        shopping_refund_request_item_id: null,
        file_uri: att.file_uri,
        file_type: att.file_type,
        file_size: att.file_size,
        uploaded_at: toISOStringSafe(newAtt.uploaded_at),
      });
    }
  }
  // Attachments per item
  for (let idx = 0; idx < body.items.length; ++idx) {
    const item = body.items[idx];
    const itemId = refundRequestItemsResults[idx].id;
    if (item.attachments && item.attachments.length) {
      for (const att of item.attachments) {
        const attId = v4();
        const newAtt = await MyGlobal.prisma.shopping_refund_attachments.create(
          {
            data: {
              id: attId,
              shopping_refund_request_id: refundRequestId,
              shopping_refund_request_item_id: itemId,
              attachment_file_id: att.attachment_file_id,
              attachment_type: att.attachment_type,
              description: att.description ?? null,
              uploaded_at: now,
            },
          },
        );
        allAttachments.push({
          ...newAtt,
          file_uri: att.file_uri,
          file_type: att.file_type,
          file_size: att.file_size,
          uploaded_at: toISOStringSafe(newAtt.uploaded_at),
        });
      }
    }
  }
  // Create status history
  const statusHistoryId = v4();
  const statusHistory =
    await MyGlobal.prisma.shopping_refund_status_histories.create({
      data: {
        id: statusHistoryId,
        shopping_refund_request_id: refundRequestId,
        shopping_actor_id: seller.id,
        actor_type: "seller",
        previous_status: "pending",
        new_status: "pending",
        timestamp: now,
        change_context: "Request created",
      },
    });
  // Build DTO
  const IShoppingOrderSummary: IShoppingOrder.ISummary = {
    id: order.id,
    order_code: order.order_code,
    total_price: order.total_price,
    status: order.status,
    created_at: order.created_at ? toISOStringSafe(order.created_at) : now,
    updated_at: order.updated_at ? toISOStringSafe(order.updated_at) : now,
    customer: {
      id: order.customer.id,
      name: order.customer.name,
      email: order.customer.email,
      is_active: order.customer.is_active,
      created_at: order.customer.created_at
        ? toISOStringSafe(order.customer.created_at)
        : now,
      deleted_at: order.customer.deleted_at
        ? toISOStringSafe(order.customer.deleted_at)
        : null,
    },
  };
  const IShoppingRefundActorSummary: IShoppingRefundActor.ISummary = {
    actor_type: "seller",
    id: seller.id,
    name: (await MyGlobal.prisma.shopping_sellers.findFirst({
      where: { id: seller.id },
    }))!.display_name,
  };
  const items: IShoppingRefundRequestItem[] = await Promise.all(
    refundRequestItemsResults.map(async (item) => {
      const attachments = allAttachments.filter(
        (a) => a.shopping_refund_request_item_id === item.id,
      );
      return {
        id: item.id,
        shopping_refund_request_id: item.shopping_refund_request_id,
        shopping_order_id: item.shopping_order_id,
        shopping_order_line_id: item.shopping_order_line_id,
        quantity: item.quantity,
        item_business_reason: item.item_business_reason ?? undefined,
        created_at: toISOStringSafe(item.created_at),
        updated_at: toISOStringSafe(item.updated_at),
        attachments: attachments.length ? attachments : undefined,
      };
    }),
  );
  const status_histories: IShoppingRefundStatusHistory[] = [
    {
      id: statusHistory.id,
      shopping_refund_request_id: refundRequestId,
      shopping_actor_id: seller.id,
      actor_type: "seller",
      previous_status: "pending",
      new_status: "pending",
      timestamp: now,
      change_context: "Request created",
    },
  ];
  return {
    id: refundRequestId,
    order: IShoppingOrderSummary,
    actor: IShoppingRefundActorSummary,
    request_type: body.request_type,
    business_reason: body.business_reason,
    request_context: body.request_context ?? undefined,
    status: "pending",
    created_at: now,
    updated_at: now,
    deleted_at: null,
    items,
    attachments: allAttachments.filter(
      (a) => a.shopping_refund_request_item_id == null,
    ),
    status_histories,
    approvals: [],
    admin_overrides: [],
  };
}

import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/client";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";
import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

import { IShoppingRefundRequest } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingRefundRequest";
import { IShoppingOrder } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingOrder";
import { IShoppingCustomer } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingCustomer";
import { IShoppingRefundActor } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingRefundActor";
