import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/client";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";
import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

import { IShoppingRefundRequest } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingRefundRequest";
import { IShoppingOrder } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingOrder";
import { IShoppingCustomer } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingCustomer";
import { IShoppingRefundActor } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingRefundActor";
import { IShoppingRefundRequestItem } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingRefundRequestItem";
import { IShoppingRefundAttachment } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingRefundAttachment";
import { IShoppingRefundStatusHistory } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingRefundStatusHistory";
import { IShoppingRefundApproval } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingRefundApproval";
import { IShoppingRefundAdminOverride } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingRefundAdminOverride";
import { SellerPayload } from "../decorators/payload/SellerPayload";

export async function getShoppingSellerRefundsRefundRequestId(props: {
  seller: SellerPayload;
  refundRequestId: string & tags.Format<"uuid">;
}): Promise<IShoppingRefundRequest> {
  const refund = await MyGlobal.prisma.shopping_refund_requests.findUnique({
    where: { id: props.refundRequestId },
  });
  if (!refund) throw new HttpException("Refund request not found", 404);
  const items = await MyGlobal.prisma.shopping_refund_request_items.findMany({
    where: { shopping_refund_request_id: refund.id },
    orderBy: { created_at: "asc" },
  });
  if (items.length === 0) throw new HttpException("Refund items missing", 404);
  const orderLineIds = items.map((it) => it.shopping_order_line_id);
  const sellerOwnedOrderLines =
    await MyGlobal.prisma.shopping_order_lines.findMany({
      where: {
        id: { in: orderLineIds },
        shopping_seller_id: props.seller.id,
        deleted_at: null,
      },
      select: { id: true },
    });
  if (sellerOwnedOrderLines.length === 0)
    throw new HttpException(
      "Forbidden: No access to this refund request for this seller",
      403,
    );
  const order = await MyGlobal.prisma.shopping_orders.findUnique({
    where: { id: refund.shopping_order_id },
  });
  if (!order) throw new HttpException("Order not found", 404);
  const orderCustomer = await MyGlobal.prisma.shopping_customers.findUnique({
    where: { id: order.shopping_customer_id },
  });
  if (!orderCustomer) throw new HttpException("Order customer not found", 404);
  let actor: IShoppingRefundActor.ISummary;
  if (refund.actor_type === "seller") {
    const sellerActor = await MyGlobal.prisma.shopping_sellers.findUnique({
      where: { id: refund.shopping_actor_id },
    });
    if (!sellerActor) throw new HttpException("Seller actor not found", 404);
    actor = {
      actor_type: "seller",
      id: sellerActor.id,
      name: sellerActor.display_name,
    };
  } else if (refund.actor_type === "customer") {
    const customerActor = await MyGlobal.prisma.shopping_customers.findUnique({
      where: { id: refund.shopping_actor_id },
    });
    if (!customerActor)
      throw new HttpException("Customer actor not found", 404);
    actor = {
      actor_type: "customer",
      id: customerActor.id,
      name: customerActor.name,
    };
  } else if (refund.actor_type === "admin") {
    const adminActor = await MyGlobal.prisma.shopping_admins.findUnique({
      where: { id: refund.shopping_actor_id },
    });
    if (!adminActor) throw new HttpException("Admin actor not found", 404);
    actor = {
      actor_type: "admin",
      id: adminActor.id,
      name: adminActor.name,
    };
  } else {
    throw new HttpException("Unknown actor type", 500);
  }
  const orderSummary: IShoppingOrder.ISummary = {
    id: order.id,
    order_code: order.order_code,
    total_price: order.total_price,
    status: order.status,
    created_at: toISOStringSafe(order.created_at),
    updated_at: toISOStringSafe(order.updated_at),
    customer: {
      id: orderCustomer.id,
      name: orderCustomer.name,
      email: orderCustomer.email,
      is_active: orderCustomer.is_active,
      created_at: toISOStringSafe(orderCustomer.created_at),
      deleted_at: orderCustomer.deleted_at
        ? toISOStringSafe(orderCustomer.deleted_at)
        : null,
    },
  };
  const attachments =
    await MyGlobal.prisma.shopping_refund_attachments.findMany({
      where: { shopping_refund_request_id: refund.id },
      orderBy: { uploaded_at: "asc" },
    });
  const status_histories =
    await MyGlobal.prisma.shopping_refund_status_histories.findMany({
      where: { shopping_refund_request_id: refund.id },
      orderBy: { timestamp: "asc" },
    });
  const approvals = await MyGlobal.prisma.shopping_refund_approvals.findMany({
    where: { shopping_refund_request_id: refund.id },
    orderBy: { created_at: "asc" },
  });
  const admin_overrides =
    await MyGlobal.prisma.shopping_refund_admin_overrides.findMany({
      where: { shopping_refund_request_id: refund.id },
      orderBy: { created_at: "asc" },
    });
  // Items serialization (with attachment structure correction)
  const lineItemAttachmentsByItem: Record<string, IShoppingRefundAttachment[]> =
    {};
  for (const a of attachments) {
    if (a.shopping_refund_request_item_id) {
      const itemId = a.shopping_refund_request_item_id;
      if (!lineItemAttachmentsByItem[itemId])
        lineItemAttachmentsByItem[itemId] = [];
      lineItemAttachmentsByItem[itemId].push({
        id: a.id,
        shopping_refund_request_id: a.shopping_refund_request_id,
        shopping_refund_request_item_id: a.shopping_refund_request_item_id,
        attachment_file_id: a.attachment_file_id,
        attachment_type: a.attachment_type,
        description: a.description ?? undefined,
        uploaded_at: toISOStringSafe(a.uploaded_at),
        file_uri: "file_uri" in a ? (a as any).file_uri : undefined,
        file_type: "file_type" in a ? (a as any).file_type : undefined,
        file_size: "file_size" in a ? (a as any).file_size : undefined,
      });
    }
  }
  const itemsDto: IShoppingRefundRequestItem[] = items.map((item) => ({
    id: item.id,
    shopping_refund_request_id: item.shopping_refund_request_id,
    shopping_order_id: item.shopping_order_id,
    shopping_order_line_id: item.shopping_order_line_id,
    quantity: item.quantity,
    item_business_reason: item.item_business_reason ?? undefined,
    created_at: toISOStringSafe(item.created_at),
    updated_at: toISOStringSafe(item.updated_at),
    attachments: lineItemAttachmentsByItem[item.id] ?? undefined,
  }));
  // Only those attachments not tied to item
  const requestAttachments: IShoppingRefundAttachment[] = attachments
    .filter((a) => !a.shopping_refund_request_item_id)
    .map((a) => ({
      id: a.id,
      shopping_refund_request_id: a.shopping_refund_request_id,
      shopping_refund_request_item_id: undefined,
      attachment_file_id: a.attachment_file_id,
      attachment_type: a.attachment_type,
      description: a.description ?? undefined,
      uploaded_at: toISOStringSafe(a.uploaded_at),
      file_uri: "file_uri" in a ? (a as any).file_uri : undefined,
      file_type: "file_type" in a ? (a as any).file_type : undefined,
      file_size: "file_size" in a ? (a as any).file_size : undefined,
    }));
  // Status histories mapping
  const statusHistoriesDto: IShoppingRefundStatusHistory[] =
    status_histories.map((h) => ({
      id: h.id,
      shopping_refund_request_id: h.shopping_refund_request_id,
      shopping_actor_id: h.shopping_actor_id,
      actor_type: typia.assert<"customer" | "seller" | "admin">(h.actor_type),
      previous_status: typia.assert<
        | "pending"
        | "awaiting_approval"
        | "approved"
        | "declined"
        | "completed"
        | "escalated"
      >(h.previous_status),
      new_status: typia.assert<
        | "pending"
        | "awaiting_approval"
        | "approved"
        | "declined"
        | "completed"
        | "escalated"
      >(h.new_status),
      timestamp: toISOStringSafe(h.timestamp),
      change_context: h.change_context ?? undefined,
    }));
  // Approvals mapping
  const approvalsDto: IShoppingRefundApproval[] = approvals.map((a) => ({
    id: a.id,
    shopping_refund_request_id: a.shopping_refund_request_id,
    shopping_refund_status_history_id: a.shopping_refund_status_history_id,
    actor_type: typia.assert<"customer" | "seller" | "admin">(a.actor_type),
    actor_id: a.shopping_actor_id,
    action: typia.assert<"approved" | "rejected">(a.action),
    note: a.note ?? undefined,
    created_at: toISOStringSafe(a.created_at),
  }));
  // Admin overrides mapping
  const adminOverridesDto: IShoppingRefundAdminOverride[] = admin_overrides.map(
    (o) => ({
      id: o.id,
      shopping_refund_request_id: o.shopping_refund_request_id,
      shopping_admin_id: o.shopping_admin_id,
      override_type: typia.assert<"force_accept" | "force_reject" | "reassign">(
        o.override_type,
      ),
      reason: o.reason,
      detailed_context: o.detailed_context ?? undefined,
      created_at: toISOStringSafe(o.created_at),
    }),
  );
  return {
    id: refund.id,
    order: orderSummary,
    actor: actor,
    request_type: typia.assert<"refund" | "return" | "cancellation">(
      refund.request_type,
    ),
    business_reason: refund.business_reason,
    request_context: refund.request_context ?? undefined,
    status: typia.assert<
      | "pending"
      | "awaiting_approval"
      | "approved"
      | "declined"
      | "completed"
      | "escalated"
    >(refund.status),
    created_at: toISOStringSafe(refund.created_at),
    updated_at: toISOStringSafe(refund.updated_at),
    deleted_at: refund.deleted_at
      ? toISOStringSafe(refund.deleted_at)
      : undefined,
    items: itemsDto,
    attachments: requestAttachments,
    status_histories: statusHistoriesDto,
    approvals: approvalsDto,
    admin_overrides: adminOverridesDto,
  };
}

import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/client";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";
import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

import { IShoppingAppeal } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingAppeal";
import { IPageIShoppingAppeal } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIShoppingAppeal";
import { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import { CustomerPayload } from "../decorators/payload/CustomerPayload";

export async function patchShoppingCustomerAppeals(props: {
  customer: CustomerPayload;
  body: IShoppingAppeal.IRequest;
}): Promise<IPageIShoppingAppeal.ISummary> {
  const { customer, body } = props;
  const page = body.page ?? 1;
  let limit = body.limit ?? 20;
  if (limit > 100) limit = 100;
  const skip = (page - 1) * limit;

  const ALLOWED_SORT_FIELDS = ["created_at", "status", "decision_at"];
  const sortField =
    body.sort_by && ALLOWED_SORT_FIELDS.includes(body.sort_by)
      ? body.sort_by
      : "created_at";
  const sortDirection = body.sort_direction === "asc" ? "asc" : "desc";

  const where: Record<string, any> = {
    filer_actor_type: "customer",
    filer_actor_id: customer.id,
    ...(body.status !== undefined && { status: body.status }),
    ...(body.type !== undefined && { type: body.type }),
    ...(body.decision !== undefined && { decision: body.decision }),
    ...(body.filer_actor_type !== undefined && {
      filer_actor_type: body.filer_actor_type,
    }),
    ...(body.filer_actor_id !== undefined &&
      body.filer_actor_id !== null && { filer_actor_id: body.filer_actor_id }),
    ...(body.affected_actor_type !== undefined && {
      affected_actor_type: body.affected_actor_type,
    }),
    ...(body.affected_actor_id !== undefined &&
      body.affected_actor_id !== null && {
        affected_actor_id: body.affected_actor_id,
      }),
    ...(body.appeal_of_policy_violation_id !== undefined &&
      body.appeal_of_policy_violation_id !== null && {
        appeal_of_policy_violation_id: body.appeal_of_policy_violation_id,
      }),
    ...(body.appeal_of_suspension_id !== undefined &&
      body.appeal_of_suspension_id !== null && {
        appeal_of_suspension_id: body.appeal_of_suspension_id,
      }),
    ...(body.created_from !== undefined || body.created_to !== undefined
      ? {
          created_at: {
            ...(body.created_from !== undefined && { gte: body.created_from }),
            ...(body.created_to !== undefined && { lte: body.created_to }),
          },
        }
      : {}),
    ...(body.decision_from !== undefined || body.decision_to !== undefined
      ? {
          decision_at: {
            ...(body.decision_from !== undefined && {
              gte: body.decision_from,
            }),
            ...(body.decision_to !== undefined && { lte: body.decision_to }),
          },
        }
      : {}),
    ...(body.search !== undefined &&
      body.search.trim() !== "" && {
        OR: [
          { reason: { contains: body.search } },
          { decision: { contains: body.search } },
        ],
      }),
  };

  const [rows, total] = await Promise.all([
    MyGlobal.prisma.shopping_appeals.findMany({
      where,
      orderBy: { [sortField]: sortDirection },
      skip,
      take: limit,
    }),
    MyGlobal.prisma.shopping_appeals.count({
      where,
    }),
  ]);

  const data = rows.map((row) => ({
    id: row.id,
    status: row.status,
    type: "", // Not present in schema, so empty string
    reason: row.reason,
    filer_actor_type: "customer", // filtered for the customer
    filer_actor_id: customer.id,
    affected_actor_type: "", // no schema support, set to empty string
    affected_actor_id: "", // no schema support, set to empty string
    decision: row.decision ?? null,
    decision_reason: "", // no schema support, set to empty string
    created_at: toISOStringSafe(row.created_at),
    updated_at: toISOStringSafe(row.updated_at),
    decision_at:
      row.decision_at === null || row.decision_at === undefined
        ? null
        : toISOStringSafe(row.decision_at),
    appeal_of_policy_violation_id: row.appeal_of_policy_violation_id ?? null,
    appeal_of_suspension_id: row.appeal_of_suspension_id ?? null,
  }));

  return {
    pagination: {
      current: Number(page),
      limit: Number(limit),
      records: total,
      pages: Math.ceil(total / limit),
    },
    data,
  };
}

import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/client";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";
import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

import { IShoppingRefundRequest } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingRefundRequest";
import { IPageIShoppingRefundRequest } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIShoppingRefundRequest";
import { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import { IShoppingOrder } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingOrder";
import { IShoppingCustomer } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingCustomer";
import { IShoppingRefundActor } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingRefundActor";
import { IShoppingRefundRequestItem } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingRefundRequestItem";
import { CustomerPayload } from "../decorators/payload/CustomerPayload";

export async function patchShoppingCustomerRefunds(props: {
  customer: CustomerPayload;
  body: IShoppingRefundRequest.IRequest;
}): Promise<IPageIShoppingRefundRequest.ISummary> {
  const { customer, body } = props;
  const page =
    typeof body.page === "number" &&
    Number.isInteger(body.page) &&
    body.page > 0
      ? body.page
      : 1;
  const limit =
    typeof body.limit === "number" &&
    Number.isInteger(body.limit) &&
    body.limit > 0 &&
    body.limit <= 100
      ? body.limit
      : 20;

  const where = {
    shopping_actor_id: customer.id,
    actor_type: "customer",
    deleted_at: null,
    ...(body.request_type ? { request_type: body.request_type } : {}),
    ...(body.status ? { status: body.status } : {}),
    ...(body.actor_id ? { shopping_actor_id: body.actor_id } : {}),
    ...(body.order_id ? { shopping_order_id: body.order_id } : {}),
    ...(body.from_date || body.to_date
      ? {
          created_at: {
            ...(body.from_date ? { gte: body.from_date } : {}),
            ...(body.to_date ? { lte: body.to_date } : {}),
          },
        }
      : {}),
  };

  const allowedFields = ["created_at", "updated_at", "status", "request_type"];
  const order_by_field = allowedFields.includes(body.order_by ?? "")
    ? (body.order_by ?? "created_at")
    : "created_at";
  const order_direction = body.order_direction === "asc" ? "asc" : "desc";

  // TypeScript only allows direct literal keys, so handle each case explicitly
  let orderBy: { [key: string]: "asc" | "desc" } = {
    created_at: order_direction,
  };
  if (order_by_field === "updated_at") {
    orderBy = { updated_at: order_direction };
  } else if (order_by_field === "status") {
    orderBy = { status: order_direction };
  } else if (order_by_field === "request_type") {
    orderBy = { request_type: order_direction };
  } // else fallback to created_at

  const [rows, total] = await Promise.all([
    MyGlobal.prisma.shopping_refund_requests.findMany({
      where,
      orderBy,
      skip: (page - 1) * limit,
      take: limit,
    }),
    MyGlobal.prisma.shopping_refund_requests.count({ where }),
  ]);

  const orderIdSet: Set<string> = new Set();
  const refundIds: Set<string> = new Set();
  const actorIdSet: Set<string> = new Set();
  rows.forEach((r) => {
    orderIdSet.add(r.shopping_order_id);
    refundIds.add(r.id);
    actorIdSet.add(r.shopping_actor_id);
  });

  const [orders, customers, items] = await Promise.all([
    MyGlobal.prisma.shopping_orders.findMany({
      where: { id: { in: Array.from(orderIdSet) } },
      select: {
        id: true,
        order_code: true,
        total_price: true,
        status: true,
        created_at: true,
        updated_at: true,
        shopping_customer_id: true,
      },
    }),
    MyGlobal.prisma.shopping_customers.findMany({
      where: { id: { in: Array.from(actorIdSet) } },
      select: {
        id: true,
        name: true,
        email: true,
        is_active: true,
        created_at: true,
        deleted_at: true,
      },
    }),
    MyGlobal.prisma.shopping_refund_request_items.findMany({
      where: { shopping_refund_request_id: { in: Array.from(refundIds) } },
      select: {
        id: true,
        shopping_refund_request_id: true,
        shopping_order_line_id: true,
        quantity: true,
        item_business_reason: true,
        created_at: true,
        updated_at: true,
      },
    }),
  ]);

  const orderMap: Record<string, (typeof orders)[number]> = {};
  const customerMap: Record<string, (typeof customers)[number]> = {};
  const itemsMap: Record<string, typeof items> = {};
  orders.forEach((o) => {
    orderMap[o.id] = o;
  });
  customers.forEach((c) => {
    customerMap[c.id] = c;
  });
  items.forEach((i) => {
    if (!itemsMap[i.shopping_refund_request_id])
      itemsMap[i.shopping_refund_request_id] = [];
    itemsMap[i.shopping_refund_request_id].push(i);
  });

  const data = rows.map((refund) => {
    const order = orderMap[refund.shopping_order_id];
    const actor = customerMap[refund.shopping_actor_id];
    const orderSummary: IShoppingOrder.ISummary = {
      id: order.id,
      order_code: order.order_code,
      total_price: order.total_price,
      status: order.status,
      created_at: toISOStringSafe(order.created_at),
      updated_at: toISOStringSafe(order.updated_at),
      customer: {
        id: actor.id,
        name: actor.name,
        email: actor.email,
        is_active: actor.is_active,
        created_at: toISOStringSafe(actor.created_at),
        deleted_at:
          actor.deleted_at === null ? null : toISOStringSafe(actor.deleted_at),
      },
    };
    const actorSummary: IShoppingRefundActor.ISummary = {
      actor_type: "customer",
      id: actor.id,
      name: actor.name,
    };
    const refundItems = (itemsMap[refund.id] || []).map((i) => ({
      id: i.id,
      shopping_refund_request_id: i.shopping_refund_request_id,
      order_line_id: i.shopping_order_line_id,
      quantity: i.quantity,
      item_business_reason: i.item_business_reason ?? undefined,
      created_at: toISOStringSafe(i.created_at),
      updated_at: toISOStringSafe(i.updated_at),
    }));
    return {
      id: refund.id,
      order: orderSummary,
      actor: actorSummary,
      request_type: refund.request_type,
      business_reason: refund.business_reason,
      request_context: refund.request_context ?? undefined,
      status: refund.status,
      created_at: toISOStringSafe(refund.created_at),
      updated_at: toISOStringSafe(refund.updated_at),
      items: refundItems,
    };
  });

  return {
    pagination: {
      current: Number(page),
      limit: Number(limit),
      records: total,
      pages: Math.ceil(total / limit),
    },
    data,
  };
}

import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/client";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";
import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

import { IShoppingReview } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingReview";
import { IPageIShoppingReview } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIShoppingReview";
import { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import { IShoppingCustomer } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingCustomer";
import { IShoppingSku } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingSku";
import { CustomerPayload } from "../decorators/payload/CustomerPayload";

export async function patchShoppingCustomerReviews(props: {
  customer: CustomerPayload;
  body: IShoppingReview.IRequest;
}): Promise<IPageIShoppingReview.ISummary> {
  const { customer, body } = props;

  // Pagination
  const page = body.page;
  const limit = body.limit <= 100 ? body.limit : 100;
  const skip = (page - 1) * limit;

  // Build created_at range if present
  let createdAtFilter: { gte?: string; lte?: string } | undefined = undefined;
  if (body.created_at_from !== undefined && body.created_at_from !== null) {
    createdAtFilter = { ...(createdAtFilter ?? {}), gte: body.created_at_from };
  }
  if (body.created_at_to !== undefined && body.created_at_to !== null) {
    createdAtFilter = { ...(createdAtFilter ?? {}), lte: body.created_at_to };
  }

  // Build where clause
  const where = {
    shopping_customer_id: customer.id,
    deleted_at: null,
    ...(body.review_state !== undefined && { state: body.review_state }),
    ...(body.star_rating !== undefined && { rating: body.star_rating }),
    ...(body.sku_id !== undefined && { shopping_sku_id: body.sku_id }),
    ...(body.order_line_id !== undefined && {
      shopping_order_line_id: body.order_line_id,
    }),
    ...(createdAtFilter !== undefined && { created_at: createdAtFilter }),
    ...(body.query !== undefined && { comment: { contains: body.query } }),
  };

  // Sorting - use type assertion to literal 'asc' | 'desc'
  const orderBy =
    body.sort_by !== undefined
      ? [
          {
            [body.sort_by]: (body.sort_order === "asc" ? "asc" : "desc") as
              | "asc"
              | "desc",
          },
        ]
      : [{ created_at: "desc" as "desc" }];

  // Fetch total count for pagination
  const total = await MyGlobal.prisma.shopping_reviews.count({ where });

  // Fetch paginated reviews (with customer and sku relations)
  const rows = await MyGlobal.prisma.shopping_reviews.findMany({
    where,
    orderBy,
    skip,
    take: limit,
    include: {
      customer: true,
      sku: true,
    },
  });

  // Map results to IShoppingReview.ISummary[]
  const data = rows.map((review: any) => ({
    id: review.id,
    customer: {
      id: review.customer.id,
      name: review.customer.name,
      email: review.customer.email,
      is_active: review.customer.is_active,
      created_at: toISOStringSafe(review.customer.created_at),
      deleted_at:
        review.customer.deleted_at !== null &&
        review.customer.deleted_at !== undefined
          ? toISOStringSafe(review.customer.deleted_at)
          : null,
    },
    sku: {
      id: review.sku.id,
      sku_code: review.sku.sku_code,
      price: review.sku.price,
      is_active: review.sku.is_active,
      status: review.sku.status,
    },
    order_line_id: review.shopping_order_line_id,
    rating: review.rating,
    comment: review.comment,
    state: review.state,
    created_at: toISOStringSafe(review.created_at),
    updated_at: toISOStringSafe(review.updated_at),
  }));

  // Final paginated response
  return {
    pagination: {
      current: Number(page),
      limit: Number(limit),
      records: total,
      pages: Math.ceil(total / limit),
    },
    data,
  };
}

