      attachment_file_id: props.body.attachment_file_id,
      attachment_type: props.body.attachment_type,
      description: props.body.description ?? null,
      uploaded_at: now,
    },
  });
  // Step 3: Compose DTO, echoing non-DB fields from the input
  return {
    id: created.id,
    shopping_refund_request_id: created.shopping_refund_request_id,
    shopping_refund_request_item_id:
      created.shopping_refund_request_item_id ?? undefined,
    attachment_file_id: created.attachment_file_id,
    attachment_type: created.attachment_type,
    description: created.description ?? undefined,
    uploaded_at: toISOStringSafe(created.uploaded_at),
    file_uri: props.body.file_uri,
    file_type: props.body.file_type,
    file_size: props.body.file_size,
  };
}

import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/client";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";
import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

import { IShoppingSellerAddress } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingSellerAddress";
import { SellerPayload } from "../decorators/payload/SellerPayload";

export async function postShoppingSellerSellersSellerIdAddresses(props: {
  seller: SellerPayload;
  sellerId: string & tags.Format<"uuid">;
  body: IShoppingSellerAddress.ICreate;
}): Promise<IShoppingSellerAddress> {
  const { seller, sellerId, body } = props;

  if (sellerId !== seller.id) {
    throw new HttpException(
      "Forbidden: Cannot create address for another seller.",
      403,
    );
  }

  // Duplicate detection WITHOUT recipient_name, which doesn't exist in schema
  const duplicate = await MyGlobal.prisma.shopping_seller_addresses.findFirst({
    where: {
      shopping_seller_id: sellerId,
      address_line1: body.address_line1,
      address_line2: body.address_line2 ?? null,
      city: body.city,
      state: body.state,
      postal_code: body.postal_code,
      country: body.country,
      is_primary: body.is_primary,
      is_return_address: body.is_return_address,
      phone: body.phone,
      deleted_at: null,
    },
  });
  if (duplicate) {
    throw new HttpException(
      "Conflict: Address with same fields already exists.",
      409,
    );
  }

  if (body.is_primary) {
    const primaryExists =
      await MyGlobal.prisma.shopping_seller_addresses.findFirst({
        where: {
          shopping_seller_id: sellerId,
          is_primary: true,
          deleted_at: null,
        },
      });
    if (primaryExists) {
      throw new HttpException(
        "Conflict: Only one primary address is allowed per seller.",
        409,
      );
    }
  }

  if (body.is_return_address) {
    const returnExists =
      await MyGlobal.prisma.shopping_seller_addresses.findFirst({
        where: {
          shopping_seller_id: sellerId,
          is_return_address: true,
          deleted_at: null,
        },
      });
    if (returnExists) {
      throw new HttpException(
        "Conflict: Only one return address is allowed per seller.",
        409,
      );
    }
  }

  const now = toISOStringSafe(new Date());
  const created = await MyGlobal.prisma.shopping_seller_addresses.create({
    data: {
      id: v4(),
      shopping_seller_id: sellerId,
      address_line1: body.address_line1,
      address_line2: body.address_line2 ?? null,
      city: body.city,
      state: body.state,
      postal_code: body.postal_code,
      country: body.country,
      is_primary: body.is_primary,
      is_return_address: body.is_return_address,
      phone: body.phone,
      created_at: now,
      updated_at: now,
    },
  });
  return {
    id: created.id,
    shopping_seller_id: created.shopping_seller_id,
    address_line1: created.address_line1,
    address_line2: created.address_line2 ?? undefined,
    city: created.city,
    state: created.state,
    postal_code: created.postal_code,
    country: created.country,
    is_primary: created.is_primary,
    is_return_address: created.is_return_address,
    phone: created.phone,
    recipient_name: body.recipient_name,
    created_at: toISOStringSafe(created.created_at),
    updated_at: toISOStringSafe(created.updated_at),
    deleted_at:
      created.deleted_at !== null && created.deleted_at !== undefined
        ? toISOStringSafe(created.deleted_at)
        : undefined,
  };
}

import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/client";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";
import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

import { IShoppingAppeal } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingAppeal";
import { IShoppingPolicyViolation } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingPolicyViolation";
import { IShoppingBusinessPolicy } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingBusinessPolicy";
import { IShoppingAdminSuspension } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingAdminSuspension";
import { AdminPayload } from "../decorators/payload/AdminPayload";

export async function putShoppingAdminAppealsAppealId(props: {
  admin: AdminPayload;
  appealId: string & tags.Format<"uuid">;
  body: IShoppingAppeal.IUpdate;
}): Promise<IShoppingAppeal> {
  // Find the target appeal (must not be soft-deleted)
  const appeal = await MyGlobal.prisma.shopping_appeals.findUnique({
    where: { id: props.appealId, deleted_at: null },
  });
  if (!appeal) throw new HttpException("Appeal not found", 404);

  const data: Record<string, unknown> = {
    updated_at: toISOStringSafe(new Date()),
  };
  if (props.body.status !== undefined) data.status = props.body.status;
  if (props.body.decision !== undefined) data.decision = props.body.decision;
  if (props.body.decision_at !== undefined)
    data.decision_at = props.body.decision_at;
  if (props.body.reason !== undefined) data.reason = props.body.reason;

  const updated = await MyGlobal.prisma.shopping_appeals.update({
    where: { id: props.appealId },
    data,
  });

  // Determine filer_actor_type/id
  let filer_actor_type: string;
  let filer_actor_id: string & tags.Format<"uuid">;
  if (updated.filed_by_admin_id) {
    filer_actor_type = "admin";
    filer_actor_id = updated.filed_by_admin_id as string & tags.Format<"uuid">;
  } else if (updated.filed_by_seller_id) {
    filer_actor_type = "seller";
    filer_actor_id = updated.filed_by_seller_id as string & tags.Format<"uuid">;
  } else if (updated.filed_by_customer_id) {
    filer_actor_type = "customer";
    filer_actor_id = updated.filed_by_customer_id as string &
      tags.Format<"uuid">;
  } else {
    filer_actor_type = "unknown";
    filer_actor_id = "" as string & tags.Format<"uuid">;
  }

  // Map type (appeal type) based on referenced fields
  let type = "account_action";
  if (updated.appeal_of_suspension_id) type = "suspension";
  else if (updated.appeal_of_policy_violation_id) type = "policy_violation";

  // Determine affected actor info (not available in core appeals schema, set undefined)
  let affected_actor_type: string | undefined = undefined;
  let affected_actor_id: (string & tags.Format<"uuid">) | undefined = undefined;
  // Only possible to deduce by joining related tables, omitted here.

  // Create audit event if status actually changes
  let audit_history: IShoppingAppeal.IAuditHistory[] | undefined = undefined;
  if (
    (props.body.status !== undefined && appeal.status !== props.body.status) ||
    (props.body.decision !== undefined &&
      appeal.decision !== props.body.decision)
  ) {
    audit_history = [
      {
        timestamp: toISOStringSafe(updated.updated_at),
        status_from: appeal.status,
        status_to: updated.status,
        actor_type: "admin",
        actor_id: props.admin.id,
        context:
          props.body.reason !== undefined ? props.body.reason : undefined,
      },
    ];
  }

  return {
    id: updated.id,
    status: updated.status,
    type,
    reason: updated.reason,
    filer_actor_type,
    filer_actor_id,
    affected_actor_type,
    affected_actor_id,
    appeal_of_policy_violation_id:
      updated.appeal_of_policy_violation_id ?? undefined,
    appeal_of_suspension_id: updated.appeal_of_suspension_id ?? undefined,
    decision: updated.decision ?? undefined,
    decision_reason: undefined,
    decision_at: updated.decision_at
      ? toISOStringSafe(updated.decision_at)
      : undefined,
    created_at: toISOStringSafe(updated.created_at),
    updated_at: toISOStringSafe(updated.updated_at),
    audit_history,
    attachments: undefined,
    related_policy_violation: undefined,
    related_suspension: undefined,
  };
}

import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/client";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";
import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

import { IShoppingRefundRequest } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingRefundRequest";
import { IShoppingOrder } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingOrder";
import { IShoppingCustomer } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingCustomer";
import { IShoppingRefundActor } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingRefundActor";
import { IShoppingRefundRequestItem } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingRefundRequestItem";
import { IShoppingRefundAttachment } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingRefundAttachment";
import { IShoppingRefundStatusHistory } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingRefundStatusHistory";
import { IShoppingRefundApproval } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingRefundApproval";
import { IShoppingRefundAdminOverride } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingRefundAdminOverride";
import { AdminPayload } from "../decorators/payload/AdminPayload";

export async function putShoppingAdminRefundsRefundRequestId(props: {
  admin: AdminPayload;
  refundRequestId: string & tags.Format<"uuid">;
  body: IShoppingRefundRequest.IUpdate;
}): Promise<IShoppingRefundRequest> {
  // 1. Check refund request exists and is not soft-deleted
  const dbRequest = await MyGlobal.prisma.shopping_refund_requests.findUnique({
    where: { id: props.refundRequestId },
  });
  if (!dbRequest || dbRequest.deleted_at !== null) {
    throw new HttpException("Refund request not found", 404);
  }
  // 2. Update refund request (patch only supplied fields, force updated_at)
  const updated = await MyGlobal.prisma.shopping_refund_requests.update({
    where: { id: props.refundRequestId },
    data: {
      ...(props.body.business_reason !== undefined
        ? { business_reason: props.body.business_reason }
        : {}),
      ...(props.body.status !== undefined ? { status: props.body.status } : {}),
      ...(props.body.request_context !== undefined
        ? { request_context: props.body.request_context }
        : {}),
      updated_at: toISOStringSafe(new Date()),
    },
  });
  // 3. Fetch related order (with customer info)
  const order = await MyGlobal.prisma.shopping_orders.findUnique({
    where: { id: updated.shopping_order_id },
    include: { customer: true },
  });
  if (!order || !order.customer) {
    throw new HttpException("Associated order or customer not found", 500);
  }
  // 4. Fetch actor (customer); only supporting customer for now
  const actorCustomer = await MyGlobal.prisma.shopping_customers.findUnique({
    where: { id: updated.shopping_actor_id },
  });
  if (!actorCustomer) {
    throw new HttpException("Associated refund actor not found", 500);
  }
  // 5. Fetch items
  const itemsRaw = await MyGlobal.prisma.shopping_refund_request_items.findMany(
    {
      where: { shopping_refund_request_id: props.refundRequestId },
    },
  );
  const items: IShoppingRefundRequestItem[] = itemsRaw.map((item) => ({
    id: item.id,
    shopping_refund_request_id: item.shopping_refund_request_id,
    shopping_order_id: item.shopping_order_id,
    shopping_order_line_id: item.shopping_order_line_id,
    quantity: item.quantity,
    item_business_reason: item.item_business_reason ?? undefined,
    created_at: toISOStringSafe(item.created_at),
    updated_at: toISOStringSafe(item.updated_at),
    attachments: undefined,
  }));
  // 6. Fetch attachments; set file_uri/type/size to safe defaults (should be from storage system)
  const attachmentsRaw =
    await MyGlobal.prisma.shopping_refund_attachments.findMany({
      where: { shopping_refund_request_id: props.refundRequestId },
    });
  const attachments: IShoppingRefundAttachment[] = attachmentsRaw.map(
    (att) => ({
      id: att.id,
      shopping_refund_request_id: att.shopping_refund_request_id,
      shopping_refund_request_item_id:
        att.shopping_refund_request_item_id ?? undefined,
      attachment_file_id: att.attachment_file_id,
      attachment_type: att.attachment_type,
      description: att.description ?? undefined,
      uploaded_at: toISOStringSafe(att.uploaded_at),
      file_uri: "",
      file_type: "",
      file_size: 0,
    }),
  );
  // 7. Fetch status histories
  const historiesRaw =
    await MyGlobal.prisma.shopping_refund_status_histories.findMany({
      where: { shopping_refund_request_id: props.refundRequestId },
    });
  const status_histories: IShoppingRefundStatusHistory[] = historiesRaw.map(
    (hist) => ({
      id: hist.id,
      shopping_refund_request_id: hist.shopping_refund_request_id,
      shopping_actor_id: hist.shopping_actor_id,
      actor_type: typia.assert<"customer" | "seller" | "admin">(
        hist.actor_type,
      ),
      previous_status: hist.previous_status,
      new_status: hist.new_status,
      timestamp: toISOStringSafe(hist.timestamp),
      change_context: hist.change_context ?? undefined,
    }),
  );
  // 8. Fetch approvals
  const approvalsRaw = await MyGlobal.prisma.shopping_refund_approvals.findMany(
    {
      where: { shopping_refund_request_id: props.refundRequestId },
    },
  );
  const approvals: IShoppingRefundApproval[] = approvalsRaw.map((appr) => ({
    id: appr.id,
    shopping_refund_request_id: appr.shopping_refund_request_id,
    shopping_refund_status_history_id: appr.shopping_refund_status_history_id,
    actor_type: appr.actor_type,
    actor_id: appr.shopping_actor_id, // <-- fixed: use shopping_actor_id
    action: appr.action,
    note: appr.note ?? undefined,
    created_at: toISOStringSafe(appr.created_at),
  }));
  // 9. Fetch admin overrides
  const overridesRaw =
    await MyGlobal.prisma.shopping_refund_admin_overrides.findMany({
      where: { shopping_refund_request_id: props.refundRequestId },
    });
  const admin_overrides: IShoppingRefundAdminOverride[] = overridesRaw.map(
    (ovr) => ({
      id: ovr.id,
      shopping_refund_request_id: ovr.shopping_refund_request_id,
      shopping_admin_id: ovr.shopping_admin_id,
      override_type: ovr.override_type,
      reason: ovr.reason,
      detailed_context: ovr.detailed_context ?? undefined,
      created_at: toISOStringSafe(ovr.created_at),
    }),
  );
  // 10. Build ISummary order
  const orderSummary: IShoppingOrder.ISummary = {
    id: order.id,
    order_code: order.order_code,
    total_price: order.total_price,
    status: order.status,
    created_at: toISOStringSafe(order.created_at),
    updated_at: toISOStringSafe(order.updated_at),
    customer: {
      id: order.customer.id,
      name: order.customer.name,
      email: order.customer.email,
      is_active: order.customer.is_active,
      created_at: toISOStringSafe(order.customer.created_at),
      deleted_at: order.customer.deleted_at
        ? toISOStringSafe(order.customer.deleted_at)
        : null,
    },
  };
  // 11. Build refund actor summary (currently supports only customer type)
  const actor: IShoppingRefundActor.ISummary = {
    actor_type: "customer",
    id: actorCustomer.id,
    name: actorCustomer.name,
  };
  return {
    id: updated.id,
    order: orderSummary,
    actor,
    request_type: typia.assert<"refund" | "return" | "cancellation">(
      updated.request_type,
    ),
    business_reason: updated.business_reason,
    request_context: updated.request_context ?? undefined,
    status: updated.status,
    created_at: toISOStringSafe(updated.created_at),
    updated_at: toISOStringSafe(updated.updated_at),
    deleted_at: updated.deleted_at
      ? toISOStringSafe(updated.deleted_at)
      : undefined,
    items,
    attachments,
    status_histories,
    approvals,
    admin_overrides,
  };
}

import { HttpException } from "@nestjs/common";
