export async function putShoppingAdminShipmentsCode(props: {
  admin: AdminPayload;
  code: string;
  body: IShoppingShipment.IUpdate;
}): Promise<IShoppingShipment> {
  const { code, body } = props;
  // Step 1: Find shipment by code (only not soft-deleted)
  const shipment = await MyGlobal.prisma.shopping_shipments.findFirst({
    where: {
      code,
      deleted_at: null,
    },
  });
  if (!shipment) {
    throw new HttpException("Shipment not found or already deleted", 404);
  }

  // Step 2: Update mutable shipment fields only
  const updated = await MyGlobal.prisma.shopping_shipments.update({
    where: { code },
    data: {
      status: body.status ?? undefined,
      carrier_company: body.carrier_company ?? undefined,
      carrier_service_type: body.carrier_service_type ?? undefined,
      scheduled_dispatch_at: body.scheduled_dispatch_at ?? undefined,
      dispatched_at: body.dispatched_at ?? undefined,
      delivered_at: body.delivered_at ?? undefined,
      canceled_at: body.canceled_at ?? undefined,
      updated_at: toISOStringSafe(new Date()),
    },
  });

  // Fetch related order
  const order = await MyGlobal.prisma.shopping_orders.findUnique({
    where: { id: updated.shopping_order_id },
    include: { customer: true },
  });
  if (!order) {
    throw new HttpException("Associated order not found", 500);
  }

  // Fetch related seller
  const seller = await MyGlobal.prisma.shopping_sellers.findUnique({
    where: { id: updated.shopping_seller_id },
  });
  if (!seller) {
    throw new HttpException("Associated seller not found", 500);
  }

  // Fetch shipment packages
  const packages = await MyGlobal.prisma.shopping_shipment_packages.findMany({
    where: { shopping_shipment_id: updated.id },
  });

  return {
    id: updated.id,
    code: updated.code,
    shopping_order_id: updated.shopping_order_id,
    shopping_seller_id: updated.shopping_seller_id,
    status: updated.status,
    carrier_company: updated.carrier_company,
    carrier_service_type: updated.carrier_service_type ?? null,
    scheduled_dispatch_at: updated.scheduled_dispatch_at
      ? toISOStringSafe(updated.scheduled_dispatch_at)
      : null,
    dispatched_at: updated.dispatched_at
      ? toISOStringSafe(updated.dispatched_at)
      : null,
    delivered_at: updated.delivered_at
      ? toISOStringSafe(updated.delivered_at)
      : null,
    canceled_at: updated.canceled_at
      ? toISOStringSafe(updated.canceled_at)
      : null,
    created_at: toISOStringSafe(updated.created_at),
    updated_at: toISOStringSafe(updated.updated_at),
    shopping_order: {
      id: order.id,
      order_code: order.order_code,
      total_price: order.total_price,
      status: order.status,
      created_at: toISOStringSafe(order.created_at),
      updated_at: toISOStringSafe(order.updated_at),
      customer: {
        id: order.customer.id,
        name: order.customer.name,
        email: order.customer.email,
        is_active: order.customer.is_active,
        created_at: toISOStringSafe(order.customer.created_at),
        deleted_at: order.customer.deleted_at
          ? toISOStringSafe(order.customer.deleted_at)
          : null,
      },
    },
    shopping_seller: {
      id: seller.id,
      display_name: seller.display_name,
      status: seller.status,
    },
    packages: packages.map((pkg) => ({
      id: pkg.id,
      shopping_shipment_id: pkg.shopping_shipment_id,
      sequence: pkg.sequence,
      package_label: pkg.package_label,
      tracking_number: pkg.tracking_number,
      package_weight_grams: pkg.package_weight_grams,
      length_cm: pkg.length_cm,
      width_cm: pkg.width_cm,
      height_cm: pkg.height_cm,
      status: pkg.status,
      delivered_at: pkg.delivered_at ? toISOStringSafe(pkg.delivered_at) : null,
      lost_at: pkg.lost_at ? toISOStringSafe(pkg.lost_at) : null,
      damaged_at: pkg.damaged_at ? toISOStringSafe(pkg.damaged_at) : null,
      created_at: toISOStringSafe(pkg.created_at),
      updated_at: toISOStringSafe(pkg.updated_at),
      deleted_at: pkg.deleted_at ? toISOStringSafe(pkg.deleted_at) : null,
    })),
    deleted_at: updated.deleted_at ? toISOStringSafe(updated.deleted_at) : null,
  };
}

import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/client";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";
import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

import { IShoppingOrder } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingOrder";
import { IShoppingOrderAddress } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingOrderAddress";
import { IShoppingCustomer } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingCustomer";
import { IShoppingOrderLine } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingOrderLine";
import { IShoppingSku } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingSku";
import { IShoppingSeller } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingSeller";
import { IShoppingOrderLineFulfillment } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingOrderLineFulfillment";
import { IShoppingOrderSplit } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingOrderSplit";
import { IShoppingOrderStatusHistory } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingOrderStatusHistory";
import { IShoppingOrderPaymentAttempt } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingOrderPaymentAttempt";
import { IShoppingOrderShipment } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingOrderShipment";
import { CustomerPayload } from "../decorators/payload/CustomerPayload";

export async function putShoppingCustomerOrdersOrderCode(props: {
  customer: CustomerPayload;
  orderCode: string;
  body: IShoppingOrder.IUpdate;
}): Promise<IShoppingOrder> {
  // Find the order by its order_code
  const order = await MyGlobal.prisma.shopping_orders.findUnique({
    where: { order_code: props.orderCode },
    include: { customer: true },
  });
  if (!order || order.deleted_at !== null) {
    throw new HttpException("Order not found", 404);
  }
  // Only the owning customer may update
  if (order.shopping_customer_id !== props.customer.id) {
    throw new HttpException(
      "Forbidden. You are not the owner of this order.",
      403,
    );
  }
  // Updates not allowed after fulfillment/shipped/canceled
  if (
    order.status === "fulfilled" ||
    order.status === "shipped" ||
    order.status === "canceled"
  ) {
    throw new HttpException(
      "Cannot update an order that is fulfilled, shipped, or canceled",
      400,
    );
  }
  // Prepare status mutation if needed
  if (typeof props.body.status === "string") {
    await MyGlobal.prisma.shopping_orders.update({
      where: { id: order.id },
      data: { status: props.body.status },
    });
  }
  // Update shipping addresses in-place (by array position, no add/remove)
  if (
    Array.isArray(props.body.shipping_addresses) &&
    props.body.shipping_addresses.length > 0
  ) {
    const addresses = await MyGlobal.prisma.shopping_order_addresses.findMany({
      where: { shopping_order_id: order.id },
      orderBy: { created_at: "asc" },
    });
    for (let idx = 0; idx < props.body.shipping_addresses.length; ++idx) {
      const upd = props.body.shipping_addresses[idx];
      const addr = addresses[idx];
      if (!addr) break;
      await MyGlobal.prisma.shopping_order_addresses.update({
        where: { id: addr.id },
        data: {
          ...(typeof upd.type === "string" && { type: upd.type }),
          ...(typeof upd.recipient_name === "string" && {
            recipient_name: upd.recipient_name,
          }),
          ...(typeof upd.recipient_phone === "string" && {
            recipient_phone: upd.recipient_phone,
          }),
          ...(typeof upd.zip_code === "string" && { zip_code: upd.zip_code }),
          ...(typeof upd.base_address === "string" && {
            base_address: upd.base_address,
          }),
          ...("detail_address" in upd && {
            detail_address: upd.detail_address,
          }),
          ...(typeof upd.city === "string" && { city: upd.city }),
          ...(typeof upd.state_province === "string" && {
            state_province: upd.state_province,
          }),
          ...(typeof upd.country === "string" && { country: upd.country }),
        },
      });
    }
  }
  // Reload full order with nested references
  const full = await MyGlobal.prisma.shopping_orders.findUnique({
    where: { id: order.id },
    include: {
      customer: true,
      shopping_order_lines: {
        include: {
          sku: true,
          seller: true,
          shopping_order_fulfillments: true,
        },
      },
      shopping_order_splits: {
        include: {
          seller: true,
          shopping_order_status_histories: true,
        },
      },
      shopping_order_addresses: true,
      shopping_order_status_histories: true,
      shopping_payment_attempts: true,
      shopping_shipments: { include: { seller: true } },
    },
  });
  if (!full) {
    throw new HttpException("Order not found after update", 404);
  }
  // Build IShoppingOrder response
  return {
    id: full.id,
    order_code: full.order_code,
    total_price: full.total_price,
    status: full.status,
    created_at: toISOStringSafe(full.created_at),
    updated_at: toISOStringSafe(full.updated_at),
    deleted_at:
      full.deleted_at !== null ? toISOStringSafe(full.deleted_at) : undefined,
    customer: {
      id: full.customer.id,
      name: full.customer.name,
      email: full.customer.email,
      is_active: full.customer.is_active,
      created_at: toISOStringSafe(full.customer.created_at),
      deleted_at:
        full.customer.deleted_at !== null
          ? toISOStringSafe(full.customer.deleted_at)
          : null,
    },
    order_lines: full.shopping_order_lines.map((line) => ({
      id: line.id,
      sku: {
        id: line.sku.id,
        sku_code: line.sku.sku_code,
        price: line.sku.price,
        is_active: line.sku.is_active,
        status: line.sku.status,
      },
      quantity: line.quantity,
      unit_price: line.unit_price,
      status: line.status,
      seller: {
        id: line.seller.id,
        display_name: line.seller.display_name,
        status: line.seller.status,
      },
      fulfillments: Array.isArray(line.shopping_order_fulfillments)
        ? line.shopping_order_fulfillments.map((ful) => ({
            id: ful.id,
            fulfillment_code: ful.fulfillment_code,
            quantity_fulfilled: ful.quantity_fulfilled,
            status: ful.status,
            fulfilled_at: toISOStringSafe(ful.fulfilled_at),
            seller_address_id: ful.shopping_seller_address_id,
          }))
        : undefined,
      created_at: toISOStringSafe(line.created_at),
      updated_at: toISOStringSafe(line.updated_at),
      deleted_at:
        line.deleted_at !== null ? toISOStringSafe(line.deleted_at) : undefined,
    })),
    order_splits: full.shopping_order_splits.map((split) => ({
      id: split.id,
      split_code: split.split_code,
      subtotal_price: split.subtotal_price,
      status: split.status,
      created_at: toISOStringSafe(split.created_at),
      updated_at:
        split.updated_at !== null
          ? toISOStringSafe(split.updated_at)
          : undefined,
      order_id: split.shopping_order_id,
      seller: {
        id: split.seller.id,
        display_name: split.seller.display_name,
        status: split.seller.status,
      },
      order_status_histories: Array.isArray(
        split.shopping_order_status_histories,
      )
        ? split.shopping_order_status_histories.map((s) => ({
            id: s.id,
            from_status: s.from_status,
            to_status: s.to_status,
            triggered_by: s.triggered_by,
            event_note: s.event_note ?? undefined,
            occurred_at: toISOStringSafe(s.occurred_at),
          }))
        : undefined,
    })),
    addresses: full.shopping_order_addresses.map((addr) => ({
      id: addr.id,
      shopping_order_id: addr.shopping_order_id,
      type: addr.type,
      recipient_name: addr.recipient_name,
      recipient_phone: addr.recipient_phone,
      zip_code: addr.zip_code,
      base_address: addr.base_address,
      detail_address: addr.detail_address ?? undefined,
      city: addr.city,
      state_province: addr.state_province,
      country: addr.country,
      created_at: toISOStringSafe(addr.created_at),
      updated_at: toISOStringSafe(addr.updated_at),
    })),
    status_history: full.shopping_order_status_histories.map((s) => ({
      id: s.id,
      shopping_order_id: s.shopping_order_id,
      shopping_order_split_id: s.shopping_order_split_id ?? undefined,
      from_status: s.from_status,
      to_status: s.to_status,
      triggered_by: s.triggered_by,
      event_note: s.event_note ?? undefined,
      occurred_at: toISOStringSafe(s.occurred_at),
    })),
    payment_attempts: full.shopping_payment_attempts.map((a) => ({
      id: a.id,
      payment_reference: a.payment_reference ?? undefined,
      attempt_status: typia.assert<
        "pending" | "completed" | "failed" | "cancelled"
      >(a.attempt_status),
      amount: a.amount,
      attempted_at: toISOStringSafe(a.attempted_at),
      completed_at:
        a.completed_at !== null ? toISOStringSafe(a.completed_at) : undefined,
    })),
    shipments: full.shopping_shipments.map((sh) => ({
      id: sh.id,
      seller: {
        id: sh.seller.id,
        display_name: sh.seller.display_name,
        status: sh.seller.status,
      },
      code: sh.code,
      status: sh.status,
      carrier_company: sh.carrier_company,
      scheduled_dispatch_at:
        sh.scheduled_dispatch_at !== null
          ? toISOStringSafe(sh.scheduled_dispatch_at)
          : undefined,
      dispatched_at:
        sh.dispatched_at !== null
          ? toISOStringSafe(sh.dispatched_at)
          : undefined,
      delivered_at:
        sh.delivered_at !== null ? toISOStringSafe(sh.delivered_at) : undefined,
      canceled_at:
        sh.canceled_at !== null ? toISOStringSafe(sh.canceled_at) : undefined,
      created_at: toISOStringSafe(sh.created_at),
      updated_at: toISOStringSafe(sh.updated_at),
    })),
  };
}

import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/client";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";
import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

import { IShoppingGuestCartItem } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingGuestCartItem";

export async function putShoppingGuestCartsGuestCartId(props: {
  guestCartId: string & tags.Format<"uuid">;
  body: IShoppingGuestCartItem.IUpdate;
}): Promise<IShoppingGuestCartItem> {
  type RawGuestCartItem = {
    shopping_sku_id: string & tags.Format<"uuid">;
    quantity: number;
  };
  // safe parse - props.body.items is RawGuestCartItem[]
  const items = props.body.items as unknown as RawGuestCartItem[];

  const cart = await MyGlobal.prisma.shopping_guest_carts.findUnique({
    where: { id: props.guestCartId },
  });
  if (!cart) {
    throw new HttpException("Guest cart not found", 404);
  }
  const now = toISOStringSafe(new Date());
  // Expiry check
  const expiresAt = toISOStringSafe(cart.expires_at);
  if (expiresAt < now) {
    throw new HttpException("Guest cart has expired", 400);
  }
  if (!Array.isArray(items) || items.length === 0) {
    throw new HttpException("'items' array must be non-empty", 400);
  }
  const skuIds = items.map((item) => item.shopping_sku_id);
  const validSkus = await MyGlobal.prisma.shopping_skus.findMany({
    where: { id: { in: skuIds }, deleted_at: null, is_active: true },
    select: { id: true },
  });
  const validSkuSet = new Set(validSkus.map((s) => s.id));
  for (const item of items) {
    if (!validSkuSet.has(item.shopping_sku_id)) {
      throw new HttpException(
        `SKU does not exist or inactive: ${item.shopping_sku_id}`,
        400,
      );
    }
    if (typeof item.quantity !== "number" || item.quantity <= 0) {
      throw new HttpException(
        `Quantity for SKU ${item.shopping_sku_id} must be > 0`,
        400,
      );
    }
  }
  await MyGlobal.prisma.shopping_guest_cart_items.deleteMany({
    where: { shopping_guest_cart_id: props.guestCartId },
  });
  await MyGlobal.prisma.shopping_guest_cart_items.createMany({
    data: items.map((item) => ({
      id: v4() as string & tags.Format<"uuid">,
      shopping_guest_cart_id: props.guestCartId,
      shopping_sku_id: item.shopping_sku_id,
      quantity: item.quantity,
      added_at: now,
      updated_at: now,
    })),
  });
  const updatedCart = await MyGlobal.prisma.shopping_guest_carts.update({
    where: { id: props.guestCartId },
    data: { updated_at: now },
  });
  // Fetch raw items after update; must project to ISummary for the API's 'items' field
  const dbItems = await MyGlobal.prisma.shopping_guest_cart_items.findMany({
    where: { shopping_guest_cart_id: props.guestCartId },
    orderBy: { added_at: "asc" },
  });
  return {
    id: updatedCart.id,
    session_key: updatedCart.session_key,
    created_at: toISOStringSafe(updatedCart.created_at),
    updated_at: toISOStringSafe(updatedCart.updated_at),
    expires_at: toISOStringSafe(updatedCart.expires_at),
    items: dbItems.map((dbItem) => ({
      session_key: updatedCart.session_key,
      created_at: toISOStringSafe(updatedCart.created_at),
      updated_at: toISOStringSafe(updatedCart.updated_at),
      expires_at: toISOStringSafe(updatedCart.expires_at),
      items: [], // leave empty as placeholder
    })),
  };
}

import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/client";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";
import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

import { IShoppingSellerAddress } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingSellerAddress";
import { IPageIShoppingSellerAddress } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIShoppingSellerAddress";
import { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import { SellerPayload } from "../decorators/payload/SellerPayload";

export async function patchShoppingSellerSellersSellerIdAddresses(props: {
  seller: SellerPayload;
  sellerId: string & tags.Format<"uuid">;
  body: IShoppingSellerAddress.IRequest;
}): Promise<IPageIShoppingSellerAddress> {
  const { seller, sellerId, body } = props;

  // Authorization: Must only access own addresses
  if (seller.id !== sellerId) {
    throw new HttpException(
      "Unauthorized: sellers can only view their own addresses",
      403,
    );
  }

  const page = body.page ?? 1;
  const limit = body.limit ?? 20;

  const where = {
    shopping_seller_id: sellerId,
    deleted_at: null,
    ...(body.is_primary !== undefined && { is_primary: body.is_primary }),
    ...(body.is_return_address !== undefined && {
      is_return_address: body.is_return_address,
    }),
    ...(body.city !== undefined &&
      body.city !== null && { city: { contains: body.city } }),
    ...(body.state !== undefined &&
      body.state !== null && { state: { contains: body.state } }),
    ...(body.country !== undefined &&
      body.country !== null && { country: { contains: body.country } }),
  };

  const allowedSort = [
    "updated_at",
    "created_at",
    "city",
    "state",
    "country",
    "is_primary",
    "is_return_address",
  ];
  const sortBy =
    body.sort_by && allowedSort.includes(body.sort_by)
      ? body.sort_by
      : "updated_at";
  const sortOrder: "asc" | "desc" = body.sort_order === "asc" ? "asc" : "desc";

  const [addresses, total] = await Promise.all([
    MyGlobal.prisma.shopping_seller_addresses.findMany({
      where,
      orderBy: { [sortBy]: sortOrder },
      skip: (page - 1) * limit,
      take: limit,
    }),
    MyGlobal.prisma.shopping_seller_addresses.count({ where }),
  ]);

  const data = addresses.map((addr) => ({
    id: addr.id,
    shopping_seller_id: addr.shopping_seller_id,
    address_line1: addr.address_line1,
    address_line2: addr.address_line2 ?? null,
    city: addr.city,
    state: addr.state,
    postal_code: addr.postal_code,
    country: addr.country,
    is_return_address: addr.is_return_address,
    is_primary: addr.is_primary,
    phone: addr.phone,
    created_at: toISOStringSafe(addr.created_at),
    updated_at: toISOStringSafe(addr.updated_at),
    deleted_at: addr.deleted_at ? toISOStringSafe(addr.deleted_at) : null,
    recipient_name: "",
  }));

  return {
    pagination: {
      current: Number(page),
      limit: Number(limit),
      records: total,
      pages: Math.ceil(total / Number(limit)),
    },
    data,
  };
}

import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/client";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";
import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

import { IShoppingCustomer } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingCustomer";
import { IShoppingAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingAuthorizationToken";

export async function postAuthCustomerLogin(props: {
  body: IShoppingCustomer.ILogin;
}): Promise<IShoppingCustomer.IAuthorized> {
  // STEP 1: Fetch customer by email and enforce not deleted
  const customer = await MyGlobal.prisma.shopping_customers.findFirst({
    where: {
      email: props.body.email,
      deleted_at: null,
    },
  });
  if (!customer) {
    throw new HttpException("Invalid email or password", 401);
  }
  if (!customer.is_active) {
    throw new HttpException("Account is not active", 403);
  }

  // STEP 2: Validate password using PasswordUtil
  const valid = await PasswordUtil.verify(
    props.body.password,
    customer.password_hash,
  );
  if (!valid) {
    throw new HttpException("Invalid email or password", 401);
  }

  // STEP 3: Create a new session for this login
  const now = toISOStringSafe(new Date());
  const accessExpiresNum = Date.now() + 60 * 60 * 1000; // 1 hour
  const refreshExpiresNum = Date.now() + 7 * 24 * 60 * 60 * 1000; // 7 days
  const accessExpires = toISOStringSafe(new Date(accessExpiresNum));
  const refreshExpires = toISOStringSafe(new Date(refreshExpiresNum));

  const sessionData: any = {
    id: v4(),
    shopping_customer_id: customer.id,
    href: props.body.href,
    referrer: props.body.referrer,
    created_at: now,
    expired_at: accessExpires,
  };
  if (props.body.ip !== null && props.body.ip !== undefined) {
    sessionData.ip = props.body.ip satisfies string as string;
  }
  const session = await MyGlobal.prisma.shopping_customer_sessions.create({
    data: sessionData,
  });

  // STEP 4: Issue JWT access & refresh tokens for the actor
  const token = {
    access: jwt.sign(
      {
        type: "customer",
        id: customer.id,
        session_id: session.id,
        created_at: now,
      },
      MyGlobal.env.JWT_SECRET_KEY,
      {
        expiresIn: "1h",
        issuer: "autobe",
      },
    ),
    refresh: jwt.sign(
      {
        type: "customer",
        id: customer.id,
        session_id: session.id,
        tokenType: "refresh",
        created_at: now,
      },
      MyGlobal.env.JWT_SECRET_KEY,
      {
        expiresIn: "7d",
        issuer: "autobe",
      },
    ),
    expired_at: accessExpires,
    refreshable_until: refreshExpires,
  };

  // STEP 5: Build the IShoppingCustomer.IAuthorized DTO for return
  return {
    id: customer.id,
    email: customer.email,
    name: customer.name,
    phone: customer.phone,
    is_active: customer.is_active,
    deleted_at: customer.deleted_at
      ? toISOStringSafe(customer.deleted_at)
      : undefined,
    created_at: toISOStringSafe(customer.created_at),
    updated_at: toISOStringSafe(customer.updated_at),
    token,
    role: "customer",
  };
}

import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/client";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";
import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

import { IShoppingRefundRequest } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingRefundRequest";
import { IShoppingRefundRequestItem } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingRefundRequestItem";
import { IShoppingRefundAttachment } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingRefundAttachment";
import { IShoppingOrder } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingOrder";
import { IShoppingCustomer } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingCustomer";
import { IShoppingRefundActor } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingRefundActor";
import { IShoppingRefundStatusHistory } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingRefundStatusHistory";
import { IShoppingRefundApproval } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingRefundApproval";
import { IShoppingRefundAdminOverride } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingRefundAdminOverride";
import { CustomerPayload } from "../decorators/payload/CustomerPayload";

export async function postShoppingCustomerRefunds(props: {
  customer: CustomerPayload;
  body: IShoppingRefundRequest.ICreate;
}): Promise<IShoppingRefundRequest> {
  const now = toISOStringSafe(new Date());
  return await MyGlobal.prisma.$transaction(async (tx) => {
    const order = await tx.shopping_orders.findFirst({
      where: {
        id: props.body.shopping_order_id,
        shopping_customer_id: props.customer.id,
        deleted_at: null,
      },
      include: {
        customer: true,
      },
    });
    if (!order) {
      throw new HttpException("Order not found or not owned by customer", 404);
    }
    const duplicate = await tx.shopping_refund_requests.findFirst({
      where: {
        shopping_order_id: props.body.shopping_order_id,
        actor_type: "customer",
        shopping_actor_id: props.customer.id,
        request_type: props.body.request_type,
        deleted_at: null,
      },
    });
    if (duplicate) {
      throw new HttpException(
        "Duplicate refund request for order already exists",
        409,
      );
    }
    const refundRequest = await tx.shopping_refund_requests.create({
      data: {
        id: v4(),
        shopping_order_id: props.body.shopping_order_id,
        shopping_actor_id: props.customer.id,
        actor_type: "customer",
        request_type: props.body.request_type,
        business_reason: props.body.business_reason,
        request_context: props.body.request_context ?? null,
        status: "pending",
        created_at: now,
        updated_at: now,
        deleted_at: null,
      },
    });
    const refundItems = await Promise.all(
      props.body.items.map(async (item) => {
        const orderLine = await tx.shopping_order_lines.findFirst({
          where: {
            id: item.shopping_order_line_id,
            shopping_order_id: props.body.shopping_order_id,
            deleted_at: null,
          },
        });
        if (!orderLine) {
          throw new HttpException(
            "Order line not found or not part of order",
            404,
          );
        }
        if (item.quantity > orderLine.quantity || item.quantity < 1) {
          throw new HttpException(
            "Requested refund quantity out of range",
            400,
          );
        }
        const refundItem = await tx.shopping_refund_request_items.create({
          data: {
            id: v4(),
            shopping_refund_request_id: refundRequest.id,
            shopping_order_id: props.body.shopping_order_id,
            shopping_order_line_id: item.shopping_order_line_id,
            quantity: item.quantity,
            item_business_reason: item.item_business_reason ?? null,
            created_at: now,
            updated_at: now,
          },
        });
        let attachments: IShoppingRefundAttachment[] = [];
        if (item.attachments && item.attachments.length > 0) {
          attachments = await Promise.all(
            item.attachments.map(async (attachment) => {
              const refundAttachment =
                await tx.shopping_refund_attachments.create({
                  data: {
                    id: v4(),
                    shopping_refund_request_id: refundRequest.id,
                    shopping_refund_request_item_id: refundItem.id,
                    attachment_file_id: attachment.attachment_file_id,
                    attachment_type: attachment.attachment_type,
                    description: attachment.description ?? null,
                    uploaded_at: now,
                  },
                });
              return {
                id: refundAttachment.id,
                shopping_refund_request_id:
                  refundAttachment.shopping_refund_request_id,
                shopping_refund_request_item_id:
                  refundAttachment.shopping_refund_request_item_id ?? null,
                attachment_file_id: refundAttachment.attachment_file_id,
                attachment_type: refundAttachment.attachment_type,
                description: refundAttachment.description ?? null,
                uploaded_at: toISOStringSafe(refundAttachment.uploaded_at),
                file_uri: attachment.file_uri,
                file_type: attachment.file_type,
                file_size: attachment.file_size,
              };
            }),
          );
        }
        return {
          id: refundItem.id,
          shopping_refund_request_id: refundItem.shopping_refund_request_id,
          shopping_order_id: refundItem.shopping_order_id,
          shopping_order_line_id: refundItem.shopping_order_line_id,
          quantity: refundItem.quantity,
          item_business_reason: refundItem.item_business_reason ?? null,
          created_at: toISOStringSafe(refundItem.created_at),
          updated_at: toISOStringSafe(refundItem.updated_at),
          attachments: attachments.length > 0 ? attachments : undefined,
        };
      }),
    );
    let standaloneAttachments: IShoppingRefundAttachment[] = [];
    if (props.body.attachments && props.body.attachments.length > 0) {
      standaloneAttachments = await Promise.all(
        props.body.attachments.map(async (attachment) => {
          const refundAttachment = await tx.shopping_refund_attachments.create({
            data: {
              id: v4(),
              shopping_refund_request_id: refundRequest.id,
              shopping_refund_request_item_id: null,
              attachment_file_id: attachment.attachment_file_id,
              attachment_type: attachment.attachment_type,
              description: attachment.description ?? null,
              uploaded_at: now,
            },
          });
          return {
            id: refundAttachment.id,
            shopping_refund_request_id:
              refundAttachment.shopping_refund_request_id,
            shopping_refund_request_item_id: null,
            attachment_file_id: refundAttachment.attachment_file_id,
            attachment_type: refundAttachment.attachment_type,
            description: refundAttachment.description ?? null,
            uploaded_at: toISOStringSafe(refundAttachment.uploaded_at),
            file_uri: attachment.file_uri,
            file_type: attachment.file_type,
            file_size: attachment.file_size,
          };
        }),
      );
    }
    const actorSummary = {
      actor_type: typia.assert<"customer" | "seller" | "admin">("customer"),
      id: order.customer.id,
      name: order.customer.name,
    };
    const orderSummary = {
      id: order.id,
      order_code: order.order_code,
      total_price: order.total_price,
      status: order.status,
      created_at: toISOStringSafe(order.created_at),
      updated_at: toISOStringSafe(order.updated_at),
      customer: {
        id: order.customer.id,
        name: order.customer.name,
        email: order.customer.email,
        is_active: order.customer.is_active,
        created_at: toISOStringSafe(order.customer.created_at),
        deleted_at: order.customer.deleted_at
          ? toISOStringSafe(order.customer.deleted_at)
          : null,
      },
    };
    const statusHistoryRecord =
      await tx.shopping_refund_status_histories.create({
        data: {
          id: v4(),
          shopping_refund_request_id: refundRequest.id,
          shopping_actor_id: props.customer.id,
          actor_type: "customer",
          previous_status: "pending",
          new_status: "pending",
          timestamp: now,
          change_context: null,
        },
      });
    return {
      id: refundRequest.id,
      order: orderSummary,
      actor: actorSummary,
      request_type: typia.assert<"refund" | "return" | "cancellation">(
        refundRequest.request_type,
      ),
      business_reason: refundRequest.business_reason,
      request_context: refundRequest.request_context ?? undefined,
      status: refundRequest.status,
      created_at: toISOStringSafe(refundRequest.created_at),
      updated_at: toISOStringSafe(refundRequest.updated_at),
      deleted_at: refundRequest.deleted_at
        ? toISOStringSafe(refundRequest.deleted_at)
        : undefined,
      items: refundItems,
      attachments: standaloneAttachments,
      status_histories: [
        {
          id: statusHistoryRecord.id,
          shopping_refund_request_id:
            statusHistoryRecord.shopping_refund_request_id,
          shopping_actor_id: statusHistoryRecord.shopping_actor_id,
          actor_type: typia.assert<"customer" | "seller" | "admin">("customer"),
          previous_status: statusHistoryRecord.previous_status,
          new_status: statusHistoryRecord.new_status,
          timestamp: toISOStringSafe(statusHistoryRecord.timestamp),
          change_context: statusHistoryRecord.change_context ?? undefined,
        },
      ],
      approvals: [],
      admin_overrides: [],
    };
  });
}

import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/client";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";
import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

import { IShoppingProductImage } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingProductImage";
import { IPageIShoppingProductImage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIShoppingProductImage";
import { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

export async function patchShoppingProductsProductCodeImages(props: {
  productCode: string;
  body: IShoppingProductImage.IRequest;
}): Promise<IPageIShoppingProductImage> {
  const { productCode, body } = props;
  const product = await MyGlobal.prisma.shopping_products.findFirst({
    where: {
      code: productCode,
      status: "active",
      deleted_at: null,
    },
    select: { id: true },
  });
  if (!product) {
    throw new HttpException("Product not found or not accessible", 404);
  }

  const page =
    body.page !== undefined &&
    body.page !== null &&
    typeof body.page === "number" &&
    body.page > 0
      ? Number(body.page)
      : 1;
  let limit =
    body.limit !== undefined &&
    body.limit !== null &&
    typeof body.limit === "number" &&
    body.limit > 0
      ? Number(body.limit)
      : 20;
  if (limit > 100) limit = 100;
  const skip = (page - 1) * limit;

  const imageSearch = body.search ? body.search : undefined;

  const allowedOrderFields = ["created_at", "order_index"] as const;
  const orderByField =
    typeof body.order_by === "string" &&
    allowedOrderFields.includes(
      body.order_by as (typeof allowedOrderFields)[number],
    )
      ? (body.order_by as (typeof allowedOrderFields)[number])
      : "created_at";
  const dir =
    body.order_direction === "asc" || body.order_direction === "desc"
      ? body.order_direction
      : "desc";

  const where = {
    shopping_product_id: product.id,
    ...(imageSearch && { image_uri: { contains: imageSearch } }),
  };

  const [rows, total] = await Promise.all([
    MyGlobal.prisma.shopping_product_images.findMany({
      where,
      orderBy: { [orderByField]: dir },
      skip,
      take: limit,
      select: {
        id: true,
        shopping_product_id: true,
        image_uri: true,
        order_index: true,
        created_at: true,
      },
    }),
    MyGlobal.prisma.shopping_product_images.count({ where }),
  ]);

  const data = rows.map((row) => ({
    id: row.id,
    shopping_product_id: row.shopping_product_id,
    image_uri: row.image_uri,
    order_index:
      row.order_index !== null && row.order_index !== undefined
        ? row.order_index
        : undefined,
    created_at: toISOStringSafe(row.created_at),
  }));

  const pages = total > 0 ? Math.ceil(total / limit) : 0;
  return {
    pagination: {
      current: Number(page),
      limit: Number(limit),
      records: total,
      pages,
    },
    data,
  };
