      {
        type: "admin",
        id,
        session_id: v4(),
        created_at: now,
        tokenType: "refresh",
      },
      MyGlobal.env.JWT_SECRET_KEY,
      { expiresIn: "7d", issuer: "autobe" },
    ),
    expired_at: accessExpires,
    refreshable_until: refreshExpires,
  };

  return {
    id: createdAdmin.id,
    email: createdAdmin.email,
    name: createdAdmin.name,
    role: createdAdmin.role,
    status: createdAdmin.status,
    created_at: toISOStringSafe(createdAdmin.created_at),
    updated_at: toISOStringSafe(createdAdmin.updated_at),
    deleted_at:
      createdAdmin.deleted_at === null
        ? null
        : toISOStringSafe(createdAdmin.deleted_at),
    token,
  };
}

import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/client";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";
import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

import { IShoppingAdmin } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingAdmin";
import { IShoppingAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingAuthorizationToken";

export async function postAuthAdminLogin(props: {
  body: IShoppingAdmin.ILogin;
}): Promise<IShoppingAdmin.IAuthorized> {
  const { email, password, ip, href, referrer } = props.body;

  // 1. Find admin by email, ensure not soft-deleted
  const admin = await MyGlobal.prisma.shopping_admins.findFirst({
    where: {
      email,
      deleted_at: null,
    },
  });
  if (!admin) {
    throw new HttpException("Invalid credentials", 401);
  }

  // 2. Verify password
  const passwordOk = await PasswordUtil.verify(password, admin.password_hash);
  if (!passwordOk) {
    throw new HttpException("Invalid credentials", 401);
  }

  // 3. Account must be active
  if (admin.status !== "active") {
    throw new HttpException("Your admin account is not active.", 403);
  }

  // 4. Create a new admin session
  const sessionId = v4();
  const now = toISOStringSafe(new Date());
  const accessExpires = toISOStringSafe(new Date(Date.now() + 60 * 60 * 1000));
  const refreshExpires = toISOStringSafe(
    new Date(Date.now() + 7 * 24 * 60 * 60 * 1000),
  );

  await MyGlobal.prisma.shopping_admin_sessions.create({
    data: {
      id: sessionId,
      shopping_admin_id: admin.id,
      ip: typeof ip === "string" && ip ? ip : "",
      href,
      referrer,
      created_at: now,
      expired_at: null,
    },
  });

  // 5. Generate JWT tokens
  const token: IShoppingAuthorizationToken = {
    access: jwt.sign(
      {
        type: "admin",
        id: admin.id,
        session_id: sessionId,
        created_at: now,
      },
      MyGlobal.env.JWT_SECRET_KEY,
      {
        expiresIn: "1h",
        issuer: "autobe",
      },
    ),
    refresh: jwt.sign(
      {
        type: "admin",
        id: admin.id,
        session_id: sessionId,
        tokenType: "refresh",
        created_at: now,
      },
      MyGlobal.env.JWT_SECRET_KEY,
      {
        expiresIn: "7d",
        issuer: "autobe",
      },
    ),
    expired_at: accessExpires,
    refreshable_until: refreshExpires,
  };

  // 6. Return authorized DTO with allowed fields only
  return {
    id: admin.id,
    email: admin.email,
    name: admin.name,
    role: admin.role,
    status: admin.status,
    created_at: toISOStringSafe(admin.created_at),
    updated_at: toISOStringSafe(admin.updated_at),
    deleted_at: admin.deleted_at
      ? toISOStringSafe(admin.deleted_at)
      : undefined,
    token,
  };
}

import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/client";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";
import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

import { IShoppingSystemConfiguration } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingSystemConfiguration";
import { IPageIShoppingSystemConfiguration } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIShoppingSystemConfiguration";
import { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import { AdminPayload } from "../decorators/payload/AdminPayload";

export async function patchShoppingAdminSystemConfigurations(props: {
  admin: AdminPayload;
  body: IShoppingSystemConfiguration.IRequest;
}): Promise<IPageIShoppingSystemConfiguration.ISummary> {
  const {
    page,
    limit,
    search,
    sortBy,
    sortOrder,
    configKey,
    configValue,
    createdFrom,
    createdTo,
    description,
  } = props.body;

  // Calculate skip for pagination
  const skip = (Number(page) - 1) * Number(limit);

  // Filtering conditions
  const where = {
    deleted_at: null,
    ...(configKey !== undefined && { config_key: configKey }),
    ...(configValue !== undefined && {
      config_value: { contains: configValue },
    }),
    ...(description !== undefined && {
      description: { contains: description },
    }),
    ...(createdFrom !== undefined || createdTo !== undefined
      ? {
          created_at: {
            ...(createdFrom !== undefined && { gte: createdFrom }),
            ...(createdTo !== undefined && { lte: createdTo }),
          },
        }
      : {}),
    ...(search !== undefined && search.length > 0
      ? {
          OR: [
            { config_key: { contains: search } },
            { config_value: { contains: search } },
            { description: { contains: search } },
          ],
        }
      : {}),
  };

  // Valid sort fields
  const allowedSortFields = ["created_at", "updated_at", "config_key"];
  const sortField = allowedSortFields.includes(sortBy ?? "")
    ? (sortBy as "created_at" | "updated_at" | "config_key")
    : "created_at";
  const order: "asc" | "desc" = sortOrder === "desc" ? "desc" : "asc";

  const [rows, total] = await Promise.all([
    MyGlobal.prisma.shopping_system_configurations.findMany({
      where,
      orderBy: { [sortField]: order },
      skip,
      take: Number(limit),
      select: {
        id: true,
        config_key: true,
        config_value: true,
        description: true,
        created_at: true,
        updated_at: true,
        deleted_at: true,
      },
    }),
    MyGlobal.prisma.shopping_system_configurations.count({ where }),
  ]);

  const data = rows.map((row) => ({
    id: row.id,
    config_key: row.config_key,
    config_value: row.config_value,
    description: row.description ?? undefined,
    created_at: toISOStringSafe(row.created_at),
    updated_at: toISOStringSafe(row.updated_at),
    deleted_at: row.deleted_at ? toISOStringSafe(row.deleted_at) : null,
  }));

  return {
    pagination: {
      current: Number(page),
      limit: Number(limit),
      records: total,
      pages: Math.ceil(total / Number(limit)),
    },
    data,
  };
}

