import { Prisma } from "@prisma/client";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";
import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

import { CustomerPayload } from "../decorators/payload/CustomerPayload";

export async function deleteShoppingCustomerCustomersCustomerId(props: {
  customer: CustomerPayload;
  customerId: string & tags.Format<"uuid">;
}): Promise<void> {
  // Only account owner can delete own account
  if (props.customer.id !== props.customerId) {
    throw new HttpException(
      "Unauthorized: You can only delete your own account",
      403,
    );
  }

  // Fetch customer, ensure not already deleted
  const customer = await MyGlobal.prisma.shopping_customers.findUnique({
    where: { id: props.customerId },
  });
  if (!customer || customer.deleted_at !== null) {
    throw new HttpException(
      "Customer account does not exist or is already deleted",
      404,
    );
  }

  // Timestamp for deletion
  const now = toISOStringSafe(new Date());

  // Remove all sessions
  await MyGlobal.prisma.shopping_customer_sessions.deleteMany({
    where: { shopping_customer_id: props.customerId },
  });
  // Remove all addresses
  await MyGlobal.prisma.shopping_customer_addresses.deleteMany({
    where: { shopping_customer_id: props.customerId },
  });
  // Remove all user emails
  await MyGlobal.prisma.shopping_user_emails.deleteMany({
    where: { shopping_customer_id: props.customerId },
  });
  // Remove cart
  await MyGlobal.prisma.shopping_carts.deleteMany({
    where: { shopping_customer_id: props.customerId },
  });
  // Remove wishlist
  await MyGlobal.prisma.shopping_wishlists.deleteMany({
    where: { shopping_customer_id: props.customerId },
  });
  // (Orders, reviews, audit logs retained per compliance)

  // Mark account as deleted (soft delete)
  await MyGlobal.prisma.shopping_customers.update({
    where: { id: props.customerId },
    data: {
      deleted_at: now,
      is_active: false,
      updated_at: now,
    },
  });
}

import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/client";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";
import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

import { AdminPayload } from "../decorators/payload/AdminPayload";

export async function deleteShoppingAdminCustomersCustomerId(props: {
  admin: AdminPayload;
  customerId: string & tags.Format<"uuid">;
}): Promise<void> {
  const now = toISOStringSafe(new Date());
  const customer = await MyGlobal.prisma.shopping_customers.findUnique({
    where: { id: props.customerId },
  });
  if (!customer || customer.deleted_at !== null) {
    throw new HttpException("Customer not found or already deleted", 404);
  }
  await MyGlobal.prisma.$transaction(async (tx) => {
    // Soft delete customer
    await tx.shopping_customers.update({
      where: { id: props.customerId },
      data: { deleted_at: now, updated_at: now },
    });
    // Delete all addresses
    await tx.shopping_customer_addresses.deleteMany({
      where: { shopping_customer_id: props.customerId },
    });
    // Delete all sessions
    await tx.shopping_customer_sessions.deleteMany({
      where: { shopping_customer_id: props.customerId },
    });
    // Delete cart items -> cart
    const cart = await tx.shopping_carts.findUnique({
      where: { shopping_customer_id: props.customerId },
    });
    if (cart) {
      await tx.shopping_cart_items.deleteMany({
        where: { shopping_cart_id: cart.id },
      });
      await tx.shopping_carts.delete({
        where: { id: cart.id },
      });
    }
    // Delete wishlist items -> wishlist
    const wishlist = await tx.shopping_wishlists.findUnique({
      where: { shopping_customer_id: props.customerId },
    });
    if (wishlist) {
      await tx.shopping_wishlist_items.deleteMany({
        where: { shopping_wishlist_id: wishlist.id },
      });
      await tx.shopping_wishlists.delete({
        where: { id: wishlist.id },
      });
    }
    // Delete user emails
    await tx.shopping_user_emails.deleteMany({
      where: { shopping_customer_id: props.customerId },
    });
  });
}

import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/client";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";
import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

import { IShoppingCustomerAddress } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingCustomerAddress";
import { IPageIShoppingCustomerAddress } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIShoppingCustomerAddress";
import { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import { CustomerPayload } from "../decorators/payload/CustomerPayload";

export async function patchShoppingCustomerCustomersCustomerIdAddresses(props: {
  customer: CustomerPayload;
  customerId: string & tags.Format<"uuid">;
  body: IShoppingCustomerAddress.IRequest;
}): Promise<IPageIShoppingCustomerAddress> {
  const { customer, customerId, body } = props;
  if (customer.id !== customerId) {
    throw new HttpException(
      "Forbidden: cannot view another customer's addresses",
      403,
    );
  }

  const includeDeleted = body.include_deleted === true;
  const where: Record<string, unknown> = {
    shopping_customer_id: customerId,
    ...(body.is_primary !== undefined && { is_primary: body.is_primary }),
    ...(includeDeleted ? {} : { deleted_at: null }),
  };

  const sortField = body.sort === "updated_at" ? "updated_at" : "created_at";
  const order = body.order === "asc" ? "asc" : "desc";
  const page = body.page ?? 1;
  const limit = body.limit ?? 100;
  const skip = (page - 1) * limit;

  const [records, total] = await Promise.all([
    MyGlobal.prisma.shopping_customer_addresses.findMany({
      where,
      orderBy: { [sortField]: order },
      skip,
      take: limit,
    }),
    MyGlobal.prisma.shopping_customer_addresses.count({ where }),
  ]);

  return {
    pagination: {
      current: Number(page),
      limit: Number(limit),
      records: total,
      pages: Math.ceil(total / limit),
    },
    data: records.map((addr) => ({
      id: addr.id,
      shopping_customer_id: addr.shopping_customer_id,
      address_line1: addr.address_line1,
      address_line2:
        addr.address_line2 === undefined
          ? undefined
          : (addr.address_line2 ?? null),
      city: addr.city,
      state: addr.state,
      postal_code: addr.postal_code,
      country: addr.country,
      is_primary: addr.is_primary,
      phone: addr.phone,
      recipient_name: addr.recipient_name,
      created_at: toISOStringSafe(addr.created_at),
      updated_at: toISOStringSafe(addr.updated_at),
      deleted_at:
        addr.deleted_at === undefined
          ? undefined
          : addr.deleted_at
            ? toISOStringSafe(addr.deleted_at)
            : null,
    })),
  };
}

