export async function putShoppingAdminAdminsAdminId(props: {
  admin: AdminPayload;
  adminId: string & tags.Format<"uuid">;
  body: IShoppingAdmin.IUpdate;
}): Promise<IShoppingAdmin> {
  // Check if the target admin exists and is not soft-deleted
  const admin = await MyGlobal.prisma.shopping_admins.findUnique({
    where: { id: props.adminId },
  });
  if (!admin || admin.deleted_at !== null) {
    throw new HttpException("Admin not found", 404);
  }
  // Email uniqueness check if email is changing
  if (
    typeof props.body.email === "string" &&
    props.body.email !== admin.email
  ) {
    const emailExists = await MyGlobal.prisma.shopping_admins.findFirst({
      where: {
        email: props.body.email,
        deleted_at: null,
        id: { not: props.adminId },
      },
    });
    if (emailExists) {
      throw new HttpException("Email already in use", 409);
    }
  }
  // Only supply provided body fields
  const updated = await MyGlobal.prisma.shopping_admins.update({
    where: { id: props.adminId },
    data: {
      ...(typeof props.body.email === "string"
        ? { email: props.body.email }
        : {}),
      ...(typeof props.body.name === "string" ? { name: props.body.name } : {}),
      ...(typeof props.body.role === "string" ? { role: props.body.role } : {}),
      ...(typeof props.body.status === "string"
        ? { status: props.body.status }
        : {}),
      updated_at: toISOStringSafe(new Date()),
    },
  });
  return {
    id: updated.id,
    email: updated.email,
    name: updated.name,
    role: updated.role,
    status: updated.status,
    created_at: toISOStringSafe(updated.created_at),
    updated_at: toISOStringSafe(updated.updated_at),
    deleted_at:
      updated.deleted_at !== null
        ? toISOStringSafe(updated.deleted_at)
        : undefined,
  };
}

import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/client";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";
import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

import { AdminPayload } from "../decorators/payload/AdminPayload";

export async function deleteShoppingAdminAdminsAdminId(props: {
  admin: AdminPayload;
  adminId: string & tags.Format<"uuid">;
}): Promise<void> {
  // 1. Deny self-deletion
  if (props.admin.id === props.adminId) {
    throw new HttpException(
      "Self-deletion of admin account is prohibited.",
      403,
    );
  }

  // 2. Get performing admin actor (caller) and check role/status
  const actor = await MyGlobal.prisma.shopping_admins.findFirst({
    where: {
      id: props.admin.id,
      status: "active",
      deleted_at: null,
    },
  });
  if (!actor) {
    throw new HttpException("Performing admin not found or not active.", 403);
  }
  if (actor.role !== "super") {
    throw new HttpException(
      "Only super-admins may permanently delete administrators.",
      403,
    );
  }

  // 3. Get target admin to delete
  const target = await MyGlobal.prisma.shopping_admins.findFirst({
    where: {
      id: props.adminId,
    },
  });
  if (!target) {
    throw new HttpException("Target admin not found.", 404);
  }

  // 4. Check: Cannot delete last remaining active admin
  const activeAdminCount = await MyGlobal.prisma.shopping_admins.count({
    where: {
      status: "active",
      deleted_at: null,
    },
  });
  if (activeAdminCount <= 1) {
    throw new HttpException("Cannot delete last remaining admin account.", 403);
  }

  // 5. Fully delete all admin sessions for the target admin
  await MyGlobal.prisma.shopping_admin_sessions.deleteMany({
    where: {
      shopping_admin_id: props.adminId,
    },
  });

  // 6. Hard delete the admin account
  await MyGlobal.prisma.shopping_admins.delete({
    where: { id: props.adminId },
  });

  // 7. Write audit log of the deletion event
  await MyGlobal.prisma.shopping_audit_logs.create({
    data: {
      id: v4(),
      admin_id: props.admin.id,
      category: "admin",
      event_type: "ADMIN_HARD_DELETE",
      description: `Hard-deleted adminId=${props.adminId}`,
      created_at: toISOStringSafe(new Date()),
      updated_at: toISOStringSafe(new Date()),
    },
  });
}

import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/client";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";
import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

import { IShoppingAdminSession } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingAdminSession";
import { IPageIShoppingAdminSession } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIShoppingAdminSession";
import { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import { AdminPayload } from "../decorators/payload/AdminPayload";

export async function patchShoppingAdminAdminsAdminIdSessions(props: {
  admin: AdminPayload;
  adminId: string & tags.Format<"uuid">;
  body: IShoppingAdminSession.IRequest;
}): Promise<IPageIShoppingAdminSession.ISummary> {
  const { admin, adminId, body } = props;

  // Validate admin exists and is not deleted
  const adminRow = await MyGlobal.prisma.shopping_admins.findFirst({
    where: {
      id: adminId,
      deleted_at: null,
    },
  });
  if (!adminRow) {
    throw new HttpException("Target admin not found", 404);
  }

  // Build query filters
  const createdAtFilter =
    body.login_time_from !== undefined &&
    body.login_time_from !== null &&
    body.login_time_to !== undefined &&
    body.login_time_to !== null
      ? { gte: body.login_time_from, lte: body.login_time_to }
      : body.login_time_from !== undefined && body.login_time_from !== null
        ? { gte: body.login_time_from }
        : body.login_time_to !== undefined && body.login_time_to !== null
          ? { lte: body.login_time_to }
          : undefined;

  const where = {
    shopping_admin_id: adminId,
    ...(body.status === "active" && { expired_at: null }),
    ...(body.status === "expired" && { NOT: { expired_at: null } }),
    ...(body.ip !== undefined &&
      body.ip !== null && {
        ip: { contains: body.ip },
      }),
    ...(createdAtFilter !== undefined && { created_at: createdAtFilter }),
  };

  // Pagination
  const page = body.page;
  const limit = body.limit;
  const skip = (page - 1) * limit;

  // Sort logic
  let orderBy: { [k: string]: "asc" | "desc" } = {};
  if (body.order_by === "expired_at") {
    orderBy["expired_at"] = body.order_direction || "desc";
  } else {
    orderBy["created_at"] = body.order_direction || "desc";
  }

  const [rows, total] = await Promise.all([
    MyGlobal.prisma.shopping_admin_sessions.findMany({
      where,
      orderBy,
      skip,
      take: limit,
    }),
    MyGlobal.prisma.shopping_admin_sessions.count({ where }),
  ]);

  await MyGlobal.prisma.shopping_audit_logs.create({
    data: {
      id: v4(),
      admin_id: admin.id,
      category: "security",
      event_type: "ADMIN_SESSION_QUERY",
      ip: undefined,
      description: `Queried admin sessions for adminId ${adminId}`,
      created_at: toISOStringSafe(new Date()),
      updated_at: toISOStringSafe(new Date()),
      deleted_at: null,
    },
  });

  const data = rows.map((row) => ({
    id: row.id,
    shopping_admin_id: row.shopping_admin_id,
    ip: row.ip,
    href: row.href,
    referrer: row.referrer,
    created_at: toISOStringSafe(row.created_at),
    expired_at: row.expired_at ? toISOStringSafe(row.expired_at) : undefined,
  }));

  return {
    pagination: {
      current: page,
      limit: limit,
      records: total,
      pages: Math.ceil(total / limit),
    },
    data,
  };
}

