import { IShoppingCartItem } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingCartItem";
import { IShoppingSku } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingSku";
import { IShoppingCustomer } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingCustomer";
import { CustomerPayload } from "../decorators/payload/CustomerPayload";

export async function getShoppingCustomerCartsCartIdItemsItemId(props: {
  customer: CustomerPayload;
  cartId: string & tags.Format<"uuid">;
  itemId: string & tags.Format<"uuid">;
}): Promise<IShoppingCartItem> {
  const { customer, cartId, itemId } = props;

  const cartItem = await MyGlobal.prisma.shopping_cart_items.findUnique({
    where: {
      id: itemId,
      shopping_cart_id: cartId,
    },
    include: {
      sku: true,
      cart: {
        include: { customer: true },
      },
    },
  });

  if (!cartItem) {
    throw new HttpException("Cart item not found", 404);
  }

  if (!cartItem.cart || cartItem.cart.shopping_customer_id !== customer.id) {
    throw new HttpException(
      "Forbidden: You may only access your own cart items",
      403,
    );
  }
  if (!cartItem.cart.customer) {
    throw new HttpException("Cart owner not found", 404);
  }
  if (!cartItem.sku) {
    throw new HttpException("Cart item SKU missing", 500);
  }

  const errorFlags: string[] = [];
  if (!cartItem.sku.is_active) errorFlags.push("sku_inactive");
  if (cartItem.sku.status !== "in_stock") errorFlags.push("unavailable_status");

  return {
    id: cartItem.id,
    shopping_cart_id: cartItem.shopping_cart_id,
    sku: {
      id: cartItem.sku.id,
      sku_code: cartItem.sku.sku_code,
      price: cartItem.sku.price,
      is_active: cartItem.sku.is_active,
      status: cartItem.sku.status,
    },
    quantity: cartItem.quantity,
    added_at: toISOStringSafe(cartItem.added_at),
    updated_at: toISOStringSafe(cartItem.updated_at),
    cart_owner: {
      id: cartItem.cart.customer.id,
      name: cartItem.cart.customer.name,
      email: cartItem.cart.customer.email,
      is_active: cartItem.cart.customer.is_active,
      created_at: toISOStringSafe(cartItem.cart.customer.created_at),
      deleted_at: cartItem.cart.customer.deleted_at
        ? toISOStringSafe(cartItem.cart.customer.deleted_at)
        : null,
    },
    error_flags: errorFlags.length > 0 ? errorFlags : undefined,
  };
}

import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/client";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";
import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

import { IShoppingCartItem } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingCartItem";
import { IShoppingSku } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingSku";
import { IShoppingCustomer } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingCustomer";
import { CustomerPayload } from "../decorators/payload/CustomerPayload";

export async function postShoppingCustomerCartsCartIdItems(props: {
  customer: CustomerPayload;
  cartId: string & tags.Format<"uuid">;
  body: IShoppingCartItem.ICreate;
}): Promise<IShoppingCartItem> {
  // 1. Validate cart existence and ownership
  const cart = await MyGlobal.prisma.shopping_carts.findUnique({
    where: { id: props.cartId },
    include: { customer: true },
  });
  if (!cart || cart.shopping_customer_id !== props.customer.id) {
    throw new HttpException(
      "Not Found: Cart not found or not owned by this customer",
      404,
    );
  }

  // 2. Validate SKU existence and activity
  const sku = await MyGlobal.prisma.shopping_skus.findFirst({
    where: {
      id: props.body.shopping_sku_id,
      deleted_at: null,
    },
  });
  if (!sku) {
    throw new HttpException("Not Found: SKU does not exist", 404);
  }
  if (
    !sku.is_active ||
    sku.status === "archived" ||
    sku.status === "discontinued"
  ) {
    throw new HttpException("SKU inactive or discontinued", 400);
  }

  // 3. Lookup max quantity per SKU (default=10 if constraint missing or invalid)
  let maxQty = 10;
  const maxQtyConstraint =
    await MyGlobal.prisma.shopping_business_constraints.findFirst({
      where: {
        constraint_name: "max_quantity_per_sku_cart_item",
        active: true,
      },
    });
  if (
    maxQtyConstraint &&
    Number.isSafeInteger(Number(maxQtyConstraint.limit_value)) &&
    Number(maxQtyConstraint.limit_value) > 0
  ) {
    maxQty = Number(maxQtyConstraint.limit_value);
  }

  // 4. Look for existing cart item for SKU
  const existing = await MyGlobal.prisma.shopping_cart_items.findFirst({
    where: {
      shopping_cart_id: props.cartId,
      shopping_sku_id: props.body.shopping_sku_id,
    },
  });

  // 5. Lookup available inventory for SKU (fail if insufficient)
  const inventory = await MyGlobal.prisma.shopping_inventory.findFirst({
    where: {
      shopping_sku_id: props.body.shopping_sku_id,
      deleted_at: null,
    },
  });
  if (!inventory || inventory.quantity <= 0) {
    throw new HttpException("Insufficient stock for this SKU", 400);
  }

  const newQuantity = (existing ? existing.quantity : 0) + props.body.quantity;
  if (newQuantity > inventory.quantity) {
    throw new HttpException("Cannot add more than available stock", 400);
  }
  if (newQuantity > maxQty) {
    throw new HttpException("Exceeds maximum allowed per item in cart", 400);
  }

  // 6. Perform cart item create or update
  const now = toISOStringSafe(new Date());
  let cartItem;
  if (existing) {
    cartItem = await MyGlobal.prisma.shopping_cart_items.update({
      where: { id: existing.id },
      data: {
        quantity: newQuantity,
        updated_at: now,
      },
    });
  } else {
    cartItem = await MyGlobal.prisma.shopping_cart_items.create({
      data: {
        id: v4(),
        shopping_cart_id: props.cartId,
        shopping_sku_id: props.body.shopping_sku_id,
        quantity: props.body.quantity,
        added_at: now,
        updated_at: now,
      },
    });
  }

  // 7. Response mapping for IShoppingCartItem fields
  const skuSummary = {
    id: sku.id,
    sku_code: sku.sku_code,
    price: sku.price,
    is_active: sku.is_active,
    status: sku.status,
  };
  const owner = cart.customer;
  const customerSummary = {
    id: owner.id,
    name: owner.name,
    email: owner.email,
    is_active: owner.is_active,
    created_at: toISOStringSafe(owner.created_at),
    deleted_at: owner.deleted_at ? toISOStringSafe(owner.deleted_at) : null,
  };
  return {
    id: cartItem.id,
    shopping_cart_id: cartItem.shopping_cart_id,
    sku: skuSummary,
    quantity: cartItem.quantity,
    added_at: toISOStringSafe(cartItem.added_at),
    updated_at: toISOStringSafe(cartItem.updated_at),
    cart_owner: customerSummary,
    error_flags: [],
  };
}

import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/client";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";
import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

import { IShoppingCartItem } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingCartItem";
import { IShoppingSku } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingSku";
import { IShoppingCustomer } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingCustomer";
import { CustomerPayload } from "../decorators/payload/CustomerPayload";

export async function putShoppingCustomerCartsCartIdItemsItemId(props: {
  customer: CustomerPayload;
  cartId: string & tags.Format<"uuid">;
  itemId: string & tags.Format<"uuid">;
  body: IShoppingCartItem.IUpdate;
}): Promise<IShoppingCartItem> {
  const { customer, cartId, itemId, body } = props;
  const maxPerSkuConstraint =
    await MyGlobal.prisma.shopping_business_constraints.findFirst({
      where: { constraint_name: "max_cart_quantity_per_sku", active: true },
    });
  const maxQuantity = maxPerSkuConstraint
    ? Number(maxPerSkuConstraint.limit_value)
    : 10;

  // Find cart item, matching cartId & itemId
  const cartItem = await MyGlobal.prisma.shopping_cart_items.findUnique({
    where: { id: itemId },
  });
  if (!cartItem || cartItem.shopping_cart_id !== cartId) {
    throw new HttpException("Cart item not found", 404);
  }

  // Load cart, check ownership
  const cart = await MyGlobal.prisma.shopping_carts.findUnique({
    where: { id: cartId },
  });
  if (!cart || cart.shopping_customer_id !== customer.id) {
    throw new HttpException("Unauthorized: Not your cart", 403);
  }

  // If quantity 0: delete item & throw 404 (API expects no item returned)
  if (body.quantity === 0) {
    await MyGlobal.prisma.shopping_cart_items.delete({ where: { id: itemId } });
    throw new HttpException("Cart item removed", 404);
  }

  // Validate quantity positive
  if (body.quantity < 1) {
    throw new HttpException("Quantity must be at least 1", 400);
  }
  if (body.quantity > maxQuantity) {
    throw new HttpException(
      `Quantity exceeds platform max per SKU (${maxQuantity})`,
      400,
    );
  }

  // Lookup SKU + summary
  const sku = await MyGlobal.prisma.shopping_skus.findUnique({
    where: { id: cartItem.shopping_sku_id },
  });
  if (
    !sku ||
    sku.deleted_at !== null ||
    !sku.is_active ||
    ["archived", "discontinued", "removed"].includes(sku.status)
  ) {
    throw new HttpException("SKU is not available for cart update", 400);
  }

  // Check inventory
  const inventory = await MyGlobal.prisma.shopping_inventory.findUnique({
    where: { shopping_sku_id: sku.id },
  });
  if (
    !inventory ||
    inventory.deleted_at !== null ||
    inventory.quantity < body.quantity
  ) {
    throw new HttpException("Insufficient stock for requested quantity", 400);
  }

  // Update item
  const now = toISOStringSafe(new Date());
  const updated = await MyGlobal.prisma.shopping_cart_items.update({
    where: { id: itemId },
    data: {
      quantity: body.quantity,
      updated_at: now,
    },
  });

  // Get customer summary
  const customerRec = await MyGlobal.prisma.shopping_customers.findUnique({
    where: { id: cart.shopping_customer_id },
  });
  if (!customerRec) {
    throw new HttpException("Cart owner not found", 404);
  }

  // SKU summary
  const skuSummary = {
    id: sku.id,
    sku_code: sku.sku_code,
    price: sku.price,
    is_active: sku.is_active,
    status: sku.status,
  };

  // Cart owner summary
  const cartOwner = {
    id: customerRec.id,
    name: customerRec.name,
    email: customerRec.email,
    is_active: customerRec.is_active,
    created_at: toISOStringSafe(customerRec.created_at),
    deleted_at: customerRec.deleted_at
      ? toISOStringSafe(customerRec.deleted_at)
      : null,
  };

  // Compose result
  return {
    id: updated.id,
    shopping_cart_id: updated.shopping_cart_id,
    sku: skuSummary,
    quantity: updated.quantity,
    added_at: toISOStringSafe(updated.added_at),
    updated_at: toISOStringSafe(updated.updated_at),
    cart_owner: cartOwner,
    error_flags: undefined,
  };
}

