import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

import { IShoppingOrderLine } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingOrderLine";
import { IShoppingSku } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingSku";
import { IShoppingSeller } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingSeller";
import { IShoppingOrderLineFulfillment } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingOrderLineFulfillment";
import { CustomerPayload } from "../decorators/payload/CustomerPayload";

export async function getShoppingCustomerOrdersOrderCodeLinesOrderLineId(props: {
  customer: CustomerPayload;
  orderCode: string;
  orderLineId: string & tags.Format<"uuid">;
}): Promise<IShoppingOrderLine> {
  const { customer, orderCode, orderLineId } = props;
  // Step 1: Find order by orderCode and verify ownership
  const order = await MyGlobal.prisma.shopping_orders.findFirst({
    where: {
      order_code: orderCode,
      deleted_at: null,
    },
    select: {
      id: true,
      shopping_customer_id: true,
    },
  });
  if (!order) {
    throw new HttpException("Order not found", 404);
  }
  if (order.shopping_customer_id !== customer.id) {
    throw new HttpException("Forbidden: You do not own this order", 403);
  }
  // Step 2: Find order line by id within order
  const orderLine = await MyGlobal.prisma.shopping_order_lines.findFirst({
    where: {
      id: orderLineId,
      shopping_order_id: order.id,
    },
    select: {
      id: true,
      shopping_sku_id: true,
      quantity: true,
      unit_price: true,
      status: true,
      shopping_seller_id: true,
      created_at: true,
      updated_at: true,
      deleted_at: true,
    },
  });
  if (!orderLine) {
    throw new HttpException("Order line not found", 404);
  }
  // Step 3: Fetch SKU summary
  const sku = await MyGlobal.prisma.shopping_skus.findUnique({
    where: { id: orderLine.shopping_sku_id },
    select: {
      id: true,
      sku_code: true,
      price: true,
      is_active: true,
      status: true,
    },
  });
  if (!sku) {
    throw new HttpException("Sku not found", 500);
  }
  // Step 4: Fetch seller summary
  const seller = await MyGlobal.prisma.shopping_sellers.findUnique({
    where: { id: orderLine.shopping_seller_id },
    select: {
      id: true,
      display_name: true,
      status: true,
    },
  });
  if (!seller) {
    throw new HttpException("Seller not found", 500);
  }
  // Step 5: Fetch fulfillments for this order line, sorted by fulfilled_at
  const fulfillmentsRaw =
    await MyGlobal.prisma.shopping_order_fulfillments.findMany({
      where: { shopping_order_line_id: orderLine.id },
      select: {
        id: true,
        fulfillment_code: true,
        quantity_fulfilled: true,
        status: true,
        fulfilled_at: true,
        shopping_seller_address_id: true,
      },
      orderBy: { fulfilled_at: "asc" },
    });
  const fulfillments = fulfillmentsRaw.length
    ? fulfillmentsRaw.map((f) => ({
        id: f.id,
        fulfillment_code: f.fulfillment_code,
        quantity_fulfilled: f.quantity_fulfilled,
        status: f.status,
        fulfilled_at: toISOStringSafe(f.fulfilled_at),
        seller_address_id: f.shopping_seller_address_id,
      }))
    : undefined;
  return {
    id: orderLine.id,
    sku: {
      id: sku.id,
      sku_code: sku.sku_code,
      price: sku.price,
      is_active: sku.is_active,
      status: sku.status,
    },
    quantity: orderLine.quantity,
    unit_price: orderLine.unit_price,
    status: orderLine.status,
    seller: {
      id: seller.id,
      display_name: seller.display_name,
      status: seller.status,
    },
    fulfillments,
    created_at: toISOStringSafe(orderLine.created_at),
    updated_at: toISOStringSafe(orderLine.updated_at),
    deleted_at: orderLine.deleted_at
      ? toISOStringSafe(orderLine.deleted_at)
      : undefined,
  };
}

import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/client";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";
import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

import { IShoppingOrderLine } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingOrderLine";
import { IShoppingSku } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingSku";
import { IShoppingSeller } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingSeller";
import { IShoppingOrderLineFulfillment } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingOrderLineFulfillment";
import { AdminPayload } from "../decorators/payload/AdminPayload";

export async function postShoppingAdminOrdersOrderCodeLines(props: {
  admin: AdminPayload;
  orderCode: string;
  body: IShoppingOrderLine.ICreate;
}): Promise<IShoppingOrderLine> {
  // 1. Retrieve parent order and validate status/editability
  const order = await MyGlobal.prisma.shopping_orders.findUnique({
    where: { order_code: props.orderCode },
  });
  if (!order || order.deleted_at !== null) {
    throw new HttpException("Order not found or has been deleted", 404);
  }
  const finalizedStatuses = ["paid", "fulfilled", "cancelled"];
  if (finalizedStatuses.includes(order.status)) {
    throw new HttpException("Cannot add line to finalized order", 400);
  }
  // 2. Retrieve SKU and validate state
  const sku = await MyGlobal.prisma.shopping_skus.findUnique({
    where: { id: props.body.shopping_sku_id },
    include: { product: true },
  });
  if (!sku || !sku.is_active || sku.deleted_at !== null) {
    throw new HttpException("SKU not found or inactive", 400);
  }
  if (!sku.product || sku.product.deleted_at !== null) {
    throw new HttpException("Associated product is not active", 400);
  }
  // 3. Prevent duplicate SKU lines for this order
  const exists = await MyGlobal.prisma.shopping_order_lines.findFirst({
    where: {
      shopping_order_id: order.id,
      shopping_sku_id: props.body.shopping_sku_id,
      deleted_at: null,
    },
  });
  if (exists) {
    throw new HttpException("Order already contains this SKU", 409);
  }
  // 4. Create new order line
  const now = toISOStringSafe(new Date());
  const newLine = await MyGlobal.prisma.shopping_order_lines.create({
    data: {
      id: v4(),
      shopping_order_id: order.id,
      shopping_sku_id: sku.id,
      shopping_seller_id: sku.product.shopping_seller_id,
      quantity: props.body.quantity,
      unit_price: props.body.unit_price,
      status: "pending",
      created_at: now,
      updated_at: now,
      deleted_at: null,
    },
    include: {
      sku: true,
      seller: true,
    },
  });
  return {
    id: newLine.id,
    sku: {
      id: sku.id,
      sku_code: sku.sku_code,
      price: sku.price,
      is_active: sku.is_active,
      status: sku.status,
    },
    quantity: newLine.quantity,
    unit_price: newLine.unit_price,
    status: newLine.status,
    seller: {
      id: newLine.seller.id,
      display_name: newLine.seller.display_name,
      status: newLine.seller.status,
    },
    fulfillments: undefined,
    created_at: toISOStringSafe(newLine.created_at),
    updated_at: toISOStringSafe(newLine.updated_at),
    deleted_at:
      newLine.deleted_at === null
        ? undefined
        : toISOStringSafe(newLine.deleted_at),
  };
}

import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/client";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";
import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

import { AdminPayload } from "../decorators/payload/AdminPayload";

export async function deleteShoppingAdminOrdersOrderCodeLinesOrderLineId(props: {
  admin: AdminPayload;
  orderCode: string;
  orderLineId: string & tags.Format<"uuid">;
}): Promise<void> {
  // 1. Find the order by business order code (order_code, must not be soft deleted)
  const order = await MyGlobal.prisma.shopping_orders.findFirst({
    where: { order_code: props.orderCode, deleted_at: null },
  });
  if (!order) {
    throw new HttpException("Order not found", 404);
  }

  // 2. Find the order line by ID, belonging to this order (must not be soft deleted)
  const orderLine = await MyGlobal.prisma.shopping_order_lines.findFirst({
    where: {
      id: props.orderLineId,
      shopping_order_id: order.id,
      deleted_at: null,
    },
  });
  if (!orderLine) {
    throw new HttpException("Order line not found in this order", 404);
  }

  // 3. Validate business logic: only allow deletion if order and line are modifiable (not fulfilled/shipped/delivered/cancelled/refunded)
  if (
    orderLine.status === "fulfilled" ||
    orderLine.status === "shipped" ||
    orderLine.status === "delivered" ||
    orderLine.status === "cancelled" ||
    orderLine.status === "refunded" ||
    order.status === "fulfilled" ||
    order.status === "shipped" ||
    order.status === "delivered" ||
    order.status === "cancelled" ||
    order.status === "refunded"
  ) {
    throw new HttpException(
      "Order or order line already fulfilled, delivered, cancelled, or refunded; cannot delete order line.",
      400,
    );
  }

  // 4. Hard delete the order line item
  await MyGlobal.prisma.shopping_order_lines.delete({
    where: { id: props.orderLineId },
  });

  // 5. Recalculate the order total (excluding any now-deleted lines) and update parent order
  const remainingLines = await MyGlobal.prisma.shopping_order_lines.findMany({
    where: {
      shopping_order_id: order.id,
      deleted_at: null,
    },
  });
  const newTotal = remainingLines.reduce(
    (sum, l) => sum + l.unit_price * l.quantity,
    0,
  );
  await MyGlobal.prisma.shopping_orders.update({
    where: { id: order.id },
    data: {
      total_price: newTotal,
      updated_at: toISOStringSafe(new Date()),
    },
  });

  // 6. Write audit log for traceability
  const nowStr = toISOStringSafe(new Date());
  await MyGlobal.prisma.shopping_audit_logs.create({
    data: {
      id: v4(),
      admin_id: props.admin.id,
      seller_id: null,
      customer_id: null,
      category: "order",
      event_type: "ORDER_LINE_DELETE",
      ip: null,
      description: `Admin ${props.admin.id} deleted order line ${props.orderLineId} from order ${props.orderCode}.`,
      created_at: nowStr,
      updated_at: nowStr,
      deleted_at: null,
    },
  });
}

import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/client";
