import { toISOStringSafe } from "../utils/toISOStringSafe";

import { IShoppingRefundRequest } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingRefundRequest";
import { IPageIShoppingRefundRequest } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIShoppingRefundRequest";
import { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import { IShoppingOrder } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingOrder";
import { IShoppingCustomer } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingCustomer";
import { IShoppingRefundActor } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingRefundActor";
import { IShoppingRefundRequestItem } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingRefundRequestItem";
import { AdminPayload } from "../decorators/payload/AdminPayload";

export async function patchShoppingAdminRefunds(props: {
  admin: AdminPayload;
  body: IShoppingRefundRequest.IRequest;
}): Promise<IPageIShoppingRefundRequest.ISummary> {
  const { body } = props;
  const page = Number(body.page ?? 1);
  const limit = Number(body.limit ?? 20);
  const skip = (page - 1) * limit;

  // Build filter conditions
  const where = {
    deleted_at: null,
    ...(body.request_type !== undefined &&
      body.request_type !== null && { request_type: body.request_type }),
    ...(body.status !== undefined &&
      body.status !== null && { status: body.status }),
    ...(body.actor_type !== undefined &&
      body.actor_type !== null && { actor_type: body.actor_type }),
    ...(body.actor_id !== undefined &&
      body.actor_id !== null && { shopping_actor_id: body.actor_id }),
    ...(body.order_id !== undefined &&
      body.order_id !== null && { shopping_order_id: body.order_id }),
    ...(body.from_date !== undefined &&
      body.from_date !== null && {
        created_at: { gte: body.from_date },
      }),
    ...(body.to_date !== undefined &&
      body.to_date !== null && {
        created_at: {
          ...(body.from_date !== undefined &&
            body.from_date !== null && { gte: body.from_date }),
          lte: body.to_date,
        },
      }),
  };

  // Sorting
  let orderBy: any = { created_at: "desc" };
  if (body.order_by?.length) {
    orderBy = {
      [body.order_by]: body.order_direction === "asc" ? "asc" : "desc",
    };
  }

  // Fetch total count for pagination
  const total = await MyGlobal.prisma.shopping_refund_requests.count({ where });
  // Fetch refund requests with related info
  const requests = await MyGlobal.prisma.shopping_refund_requests.findMany({
    where,
    orderBy,
    skip,
    take: limit,
    include: {
      order: {
        include: {
          customer: true,
        },
      },
      shopping_refund_request_items: true,
    },
  });

  // Build summary data
  const data = requests.map((request) => {
    // Resolve actor
    let actor: IShoppingRefundActor.ISummary;
    if (request.actor_type === "customer") {
      // Only customer supported in DB schema for actor
      actor = {
        actor_type: "customer",
        id: request.shopping_actor_id,
        name: request.order.customer.name,
      };
    } else if (
      request.actor_type === "seller" ||
      request.actor_type === "admin"
    ) {
      // If needed, could join corresponding user
      actor = {
        actor_type: request.actor_type as "seller" | "admin",
        id: request.shopping_actor_id,
        name: "", // Not available, would require join from seller/admin tables
      };
    } else {
      actor = {
        actor_type: "customer",
        id: request.shopping_actor_id,
        name: "",
      };
    }

    // Refund items summary
    const items: IShoppingRefundRequestItem.ISummary[] =
      request.shopping_refund_request_items.map((item) => ({
        id: item.id,
        shopping_refund_request_id: item.shopping_refund_request_id,
        order_line_id: item.shopping_order_line_id,
        quantity: item.quantity,
        item_business_reason: item.item_business_reason ?? null,
        created_at: toISOStringSafe(item.created_at),
        updated_at: toISOStringSafe(item.updated_at),
      }));

    // Order summary
    const order = request.order;
    const customer = order.customer;

    const orderSummary: IShoppingOrder.ISummary = {
      id: order.id,
      order_code: order.order_code,
      total_price: order.total_price,
      status: order.status,
      created_at: toISOStringSafe(order.created_at),
      updated_at: toISOStringSafe(order.updated_at),
      customer: {
        id: customer.id,
        name: customer.name,
        email: customer.email,
        is_active: customer.is_active,
        created_at: toISOStringSafe(customer.created_at),
        deleted_at: customer.deleted_at
          ? toISOStringSafe(customer.deleted_at)
          : null,
      },
    };

    return {
      id: request.id,
      order: orderSummary,
      actor,
      request_type: request.request_type,
      business_reason: request.business_reason,
      request_context: request.request_context ?? null,
      status: request.status,
      created_at: toISOStringSafe(request.created_at),
      updated_at: toISOStringSafe(request.updated_at),
      items,
    };
  });

  return {
    pagination: {
      current: page,
      limit: limit,
      records: total,
      pages: Math.ceil(total / limit),
    },
    data,
  };
}

import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/client";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";
import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

import { CustomerPayload } from "../decorators/payload/CustomerPayload";

export async function deleteShoppingCustomerRefundsRefundRequestId(props: {
  customer: CustomerPayload;
  refundRequestId: string & tags.Format<"uuid">;
}): Promise<void> {
  // 1. Find the refund request
  const refundRequest =
    await MyGlobal.prisma.shopping_refund_requests.findUnique({
      where: { id: props.refundRequestId },
    });
  if (!refundRequest) {
    throw new HttpException("Refund request not found", 404);
  }
  // 2. Auth: Only the customer actor who created this can delete
  if (
    refundRequest.actor_type !== "customer" ||
    refundRequest.shopping_actor_id !== props.customer.id
  ) {
    throw new HttpException(
      "You do not have permission to delete this refund request",
      403,
    );
  }
  // 3. Only allow deletion for eligible statuses (pending only)
  if (refundRequest.status !== "pending") {
    throw new HttpException(
      "Refund request cannot be deleted due to its current status",
      409,
    );
  }
  // 4. Soft delete: set deleted_at
  await MyGlobal.prisma.shopping_refund_requests.update({
    where: { id: props.refundRequestId },
    data: { deleted_at: toISOStringSafe(new Date()) },
  });
  // 5. AUDIT LOGGING: Omitted (DTO for audit-log not provided)
}

import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/client";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";
import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

import { SellerPayload } from "../decorators/payload/SellerPayload";

export async function deleteShoppingSellerRefundsRefundRequestId(props: {
  seller: SellerPayload;
  refundRequestId: string & tags.Format<"uuid">;
}): Promise<void> {
  // Fetch refund request to ensure it exists and is not already deleted
  const refund = await MyGlobal.prisma.shopping_refund_requests.findUnique({
    where: { id: props.refundRequestId },
  });
  if (!refund || refund.deleted_at !== null) {
    throw new HttpException("Refund request not found or already deleted", 404);
  }
  // Check that the actor is a seller and matches the authenticated seller
  if (
    refund.actor_type !== "seller" ||
    refund.shopping_actor_id !== props.seller.id
  ) {
    throw new HttpException(
      "Forbidden: Only the original seller can delete this refund request",
      403,
    );
  }
  // Prevent deletion if in a locked status (extend as needed)
  const lockedStatuses = ["under_review", "locked"];
  if (lockedStatuses.includes(refund.status)) {
    throw new HttpException(
      "Refund request cannot be deleted in the current state",
      403,
    );
  }
  // Perform soft delete by populating deleted_at
  await MyGlobal.prisma.shopping_refund_requests.update({
    where: { id: props.refundRequestId },
    data: { deleted_at: toISOStringSafe(new Date()) },
  });
}

import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/client";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";
import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

import { AdminPayload } from "../decorators/payload/AdminPayload";

export async function deleteShoppingAdminRefundsRefundRequestId(props: {
  admin: AdminPayload;
  refundRequestId: string & tags.Format<"uuid">;
}): Promise<void> {
  const { admin, refundRequestId } = props;

  // Find the refund request (must exist, not already deleted)
  const refundRequest =
    await MyGlobal.prisma.shopping_refund_requests.findUnique({
      where: { id: refundRequestId },
    });
  if (!refundRequest) {
    throw new HttpException("Refund request not found", 404);
  }
  if (refundRequest.deleted_at !== null) {
    throw new HttpException("Refund request has already been deleted", 409);
  }
  // Check business logic for eligibility
  if (
    refundRequest.status === "under_review" ||
    refundRequest.status === "locked"
  ) {
    throw new HttpException(
      "Cannot delete refund request in locked or under_review state",
      403,
    );
  }

  // Soft-delete: set deleted_at to now (ISO 8601 format string)
  const now = toISOStringSafe(new Date());
  await MyGlobal.prisma.shopping_refund_requests.update({
    where: { id: refundRequestId },
    data: { deleted_at: now },
  });

  // Log admin deletion event for compliance/audit
  await MyGlobal.prisma.shopping_audit_logs.create({
    data: {
      id: v4(),
      admin_id: admin.id,
      category: "refund_request",
      event_type: "ADMIN_REFUND_REQUEST_DELETE",
      description: `Admin ${admin.id} deleted refund request ${refundRequestId} at ${now}`,
      created_at: now,
      updated_at: now,
    },
  });
}

import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/client";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";
import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

import { IShoppingRefundRequestItem } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingRefundRequestItem";
import { IPageIShoppingRefundRequestItem } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIShoppingRefundRequestItem";
import { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import { SellerPayload } from "../decorators/payload/SellerPayload";

export async function patchShoppingSellerRefundsRefundRequestIdItems(props: {
  seller: SellerPayload;
  refundRequestId: string & tags.Format<"uuid">;
  body: IShoppingRefundRequestItem.IRequest;
}): Promise<IPageIShoppingRefundRequestItem.ISummary> {
  const page = props.body.page !== undefined ? props.body.page : 1;
  const limit = props.body.limit !== undefined ? props.body.limit : 20;
  const offset = (page - 1) * limit;

  // 1. Query relevant refund items for this refund request (must be for order lines owned by this seller)
  // Also support sku_code/order_line_id/status filtering (sku_code requires join to order_lines+skus)

  // First, gather all order line IDs for this seller
  const orderLines = await MyGlobal.prisma.shopping_order_lines.findMany({
    where: { shopping_seller_id: props.seller.id },
    select: {
      id: true,
      sku: { select: { sku_code: true } },
    },
  });
  const sellerOrderLineIds = orderLines.map((l) => l.id);
  if (sellerOrderLineIds.length === 0) {
    // Seller is not related to this refund request (no order lines owned)
    return {
      pagination: {
        current: Number(page),
        limit: Number(limit),
        records: 0,
        pages: 0,
      },
      data: [],
    };
  }

  // Optional filter: by sku_code
  let skuFilteredLineIds: string[] | null = null;
  if (props.body.sku_code !== undefined) {
    skuFilteredLineIds = orderLines
      .filter((ol) => ol.sku && ol.sku.sku_code === props.body.sku_code)
      .map((ol) => ol.id);
    // If no order lines with this sku_code for seller, can only return empty
    if (skuFilteredLineIds.length === 0) {
      return {
        pagination: {
          current: Number(page),
          limit: Number(limit),
          records: 0,
          pages: 0,
        },
        data: [],
      };
    }
  }

  // Build where clause for refund items
  const where = {
    shopping_refund_request_id: props.refundRequestId,
    shopping_order_line_id: {
      in:
        skuFilteredLineIds !== null
          ? skuFilteredLineIds
          : props.body.order_line_id !== undefined
            ? [props.body.order_line_id]
            : sellerOrderLineIds,
    },
  };

  // 2. Query matching refund items with pagination
  const [rows, total] = await Promise.all([
    MyGlobal.prisma.shopping_refund_request_items.findMany({
      where,
      orderBy: { created_at: "desc" },
      skip: offset,
      take: limit,
      select: {
        id: true,
        shopping_refund_request_id: true,
        shopping_order_line_id: true,
        quantity: true,
        item_business_reason: true,
        created_at: true,
        updated_at: true,
      },
    }),
    MyGlobal.prisma.shopping_refund_request_items.count({ where }),
  ]);

  const data = rows.map((item) => {
    const summary: IShoppingRefundRequestItem.ISummary = {
      id: item.id,
      shopping_refund_request_id: item.shopping_refund_request_id,
      order_line_id: item.shopping_order_line_id,
      quantity: item.quantity,
      created_at: toISOStringSafe(item.created_at),
      updated_at: toISOStringSafe(item.updated_at),
    };
    if (
      item.item_business_reason !== undefined &&
      item.item_business_reason !== null
    ) {
      summary.item_business_reason = item.item_business_reason;
    }
    return summary;
  });

  return {
    pagination: {
      current: Number(page),
      limit: Number(limit),
      records: total,
      pages: Math.ceil(total / (limit === 0 ? 1 : limit)),
    },
    data,
  };
}

import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/client";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";
import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

import { CustomerPayload } from "../decorators/payload/CustomerPayload";

export async function deleteShoppingCustomerRefundsRefundRequestIdItemsItemId(props: {
  customer: CustomerPayload;
  refundRequestId: string & tags.Format<"uuid">;
  itemId: string & tags.Format<"uuid">;
}): Promise<void> {
  // Fetch the refund request item and its parent; validate both existence and ownership.
  const [refundRequest, refundItem] = await Promise.all([
    MyGlobal.prisma.shopping_refund_requests.findFirst({
      where: {
        id: props.refundRequestId,
        shopping_actor_id: props.customer.id,
        deleted_at: null,
      },
    }),
    MyGlobal.prisma.shopping_refund_request_items.findFirst({
      where: {
        id: props.itemId,
        shopping_refund_request_id: props.refundRequestId,
      },
    }),
  ]);
  if (!refundRequest) {
    throw new HttpException("Refund request not found or access denied.", 404);
  }
  if (!refundItem) {
    throw new HttpException("Refund request item not found.", 404);
  }
  if (refundRequest.status !== "pending") {
    throw new HttpException(
      "Refund request is already processed or not deletable.",
      409,
    );
  }
  await MyGlobal.prisma.shopping_refund_request_items.delete({
    where: { id: props.itemId },
  });
}

import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/client";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";
import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

import { AdminPayload } from "../decorators/payload/AdminPayload";

export async function deleteShoppingAdminRefundsRefundRequestIdItemsItemId(props: {
  admin: AdminPayload;
  refundRequestId: string & tags.Format<"uuid">;
  itemId: string & tags.Format<"uuid">;
}): Promise<void> {
  // Find the refund request item and verify its parent refundRequestId
  const item = await MyGlobal.prisma.shopping_refund_request_items.findUnique({
    where: { id: props.itemId },
    select: { id: true, shopping_refund_request_id: true },
  });
  if (!item || item.shopping_refund_request_id !== props.refundRequestId) {
    throw new HttpException(
      "Refund request item not found for specified refundRequestId",
      404,
    );
  }

  // Get the parent refund request for status
  const refund = await MyGlobal.prisma.shopping_refund_requests.findUnique({
    where: { id: props.refundRequestId },
    select: { status: true },
  });
  if (!refund) {
    throw new HttpException("Refund request not found", 404);
  }

  // Only allow delete for pending/draft refund status per business rules
  if (refund.status !== "pending" && refund.status !== "draft") {
    throw new HttpException(
      "Cannot delete item: refund is not in a modifiable state",
      409,
    );
  }

  // Delete the refund request item
  await MyGlobal.prisma.shopping_refund_request_items.delete({
    where: { id: props.itemId },
  });

  // Audit log for admin action
  await MyGlobal.prisma.shopping_audit_logs.create({
    data: {
      id: v4(),
      admin_id: props.admin.id,
      seller_id: undefined,
      customer_id: undefined,
      category: "refund",
      event_type: "ADMIN_DELETE_REFUND_ITEM",
      ip: undefined,
      description: `Admin deleted refund item ${props.itemId} from refund ${props.refundRequestId}`,
      created_at: toISOStringSafe(new Date()),
      updated_at: toISOStringSafe(new Date()),
      deleted_at: undefined,
    },
  });
}

import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/client";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";
import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

import { IShoppingRefundAttachment } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingRefundAttachment";
import { IPageIShoppingRefundAttachment } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIShoppingRefundAttachment";
import { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import { CustomerPayload } from "../decorators/payload/CustomerPayload";

export async function patchShoppingCustomerRefundsRefundRequestIdAttachments(props: {
  customer: CustomerPayload;
  refundRequestId: string & tags.Format<"uuid">;
  body: IShoppingRefundAttachment.IRequest;
}): Promise<IPageIShoppingRefundAttachment.ISummary> {
  // 1. Check that the refund request exists and belongs to this customer
  const refundRequest =
    await MyGlobal.prisma.shopping_refund_requests.findFirst({
      where: {
        id: props.refundRequestId,
        shopping_actor_id: props.customer.id,
        deleted_at: null,
      },
    });
  if (!refundRequest) {
    throw new HttpException("Refund request not found or access denied", 404);
  }
  // 2. Build Prisma where condition
  const page = props.body.page ?? 1;
  const limit = (() => {
    const l = props.body.limit ?? 20;
    return l > 100 ? 100 : l;
  })();
  const skip = (page - 1) * limit;
  // Build uploaded_at filter range
  let uploadedAtCond: Record<string, string> = {};
  if (props.body.uploaded_after !== undefined) {
    uploadedAtCond.gte = props.body.uploaded_after;
  }
  if (props.body.uploaded_before !== undefined) {
    uploadedAtCond.lte = props.body.uploaded_before;
  }

  const where = {
    shopping_refund_request_id: props.refundRequestId,
    deleted_at: null,
    ...(props.body.attachment_type !== undefined && {
      attachment_type: props.body.attachment_type,
    }),
    ...(Object.keys(uploadedAtCond).length > 0 && {
      uploaded_at: uploadedAtCond,
    }),
    ...(props.body.keyword !== undefined &&
      props.body.keyword.trim().length > 0 && {
        description: { contains: props.body.keyword },
      }),
  };

  const [attachments, total] = await Promise.all([
    MyGlobal.prisma.shopping_refund_attachments.findMany({
      where,
      orderBy: { uploaded_at: "desc" },
      skip,
      take: limit,
    }),
    MyGlobal.prisma.shopping_refund_attachments.count({ where }),
  ]);

  const data = attachments.map((row) => ({
    id: row.id,
    shopping_refund_request_id: row.shopping_refund_request_id,
    shopping_refund_request_item_id:
      row.shopping_refund_request_item_id ?? null,
    attachment_file_id: row.attachment_file_id,
    attachment_type: row.attachment_type,
    description: row.description ?? null,
    uploaded_at: toISOStringSafe(row.uploaded_at),
  }));

  return {
    pagination: {
      current: Number(page),
      limit: Number(limit),
      records: total,
      pages: Math.ceil(total / limit),
    },
    data,
  };
}

