import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/client";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";
import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

import { SellerPayload } from "../decorators/payload/SellerPayload";

export async function deleteShoppingSellerRefundsRefundRequestIdAttachmentsAttachmentId(props: {
  seller: SellerPayload;
  refundRequestId: string & tags.Format<"uuid">;
  attachmentId: string & tags.Format<"uuid">;
}): Promise<void> {
  // 1. Validate attachment exists and linked to given refundRequestId
  const attachment =
    await MyGlobal.prisma.shopping_refund_attachments.findFirst({
      where: {
        id: props.attachmentId,
        shopping_refund_request_id: props.refundRequestId,
      },
      select: { id: true, shopping_refund_request_id: true },
    });
  if (!attachment) {
    throw new HttpException(
      "Attachment not found or not linked to this refund request",
      404,
    );
  }

  // 2. Fetch refund request and check seller owns it (via order line seller matching this seller id)
  const refund = await MyGlobal.prisma.shopping_refund_requests.findUnique({
    where: { id: props.refundRequestId },
    select: { shopping_order_id: true, status: true },
  });
  if (!refund) {
    throw new HttpException("Refund request not found", 404);
  }
  // Any order line with correct seller is sufficient for authorization
  const orderLine = await MyGlobal.prisma.shopping_order_lines.findFirst({
    where: {
      shopping_order_id: refund.shopping_order_id,
      shopping_seller_id: props.seller.id,
    },
    select: { id: true },
  });
  if (!orderLine) {
    throw new HttpException(
      "You are not authorized to delete attachments from this refund request",
      403,
    );
  }
  // 3. Check refund request status isn't closed/locked
  if (refund.status === "closed" || refund.status === "locked") {
    throw new HttpException(
      "Refund request is closed or locked and cannot be modified",
      409,
    );
  }
  // 4. Delete the attachment row
  await MyGlobal.prisma.shopping_refund_attachments.delete({
    where: { id: props.attachmentId },
  });

  // 5. Add audit entry (log deletion)
  const now = toISOStringSafe(new Date());
  await MyGlobal.prisma.shopping_system_logs.create({
    data: {
      id: v4(),
      event_time: now,
      log_level: "info",
      event_type: "refund_attachment_deleted",
      event_source: "refund_attachment_service",
      message: `Attachment ${props.attachmentId} deleted from refund request ${props.refundRequestId} by seller ${props.seller.id}`,
      details: null,
      created_at: now,
    },
  });
  // (Optional) Remove file blob from storage here if managed externally
}

import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/client";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";
import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

import { IShoppingRefundApproval } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingRefundApproval";
import { IPageIShoppingRefundApproval } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIShoppingRefundApproval";
import { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import { AdminPayload } from "../decorators/payload/AdminPayload";

export async function patchShoppingAdminRefundsRefundRequestIdApprovals(props: {
  admin: AdminPayload;
  refundRequestId: string & tags.Format<"uuid">;
  body: IShoppingRefundApproval.IRequest;
}): Promise<IPageIShoppingRefundApproval.ISummary> {
  const { refundRequestId, body } = props;

  // 1. Validate refundRequest exists and is not soft-deleted
  const refundRequest =
    await MyGlobal.prisma.shopping_refund_requests.findFirst({
      where: {
        id: refundRequestId,
        deleted_at: null,
      },
      select: { id: true },
    });
  if (!refundRequest) {
    throw new HttpException("Refund request not found", 404);
  }

  // 2. Pagination enforcement
  const page = Number(body.page ?? 1);
  const pageSize = Math.min(Math.max(Number(body.pageSize ?? 20), 1), 100);
  const skip = (page - 1) * pageSize;
  const take = pageSize;

  // 3. Build where clause for Prisma
  const where: Record<string, unknown> = {
    shopping_refund_request_id: refundRequestId,
  };
  if (
    typeof body.actor_type === "string" &&
    (body.actor_type === "admin" || body.actor_type === "seller")
  ) {
    where.actor_type = body.actor_type;
  }
  if (typeof body.actor_id === "string") {
    where.shopping_actor_id = body.actor_id;
  }
  if (typeof body.action === "string") {
    where.action = body.action;
  }
  if (typeof body.fromCreatedAt === "string") {
    (where.created_at ??= {}) as { gte?: string; lte?: string };
    (where.created_at as { gte?: string }).gte = body.fromCreatedAt;
  }
  if (typeof body.toCreatedAt === "string") {
    (where.created_at ??= {}) as { gte?: string; lte?: string };
    (where.created_at as { lte?: string }).lte = body.toCreatedAt;
  }
  if (typeof body.has_note === "boolean") {
    if (body.has_note) {
      where.NOT = { note: null };
    } else {
      where.note = null;
    }
  }

  // 4. Query approvals and count in parallel
  const [records, total] = await Promise.all([
    MyGlobal.prisma.shopping_refund_approvals.findMany({
      where,
      orderBy: { created_at: "desc" },
      skip,
      take,
      select: {
        id: true,
        shopping_refund_request_id: true,
        shopping_refund_status_history_id: true,
        shopping_actor_id: true,
        actor_type: true,
        action: true,
        note: true,
        created_at: true,
      },
    }),
    MyGlobal.prisma.shopping_refund_approvals.count({ where }),
  ]);

  // 5. Format and return
  return {
    pagination: {
      current: page,
      limit: pageSize,
      records: total,
      pages: Math.ceil(total / pageSize),
    },
    data: records.map((row) => ({
      id: row.id,
      shopping_refund_request_id: row.shopping_refund_request_id,
      shopping_refund_status_history_id: row.shopping_refund_status_history_id,
      shopping_actor_id: row.shopping_actor_id,
      actor_type: row.actor_type === "admin" ? "admin" : "seller",
      action: row.action,
      note: row.note ?? undefined,
      created_at: toISOStringSafe(row.created_at),
    })),
  };
}

