export async function getShoppingAdminShipmentsCodePackagesPackageLabelTrackingsTrackingSource(props: {
  admin: AdminPayload;
  code: string;
  packageLabel: string;
  trackingSource: string;
}): Promise<IShoppingShipmentTracking> {
  const { code, packageLabel, trackingSource } = props;

  // 1. Find shipment by unique code
  const shipment = await MyGlobal.prisma.shopping_shipments.findUnique({
    where: { code },
    select: { id: true },
  });
  if (!shipment) {
    throw new HttpException("Shipment not found", 404);
  }

  // 2. Find package by label and shipment id
  const pkg = await MyGlobal.prisma.shopping_shipment_packages.findFirst({
    where: {
      shopping_shipment_id: shipment.id,
      package_label: packageLabel,
      deleted_at: null,
    },
    select: { id: true },
  });
  if (!pkg) {
    throw new HttpException("Package not found", 404);
  }

  // 3. Find tracking by tracking_source and package id
  const tracking = await MyGlobal.prisma.shopping_shipment_trackings.findFirst({
    where: {
      shopping_shipment_package_id: pkg.id,
      tracking_source: trackingSource,
      deleted_at: null,
    },
  });
  if (!tracking) {
    throw new HttpException("Tracking not found", 404);
  }

  // 4. Construct IShoppingShipmentTracking
  return {
    id: tracking.id,
    shopping_shipment_package_id: tracking.shopping_shipment_package_id,
    tracking_source: tracking.tracking_source,
    external_tracking_id: tracking.external_tracking_id ?? undefined,
    status: tracking.status,
    status_detail: tracking.status_detail ?? undefined,
    last_update_at: toISOStringSafe(tracking.last_update_at),
    estimated_delivery_at: tracking.estimated_delivery_at
      ? toISOStringSafe(tracking.estimated_delivery_at)
      : undefined,
    created_at: toISOStringSafe(tracking.created_at),
    updated_at: toISOStringSafe(tracking.updated_at),
    deleted_at: tracking.deleted_at
      ? toISOStringSafe(tracking.deleted_at)
      : undefined,
  };
}

import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/client";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";
import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

import { IShoppingShipmentTrackingEvent } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingShipmentTrackingEvent";
import { IPageIShoppingShipmentTrackingEvent } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIShoppingShipmentTrackingEvent";
import { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import { AdminPayload } from "../decorators/payload/AdminPayload";

export async function patchShoppingAdminShipmentsCodePackagesPackageLabelTrackingsTrackingSourceEvents(props: {
  admin: AdminPayload;
  code: string;
  packageLabel: string;
  trackingSource: string;
  body: IShoppingShipmentTrackingEvent.IRequest;
}): Promise<IPageIShoppingShipmentTrackingEvent> {
  const { code, packageLabel, trackingSource, body } = props;

  const shipment = await MyGlobal.prisma.shopping_shipments.findFirst({
    where: { code, deleted_at: null },
  });
  if (!shipment) throw new HttpException("Shipment not found", 404);

  const shipmentPackage =
    await MyGlobal.prisma.shopping_shipment_packages.findFirst({
      where: {
        shopping_shipment_id: shipment.id,
        package_label: packageLabel,
        deleted_at: null,
      },
    });
  if (!shipmentPackage) throw new HttpException("Package not found", 404);

  const tracking = await MyGlobal.prisma.shopping_shipment_trackings.findFirst({
    where: {
      shopping_shipment_package_id: shipmentPackage.id,
      tracking_source: trackingSource,
      deleted_at: null,
    },
  });
  if (!tracking) throw new HttpException("Tracking instance not found", 404);

  const page = body.page ?? 1;
  const limit = body.limit ?? 20;
  const skip = (page - 1) * limit;
  const take = limit;

  const where: Record<string, any> = {
    shopping_shipment_tracking_id: tracking.id,
    deleted_at: null,
    ...(body.event_code !== undefined &&
      body.event_code !== null && { event_code: body.event_code }),
    ...(body.location !== undefined &&
      body.location !== null && { location: body.location }),
    ...(body.from_datetime !== undefined &&
      body.from_datetime !== null && {
        event_time: { gte: body.from_datetime },
      }),
    ...(body.to_datetime !== undefined &&
      body.to_datetime !== null && {
        event_time: {
          ...(body.from_datetime !== undefined &&
            body.from_datetime !== null && { gte: body.from_datetime }),
          lte: body.to_datetime,
        },
      }),
  };
  if (body.search) {
    where.OR = [
      { event_code: { contains: body.search } },
      { raw_status: { contains: body.search } },
      { location: { contains: body.search } },
    ];
  }

  const validSortFields = ["event_time", "event_code", "location"];
  const sortField =
    typeof body.sort_by === "string" && validSortFields.includes(body.sort_by)
      ? body.sort_by
      : "event_time";
  const sortOrder = body.order === "asc" ? "asc" : "desc";

  const [rows, total] = await Promise.all([
    MyGlobal.prisma.shopping_shipment_tracking_events.findMany({
      where,
      orderBy: { [sortField]: sortOrder },
      skip,
      take,
    }),
    MyGlobal.prisma.shopping_shipment_tracking_events.count({ where }),
  ]);

  return {
    pagination: {
      current: Number(page),
      limit: Number(limit),
      records: total,
      pages: Math.ceil(total / Number(limit)),
    },
    data: rows.map((row) => ({
      id: row.id,
      shopping_shipment_tracking_id: row.shopping_shipment_tracking_id,
      event_time: toISOStringSafe(row.event_time),
      event_code: row.event_code,
      location: row.location ?? undefined,
      raw_status: row.raw_status,
      external_ref: row.external_ref ?? undefined,
      ingested_at: toISOStringSafe(row.ingested_at),
      created_at: toISOStringSafe(row.created_at),
      deleted_at: row.deleted_at ? toISOStringSafe(row.deleted_at) : undefined,
    })),
  };
}

import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/client";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";
import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

import { IShoppingReview } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingReview";
import { IShoppingCustomer } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingCustomer";
import { IShoppingSku } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingSku";
import { IShoppingReviewAttachment } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingReviewAttachment";
import { IShoppingReviewModeration } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingReviewModeration";
import { IShoppingReviewAbuseReport } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingReviewAbuseReport";
import { SellerPayload } from "../decorators/payload/SellerPayload";

export async function getShoppingSellerReviewsReviewId(props: {
  seller: SellerPayload;
  reviewId: string & tags.Format<"uuid">;
}): Promise<IShoppingReview> {
  // Fetch review by reviewId and soft-deletion
  const review = await MyGlobal.prisma.shopping_reviews.findUnique({
    where: { id: props.reviewId },
  });
  if (!review || review.deleted_at) {
    throw new HttpException("Review not found", 404);
  }

  // Get SKU and product, confirm ownership
  const sku = await MyGlobal.prisma.shopping_skus.findUnique({
    where: { id: review.shopping_sku_id },
  });
  if (!sku || sku.deleted_at) {
    throw new HttpException("Review's SKU not found", 404);
  }
  const product = await MyGlobal.prisma.shopping_products.findUnique({
    where: { id: sku.shopping_product_id },
  });
  if (!product || product.deleted_at) {
    throw new HttpException("Related product not found", 404);
  }
  if (product.shopping_seller_id !== props.seller.id) {
    throw new HttpException("Forbidden: Review is not for your product", 403);
  }

  // Fetch customer summary
  const customer = await MyGlobal.prisma.shopping_customers.findUnique({
    where: { id: review.shopping_customer_id },
  });
  if (!customer) {
    throw new HttpException("Customer not found", 404);
  }
  const customerSummary = {
    id: customer.id,
    name: customer.name,
    email: customer.email,
    is_active: customer.is_active,
    created_at: toISOStringSafe(customer.created_at),
    deleted_at: customer.deleted_at
      ? toISOStringSafe(customer.deleted_at)
      : null,
  };

  // Map SKU summary
  const skuSummary = {
    id: sku.id,
    sku_code: sku.sku_code,
    price: sku.price,
    is_active: sku.is_active,
    status: sku.status,
  };

  // Gather attachments (excluding soft-deleted)
  const attachmentsRows =
    await MyGlobal.prisma.shopping_review_attachments.findMany({
      where: { shopping_review_id: props.reviewId, deleted_at: null },
    });
  const attachments = attachmentsRows.map((att) => ({
    id: att.id,
    shopping_review_id: att.shopping_review_id,
    file_uri: att.file_uri,
    file_type: att.file_type,
    file_size: att.file_size,
    created_at: toISOStringSafe(att.created_at),
    deleted_at: undefined,
    shopping_review: undefined,
  }));

  // Moderation logs
  const moderationRows =
    await MyGlobal.prisma.shopping_review_moderations.findMany({
      where: { shopping_review_id: props.reviewId },
      orderBy: { created_at: "asc" },
    });
  const moderation =
    moderationRows.length > 0
      ? moderationRows.map((m) => ({
          id: m.id,
          shopping_review_id: m.shopping_review_id,
          moderator_admin_id: m.moderator_admin_id,
          action: m.action,
          reason: m.reason ?? undefined,
          created_at: toISOStringSafe(m.created_at),
        }))
      : undefined;

  // Abuse reports (exclude soft-deleted)
  const abuseReportRows =
    await MyGlobal.prisma.shopping_review_abuse_reports.findMany({
      where: { shopping_review_id: props.reviewId, deleted_at: null },
    });
  const abuse_reports =
    abuseReportRows.length > 0
      ? abuseReportRows.map((r) => ({
          id: r.id,
          shopping_review_id: r.shopping_review_id,
          reporter_customer_id: r.reporter_customer_id,
          report_type: r.report_type,
          comment: r.comment ?? undefined,
          state: r.state,
          created_at: toISOStringSafe(r.created_at),
          updated_at: toISOStringSafe(r.updated_at),
          deleted_at: undefined,
        }))
      : undefined;

  // Map state to IShoppingReview['state']
  let state: IShoppingReview["state"] =
    review.state === "pending_moderation"
      ? "pending_moderation"
      : review.state === "under_review"
        ? "under_review"
        : review.state === "removed"
          ? "removed"
          : "visible";

  return {
    id: review.id,
    customer: customerSummary,
    sku: skuSummary,
    order_line_id: review.shopping_order_line_id,
    rating: review.rating,
    comment: review.comment,
    state,
    created_at: toISOStringSafe(review.created_at),
    updated_at: toISOStringSafe(review.updated_at),
    deleted_at: review.deleted_at
      ? toISOStringSafe(review.deleted_at)
      : undefined,
    attachments,
    moderation,
    abuse_reports,
  };
}

import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/client";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";
import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

import { IShoppingReview } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingReview";
import { IShoppingReviewAttachment } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingReviewAttachment";
import { IShoppingCustomer } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingCustomer";
import { IShoppingSku } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingSku";
import { IShoppingReviewModeration } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingReviewModeration";
import { IShoppingReviewAbuseReport } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingReviewAbuseReport";
import { CustomerPayload } from "../decorators/payload/CustomerPayload";

export async function putShoppingCustomerReviewsReviewId(props: {
  customer: CustomerPayload;
  reviewId: string & tags.Format<"uuid">;
  body: IShoppingReview.IUpdate;
}): Promise<IShoppingReview> {
  const { customer, reviewId, body } = props;

  // Fetch review record by ID
  const review = await MyGlobal.prisma.shopping_reviews.findUnique({
    where: { id: reviewId },
  });
  if (!review || review.deleted_at !== null) {
    throw new HttpException("Review not found", 404);
  }
  // Authorship check
  if (review.shopping_customer_id !== customer.id) {
    throw new HttpException(
      "Only the review author may edit this review.",
      403,
    );
  }
  if (review.state === "removed" || review.state === "under_review") {
    throw new HttpException("This review cannot be modified.", 403);
  }
  // Editing window: 7 days from creation
  const nowIso: string & tags.Format<"date-time"> = toISOStringSafe(new Date());
  const createdMs = new Date(toISOStringSafe(review.created_at)).getTime();
  const nowMs = new Date(nowIso).getTime();
  const sevenDaysMs = 7 * 24 * 60 * 60 * 1000;
  if (nowMs - createdMs > sevenDaysMs) {
    throw new HttpException("REVIEW_EDIT_WINDOW_EXPIRED", 403);
  }
  // Prepare patch for allowed fields
  const update: Record<string, unknown> = {
    updated_at: nowIso,
  };
  if (typeof body.rating !== "undefined") {
    update.rating = body.rating;
  }
  if (typeof body.comment !== "undefined") {
    update.comment = body.comment;
  }
  // Apply update
  const updated = await MyGlobal.prisma.shopping_reviews.update({
    where: { id: reviewId },
    data: update,
  });
  // Handle attachments replacement if provided
  if (typeof body.attachments !== "undefined") {
    await MyGlobal.prisma.shopping_review_attachments.deleteMany({
      where: { shopping_review_id: reviewId },
    });
    if (Array.isArray(body.attachments) && body.attachments.length > 0) {
      await Promise.all(
        body.attachments.map((a) =>
          MyGlobal.prisma.shopping_review_attachments.create({
            data: {
              id: v4(),
              shopping_review_id: reviewId,
              file_uri: a.file_uri,
              file_type: a.file_type,
              file_size: a.file_size,
              created_at: nowIso,
              deleted_at: null,
            },
          }),
        ),
      );
    }
  }
  // Join customer, sku, attachments, mod, abuse reports
  const [customerRow, skuRow] = await Promise.all([
    MyGlobal.prisma.shopping_customers.findUniqueOrThrow({
      where: {
        id: updated.shopping_customer_id,
        deleted_at: null,
      },
    }),
    MyGlobal.prisma.shopping_skus.findUniqueOrThrow({
      where: { id: updated.shopping_sku_id },
    }),
  ]);
  const attachments =
    await MyGlobal.prisma.shopping_review_attachments.findMany({
      where: { shopping_review_id: updated.id, deleted_at: null },
      orderBy: { created_at: "asc" },
    });
  const moderation = await MyGlobal.prisma.shopping_review_moderations.findMany(
    {
      where: { shopping_review_id: updated.id },
      orderBy: { created_at: "desc" },
    },
  );
  const abuse_reports =
    await MyGlobal.prisma.shopping_review_abuse_reports.findMany({
      where: { shopping_review_id: updated.id },
      orderBy: { created_at: "desc" },
    });
  return {
    id: updated.id,
    customer: {
      id: customerRow.id,
      name: customerRow.name,
      email: customerRow.email,
      is_active: customerRow.is_active,
      created_at: toISOStringSafe(customerRow.created_at),
      deleted_at: customerRow.deleted_at
        ? toISOStringSafe(customerRow.deleted_at)
        : null,
    },
    sku: {
      id: skuRow.id,
      sku_code: skuRow.sku_code,
      price: skuRow.price,
      is_active: skuRow.is_active,
      status: skuRow.status,
    },
    order_line_id: updated.shopping_order_line_id,
    rating: updated.rating,
    comment: updated.comment,
    state: updated.state as
      | "visible"
      | "pending_moderation"
      | "removed"
      | "under_review",
    created_at: toISOStringSafe(updated.created_at),
    updated_at: toISOStringSafe(updated.updated_at),
    deleted_at:
      updated.deleted_at !== null
        ? toISOStringSafe(updated.deleted_at)
        : undefined,
    attachments: attachments.map((att) => ({
      id: att.id,
      shopping_review_id: att.shopping_review_id,
      file_uri: att.file_uri,
      file_type: att.file_type,
      file_size: att.file_size,
      created_at: toISOStringSafe(att.created_at),
      deleted_at:
        att.deleted_at !== null ? toISOStringSafe(att.deleted_at) : undefined,
      shopping_review: undefined,
    })),
    moderation: moderation.map((m) => ({
      id: m.id,
      shopping_review_id: m.shopping_review_id,
      moderator_admin_id: m.moderator_admin_id,
      action: m.action,
      reason: m.reason ?? undefined,
      created_at: toISOStringSafe(m.created_at),
    })),
    abuse_reports: abuse_reports.map((r) => ({
      id: r.id,
      shopping_review_id: r.shopping_review_id,
      reporter_customer_id: r.reporter_customer_id,
      report_type: r.report_type,
      comment: r.comment ?? undefined,
      state: r.state,
      created_at: toISOStringSafe(r.created_at),
      updated_at: toISOStringSafe(r.updated_at),
      deleted_at:
        r.deleted_at !== null ? toISOStringSafe(r.deleted_at) : undefined,
    })),
  };
}

import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/client";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";
import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

import { CustomerPayload } from "../decorators/payload/CustomerPayload";

export async function deleteShoppingCustomerReviewsReviewId(props: {
  customer: CustomerPayload;
  reviewId: string & tags.Format<"uuid">;
}): Promise<void> {
  // Fetch the review to check if it exists and is owned by the customer
  const review = await MyGlobal.prisma.shopping_reviews.findUnique({
    where: { id: props.reviewId },
    select: { id: true, shopping_customer_id: true },
  });
  if (!review) {
    throw new HttpException("Review not found", 404);
  }
  if (review.shopping_customer_id !== props.customer.id) {
    throw new HttpException(
      "Forbidden: You can only delete your own reviews",
      403,
    );
  }
  // Delete attachments and review in transaction
  await MyGlobal.prisma.$transaction([
    MyGlobal.prisma.shopping_review_attachments.deleteMany({
      where: { shopping_review_id: props.reviewId },
    }),
    MyGlobal.prisma.shopping_reviews.delete({
      where: { id: props.reviewId },
    }),
  ]);
}

import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/client";
