import { Controller } from "@nestjs/common";
import { TypedRoute, TypedParam, TypedBody } from "@nestia/core";
import typia from "typia";
import { postShoppingSellerProductsProductCodeSkus } from "../../../../../providers/postShoppingSellerProductsProductCodeSkus";
import { SellerAuth } from "../../../../../decorators/SellerAuth";
import { SellerPayload } from "../../../../../decorators/payload/SellerPayload";
import { patchShoppingSellerProductsProductCodeSkus } from "../../../../../providers/patchShoppingSellerProductsProductCodeSkus";
import { putShoppingSellerProductsProductCodeSkusSkuCode } from "../../../../../providers/putShoppingSellerProductsProductCodeSkusSkuCode";
import { deleteShoppingSellerProductsProductCodeSkusSkuCode } from "../../../../../providers/deleteShoppingSellerProductsProductCodeSkusSkuCode";

import { IShoppingSku } from "../../../../../api/structures/IShoppingSku";
import { IPageIShoppingSku } from "../../../../../api/structures/IPageIShoppingSku";

@Controller("/shopping/seller/products/:productCode/skus")
export class ShoppingSellerProductsSkusController {
  /**
   * Create a new SKU under an existing product identified by productCode.
   *
   * This API operation allows a seller or admin to create a new SKU for an
   * existing product, using the product's global business code as a path
   * parameter. The request body must include all relevant data for SKU
   * creation—such as sku_code (unique), price, is_active flag, barcode
   * (optional), and any attribute variant selections. The operation validates
   * that the parent product exists and belongs to the requesting seller or
   * current business context.
   *
   * Creation logic enforces maximum allowable SKUs per product per business
   * policy, prevents duplicate codes, and requires all mandatory fields defined
   * in the shopping_skus schema. If attribute variant selection logic is
   * required (e.g., color, size), those should be included in the request body
   * according to how variant composition is implemented. Upon success, the new
   * SKU is registered under the target product and immediately available for
   * inventory setup and catalog inclusion, subject to status and activation
   * logic.
   *
   * Permission checks ensure only authorized sellers (owners of the product) or
   * platform admins can create SKUs under a product. If the path productCode
   * does not resolve to an existing or accessible product, the operation
   * returns a 404 not found or 403 forbidden. Request and response structures
   * align strictly with the schema's validation and composition rules. No
   * request body duplication of path parameter fields is allowed; the
   * productCode context is from the path, not the body.
   *
   * @param connection
   * @param productCode Unique business identifier code of the target product
   *   (global scope)
   * @param body Required information for creating a new SKU (Stock Keeping
   *   Unit) belonging to the product context.
   * @nestia Generated by Nestia - https://github.com/samchon/nestia
   */
  @TypedRoute.Post()
  public async create(
    @SellerAuth()
    seller: SellerPayload,
    @TypedParam("productCode")
    productCode: string,
    @TypedBody()
    body: IShoppingSku.ICreate,
  ): Promise<IShoppingSku> {
    try {
      return await postShoppingSellerProductsProductCodeSkus({
        seller,
        productCode,
        body,
      });
    } catch (error) {
      console.log(error);
      throw error;
    }
  }

  /**
   * Retrieve a paginated, searchable list of SKUs for a product using its
   * business code from shopping_skus.
   *
   * This endpoint provides a paginated, filterable list of SKUs for a specified
   * product, identified by the unique business 'code' provided as a path
   * parameter. Using the relationship between shopping_products (via code) and
   * shopping_skus (via shopping_product_id), it enables sellers or admins to
   * review all associated SKUs, control variant availability, and analyze
   * inventory status. The operation supports complex search queries, advanced
   * filtering (e.g., is_active, status, price ranges, barcode), and granular
   * sorting for product variant management.
   *
   * Security is enforced so only the product owner (seller) or platform admin
   * may view and manage variant SKUs for each product. Pagination and sorting
   * parameters are consumed via the request body for scalable collection
   * retrieval. The response format follows platform pagination standards,
   * including total count, page size, and a summary view of each SKU for list
   * performance. This endpoint supports all catalog operations such as
   * inventory checks, price audits, and detailed reporting. Audit logs should
   * capture SKU list queries for compliance and operational monitoring. Any
   * access violations or data integrity errors result in appropriate business
   * errors following platform conventions.
   *
   * @param connection
   * @param productCode Unique business identifier code of the target product
   *   (global scope)
   * @param body Search and pagination filters for retrieving SKUs under a
   *   product code.
   * @nestia Generated by Nestia - https://github.com/samchon/nestia
   */
  @TypedRoute.Patch()
  public async index(
    @SellerAuth()
    seller: SellerPayload,
    @TypedParam("productCode")
    productCode: string,
    @TypedBody()
    body: IShoppingSku.IRequest,
  ): Promise<IPageIShoppingSku.ISummary> {
    try {
      return await patchShoppingSellerProductsProductCodeSkus({
        seller,
        productCode,
        body,
      });
    } catch (error) {
      console.log(error);
      throw error;
    }
  }

  /**
   * Update a specific SKU for a given product.
   *
   * Update the properties of a specific SKU that belongs to a product. The SKU
   * is identified by the combination of product code (global, unique business
   * identifier for the parent product) and SKU code (unique across all SKUs).
   * This operation is intended for use by authorized actors such as sellers
   * (own SKUs) and admins (all SKUs) to modify SKU attributes such as retail
   * price, status (active, discontinued), barcode, and activation state.
   *
   * Security considerations require that only sellers who own the product or
   * admins can invoke this operation. SKU updates must respect inventory
   * policies (inventory is not modified directly here—see dedicated inventory
   * API). All business validations from the Prisma schema (e.g., unique
   * constraint for sku_code, valid price formats, and status enums) MUST be
   * enforced. If the SKU is involved in active orders, only permissible fields
   * may be edited as per business workflow.
   *
   * This operation references the 'shopping_products' and 'shopping_skus'
   * tables in the Prisma schema, extracting necessary columns for SKU edits.
   * Errors are returned if either the product code or SKU code are invalid, not
   * found, or outside the permissions of the caller. Typical clients for this
   * operation are product management interfaces for sellers and admin
   * dashboards. Related operations include creation (POST), retrieval (GET),
   * and removal (DELETE) of SKUs.
   *
   * @param connection
   * @param productCode Unique business code of the parent product (global
   *   scope)
   * @param skuCode Globally unique business code for the SKU (global scope)
   * @param body Fields to update for the specific SKU under the designated
   *   product. The structure follows the IShoppingSku.IUpdate DTO, supporting
   *   updates to price, status, barcode, and is_active attributes per schema.
   * @nestia Generated by Nestia - https://github.com/samchon/nestia
   */
  @TypedRoute.Put(":skuCode")
  public async update(
    @SellerAuth()
    seller: SellerPayload,
    @TypedParam("productCode")
    productCode: string,
    @TypedParam("skuCode")
    skuCode: string,
    @TypedBody()
    body: IShoppingSku.IUpdate,
  ): Promise<IShoppingSku> {
    try {
      return await putShoppingSellerProductsProductCodeSkusSkuCode({
        seller,
        productCode,
        skuCode,
        body,
      });
    } catch (error) {
      console.log(error);
      throw error;
    }
  }

  /**
   * Soft delete (archive) a specific SKU under a given product.
   *
   * This operation archives (soft deletes) a SKU under a specified product. The
   * SKU is uniquely identified by its skuCode within the context of the parent
   * productCode. Upon invocation, the SKU's 'deleted_at' field is set to the
   * current timestamp, ensuring the record remains in the database for audit,
   * compliance, and possible restoration, but is excluded from normal business
   * processes such as listing, ordering, and fulfillment.
   *
   * Role-based access controls restrict this endpoint to sellers who own the
   * product or platform admins. If the SKU is associated with active orders,
   * deletion may be blocked or require additional validation as specified in
   * the requirements; the system enforces these constraints at the
   * provider/service layer. This operation references the 'shopping_products'
   * and 'shopping_skus' tables in the Prisma schema.
   *
   * Business logic ensures that a SKU may only be soft deleted if it is not in
   * use by ongoing transactions, and that the combination of 'productCode' and
   * 'skuCode' maps uniquely to an existing, owned SKU. Related operations
   * include SKU update (PUT), creation (POST), and retrieval (GET), as well as
   * the corresponding hard-delete action for system-admin override in
   * compliance cases (not covered here).
   *
   * @param connection
   * @param productCode Unique business code of the parent product (global
   *   scope)
   * @param skuCode Globally unique business code for the SKU (global scope)
   * @nestia Generated by Nestia - https://github.com/samchon/nestia
   */
  @TypedRoute.Delete(":skuCode")
  public async erase(
    @SellerAuth()
    seller: SellerPayload,
    @TypedParam("productCode")
    productCode: string,
    @TypedParam("skuCode")
    skuCode: string,
  ): Promise<void> {
    try {
      return await deleteShoppingSellerProductsProductCodeSkusSkuCode({
        seller,
        productCode,
        skuCode,
      });
    } catch (error) {
      console.log(error);
      throw error;
    }
  }
}

