   */
  @TypedRoute.Get(":skuCode")
  public async at(
    @AdminAuth()
    admin: AdminPayload,
    @TypedParam("skuCode")
    skuCode: string,
  ): Promise<IShoppingInventory> {
    try {
      return await getShoppingAdminInventorySkuCode({
        admin,
        skuCode,
      });
    } catch (error) {
      console.log(error);
      throw error;
    }
  }
}

