      return await patchShoppingCustomerShipmentsCodePackagesPackageLabelTrackingsTrackingSourceEvents(
        {
          customer,
          code,
          packageLabel,
          trackingSource,
          body,
        },
      );
    } catch (error) {
      console.log(error);
      throw error;
    }
  }
}

